INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('davidcarma/MarkdownViewer-web-pro/local-deploy', 'community', 'davidcarma', 'MarkdownViewer-web-pro', 'davidcarma/MarkdownViewer-web-pro', 'local-deploy', 1, 0, 33, '2026-03-02T13:31:58Z', '2026-03-06T07:18:19.048Z', 'cf8669958c36e77341fbcad54e0aafeb1f8069d30892ccbc61736c2f30cd7543', '{"id":"davidcarma/MarkdownViewer-web-pro/local-deploy","name":"local-deploy","description":{"en":"The local-deploy skill serves the app locally to verify changes before pushing to the public repository, benefiting developers who need to test and validate their work. It ensures privacy and integrity of the codebase.","zh":"本地部署技能用于在推送代码到公共仓库前验证更改","ja":"ローカルデプロイスキルは、公開リポジトリへのプッシュ前に変更を検証するために使用されます","ko":"로컬 배포 스킬은 공개 저장소에 푸시하기 전에 변경 사항을 확인하는 데 사용됩니다","es":"La implementación local te permite servir la aplicación de forma local para verificar los cambios antes de enviarlos al repositorio público. Incluye un análisis de privacidad y verificación de archivos","fr":"Le déploiement local vous permet de servir l''application localement pour vérifier les modifications avant de les envoyer au référentiel public. Il inclut une analyse de confidentialité et une vérification de fichiers","de":"Die lokale Bereitstellung ermöglicht es Ihnen, die Anwendung lokal zu servieren, um Änderungen zu überprüfen, bevor Sie sie an das öffentliche Repository senden. Sie umfasst eine Privatsphärenanalyse und eine Dateiverifikation","pt":"O local-deploy é uma ferramenta que permite servir aplicativos localmente para verificar alterações antes de enviar para o repositório público. Ele inclui verificação de privacidade e pré-voo de arquivos","ru":"Местное развертывание - это инструмент, который позволяет обслуживать приложения локально для проверки изменений перед отправкой в публичный репозиторий. Он включает сканирование конфиденциальности и предварительный проверку файлов","ar":"تطبيق LOCAL-DEPLOY المحلي هو أداة تمكنك من تشغيل التطبيقات محليًا لاختبار التغييرات قبل إرسالها إلى المستودع العام. يتضمن فحص الخصوصية والتحقق المسبق من الملفات"},"seo":{"title":{"en":"local-deploy: Setup Guide for AI Agents | AI Agent Skill","zh":"本地部署设置指南 - AI工具","ja":"ローカルデプロイのベストプラクティス - AIエージェント","ko":"로컬 배포 설정 가이드 - AI 에이전트","es":"Guía de Configuración de Implementación Local con Herrami...","fr":"Guide de Configuration de Déploiement Local avec Outils d''IA","de":"Einrichtungsleitfaden für Lokale Bereitstellung mit KI-Tools","pt":"Guia de Configuração Local-Deploy para Desenvolvedores","ru":"Местное развертывание: Руководство по настройке для ИИ Аг...","ar":"إعداد تطبيق LOCAL-DEPLOY المحلي: دليل المستخدمين"},"description":{"en":"Verify app changes locally before pushing to public repo. Learn how to use local-deploy with step-by-step guide and expert tips. Get started now!","zh":"使用本地部署技能验证更改前推送到公共仓库，确保代码质量和安全","ja":"ローカルデプロイスキルを使用して、公開リポジトリへのプッシュ前に変更を検証し、コードの品質とセキュリティを確保します","ko":"로컬 배포 스킬을 사용하여 공개 저장소에 푸시하기 전에 변경 사항을 확인하고 코드 품질 및 보안을 보장합니다","es":"Aprende a configurar la implementación local con nuestra guía paso a paso para herramientas de AI y asegúrate de que tu aplicación esté lista para el reposit...","fr":"Découvrez comment configurer le déploiement local avec notre guide étape par étape pour les outils d''IA et assurez-vous que votre application est prête pour ...","de":"Erfahren Sie, wie Sie die lokale Bereitstellung mit unserem Schritt-für-Schritt-Leitfaden für KI-Tools konfigurieren und stellen Sie sicher, dass Ihre Anwend...","pt":"Aprenda a configurar o local-deploy para testar alterações antes de enviar para o repositório público, incluindo verificação de privacidade e pré-voo de arqu...","ru":"Узнайте, как настроить местное развертывание для проверки изменений перед отправкой в публичный репозиторий, включая сканирование конфиденциальности и предва...","ar":"تعلم كيفية إعداد تطبيق LOCAL-DEPLOY المحلي لاختبار التغييرات قبل إرسالها إلى المستودع العام، بما في ذلك فحص الخصوصية والتحقق المسبق من الملفات"},"definition":{"en":"local-deploy is a skill that enables local serving of an app to verify changes before public deployment, ensuring code privacy and integrity.","zh":"本地部署是指在本地环境中部署应用程序以验证更改","ja":"ローカルデプロイとは、変更を検証するためにローカル環境でアプリケーションをデプロイすること","ko":"로컬 배포는 변경 사항을 확인하기 위해 로컬 환경에서 애플리케이션을 배포하는 것을 의미합니다","es":"La implementación local es una función de las herramientas de AI que permite a los desarrolladores probar y verificar sus aplicaciones de forma local antes de publicarlas","fr":"Le déploiement local est une fonctionnalité des outils d''IA qui permet aux développeurs de tester et de vérifier leurs applications localement avant de les publier","de":"Die lokale Bereitstellung ist eine Funktion der KI-Tools, die es Entwicklern ermöglicht, ihre Anwendungen lokal zu testen und zu überprüfen, bevor sie sie veröffentlichen","pt":"O local-deploy é uma técnica de desenvolvimento que permite testar alterações em um aplicativo antes de enviá-las para um repositório público","ru":"Местное развертывание - это метод разработки, который позволяет проверить изменения в приложении перед отправкой их в публичный репозиторий","ar":"تطبيق LOCAL-DEPLOY المحلي هو طريقة لاختبار التغييرات في التطبيق قبل إرسالها إلى المستودع العام"},"features":{"en":["Runs mandatory privacy scan using bash scripts/privacy-scan.sh","Performs pre-flight file check with bash check-deployment.sh","Confirms presence of vendored libraries, app files, and KaTeX fonts","Starts the local deployment process for testing and validation","Ensures personal info such as paths, emails, and names are not publicly visible"],"zh":["隐私扫描以确保代码安全","预飞检查以确认依赖库和文件","支持bash脚本执行","验证vendored libs和KaTeX字体","确认应用程序文件和CSS文件"],"ja":["プライバシースキャンによるコードのセキュリティ確保","事前チェックによる依存ライブラリとファイルの確認","bashスクリプトの実行をサポート","vendored libsとKaTeXフォントの検証","アプリケーションファイルとCSSファイルの確認"],"ko":["코드 보안을 보장하기 위한 개인 정보 스캔","의존성 라이브러리와 파일을 확인하기 위한 사전 체크","bash 스크립트 실행 지원","vendored libs와 KaTeX 폰트의 검증","애플리케이션 파일과 CSS 파일의 확인"],"es":["Análisis de privacidad obligatorio para evitar violaciones de seguridad","Verificación de archivos para asegurarse de que los archivos necesarios estén presentes","Soporte para bibliotecas y frameworks como KaTeX","Uso de scripts de Bash para automatizar tareas","Compatibilidad con repositorios públicos para una implementación segura","Verificación de archivos de vendor y de aplicación"],"fr":["Analyse de confidentialité obligatoire pour éviter les violations de sécurité","Vérification de fichiers pour s''assurer que les fichiers nécessaires sont présents","Prise en charge des bibliothèques et des frameworks tels que KaTeX","Utilisation de scripts Bash pour automatiser les tâches","Compatibilité avec les référentiels publics pour une mise en œuvre sécurisée","Vérification des fichiers de fournisseur et d''application"],"de":["Pflichtprivatsphärenanalyse, um Sicherheitsverletzungen zu vermeiden","Dateiverifikation, um sicherzustellen, dass die erforderlichen Dateien vorhanden sind","Unterstützung für Bibliotheken und Frameworks wie KaTeX","Verwendung von Bash-Skripten zur Automatisierung von Aufgaben","Kompatibilität mit öffentlichen Repositorys für eine sichere Implementierung","Verifikation von Lieferantendateien und Anwendungsdateien"],"pt":["Verificação de privacidade com script de bash","Pré-voo de arquivos para confirmar a presença de bibliotecas e arquivos","Suporte a vendored libs e KaTeX fonts","Execução de comandos bash para iniciar o servidor local","Confirmação da presença de arquivos em pastas específicas","Integração com repositórios públicos para deploy"],"ru":["Сканирование конфиденциальности с помощью скрипта bash","Предварительный проверку файлов для подтверждения наличия библиотек и файлов","Поддержка vendored libs и KaTeX fonts","Выполнение команд bash для запуска локального сервера","Подтверждение наличия файлов в конкретных папках","Интеграция с публичными репозиториями для развертывания"],"ar":["فحص الخصوصية باستخدام سكريبت bash","التحقق المسبق من الملفات لتأكيد وجود المكتبات والملفات","دعم vendored libs و KaTeX fonts","تشغيل أوامر bash لبدء تشغيل الخادم المحلي","تأكيد وجود الملفات في مجلدات محددة","التكامل مع المستودعات العامة لنشر التطبيق"]},"keywords":{"en":["how to use local-deploy","what is local-deploy","local-deploy setup guide","local-deploy install","local-deploy alternative","local-deploy vs git deploy","local-deploy for AI agents","local-deploy privacy scan","local-deploy pre-flight check"],"zh":["本地部署","AI工具","代码验证","隐私扫描","预飞检查","bash脚本","vendored libs","KaTeX字体"],"ja":["ローカルデプロイ","AIエージェント","コード検証","プライバシースキャン","事前チェック","bashスクリプト","vendored libs","KaTeXフォント"],"ko":["로컬 배포","AI 에이전트","코드 검증","개인 정보 스캔","사전 체크","bash 스크립트","vendored libs","KaTeX 폰트"],"es":["implementación local","herramientas de AI","análisis de privacidad","verificación de archivos","desarrollo de aplicaciones","repositorios públicos","seguridad de la aplicación","automatización de tareas","Bash scripts","KaTeX"],"fr":["déploiement local","outils d''IA","analyse de confidentialité","vérification de fichiers","développement d''applications","référentiels publics","sécurité de l''application","automatisation de tâches","scripts Bash","KaTeX"],"de":["lokale Bereitstellung","KI-Tools","Privatsphärenanalyse","Dateiverifikation","Anwendungsentwicklung","öffentliche Repositorys","Anwendungssicherheit","Automatisierung von Aufgaben","Bash-Skripte","KaTeX"],"pt":["local-deploy","desenvolvimento de aplicativos","verificação de privacidade","pré-voo de arquivos","vendored libs","KaTeX fonts","bash scripts","repositórios públicos"],"ru":["местное развертывание","разработка приложений","сканирование конфиденциальности","предварительный проверку файлов","vendored libs","KaTeX fonts","скрипты bash","публичные репозитории"],"ar":["LOCAL-DEPLOY المحلي","تطوير التطبيقات","فحص الخصوصية","التحقق المسبق من الملفات","vendored libs","KaTeX fonts","سكريبتات bash","المستودعات العامة"]}},"owner":"davidcarma","repo":"MarkdownViewer-web-pro","repoPath":"davidcarma/MarkdownViewer-web-pro","stars":1,"forks":0,"updatedAt":"2026-03-02T13:31:58Z","topics":[],"category":"community","skillMd":{"name":"local-deploy","description":"Serve MarkdownViewer-web-pro locally for testing. Use when the user says /localdeploy, asks to test locally, run a local server, or preview before pushing.","bodyPreview":"# Local Deploy\n\nServe the app locally to verify changes before pushing to the **public** repo.\n\n## Steps\n\n### 1. Privacy scan (MANDATORY — public repo)\n\n```bash\nbash scripts/privacy-scan.sh\n```\n\n**Do NOT proceed if this fails.** Fix every violation first — any personal info (paths, emails, names) will be publicly visible.\n\n### 2. Pre-flight file check\n\n```bash\nbash check-deployment.sh\n```\n\nConfirms vendored libs (`lib/`), app files (`js/`, `css/`), and KaTeX fonts are all present.\n\n### 3. Start","body":"# Local Deploy\n\nServe the app locally to verify changes before pushing to the **public** repo.\n\n## Steps\n\n### 1. Privacy scan (MANDATORY — public repo)\n\n```bash\nbash scripts/privacy-scan.sh\n```\n\n**Do NOT proceed if this fails.** Fix every violation first — any personal info (paths, emails, names) will be publicly visible.\n\n### 2. Pre-flight file check\n\n```bash\nbash check-deployment.sh\n```\n\nConfirms vendored libs (`lib/`), app files (`js/`, `css/`), and KaTeX fonts are all present.\n\n### 3. Start local server\n\n```bash\n# Python (zero-install)\npython3 -m http.server 8080\n\n# Or Node\nnpx serve -l 8080\n```\n\nOpen: **http://localhost:8080**\n\n## What to Verify\n\n1. **Console clean** — no 404s or JS errors in DevTools\n2. **Markdown rendering** — type markdown, confirm preview renders\n3. **Math** — paste `$E=mc^2$` and `$$\\int_0^1 x\\,dx$$`\n4. **Mermaid** — paste a mermaid code block, verify render + zoom/pan + copy-image\n5. **Themes** — cycle Light / Dark / Gwyneth\n6. **Minimaps** — visible on editor and preview, toggle buttons work\n7. **View persistence** — switch to preview-only, reload, confirm mode remembered\n8. **File ops** — open, save, drag-drop a `.md` file\n9. **Image paste** — paste image from clipboard, verify embed\n\n## Troubleshooting\n\n| Symptom | Fix |\n|---------|-----|\n| Port in use | `python3 -m http.server 8081` |\n| KaTeX fonts 404 | Check `lib/fonts/` has 20 `.woff2` files |\n| Mermaid not rendering | Check `lib/mermaid.min.js` loads (Network tab) |\n| `file://` protocol issues | Always use HTTP server; `file://` breaks clipboard/CORS |\n"},"lastSynced":"2026-03-06T07:18:19.048Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing private and secure code validation before public deployment.","zh":"非常适合需要在公开部署前进行私密和安全代码验证的开发代理。","ja":"公開デプロイ前にプライベートでセキュアなコード検証が必要な開発エージェントに最適です。","ko":"공개 배포 전에 개인 정보 및 보안 코드 유효성을 검사해야 하는 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una validación de código privada y segura antes de la implementación pública.","fr":"Parfait pour les Agents de Développement ayant besoin d''une validation de code privée et sécurisée avant le déploiement public.","de":"Perfekt für Entwicklungsagenten, die eine private und sichere Codevalidierung vor dem öffentlichen Einsatz benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de validação de código privada e segura antes do deploy público.","ru":"Идеально для агентов разработки, которым нужна частная и безопасная проверка кода перед публичным развертыванием.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى التحقق من الشفرة الخاصة والأمن قبل النشر العام."},"recommendation":{"en":"Empowers agents to verify changes locally, ensuring code integrity and privacy by running mandatory privacy scans and pre-flight file checks using bash scripts like privacy-scan.sh and check-deployment.sh.","zh":"赋予代理验证本地更改的能力，通过运行诸如privacy-scan.sh和check-deployment.sh的bash脚本执行强制的隐私扫描和预飞行文件检查，以确保代码完整性和隐私。","ja":"エージェントにローカルで変更を検証する能力を付与し、privacy-scan.shやcheck-deployment.shのようなbashスクリプトを使用して、プライバシスキャンや事前飛行ファイルチェックを実行し、コードの完全性とプライバシーを確保する。","ko":"에이전트가 로컬에서 변경 사항을 검증할 수 있는 능력을 부여하여 privacy-scan.sh 및 check-deployment.sh와 같은 bash 스크립트를 사용하여 코드의 무결성과 개인 정보를 보호하기 위한 필수적인 개인 정보 스캔 및 사전 비행 파일 확인을 실행합니다.","es":"Permite a los agentes verificar los cambios de forma local, garantizando la integridad y la privacidad del código mediante la ejecución de análisis de privacidad obligatorios y comprobaciones de archivos pre vuelo usando scripts de bash como privacy-scan.sh y check-deployment.sh.","fr":"Permet aux agents de vérifier les modifications de manière locale, garantissant l''intégrité et la confidentialité du code en exécutant des analyses de confidentialité obligatoires et des vérifications de fichiers pré-vol en utilisant des scripts bash tels que privacy-scan.sh et check-deployment.sh.","de":"Ermöglicht es Agenten, Änderungen lokal zu überprüfen, um die Code-Integrität und -Privatsphäre sicherzustellen, indem obligatorische Datenschutzscans und Vorab-Dateprüfungen mithilfe von Bash-Skripten wie privacy-scan.sh und check-deployment.sh ausgeführt werden.","pt":"Habilita os agentes a verificar alterações localmente, garantindo a integridade e privacidade do código, executando verificações de privacidade obrigatórias e pré-voo de arquivos usando scripts bash como privacy-scan.sh e check-deployment.sh.","ru":"Наделяет агентов возможностью проверять изменения локально, обеспечивая целостность и конфиденциальность кода, запуская обязательные сканирования конфиденциальности и предварительные проверки файлов с помощью скриптов bash, таких как privacy-scan.sh и check-deployment.sh.","ar":"يمنح الوكلاء القدرة على التحقق من التغييرات محليًا، وضمان سلامة الشفرة وسريتها عن طريق تشغيل فحوصات خصوصية إجبارية وفحوصات الملفات قبل الطيران باستخدام سكريبتات مثل privacy-scan.sh و check-deployment.sh."},"useCases":{"en":["Validating code changes before public repository push","Running privacy scans to protect personal info","Confirming presence of vendored libraries and app files"],"zh":["在公开仓库推送前验证代码更改","运行隐私扫描以保护个人信息","确认存在的第三方库和应用程序文件"],"ja":["公開リポジトリへのプッシュ前にコードの変更を検証する","個人情報を保護するためのプライバシスキャンを実行する","ベンダライズされたライブラリとアプリケーションファイルの存在を確認する"],"ko":["공개 저장소에 푸시하기 전에 코드 변경 사항을 확인하는 것","개인 정보를 보호하기 위한 개인 정보 스캔을 실행하는 것","사용 가능한 라이브러리 및 애플리케이션 파일의 존재를 확인하는 것"],"es":["Validar los cambios de código antes de enviarlos al repositorio público","Ejecutar análisis de privacidad para proteger la información personal","Confirmar la presencia de bibliotecas y archivos de aplicaciones empaquetados"],"fr":["Valider les modifications de code avant de les pousser vers le référentiel public","Exécuter des analyses de confidentialité pour protéger les informations personnelles","Confirmer la présence de bibliothèques et de fichiers d''applications incorporés"],"de":["Änderungen am Code überprüfen, bevor sie an das öffentliche Repository gesendet werden","Datenschutzscans durchführen, um personenbezogene Informationen zu schützen","Die Anwesenheit von vertriebenen Bibliotheken und Anwendungsdateien bestätigen"],"pt":["Validar alterações de código antes do push para o repositório público","Executar verificações de privacidade para proteger informações pessoais","Confirmar a presença de bibliotecas e arquivos de aplicativos vendidos"],"ru":["Проверка изменений кода перед публичным пушированием в репозиторий","Запуск сканирований конфиденциальности для защиты личной информации","Подтверждение наличия вендорских библиотек и файлов приложений"],"ar":["التحقق من تغييرات الشفرة قبل دفعها إلى المستودع العام","تشغيل فحوصات الخصوصية لحماية المعلومات الشخصية","التأكد من وجود مكتبات تطبيقات وملفات تم بيعها"]},"limitations":{"en":["Requires local environment setup","Bash script compatibility needed","Public repository push requires passing privacy scan"],"zh":["需要本地环境设置","需要bash脚本兼容性","公开仓库推送需要通过隐私扫描"],"ja":["ローカル環境の設定が必要","bashスクリプトの互換性が必要","公開リポジトリへのプッシュにはプライバシスキャンの合格が必要"],"ko":["로컬 환경 설정이 필요합니다.","bash 스크립트 호환성이 필요합니다.","공개 저장소 푸시에는 개인 정보 스캔 통과가 필요합니다."],"es":["Requiere configuración del entorno local","Se necesita compatibilidad con scripts de bash","El envío al repositorio público requiere la aprobación del análisis de privacidad"],"fr":["Nécessite une configuration de l''environnement local","La compatibilité avec les scripts bash est nécessaire","L''envoi vers le référentiel public nécessite le passage de l''analyse de confidentialité"],"de":["Benötigt lokale Umgebungssetup","Bash-Skript-Kompatibilität ist erforderlich","Das Senden an das öffentliche Repository erfordert das Bestehen des Datenschutzscans"],"pt":["Requer configuração do ambiente local","Compatibilidade com script bash necessária","Push para repositório público requer aprovação da verificação de privacidade"],"ru":["Требуется настройка локальной среды","Необходима совместимость со скриптом bash","Публичный пушинг репозитория требует прохождения сканирования конфиденциальности"],"ar":["يتطلب إعداد بيئة محلية","مطلوب توافق مع سكريبتات bash","يتطلب دفع المستودع العام прохождение فحص الخصوصية"]},"version":4},"contentHash":"cf8669958c36e77341fbcad54e0aafeb1f8069d30892ccbc61736c2f30cd7543","qualityScore":33}');
