INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('davidcarma/MarkdownViewer-web-pro/local-deploy', 'local-deploy', 'davidcarma', 'MarkdownViewer-web-pro', 'community', 'local-deploy davidcarma MarkdownViewer-web-pro community The local-deploy skill serves the app locally to verify changes before pushing to the public repository, benefiting developers who need to test and validate their work. It ensures privacy and integrity of the codebase. 本地部署技能用于在推送代码到公共仓库前验证更改 ローカルデプロイスキルは、公開リポジトリへのプッシュ前に変更を検証するために使用されます 로컬 배포 스킬은 공개 저장소에 푸시하기 전에 변경 사항을 확인하는 데 사용됩니다 La implementación local te permite servir la aplicación de forma local para verificar los cambios antes de enviarlos al repositorio público. Incluye un análisis de privacidad y verificación de archivos Le déploiement local vous permet de servir l''application localement pour vérifier les modifications avant de les envoyer au référentiel public. Il inclut une analyse de confidentialité et une vérification de fichiers Die lokale Bereitstellung ermöglicht es Ihnen, die Anwendung lokal zu servieren, um Änderungen zu überprüfen, bevor Sie sie an das öffentliche Repository senden. Sie umfasst eine Privatsphärenanalyse und eine Dateiverifikation O local-deploy é uma ferramenta que permite servir aplicativos localmente para verificar alterações antes de enviar para o repositório público. Ele inclui verificação de privacidade e pré-voo de arquivos Местное развертывание - это инструмент, который позволяет обслуживать приложения локально для проверки изменений перед отправкой в публичный репозиторий. Он включает сканирование конфиденциальности и предварительный проверку файлов تطبيق LOCAL-DEPLOY المحلي هو أداة تمكنك من تشغيل التطبيقات محليًا لاختبار التغييرات قبل إرسالها إلى المستودع العام. يتضمن فحص الخصوصية والتحقق المسبق من الملفات how to use local-deploy what is local-deploy local-deploy setup guide local-deploy install local-deploy alternative local-deploy vs git deploy local-deploy for AI agents local-deploy privacy scan local-deploy pre-flight check 本地部署 AI工具 代码验证 隐私扫描 预飞检查 bash脚本 vendored libs KaTeX字体 Runs mandatory privacy scan using bash scripts/privacy-scan.sh Performs pre-flight file check with bash check-deployment.sh Confirms presence of vendored libraries, app files, and KaTeX fonts Starts the local deployment process for testing and validation Ensures personal info such as paths, emails, and names are not publicly visible local-deploy is a skill that enables local serving of an app to verify changes before public deployment, ensuring code privacy and integrity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('k1-c/linear-tui/m04-zero-cost', 'community', 'k1-c', 'linear-tui', 'k1-c/linear-tui', 'm04-zero-cost', 1, 0, 33, '2026-03-05T00:40:17Z', '2026-03-06T07:19:51.366Z', '3a2eed8faf0a0087aa5c823d66341123cc6f43ef36d1767c3fdbcc86cf8b4b54', '{"id":"k1-c/linear-tui/m04-zero-cost","name":"m04-zero-cost","description":{"en":"m04-zero-cost is a TUI client for Linear.app, enabling developers to manage issues, projects, and cycles from their terminal. It provides a zero-cost abstraction layer for efficient development.","zh":"m04-zero-cost是一款用于Linear.app的TUI客户端，允许用户从终端管理问题、项目和周期","ja":"m04-zero-costはLinear.app用のTUIクライアントであり、ユーザーがターミナルから問題、プロジェクト、サイクルを管理できるようにします","ko":"m04-zero-cost는 Linear.app용 TUI 클라이언트로 사용자가 터미널에서 문제, 프로젝트, 사이클을 관리할 수 있습니다","es":"m04-zero-cost es un cliente TUI para Linear.app que permite gestionar problemas, proyectos y ciclos desde la terminal. Ofrece abstracción de costo cero y polimorfismo en tiempo de compilación o ejecución","fr":"m04-zero-cost est un client TUI pour Linear.app qui permet de gérer les problèmes, les projets et les cycles depuis le terminal. Il offre une abstraction à coût nul et un polymorphisme en temps de compilation ou d''exécution","de":"m04-zero-cost ist ein TUI-Client für Linear.app, der die Verwaltung von Problemen, Projekten und Zyklen im Terminal ermöglicht. Er bietet eine Zero-Cost-Abstraktion und Polymorphismus zur Compile- oder Laufzeit","pt":"O m04-zero-cost é um cliente TUI para Linear.app que permite gerenciar problemas, projetos e ciclos de forma eficiente","ru":"m04-zero-cost - это клиент TUI для Linear.app, который позволяет управлять задачами, проектами и циклами эффективно","ar":"m04-zero-cost هو عميل واجهة المستخدم النصية للinear.app الذي يسمح بإدارة المشكلات والمشاريع والدورات بفعالية"},"seo":{"title":{"en":"m04-zero-cost: Zero-Cost Abstraction Setup Guide | AI Age...","zh":"m04-zero-cost终端客户端安装指南 - Linear.app管理工具","ja":"m04-zero-costのセットアップガイド - Linear.app用TUIクライアント","ko":"m04-zero-cost 터미널 클라이언트 설정 가이드 - Linear.app 관리 도구","es":"Guía de Configuración de m04-zero-cost: Abstracción de Co...","fr":"Guide de Configuration de m04-zero-cost : Abstraction à C...","de":"Einrichtungsleitfaden für m04-zero-cost: Zero-Cost-Abstra...","pt":"Guia de Configuração do m04-zero-cost: Abstração de Baixo...","ru":"ИИ Агенты: Руководство по настройке m04-zero-cost для Lin...","ar":"دليل إعداد m04-zero-cost: تجريد منخفض التكلفة للعمليات"},"description":{"en":"Discover how m04-zero-cost simplifies issue management with Linear.app. Learn to optimize your workflow with this TUI client and improve your development exp...","zh":"了解m04-zero-cost终端客户端的优势和功能，实现高效的Linear.app管理","ja":"m04-zero-costの特徴と機能を学び、Linear.appの管理を効率化しましょう","ko":"m04-zero-cost 터미널 클라이언트의 장점과 기능을 알아보고 Linear.app 관리를 최적화하세요","es":"Aprende a configurar m04-zero-cost para gestionar problemas, proyectos y ciclos en tu terminal con esta guía paso a paso","fr":"Découvrez comment configurer m04-zero-cost pour gérer les problèmes, les projets et les cycles depuis votre terminal avec ce guide étape par étape","de":"Erfahren Sie, wie Sie m04-zero-cost konfigurieren, um Probleme, Projekte und Zyklen in Ihrem Terminal zu verwalten, mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o m04-zero-cost, um cliente TUI para Linear.app, e otimize a gestão de problemas, projetos e ciclos","ru":"Узнайте, как настроить m04-zero-cost, клиент TUI для Linear.app, и оптимизировать управление задачами, проектами и циклами","ar":"تعرف على كيفية إعداد m04-zero-cost، عميل واجهة المستخدم النصية للinear.app، وتحسين إدارة المشكلات والمشاريع والدورات"},"definition":{"en":"m04-zero-cost is a terminal-based user interface client for Linear.app, designed to streamline issue and project management with a focus on zero-cost abstraction.","zh":"m04-zero-cost是一款终端客户端，用于管理Linear.app的问题、项目和周期","ja":"m04-zero-costはLinear.appの問題、プロジェクト、サイクルの管理に使用されるTUIクライアントです","ko":"m04-zero-cost는 Linear.app의 문제, 프로젝트, 사이클 관리에 사용되는 TUI 클라이언트입니다","es":"m04-zero-cost es un cliente de interfaz de usuario de texto para Linear.app que proporciona abstracción de costo cero y polimorfismo","fr":"m04-zero-cost est un client d''interface utilisateur en texte pour Linear.app qui fournit une abstraction à coût nul et un polymorphisme","de":"m04-zero-cost ist ein Textbenutzeroberflächen-Client für Linear.app, der eine Zero-Cost-Abstraktion und Polymorphismus bietet","pt":"O m04-zero-cost é uma abstração de baixo custo para a gestão de problemas e projetos","ru":"m04-zero-cost - это абстракция с низкими затратами для управления задачами и проектами","ar":"m04-zero-cost هو تجريد منخفض التكلفة لإدارة المشكلات والمشاريع"},"features":{"en":["Manages issues, projects, and cycles from the terminal using Linear.app","Utilizes zero-cost abstraction for efficient development","Handles compile-time and runtime polymorphism for optimal performance","Provides solutions for error codes E0277 and E0308 with trait bounds and design questions","Optimizes performance priority with heterogeneous collections and generics"],"zh":["支持编译时和运行时多态性","提供Layer 1语言机制","支持泛型和特征对象","优化性能","支持错误处理和设计问题"],"ja":["コンパイル時とランタイムの多相性をサポート","Layer 1言語メカニズムを提供","ジェネリクスとトレイトオブジェクトをサポート","パフォーマンスを最適化","エラー処理と設計問題をサポート"],"ko":["컴파일 시와 런타임 多相性 지원","Layer 1 언어 메커니즘 제공","제네릭스와 트레이트 객체 지원","성능 최적화","에러 처리와 설계 문제 지원"],"es":["Abstracción de costo cero","Polimorfismo en tiempo de compilación o ejecución","Gestión de problemas, proyectos y ciclos en la terminal","Compatibilidad con Linear.app","Interfaz de usuario de texto (TUI) para una experiencia de usuario más eficiente"],"fr":["Abstraction à coût nul","Polymorphisme en temps de compilation ou d''exécution","Gestion des problèmes, des projets et des cycles depuis le terminal","Compatibilité avec Linear.app","Interface utilisateur en texte (TUI) pour une expérience utilisateur plus eff