INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('martin-janci/claude-code-reviewer/jira-lookup', 'jira-lookup', 'martin-janci', 'claude-code-reviewer', 'community', 'jira-lookup martin-janci claude-code-reviewer community The jira-lookup skill automates PR code review using Claude Code CLI, tracking the full PR lifecycle state. It benefits developers by simplifying code review processes. Jira-Lookup是一个使用REST API查找Jira问题并显示其详细信息的AI工具 Jira-Lookupは、REST APIを使用してJira問題を検索し、その詳細を表示するAIエージェントです Jira-Lookup는 REST API를 사용하여 Jira 이슈를 조회하고其详细信息을 표시하는 AI 도구입니다 jira-lookup es un servicio de revisión de código automatizado que utiliza Claude Code CLI para realizar un seguimiento del ciclo de vida de las solicitudes de extracción jira-lookup est un service de révision de code automatisé qui utilise Claude Code CLI pour effectuer un suivi du cycle de vie des demandes d''extraction jira-lookup ist ein automatisierter Code-Überprüfungsdienst, der Claude Code CLI verwendet, um den Lebenszyklus von Pull-Requests zu verfolgen O jira-lookup é um serviço que consulta issues do Jira usando a CLI e a API REST. Ele permite a automação de processos e a integração com outros serviços. jira-lookup - это сервис, который запрашивает информацию о проблемах Jira с помощью CLI и REST API, используя ИИ Агенты. Он позволяет автоматизировать процессы и интегрироваться с другими сервисами. jira-lookup هو خدمة تقوم بإستعلام عن قضايا Jira باستخدام واجهة سطر الأوامر وواجهة برمجة التطبيقات REST. وهو يسمح بالتأشير التلقائي والدمج مع خدمات أخرى how to use jira-lookup jira-lookup setup guide jira-lookup alternative jira-lookup vs claude code cli jira-lookup install automated pr code review jira rest api tutorial claude code cli documentation Jira-Lookup REST API Jira问题查找 AI工具 环境变量 curl命令行工具 Reads config.yaml to retrieve Jira base URL Uses $JIRA_EMAIL and $JIRA_TOKEN environment variables for authentication Fetches Jira issues via the REST API with curl commands Displays issue details, including summary, status, assignee, and priority Supports webhooks for real-time updates and PR lifecycle state tracking jira-lookup is a skill that automates PR code review using the Jira REST API and Claude Code CLI, enabling efficient issue tracking and code review');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('0xkemcho/AutoClaw/thirdweb', 'community', '0xkemcho', 'AutoClaw', '0xkemcho/AutoClaw', 'thirdweb', 0, 1, 33, '2026-02-17T12:57:41Z', '2026-03-07T03:39:39.480Z', '5352df5277fc903cc0734ff777aacb9df6342b1e66a85b4baae6a4fa6a6babbb', '{"id":"0xkemcho/AutoClaw/thirdweb","name":"thirdweb","description":{"en":"thirdweb is a Web3 development tool that enables developers to build and manage blockchain applications. It provides specialized modules like wallets and auth, using sub-path imports.","zh":"Thirdweb 是一个 Web3 开发工具，提供了子路径导入等功能，帮助开发者简化开发流程","ja":"Thirdweb は Web3 開発ツールで、サブパスインポートなどの機能を提供し、開発者が開発プロセスを簡素化できる","ko":"Thirdweb는 Web3 개발을 위한 도구로 서브 경로 가져오기와 같은 기능을 제공하여 개발 프로세스를 단순화합니다","es":"Thirdweb es una herramienta para desarrolladores que ofrece imports de sub-rutas y módulos especializados para web3 y criptomonedas","fr":"Thirdweb est un outil pour les développeurs qui propose des imports de sous-chemins et des modules spécialisés pour web3 et crypto","de":"Thirdweb ist ein Tool für Entwickler, das Sub-Path-Imports und spezialisierte Module für web3 und Kryptowährungen bietet","pt":"O Thirdweb é uma ferramenta poderosa para desenvolvedores que desejam criar aplicativos Web3 com facilidade. Com sub-path imports, você pode importar módulos especializados de forma eficiente","ru":"Thirdweb — это мощный инструмент для разработчиков, которые хотят создавать приложения Web3 легко. С помощью sub-path imports вы можете импортировать специализированные модули эффективно ИИ Агентов","ar":"Thirdweb هو أداة قوية للمطورين الذين يرغبون في إنشاء تطبيقات الويب 3 بسهولة. باستخدام Imports.sub-path ، يمكنك استيراد الوحدات المتخصصة بطريقة فعالة لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"thirdweb: Web3 Development Setup Guide | AI Agent Skill","zh":"Thirdweb 集成指南：Web3 开发最佳实践","ja":"Thirdweb 導入ガイド：Web3 開発のベストプラクティス","ko":"Thirdweb 설정 가이드: Web3 개발 모범 사례","es":"Guía de configuración de thirdweb para desarrolladores","fr":"Guide de mise en route de thirdweb pour les développeurs","de":"Thirdweb-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Thirdweb: Melhores Práticas para ...","ru":"Руководство по настройке Thirdweb: Лучшие практики для ра...","ar":"دليل إعداد Thirdweb: أفضل الممارسات لتنمية أدوات الذكاء ا..."},"description":{"en":"Unlock the power of Web3 with thirdweb. Learn how to set up and use sub-path imports for specialized modules like wallets and auth. Get started now!","zh":"了解 Thirdweb 的子路径导入，优化 Web3 开发体验，提升开发效率","ja":"Thirdweb のサブパスインポートを理解し、Web3 開発のエクスペリエンスを最適化する","ko":"Thirdweb의 서브 경로 가져오기 기능을 이해하고 Web3 개발 경험을 최적화하십시오","es":"Aprende a utilizar thirdweb con imports de sub-rutas y módulos especializados para web3 y criptomonedas","fr":"Découvrez comment utiliser thirdweb avec des imports de sous-chemins et des modules spécialisés pour web3 et crypto","de":"Erfahren Sie, wie Sie thirdweb mit Sub-Path-Imports und spezialisierten Modulen für web3 und Kryptowährungen verwenden","pt":"Aprenda como configurar o Thirdweb com sub-path imports e melhore a eficiência do seu projeto com nossas dicas de especialista","ru":"Узнайте, как настроить Thirdweb с помощью sub-path imports и повысьте эффективность своего проекта с нашей экспертной помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Thirdweb باستخدام Imports.sub-path و تحسين كفاءة مشروعك مع نصائح chuyênática لأدوات الذكاء الاصطناعي"},"definition":{"en":"thirdweb is a Web3 development framework that utilizes sub-path imports for specialized modules, such as wallets and authentication.","zh":"Thirdweb 是一个提供子路径导入的 Web3 开发工具","ja":"Thirdweb はサブパスインポートを提供する Web3 開発ツール","ko":"Thirdweb는 서브 경로 가져오기를 제공하는 Web3 개발 도구입니다","es":"Thirdweb es un conjunto de herramientas para desarrolladores de web3 que utiliza imports de sub-rutas","fr":"Thirdweb est un ensemble d''outils pour les développeurs de web3 qui utilise des imports de sous-chemins","de":"Thirdweb ist ein Satz von Tools für web3-Entwickler, der Sub-Path-Imports verwendet","pt":"Thirdweb é uma plataforma de desenvolvimento Web3 que fornece sub-path imports para módulos especializados","ru":"Thirdweb — это платформа для разработки Web3, которая предоставляет sub-path imports для специализированных модулей ИИ Агентов","ar":"Thirdweb هو منصة تطوير الويب 3 التي توفر Imports.sub-path للوحدات المتخصصة لأدوات الذكاء الاصطناعي"},"features":{"en":["Uses sub-path imports for specialized modules like wallets and auth","Provides modules like inAppWallet and createWallet for wallet management","Includes darkTheme for React applications","Supports createAuth for authentication management","Utilizes privateKeyToAccount for account management"],"zh":["子路径导入","支持 React 和 Web3 开发","提供 wallet 和 auth 模块","支持暗黑主题","提供 createThirdwebClient 函数"],"ja":["サブパスインポート","React と Web3 開発をサポート","wallet と auth モジュールを提供","ダークテーマをサポート","createThirdwebClient 関数を提供"],"ko":["서브 경로 가져오기","React 및 Web3 개발 지원","지갑 및 인증 모듈 제공","다크 테마 지원","createThirdwebClient 함수 제공"],"es":["Imports de sub-rutas para módulos especializados","Compatibilidad con web3 y criptomonedas","Módulos de autenticación y autorización","Soporte para wallets y cuentas","Integración con React y otros frameworks"],"fr":["Imports de sous-chemins pour des modules spécialisés","Compatibilité avec web3 et crypto","Modules d''authentification et d''autorisation","Prise en charge de wallets et de comptes","Intégration avec React et d''autres frameworks"],"de":["Sub-Path-Imports für spezialisierte Module","Kompatibilität mit web3 und Kryptowährungen","Module für Authentifizierung und Autorisierung","Unterstützung für Wallets und Konten","Integration mit React und anderen Frameworks"],"pt":["Sub-path imports para módulos especializados","Importação de módulos como createThirdwebClient e inAppWallet","Suporte a React com darkTheme","Autenticação com createAuth","Gerenciamento de carteiras com privateKeyToAccount"],"ru":["Sub-path imports для специализированных модулей ИИ Агентов","Импорт модулей как createThirdwebClient и inAppWallet","Поддержка React с darkTheme","Аутентификация с createAuth","Управление кошельками с privateKeyToAccount"],"ar":["Imports.sub-path للوحدات المتخصصة لأدوات الذكاء الاصطناعي","استيراد الوحدات مثل createThirdwebClient و inAppWallet","دعم React مع darkTheme","التحقق مع createAuth","إدارة المحافظ مع privateKeyToAccount"]},"keywords":{"en":["how to use thirdweb","thirdweb setup guide","thirdweb vs celo","thirdweb install","what is thirdweb","thirdweb alternative","thirdweb web3 development","thirdweb crypto integration","thirdweb ai agent"],"zh":["Thirdweb","Web3 开发","子路径导入","React","wallet","auth","暗黑主题","createThirdwebClient"],"ja":["Thirdweb","Web3 開発","サブパスインポート","React","wallet","auth","ダークテーマ","createThirdwebClient"],"ko":["Thirdweb","Web3 개발","서브 경로 가져오기","React","지갑","인증","다크 테마","createThirdwebClient"],"es":["thirdweb","web3","criptomonedas","imports de sub-rutas","módulos especializados","autenticación","autorización","wallets","cuentas","React","desarrollo de aplicaciones"],"fr":["thirdweb","web3","crypto","imports de sous-chemins","modules spécialisés","authentification","autorisation","wallets","comptes","React","développement d''applications"],"de":["thirdweb","web3","Kryptowährungen","Sub-Path-Imports","spezialisierte Module","Authentifizierung","Autorisierung","Wallets","Konten","React","Anwendungsentwicklung"],"pt":["thirdweb","sub-path imports","desenvolvimento web3","react","autenticação","gerenciamento de carteiras","ai agents","ferramentas de desenvolvimento","melhores práticas"],"ru":["thirdweb","sub-path imports","разработка web3","react","аутентификация","управление кошельками","ИИ Агенты","инструменты разработки","лучшие практики"],"ar":["thirdweb","imports.sub-path","تطوير الويب 3","react","التحقق","إدارة المحافظ","أدوات الذكاء الاصطناعي","أدوات التطوير","أفضل الممارسات"]}},"owner":"0xkemcho","repo":"AutoClaw","repoPath":"0xkemcho/AutoClaw","stars":0,"forks":1,"updatedAt":"2026-02-17T12:57:41Z","topics":["ai","ai-agent","celo","crypto","web3"],"category":"community","skillMd":{"name":"thirdweb","description":"Thirdweb v5 SDK usage in AutoClaw. Use when working with wallet connection, social login, SIWE authentication, or thirdweb client/provider setup. Triggers on: thirdweb, wallet connect, inAppWallet, social login, SIWE, ConnectButton, thirdweb auth, thirdweb provider.","bodyPreview":"## Critical: Thirdweb v5 Sub-Path Imports\n\nThirdweb v5 uses sub-path imports. Never import from the root `thirdweb` package for specialized modules:\n\n```ts\n// CORRECT\nimport { createThirdwebClient } from ''thirdweb'';\nimport { inAppWallet, createWallet } from ''thirdweb/wallets'';\nimport { darkTheme } from ''thirdweb/react'';\nimport { createAuth } from ''thirdweb/auth'';\nimport { privateKeyToAccount } from ''thirdweb/wallets'';\n\n// WRONG — do not import wallet/auth/react from root\nimport { inAppWallet } f","body":"## Critical: Thirdweb v5 Sub-Path Imports\n\nThirdweb v5 uses sub-path imports. Never import from the root `thirdweb` package for specialized modules:\n\n```ts\n// CORRECT\nimport { createThirdwebClient } from ''thirdweb'';\nimport { inAppWallet, createWallet } from ''thirdweb/wallets'';\nimport { darkTheme } from ''thirdweb/react'';\nimport { createAuth } from ''thirdweb/auth'';\nimport { privateKeyToAccount } from ''thirdweb/wallets'';\n\n// WRONG — do not import wallet/auth/react from root\nimport { inAppWallet } from ''thirdweb''; // ❌\n```\n\n## Project Setup\n\n### Client (Web — `apps/web/src/lib/thirdweb.ts`)\n\n```ts\nimport { createThirdwebClient } from ''thirdweb'';\n\nexport const client = createThirdwebClient({\n  clientId: process.env.NEXT_PUBLIC_THIRDWEB_CLIENT_ID!,\n});\n```\n\n### Client (API — `apps/api/src/lib/thirdweb.ts`)\n\n```ts\nimport { createThirdwebClient } from ''thirdweb'';\n\nexport const thirdwebClient = createThirdwebClient({\n  secretKey: process.env.THIRDWEB_SECRET_KEY,\n});\n```\n\n### Wallets Configuration\n\n```ts\nimport { inAppWallet, createWallet } from ''thirdweb/wallets'';\n\nexport const wallets = [\n  inAppWallet({\n    auth: { options: [''email'', ''google'', ''apple'', ''passkey''] },\n  }),\n  createWallet(''io.metamask''),\n  createWallet(''com.coinbase.wallet''),\n  createWallet(''walletConnect''),\n];\n```\n\n### SIWE Auth (Server-Side)\n\n```ts\nimport { createAuth } from ''thirdweb/auth'';\nimport { privateKeyToAccount } from ''thirdweb/wallets'';\n\nconst adminAccount = privateKeyToAccount({\n  client: thirdwebClient,\n  privateKey: process.env.THIRDWEB_ADMIN_PRIVATE_KEY as `0x${string}`,\n});\n\nexport const thirdwebAuth = createAuth({\n  domain: process.env.AUTH_DOMAIN,\n  client: thirdwebClient,\n  adminAccount,\n});\n```\n\nAuth flow: `thirdwebAuth.generatePayload()` → client signs → `thirdwebAuth.verifyPayload()` → JWT via `thirdwebAuth.generateJWT()`.\n\n### Provider Stack (Web)\n\nWrap app with `QueryClientProvider` (from `@tanstack/react-query`) + `ThirdwebProvider`:\n\n```tsx\nimport { ThirdwebProvider } from ''thirdweb/react'';\n\n<QueryClientProvider client={queryClient}>\n  <ThirdwebProvider>{children}</ThirdwebProvider>\n</QueryClientProvider>\n```\n\n## Theme\n\nThis project uses `darkTheme()` from `thirdweb/react` with custom indigo accent colors. See `apps/web/src/lib/thirdweb.ts` for the full theme config.\n\n## Environment Variables\n\n| Variable | Location | Description |\n|---|---|---|\n| `NEXT_PUBLIC_THIRDWEB_CLIENT_ID` | Web | Public client ID |\n| `THIRDWEB_SECRET_KEY` | API | Server-side secret key |\n| `THIRDWEB_ADMIN_PRIVATE_KEY` | API | Admin wallet for SIWE signing |\n| `AUTH_DOMAIN` | API | SIWE auth domain |\n\n## Key Hooks\n\n- `useActiveAccount()` — Get connected wallet account\n- `useActiveWallet()` — Get connected wallet instance\n- `useConnect()` — Connect a wallet programmatically\n- `useDisconnect()` — Disconnect current wallet\n\n## Chain Configuration\n\nThis project targets Celo mainnet (chain ID 42220). When using `ConnectButton`, set `chain={celo}` from `thirdweb/chains`.\n"},"lastSynced":"2026-03-07T03:39:39.480Z","agentAnalysis":{"suitability":{"en":"Perfect for Web3 Development Agents needing streamlined blockchain application management with sub-path imports.","zh":"非常适合需要简化区块链应用程序管理和子路径导入的Web3开发代理。","ja":"Web3開発エージェントがブロックチェーンアプリケーション管理をストリームライン化する必要がある場合に最適です。","ko":"블록체인 애플리케이션 관리를 단순화하고 서브 경로 가져오기를 필요로 하는 Web3 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo Web3 que necesitan una gestión de aplicaciones de blockchain simplificada con importaciones de sub-rutas.","fr":"Parfait pour les agents de développement Web3 qui ont besoin d''une gestion d''applications de blockchain simplifiée avec des importations de sous-chemins.","de":"Perfekt für Web3-Entwicklungsagenten, die eine vereinfachte Blockchain-Anwendungsverwaltung mit Subpfad-Importen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web3 que necessitam de gerenciamento de aplicativos de blockchain otimizado com imports de sub-caminho.","ru":"Идеально подходит для агентов разработки Web3, которым требуется оптимизированное управление приложениями блокчейна с импортом подпутей.","ar":"مثالي لعميل تطوير الويب 3 الذي يحتاج إلى إدارة تطبيقات البلوكتشين المتدفقة مع استيرادات المسار الفرعي."},"recommendation":{"en":"Empowers agents to build and manage blockchain applications using specialized modules like wallets and auth, leveraging sub-path imports from ''thirdweb/wallets'' and ''thirdweb/auth'' to create secure and scalable Web3 solutions.","zh":"赋予代理构建和管理区块链应用程序的能力，利用诸如钱包和身份验证等专用模块，并利用来自''thirdweb/wallets''和''thirdweb/auth''的子路径导入来创建安全且可扩展的Web3解决方案。","ja":"エージェントがウォレットや認証などの専用モジュールを使用してブロックチェーンアプリケーションを構築して管理できるようにし、''thirdweb/wallets''と''thirdweb/auth''からのサブパスインポートを活用して、セキュアでスケーラブルなWeb3ソリューションを作成できる。","ko":"에이전트가 지갑 및 인증과 같은 전문 모듈을 사용하여 블록체인 애플리케이션을 구축하고 관리할 수 있도록 하며, ''thirdweb/wallets'' 및 ''thirdweb/auth''의 서브 경로 가져오기를 활용하여 보안 및 확장 가능한 Web3 솔루션을 만듭니다.","es":"Habilita a los agentes a crear y gestionar aplicaciones de blockchain utilizando módulos especializados como carteras y autenticación, aprovechando importaciones de sub-rutas de ''thirdweb/wallets'' y ''thirdweb/auth'' para crear soluciones Web3 seguras y escalables.","fr":"Permet aux agents de créer et de gérer des applications de blockchain en utilisant des modules spécialisés tels que les portefeuilles et l''authentification, en exploitant les importations de sous-chemins de ''thirdweb/wallets'' et ''thirdweb/auth'' pour créer des solutions Web3 sécurisées et évolutives.","de":"Ermächtigt Agenten, Blockchain-Anwendungen zu erstellen und zu verwalten, indem sie spezialisierte Module wie Wallets und Authentifizierung verwenden, Subpfad-Importe von ''thirdweb/wallets'' und ''thirdweb/auth'' nutzend, um sichere und skalierbare Web3-Lösungen zu erstellen.","pt":"Habilita os agentes a construir e gerenciar aplicativos de blockchain usando módulos especializados como carteiras e autenticação, aproveitando imports de sub-caminho de ''thirdweb/wallets'' e ''thirdweb/auth'' para criar soluções Web3 seguras e escaláveis.","ru":"Позволяет агентам создавать и управлять приложениями блокчейна, используя специализированные модули, такие как кошельки и аутентификация, используя импорт подпутей из ''thirdweb/wallets'' и ''thirdweb/auth'', для создания безопасных и масштабируемых решений Web3.","ar":"تمكّن الوكيل من بناء وإدارة تطبيقات البلوكتشين باستخدام الوحدات المتخصصة مثل المحافظ والتحقق، واستخدام استيرادات المسار الفرعي من ''thirdweb/wallets'' و ''thirdweb/auth'' لإنشاء حلول الويب 3 الآمنة والموسعة."},"useCases":{"en":["Building decentralized applications with thirdweb''s createThirdwebClient","Implementing in-app wallets using ''thirdweb/wallets'' and ''thirdweb/auth'' modules","Customizing blockchain application UI with ''thirdweb/react'' themes like darkTheme"],"zh":["使用thirdweb的createThirdwebClient构建去中心化应用程序","使用''thirdweb/wallets''和''thirdweb/auth''模块实现应用内钱包","使用''thirdweb/react''主题（如darkTheme）自定义区块链应用程序UI"],"ja":["thirdwebのcreateThirdwebClientを使用して分散型アプリケーションを構築する","''thirdweb/wallets''と''thirdweb/auth''モジュールを使用してアプリ内ウォレットを実装する","''thirdweb/react''テーマ（例：darkTheme）を使用してブロックチェーンアプリケーションのUIをカスタマイズする"],"ko":["thirdweb의 createThirdwebClient를 사용하여 분산형 애플리케이션을 구축하는 것","''thirdweb/wallets'' 및 ''thirdweb/auth'' 모듈을 사용하여 앱 내.wallet을 구현하는 것","''thirdweb/react'' 테마(예: darkTheme)를 사용하여 블록체인 애플리케이션 UI를 사용자 지정하는 것"],"es":["Creación de aplicaciones descentralizadas con createThirdwebClient de thirdweb","Implementación de carteras en aplicaciones utilizando los módulos ''thirdweb/wallets'' y ''thirdweb/auth''","Personalización de la interfaz de usuario de la aplicación de blockchain con temas ''thirdweb/react'' como darkTheme"],"fr":["Création d''applications décentralisées avec createThirdwebClient de thirdweb","Mise en œuvre de portefeuilles dans les applications en utilisant les modules ''thirdweb/wallets'' et ''thirdweb/auth''","Personnalisation de l''interface utilisateur de l''application de blockchain avec des thèmes ''thirdweb/react'' tels que darkTheme"],"de":["Erstellung dezentraler Anwendungen mit createThirdwebClient von thirdweb","Implementierung von Wallets in Anwendungen unter Verwendung der Module ''thirdweb/wallets'' und ''thirdweb/auth''","Anpassung der Benutzeroberfläche der Blockchain-Anwendung mit ''thirdweb/react''-Themen wie darkTheme"],"pt":["Construir aplicações descentralizadas com o createThirdwebClient da thirdweb","Implementar carteiras dentro de aplicativos usando módulos ''thirdweb/wallets'' e ''thirdweb/auth''","Personalizar a interface do usuário de aplicativos de blockchain com temas ''thirdweb/react'' como darkTheme"],"ru":["Создание децентрализованных приложений с помощью createThirdwebClient от thirdweb","Реализация встроенных кошельков с использованием модулей ''thirdweb/wallets'' и ''thirdweb/auth''","Настройка интерфейса пользователя приложений блокчейна с помощью тем ''thirdweb/react'', таких как darkTheme"],"ar":["بناء التطبيقات اللامركزية باستخدام createThirdwebClient من thirdweb","تنفيذ المحافظ داخل التطبيقات باستخدام الوحدات ''thirdweb/wallets'' و ''thirdweb/auth''","تخصيص واجهة المستخدم لتطبيقات البلوكتشين باستخدام موضوعات ''thirdweb/react'' مثل darkTheme"]},"limitations":{"en":["Requires correct sub-path imports for specialized modules","Thirdweb v5 compatibility necessary for sub-path imports"],"zh":["需要正确的子路径导入来使用专用模块","thirdweb v5 兼容性是子路径导入所必需的"],"ja":["専用モジュールを使用するには正しいサブパスインポートが必要","thirdweb v5の互換性はサブパスインポートに必要"],"ko":["전문 모듈을 사용하려면 올바른 서브 경로 가져오기가 필요합니다","thirdweb v5 호환성이 서브 경로 가져오기에 필요합니다"],"es":["Requiere importaciones de sub-rutas correctas para módulos especializados","Compatibilidad con Thirdweb v5 necesaria para importaciones de sub-rutas"],"fr":["Nécessite des importations de sous-chemins correctes pour les modules spécialisés","Compatibilité avec Thirdweb v5 nécessaire pour les importations de sous-chemins"],"de":["Benötigt korrekte Subpfad-Importe für spezialisierte Module","Kompatibilität mit Thirdweb v5 erforderlich für Subpfad-Importe"],"pt":["Exige imports de sub-caminho corretos para módulos especializados","Compatibilidade com o Thirdweb v5 necessária para imports de sub-caminho"],"ru":["Требует правильного импорта подпутей для специализированных модулей","Необходимо совместимость с Thirdweb v5 для импорта подпутей"],"ar":["يتطلب استيرادات المسار الفرعي الصحيحة للوحدات المتخصصة","التوافق مع Thirdweb v5 ضروري لاستيرادات المسار الفرعي"]},"version":4},"contentHash":"5352df5277fc903cc0734ff777aacb9df6342b1e66a85b4baae6a4fa6a6babbb","qualityScore":33}');
