INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('0xkemcho/AutoClaw/thirdweb', 'thirdweb', '0xkemcho', 'AutoClaw', 'community', 'thirdweb 0xkemcho AutoClaw community ai ai-agent celo crypto web3 thirdweb is a Web3 development tool that enables developers to build and manage blockchain applications. It provides specialized modules like wallets and auth, using sub-path imports. Thirdweb 是一个 Web3 开发工具，提供了子路径导入等功能，帮助开发者简化开发流程 Thirdweb は Web3 開発ツールで、サブパスインポートなどの機能を提供し、開発者が開発プロセスを簡素化できる Thirdweb는 Web3 개발을 위한 도구로 서브 경로 가져오기와 같은 기능을 제공하여 개발 프로세스를 단순화합니다 Thirdweb es una herramienta para desarrolladores que ofrece imports de sub-rutas y módulos especializados para web3 y criptomonedas Thirdweb est un outil pour les développeurs qui propose des imports de sous-chemins et des modules spécialisés pour web3 et crypto Thirdweb ist ein Tool für Entwickler, das Sub-Path-Imports und spezialisierte Module für web3 und Kryptowährungen bietet O Thirdweb é uma ferramenta poderosa para desenvolvedores que desejam criar aplicativos Web3 com facilidade. Com sub-path imports, você pode importar módulos especializados de forma eficiente Thirdweb — это мощный инструмент для разработчиков, которые хотят создавать приложения Web3 легко. С помощью sub-path imports вы можете импортировать специализированные модули эффективно ИИ Агентов Thirdweb هو أداة قوية للمطورين الذين يرغبون في إنشاء تطبيقات الويب 3 بسهولة. باستخدام Imports.sub-path ، يمكنك استيراد الوحدات المتخصصة بطريقة فعالة لأدوات الذكاء الاصطناعي how to use thirdweb thirdweb setup guide thirdweb vs celo thirdweb install what is thirdweb thirdweb alternative thirdweb web3 development thirdweb crypto integration thirdweb ai agent Thirdweb Web3 开发 子路径导入 React wallet auth 暗黑主题 createThirdwebClient Uses sub-path imports for specialized modules like wallets and auth Provides modules like inAppWallet and createWallet for wallet management Includes darkTheme for React applications Supports createAuth for authentication management Utilizes privateKeyToAccount for account management thirdweb is a Web3 development framework that utilizes sub-path imports for specialized modules, such as wallets and authentication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Mjvolk3/Swanki/stage', 'community', 'Mjvolk3', 'Swanki', 'Mjvolk3/Swanki', 'stage', 0, 0, 33, '2026-02-26T20:38:24Z', '2026-03-07T03:45:24.563Z', '723783aa150a4c129f33f1c916c777b9a768e7041fbb2f2be569273947de8bb5', '{"id":"Mjvolk3/Swanki/stage","name":"stage","description":{"en":"Stage automates Git workflows by scanning unstaged files and auto-detecting logical blocks for commit. Developers can benefit from this skill by simplifying their Git workflow.","zh":"Stage 是一种智能的文件提交方式，通过自动检测逻辑块，并允许用户通过交互式选择来提交更改","ja":"ステージは、自動的な論理ブロック検出と交互式選択による変更のコミットを可能にするスマートなファイル提交方法です","ko":"스테이지는 자동 논리 블록 감지 및 상호 작용 선택을 통해 변경 사항을 커밋하는 스마트한 파일 제출 방법입니다","es":"Stage es una herramienta que permite committar archivos con bloques lógicos auto-detectados. Mejora tu flujo de trabajo con Git","fr":"Stage est un outil qui permet de committer des fichiers avec des blocs logiques auto-détectés. Améliorez votre flux de travail avec Git","de":"Stage ist ein Tool, das das Committen von Dateien mit auto-erkannten logischen Blöcken ermöglicht. Verbessern Sie Ihren Git-Arbeitsablauf","pt":"O Stage é uma ferramenta que permite a auto-detecção de blocos lógicos e o commit de arquivos usando Git. Aprenda a configurá-lo com nosso guia","ru":"Stage - это инструмент, который позволяет авто-обнаруживать логические блоки и коммитить файлы с помощью Git. Узнайте, как его настроить","ar":"المرحلة هي أداة تسمح بالكشف التلقائي عن الكتلة المنطقية وإرسال الملفات باستخدام جيت. تعلم كيفية إعدادها باستخدام دليلنا"},"seo":{"title":{"en":"Stage: Smart Git Workflow Automation | AI Agent Skill","zh":"Stage Setup Guide: 使用智能 Stage 文件提交","ja":"ステージの設定方法: AIエージェントを使用した自動的な論理ブロック検出","ko":"스테이지 설정 가이드: 자동 논리 블록 감지로 파일 커밋하기","es":"Configuración de Stage: Guía para committing con bloques ...","fr":"Mise en place de Stage: Guide pour le commit avec des blo...","de":"Stage-Setup: Anleitung für commit mit logischen Blöcken","pt":"Guia de Configuração do Stage para Desenvolvedores","ru":"Настройка Stage: Руководство для Разработчиков ИИ Агентов","ar":"دليل إعداد المرحلة لأصحاب المهارات التطويرية"},"description":{"en":"Streamline your Git workflow with Stage, an AI agent skill that auto-detects logical blocks for commit. Learn how to use Stage today!","zh":"了解如何使用 Stage 智能文件提交功能，自动检测逻辑块，并通过交互式选择来提交更改","ja":"ステージを使用して、自動的な論理ブロック検出と交互式選択による変更のコミット方法を学習します","ko":"스테이지를 사용하여 자동 논리 블록 감지 및 상호 작용 선택을 통해 변경 사항을 커밋하는 방법을 알아보세요","es":"Aprende a utilizar Stage para commit con bloques lógicos auto-detectados y mejora tu flujo de trabajo con Git","fr":"Découvrez comment utiliser Stage pour commit avec des blocs logiques auto-détectés et améliorez votre flux de travail avec Git","de":"Erfahren Sie, wie Sie Stage verwenden, um mit auto-erkannten logischen Blöcken zu committen und Ihren Git-Arbeitsablauf zu verbessern","pt":"Aprenda a configurar o Stage com nosso guia passo a passo para desenvolvedores, incluindo Git e auto-detecção de blocos lógicos","ru":"Узнайте, как настроить Stage с нашей пошаговой инструкцией для разработчиков ИИ Агентов, включая Git и авто-обнаружение логических блоков","ar":"تعلم كيفية إعداد المرحلة باستخدام دليلنا خطوة بخطوة لأصحاب المهارات التطويرية، بما في ذلك جيت واكتشاف الكتلة المنطقية"},"definition":{"en":"Stage is a Git workflow automation skill that uses auto-detected logical blocks for commit, simplifying the development process.","zh":"Stage 是一种智能文件提交工具，使用自动检测逻辑块的方法来简化提交过程","ja":"ステージは、自動的な論理ブロック検出を使用してコミットプロセスを簡素化するスマートなファイル提交ツールです","ko":"스테이지는 자동 논리 블록 감지를 사용하여 제출 프로세스를 단순화하는 스마트 파일 제출 도구입니다","es":"Stage es una herramienta de Git que permite committar archivos con bloques lógicos auto-detectados","fr":"Stage est un outil Git qui permet de committer des fichiers avec des blocs logiques auto-détectés","de":"Stage ist ein Git-Tool, das das Committen von Dateien mit auto-erkannten logischen Blöcken ermöglicht","pt":"O Stage é uma ferramenta de desenvolvimento que permite a auto-detecção de blocos lógicos de código","ru":"Stage - это инструмент разработки, который позволяет авто-обнаруживать логические блоки кода","ar":"المرحلة هي أداة تطوير تسمح بالكشف التلقائي عن الكتلة المنطقية من الكود"},"features":{"en":["Runs `git status` to scan unstaged and untracked files","Auto-detects logical blocks based on predefined rules","Supports interactive selection of blocks for staging","Integrates with Git workflow via `/stage` and `/commit` commands"],"zh":["自动检测逻辑块","交互式选择提交更改","使用 Git Status 获取文件修改信息","支持多文件提交"],"ja":["自動的な論理ブロック検出","交互式選択による変更のコミット","Git Status を使用したファイル変更情報の取得","複数ファイルのコミットをサポート"],"ko":["자동 논리 블록 감지","상호 작용 선택을 통해 변경 사항 커밋","Git Status를 사용한 파일 변경 정보 조회","다중 파일 제출 지원"],"es":["Detección automática de bloques lógicos","Selección interactiva de bloques para committar","Integración con Git para committar archivos","Soporte para archivos modificados, eliminados y no rastreados","Compatibilidad con flujos de trabajo de Git"],"fr":["Détection automatique de blocs logiques","Sélection interactive de blocs pour committer","Intégration avec Git pour committer des fichiers","Prise en charge de fichiers modifiés, supprimés et non suivis","Compatibilité avec les flux de travail Git"],"de":["Automatische Erkennung logischer Blöcke","Interaktive Auswahl von Blöcken zum Committen","Integration mit Git zum Committen von Dateien","Unterstützung für geänderte, gelöschte und nicht verfolgte Dateien","Kompatibilität mit Git-Arbeitsabläufen"],"pt":["Auto-detecção de blocos lógicos de código","Commit de arquivos usando Git","Interação com o usuário para seleção de blocos","Execução de `git status` para verificar alterações","Suporte a desenvolvedores para melhorar a produtividade"],"ru":["Авто-обнаружение логических блоков кода","Коммит файлов с помощью Git","Взаимодействие с пользователем для выбора блоков","Выполнение `git status` для проверки изменений","Поддержка разработчиков для повышения производительности"],"ar":["اكتشاف الكتلة المنطقية التلقائي من الكود","إرسال الملفات باستخدام جيت","التفاعل مع المستخدم لاختيار الكتلة","تشغيل `git status` للتحقق من التغييرات","دعم المطورين لتحسين الإنتاجية"]},"keywords":{"en":["how to use stage","stage alternative","stage vs git","stage install","stage setup guide","what is stage","stage git workflow automation","stage ai agent skill"],"zh":["Stage 文件提交","智能提交工具","自动检测逻辑块","交互式选择提交","Git Status","文件提交方法","AIエージェント工具"],"ja":["ステージのファイル提交","スマートなファイル提交ツール","自動的な論理ブロック検出","交互式選択による変更のコミット","Git Status","ファイル提交方法","AIエージェントツール"],"ko":["스테이지 파일 제출","스마트 파일 제출 도구","자동 논리 블록 감지","상호 작용 선택을 통해 변경 사항 커밋","Git Status","파일 제출 방법","AI 에이전트 도구"],"es":["herramientas de Git","commit con bloques lógicos","Stage para desarrolladores","flujo de trabajo de Git","detención automática de bloques","selección interactiva de bloques"],"fr":["outils Git","commit avec des blocs logiques","Stage pour les développeurs","flux de travail Git","détection automatique de blocs","sélection interactive de blocs"],"de":["Git-Tools","Commit mit logischen Blöcken","Stage für Entwickler","Git-Arbeitsablauf","automatische Erkennung von Blöcken","interaktive Auswahl von Blöcken"],"pt":["stage","desenvolvimento","git","auto-detecção","blocos lógicos","commit","produtividade","ferramentas de desenvolvimento"],"ru":["stage","разработка","git","авто-обнаружение","логические блоки","коммит","производительность","инструменты разработки"],"ar":["المرحلة","التطوير","جيت","اكتشاف الكتلة المنطقية","الكتلة المنطقية","إرسال","الإنتاجية","أدوات التطوير"]}},"owner":"Mjvolk3","repo":"Swanki","repoPath":"Mjvolk3/Swanki","stars":0,"forks":0,"updatedAt":"2026-02-26T20:38:24Z","topics":[],"category":"community","skillMd":{"name":"stage","description":"Smart staging with auto-detected file blocks and interactive override. Use before /commit.","bodyPreview":"# Smart Stage\n\nStage files for commit using auto-detected logical blocks. The user picks which blocks to stage via interactive selection.\n\n## Workflow\n\n```\n/stage -> /commit\n```\n\n## Step 1: Scan unstaged/untracked files\n\nRun `git status` (never use `-uall` flag) to get the full picture of modified, deleted, and untracked files.\n\nIf there are no unstaged or untracked changes, inform the user and stop.\n\n## Step 2: Auto-detect file blocks\n\nGroup related files into logical blocks based on these rule","body":"# Smart Stage\n\nStage files for commit using auto-detected logical blocks. The user picks which blocks to stage via interactive selection.\n\n## Workflow\n\n```\n/stage -> /commit\n```\n\n## Step 1: Scan unstaged/untracked files\n\nRun `git status` (never use `-uall` flag) to get the full picture of modified, deleted, and untracked files.\n\nIf there are no unstaged or untracked changes, inform the user and stop.\n\n## Step 2: Auto-detect file blocks\n\nGroup related files into logical blocks based on these rules (applied in order of priority):\n\n### The Commit Trio rule\n\nAny block that contains a `.py` file under `swanki/` or `tests/` MUST also include:\n\n1. The paired dendron note (`notes/<dendron-path>.md`) -- if it exists in the changed file list\n2. The paired test file (`tests/.../<test_file>.py`) or source file -- if it exists in the changed file list\n3. The current weekly note (`notes/user.mjvolk3.swanki.tasks.weekly.*.md`) -- always pulled into any block containing Python files\n\nThe weekly note appears in the FIRST Python block only (not duplicated across blocks). This enforces the project''s atomic commit rule: source + note + weekly travel together.\n\n### Block detection rules (in priority order)\n\n1. **Python trio**: a `.py` source file + its `notes/<dendron-path>.md` + its `tests/` counterpart + the weekly note. Multiple related `.py` files in the same package can be grouped into one block (e.g., all files under `swanki/processing/`).\n2. **Skill bundles**: all files under a `.claude/skills/<name>/` directory grouped together\n3. **Config clusters**: related config files (e.g., `.pre-commit-config.yaml` + `pyproject.toml` when both have lint-related changes)\n4. **Shell scripts + notes**: `.sh` files paired with their `notes/scripts.<name>.md` counterpart\n5. **Standalone notes**: `notes/*.md` files not already paired with Python or shell files\n6. **Other files**: anything not covered above (configs, docs, etc.)\n\nA file should only appear in one block. If a file could fit multiple blocks, use the highest-priority rule.\n\n## Step 3: Present blocks to user\n\nDisplay numbered blocks with file lists. Mark the weekly note explicitly so the user sees it:\n\n```\nDetected file blocks:\n[1] Processing package (4 files):\n    swanki/processing/pdf_processor.py\n    swanki/processing/image_processor.py\n    notes/swanki.processing.pdf_processor.md\n    notes/user.mjvolk3.swanki.tasks.weekly.2026.08.md  (weekly)\n[2] Scripts: scripts/dendron-tree.sh\n[3] Standalone notes: notes/scratch.2026.02.11.*.md (3 files)\n```\n\n## Step 4: User picks blocks\n\nUse `AskUserQuestion` with `multiSelect: true` to let the user choose which blocks to stage. Options:\n\n- Each detected block as a selectable option\n- \"All\" to stage everything\n\n## Step 5: Pre-stage reminders\n\nPrint reminders as informational text (not blocking):\n\n- If selected files include `.py` under `swanki/` or `tests/`: \"Python files detected. Consider running `/update-py-notes` and `/ruff` first.\"\n\n## Step 6: Stage selected blocks\n\n- Run `git add <files>` for chosen blocks (explicit file paths, never `git add -A` or `git add .`)\n- Use `git rm` for deleted files\n- Never stage `.env`, credentials, or secrets -- warn the user if detected\n\n## Step 7: Confirm\n\nRun `git diff --cached --name-status` to show what is now staged.\n\n## Important Rules\n\n- NEVER run `git add -A` or `git add .`\n- NEVER stage `.env`, credentials, secrets, or similar sensitive files -- warn the user\n- Use `git rm` for deleted files\n- The user''s tool approval prompt is the gate -- do NOT ask extra confirmation questions\n- A file appears in exactly one block\n- Do NOT ask extra approval questions -- tool approval prompts are the gates\n- The weekly note is always included with the first Python block -- never staged alone as a separate block when Python files are present\n\n## Example Invocations\n\n- `/stage` -- interactive staging of all changes\n- \"stage my changes\"\n- \"stage files for commit\"\n"},"lastSynced":"2026-03-07T03:45:24.563Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined Git workflow automation.","zh":"非常适合需要简化Git工作流自动化的开发代理。","ja":"開発エージェントがGitのワークフローをストリームライン化する必要がある場合に最適です。","ko":"개발 에이전트가 Git 워크플로 자동화를 간소화해야 하는 경우에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una automatización de flujo de trabajo de Git optimizada.","fr":"Parfait pour les agents de développement ayant besoin d''une automatisation de workflow Git simplifiée.","de":"Perfekt für Entwicklungsmittelstände, die eine optimierte Git-Workflow-Automatisierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de automação de fluxo de trabalho do Git simplificado.","ru":"Идеально для агентов разработки, которым необходима упрощенная автоматизация рабочего процесса Git.","ar":"مثالي لعميل التطوير الذي يحتاج إلى تسهيل تدفق عمل Git المُستخدم."},"recommendation":{"en":"Empowers agents to simplify Git workflows by auto-detecting logical blocks for commit using Git status scans and interactive selection, streamlining the development process with efficient file staging and commit protocols.","zh":"通过Git状态扫描和交互式选择自动检测逻辑块来简化Git工作流，实现文件暂存和提交协议的开发过程高效化。","ja":"Gitステータススキャンと対話式の選択を使用して論理ブロックを自動検出してGitワークフローを簡素化し、ファイルのステージングとコミットプロトコルを使用して開発プロセスを効率化します。","ko":"Git 상태 스캔 및 상호 작용 선택을 사용하여 논리 블록을 자동으로 감지하여 Git 워크플로를 간소화하고 파일 스테이징 및 커밋 프로토콜을 사용하여 개발 프로세스를 효율적으로 만듭니다.","es":"Permite a los agentes simplificar los flujos de trabajo de Git mediante la detección automática de bloques lógicos para el compromiso utilizando exploraciones de estado de Git y selección interactiva, optimizando el proceso de desarrollo con protocolos de puesta en escena y confirmación de archivos eficientes.","fr":"Permet aux agents de simplifier les flux de travail Git en détectant automatiquement les blocs logiques pour l''engagement à l''aide d''analyses d''état Git et de sélection interactive, rationalisant le processus de développement avec des protocoles de mise en scène et d''engagement de fichiers efficaces.","de":"Ermöglicht es Agenten, Git-Workflows zu vereinfachen, indem sie logische Blöcke für das Commit mithilfe von Git-Status-Scans und interaktiver Auswahl automatisch erkennen, und rationalisiert den Entwicklungsprozess mit effizienten Datei-Staging- und Commit-Protokollen.","pt":"Habilita os agentes a simplificar os fluxos de trabalho do Git, detectando automaticamente blocos lógicos para confirmação, utilizando varreduras de status do Git e seleção interativa, simplificando o processo de desenvolvimento com protocolos de estadia e confirmação de arquivos eficientes.","ru":"Наделяет агентов возможностью упростить рабочие процессы Git, автоматически обнаруживая логические блоки для фиксации с помощью сканирования состояния Git и интерактивного выбора, оптимизируя процесс разработки эффективными протоколами подготовки и фиксации файлов.","ar":"يمنح الوكالات القدرة على تبسيط تدفقات عمل Git من خلال الكشف التلقائي عن الكتل المنطقية للتأكيد باستخدام مسح حالة Git والاختيار التفاعلي، وتبسيط عملية التطوير ببروتوكولات مراحل وأوامر الملفات الفعالة."},"useCases":{"en":["Automating Git workflows","Simplifying commit processes with logical block detection","Streamlining development workflows with interactive file staging"],"zh":["自动化Git工作流","使用逻辑块检测简化提交过程","使用交互式文件暂存简化开发工作流"],"ja":["Gitワークフローの自動化","論理ブロック検出によるコミットプロセスの簡素化","対話式ファイルステージングによる開発ワークフローの効率化"],"ko":["Git 워크플로 자동화","논리 블록 감지를 사용한 커밋 프로세스 간소화"," 상호 작용 파일 스테이징을 사용한 개발 워크플로우 효율화"],"es":["Automatización de flujos de trabajo de Git","Simplificación de procesos de confirmación con detección de bloques lógicos","Optimización de flujos de trabajo de desarrollo con puesta en escena de archivos interactiva"],"fr":["Automatisation des flux de travail Git","Simplification des processus d''engagement avec détection de blocs logiques","Rationalisation des flux de travail de développement avec une mise en scène de fichiers interactive"],"de":["Automatisierung von Git-Workflows","Vereinfachung von Commit-Prozessen mit Erkennung logischer Blöcke","Optimierung von Entwicklungs-Workflows mit interaktiver Datei-Staging"],"pt":["Automatizar fluxos de trabalho do Git","Simplificar processos de confirmação com detecção de blocos lógicos","Otimizar fluxos de trabalho de desenvolvimento com estadia interativa de arquivos"],"ru":["Автоматизация рабочих процессов Git","Упрощение процессов фиксации с помощью обнаружения логических блоков","Оптимизация рабочих процессов разработки с помощью интерактивной подготовки файлов"],"ar":["تأهيل تدفقات عمل Git","تبسيط عمليات التأكيد باستخدام الكشف عن الكتل المنطقية","تبسيط تدفقات عمل التطوير بمراحل الملفات التفاعلية"]},"limitations":{"en":["Requires Git installation and configuration","Limited to local repository scanning"],"zh":["需要Git安装和配置","仅限本地仓库扫描"],"ja":["Gitのインストールと設定が必要","ローカルリポジトリのスキャンに限定される"],"ko":["Git 설치 및 구성이 필요","로컬 저장소 스캔에만限됨"],"es":["Requiere instalación y configuración de Git","Limitado a la exploración de repositorios locales"],"fr":["Nécessite l''installation et la configuration de Git","Limité à l''analyse de dépôts locaux"],"de":["Benötigt Git-Installation und -Konfiguration","Begrenzt auf die Analyse lokaler Repositorys"],"pt":["Requer instalação e configuração do Git","Limitado à varredura de repositórios locais"],"ru":["Требуется установка и настройка Git","Ограничен сканированием локальных репозиториев"],"ar":["يتطلب تثبيت وتكوين Git","محدود بمسح المستودعات المحلية"]},"version":4},"contentHash":"723783aa150a4c129f33f1c916c777b9a768e7041fbb2f2be569273947de8bb5","qualityScore":33}');
