INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Mjvolk3/Swanki/stage', 'stage', 'Mjvolk3', 'Swanki', 'community', 'stage Mjvolk3 Swanki community Stage automates Git workflows by scanning unstaged files and auto-detecting logical blocks for commit. Developers can benefit from this skill by simplifying their Git workflow. Stage 是一种智能的文件提交方式，通过自动检测逻辑块，并允许用户通过交互式选择来提交更改 ステージは、自動的な論理ブロック検出と交互式選択による変更のコミットを可能にするスマートなファイル提交方法です 스테이지는 자동 논리 블록 감지 및 상호 작용 선택을 통해 변경 사항을 커밋하는 스마트한 파일 제출 방법입니다 Stage es una herramienta que permite committar archivos con bloques lógicos auto-detectados. Mejora tu flujo de trabajo con Git Stage est un outil qui permet de committer des fichiers avec des blocs logiques auto-détectés. Améliorez votre flux de travail avec Git Stage ist ein Tool, das das Committen von Dateien mit auto-erkannten logischen Blöcken ermöglicht. Verbessern Sie Ihren Git-Arbeitsablauf O Stage é uma ferramenta que permite a auto-detecção de blocos lógicos e o commit de arquivos usando Git. Aprenda a configurá-lo com nosso guia Stage - это инструмент, который позволяет авто-обнаруживать логические блоки и коммитить файлы с помощью Git. Узнайте, как его настроить المرحلة هي أداة تسمح بالكشف التلقائي عن الكتلة المنطقية وإرسال الملفات باستخدام جيت. تعلم كيفية إعدادها باستخدام دليلنا how to use stage stage alternative stage vs git stage install stage setup guide what is stage stage git workflow automation stage ai agent skill Stage 文件提交 智能提交工具 自动检测逻辑块 交互式选择提交 Git Status 文件提交方法 AIエージェント工具 Runs `git status` to scan unstaged and untracked files Auto-detects logical blocks based on predefined rules Supports interactive selection of blocks for staging Integrates with Git workflow via `/stage` and `/commit` commands Stage is a Git workflow automation skill that uses auto-detected logical blocks for commit, simplifying the development process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tqer39/openclaw-ops/sync-install-docs', 'community', 'tqer39', 'openclaw-ops', 'tqer39/openclaw-ops', 'sync-install-docs', 0, 0, 33, '2026-02-20T03:34:48Z', '2026-03-07T03:47:50.941Z', '977719002e51b46a6f1c8207042633cb60573a23f8511de06ecd573a938e2f93', '{"id":"tqer39/openclaw-ops/sync-install-docs","name":"sync-install-docs","description":{"en":"The sync-install-docs skill ensures configuration and operations repository consistency for OpenClaw, benefiting developers by updating related documentation after modifying install scripts.","zh":"Sync Install Docs 是一个用于OpenClaw配置和操作文档同步的AIエージェント技能","ja":"Sync Install Docsは、OpenClawの設定と操作リポジトリのドキュメントを同期するスキルです","ko":"Sync Install Docs는 OpenClaw의 설정 및 운영 저장소 문서를 동기화하는 스킬입니다","es":"sync-install-docs es un repositorio de configuración y operaciones para OpenClaw que garantiza la coherencia de la documentación","fr":"sync-install-docs est un référentiel de configuration et d''exploitation pour OpenClaw qui assure la cohérence de la documentation","de":"sync-install-docs ist ein Konfigurations- und Betreibungsrepository für OpenClaw, das die Konsistenz der Dokumentation gewährleistet","pt":"O Sync Install Docs é uma habilidade que garante a consistência da documentação após alterações nos scripts de instalação do OpenClaw","ru":"Sync Install Docs - это навык, обеспечивающий согласованность документации после изменений в скриптах установки OpenClaw","ar":"Sync Install Docs هو مهارة تضمن الاتساق في الوثائق بعد تعديل سكريبتات التثبيت لOpenClaw"},"seo":{"title":{"en":"sync-install-docs: Configuration and Ops Setup Guide | AI...","zh":"Sync Install Docs Setup Guide - AIエージェント配置","ja":"Sync Install Docs 設定ガイド - AIエージェント","ko":"Sync Install Docs 설정 가이드 - AI 에이전트","es":"Guía de Configuración de sync-install-docs para OpenClaw","fr":"Guide d''Installation de sync-install-docs p