INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tqer39/openclaw-ops/sync-install-docs', 'sync-install-docs', 'tqer39', 'openclaw-ops', 'community', 'sync-install-docs tqer39 openclaw-ops community openclaw ops The sync-install-docs skill ensures configuration and operations repository consistency for OpenClaw, benefiting developers by updating related documentation after modifying install scripts. Sync Install Docs 是一个用于OpenClaw配置和操作文档同步的AIエージェント技能 Sync Install Docsは、OpenClawの設定と操作リポジトリのドキュメントを同期するスキルです Sync Install Docs는 OpenClaw의 설정 및 운영 저장소 문서를 동기화하는 스킬입니다 sync-install-docs es un repositorio de configuración y operaciones para OpenClaw que garantiza la coherencia de la documentación sync-install-docs est un référentiel de configuration et d''exploitation pour OpenClaw qui assure la cohérence de la documentation sync-install-docs ist ein Konfigurations- und Betreibungsrepository für OpenClaw, das die Konsistenz der Dokumentation gewährleistet O Sync Install Docs é uma habilidade que garante a consistência da documentação após alterações nos scripts de instalação do OpenClaw Sync Install Docs - это навык, обеспечивающий согласованность документации после изменений в скриптах установки OpenClaw Sync Install Docs هو مهارة تضمن الاتساق في الوثائق بعد تعديل سكريبتات التثبيت لOpenClaw how to use sync-install-docs sync-install-docs setup guide OpenClaw configuration repository install script documentation sync-install-docs alternative sync-install-docs vs OpenClaw what is sync-install-docs sync-install-docs install sync-install-docs for AI agents AIエージェント Sync Install Docs OpenClaw 配置和操作 Bash脚本 PowerShell脚本 README.md 文档同步 Checks install script modifications in install.sh and install.ps1 Updates related documentation, including README.md Ensures consistency between Bash and PowerShell install scripts Triggers documentation checks after script edits Supports OpenClaw configuration and operations repository sync-install-docs is a skill that verifies and updates documentation consistency after changes are made to install scripts, such as install.sh or install.ps1.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Tendo33/python-template/project-development-playbook', 'community', 'Tendo33', 'python-template', 'Tendo33/python-template', 'project-development-playbook', 0, 0, 33, '2026-03-06T02:59:42Z', '2026-03-07T03:49:45.866Z', 'f752fb26ac2be27795ef158d43472dd25e7fadd330d95218ee77b4abb22b7223', '{"id":"Tendo33/python-template/project-development-playbook","name":"project-development-playbook","description":{"en":"The project-development-playbook skill provides a self-use Python template for consistent delivery workflows across backend and frontend tasks, benefiting developers with efficient project management.","zh":"项目开发游戏规则配置指南提供了一致的交付工作流，帮助开发者使用Python模板提高项目开发效率","ja":"プロジェクト開発プレイブック設定ガイドは一貫したデリバリーフローを提供し、Pythonテンプレートを使用してプロジェクト開発の効率を高めるのに役立ちます","ko":"프로젝트 개발 플레이북 설정 가이드는 일관된 전달 워크플로를 제공하여 Python 템플릿을 사용하여 프로젝트 개발 효율을 높이는 데 도움이 됩니다","es":"Project-development-playbook es una plantilla de Python para mejorar la entrega de proyectos con un flujo de trabajo consistente","fr":"Project-development-playbook est un modèle Python pour améliorer la livraison de projets avec un flux de travail cohérent","de":"Project-development-playbook ist eine Python-Vorlage für die Verbesserung der Projektlieferung mit einem konsistenten Arbeitsablauf","pt":"O Project Development Playbook é um modelo de Python para entrega de projetos com uma abordagem consistente. Ele utiliza Python 3.10+, uv para dependências e execução, ruff para lint/format e pytest para testes.","ru":"Project Development Playbook - это шаблон Python для доставки проектов с последовательным подходом. Он использует Python 3.10+, uv для зависимостей и выполнения, ruff для lint/формат и pytest для тестов, а также ИИ Агенты.","ar":"كتاب إرشادات المشروع هو نموذج بايثون لتقديم مشاريع بالاعتماد على نهج متسق. يستخدم بايثون 3.10+، uv للDEPENDENCIES وتنفيذ، ruff لتنسيق و pytest للاختبارات"},"seo":{"title":{"en":"project-development-playbook: Python Template Setup Guide...","zh":"项目开发游戏规则配置指南 - Python模板","ja":"プロジェクト開発プレイブック設定ガイド - Pythonテンプレート","ko":"프로젝트 개발 플레이북 설정 가이드 - Python 템플릿","es":"Guía de configuración para proyecto-development-playbook ...","fr":"Guide de mise en place pour project-development-playbook ...","de":"Einrichtungsleitfaden für project-development-playbook mi...","pt":"Guia de Configuração do Project Development Playbook com ...","ru":"Настройка Project Development Playbook: ИИ Агенты для Python","ar":"إعداد كتاب إرشادات المشروع مع بايثون"},"description":{"en":"Streamline your development workflow with the project-development-playbook skill, featuring Python 3.10+ and uv for dependencies. Get started now!","zh":"使用Python模板和一致的交付工作流，提高项目开发效率。了解项目开发游戏规则配置指南","ja":"Pythonテンプレートと一貫したデリバリーフローを使用してプロジェクト開発の効率を高める。プロジェクト開発プレイブック設定ガイドを参照","ko":"Python 템플릿과 일관된 전달 워크플로를 사용하여 프로젝트 개발 효율을 높입니다. 프로젝트 개발 플레이북 설정 가이드 참조","es":"Aprende a utilizar project-development-playbook con Python 3.10+ y herramientas como uv, ruff y pytest para mejorar tus flujos de trabajo","fr":"Découvrez comment utiliser project-development-playbook avec Python 3.10+ et des outils comme uv, ruff et pytest pour améliorer vos flux de travail","de":"Erfahren Sie, wie Sie project-development-playbook mit Python 3.10+ und Tools wie uv, ruff und pytest verwenden können, um Ihre Arbeitsabläufe zu optimieren","pt":"Aprenda a configurar o Project Development Playbook com Python 3.10+ e melhore a entrega de projetos com uma abordagem consistente","ru":"Узнайте, как настроить Project Development Playbook с Python 3.10+ и улучшить доставку проектов с помощью последовательного подхода и ИИ Агентов","ar":"تعلم كيفية إعداد كتاب إرشادات المشروع مع بايثون 3.10+ وتحسين تسليم المشاريع بالاعتماد على نهج متسق"},"definition":{"en":"project-development-playbook is a Python-based skill that applies a consistent delivery workflow across backend and frontend tasks using uv, ruff, 