INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Tendo33/IdeaGo/project-development-playbook', 'project-development-playbook', 'Tendo33', 'IdeaGo', 'community', 'project-development-playbook Tendo33 IdeaGo community ideas The project-development-playbook skill provides a consistent delivery workflow for startup ideas, utilizing technologies like Python 3.10+ and uv for efficient project development. 项目开发游戏规则是AI驱动的竞争对手研究引擎，用于启动创业想法。它提供了一致的交付流程，用于后端和前端任务 プロジェクト開発プレイブックは、スタートアップアイデアの研究を支援するAIエージェントを使用した競争対象研究エンジンです。バックエンドとフロントエンドのタスクに一貫したデリバリーフローを提供します 프로젝트 개발 플레이북은 스타트업 아이디어 연구를 지원하는 AI 에이전트를 사용한 경쟁자 연구 엔진입니다. 백엔드와 프론트엔드 태스크에 일관된 배달 흐름을 제공합니다 Project Development Playbook es un motor de investigación de competidores impulsado por inteligencia artificial para ideas de startups, que utiliza tecnologías como Python y uv Project Development Playbook est un moteur de recherche de concurrents propulsé par l''intelligence artificielle pour les idées de startups, qui utilise des technologies comme Python et uv Project Development Playbook ist ein von künstlicher Intelligenz angetriebener Wettbewerbsforschungsmotor für Startup-Ideen, der Technologien wie Python und uv verwendet O Project Development Playbook é um motor de pesquisa de concorrentes impulsionado por IA para ideias de startup, utilizando tecnologias como Python e uv Project Development Playbook — это движок исследования конкурентов на основе ИИ для стартап-идей, использующий технологии как Python и uv كتاب تطوير المشروع هو محرك بحث منافسات مدفوع بالذكاء الاصطناعي لأفكار الاستارتآب، يستخدم تقنيات مثل Python و uv how to use project-development-playbook project-development-playbook setup guide project-development-playbook alternative project-development-playbook vs competitor project-development-playbook install what is project-development-playbook 项目开发游戏规则 AI竞争对手研究 启动创业想法 Python 3.10+ uv ruff pytest 一致的交付流程 Applies consistent delivery workflow across backend and frontend tasks Utilizes Python 3.10+ for implementation Leverages uv for dependencies and execution Employs ruff for linting and formatting Runs verification commands using pytest project-development-playbook is a technical workflow for applying consistent delivery across backend and frontend tasks using specific tools and technologies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('buddypia/kaiju-voice/app-review-analyzer', 'community', 'buddypia', 'kaiju-voice', 'buddypia/kaiju-voice', 'app-review-analyzer', 0, 0, 33, '2026-02-26T12:06:38Z', '2026-03-07T03:51:08.326Z', 'd18a052492e0dd01d5365415fce4543f6022963518ef18a581cfc20b5bc9b688', '{"id":"buddypia/kaiju-voice/app-review-analyzer","name":"app-review-analyzer","description":{"en":"The app-review-analyzer skill analyzes app store review CSV data, providing visualizations of review distributions, time-based trends, and version-based ratings. It benefits developers seeking to understand user feedback.","zh":"应用评论分析器是一种使用AIエージェント分析应用评论数据的工具，支持CSV数据格式，能够分析评分分布、时间别趋势、版本别评分等","ja":"App Review Analyzerは、アプリストアレビューデータを分析するAIエージェントです。CSVデータ形式をサポートし、評点分布、時間別トレンド、バージョン別評点などの分析が可能です","ko":"애플리케이션 리뷰 분석기는 애플리케이션 리뷰 데이터를 분석하는 AI Tools입니다. CSV 데이터 형식을 지원하며,评分 分布, 시간별 트렌드, 버전별 평가 등 다양한 분석을 수행할 수 있습니다","es":"El analizador de reseñas de aplicaciones es una herramienta que analiza datos de reseñas en formato CSV y los visualiza en gráficos","fr":"L''outil d''analyse de critiques d''applications est un outil qui analyse les données de critiques au format CSV et les visualise en graphiques","de":"Das App-Bewertungsanalyse-Tool ist ein Tool, das Bewertungsdaten im CSV-Format analysiert und in Grafiken visualisiert","pt":"O App Review Analyzer é uma ferramenta que analisa dados de avaliações de aplicativos e gera gráficos para visualizar tendências","ru":"ИИ Агент App Review Analyzer - это инструмент, который анализирует данные отзывов приложений и генерирует графики для визуализации тенденций","ar":"Analyzer لتقارير التطبيقات هي أداة تحليل بيانات تقارير التطبيقات وتوليد رسومات لتصور الاتجاهات"},"seo":{"title":{"en":"app-review-analyzer: CSV Data Analysis for AI Agents | Ap...","zh":"应用评论分析器设置指南 - 使用AIエージェント分析应用评论数据","ja":"App Review Analyzer設定ガイド - アプリストアレビューデータを分析するAIエージェント","ko":"애플리케이션 리뷰 분석기 설정 가이드 - AI Tools를 사용하여 애플리케이션 리뷰 데이터 분석","es":"Guía de configuración del analizador de reseñas de aplica...","fr":"Configurer l''outil d''analyse de critiques d''applications","de":"Einrichten des App-Bewertungsanalyse-Tools","pt":"Guia de Configuração do App Review Analyzer para Análise ...","ru":"ИИ Агент App Review Analyzer: Руководство по Настройке","ar":"دليل إعداد Analyzer لتقارير التطبيقات لتحليل البيانات"},"description":{"en":"Unlock app review trends with app-review-analyzer. Analyze CSV data, visualize review distributions, and discover key insights - get started now!","zh":"了解应用评论分析器的功能和设置方法，使用AIエージェント分析应用评论数据，提高应用程序的用户体验","ja":"アプリストアレビューデータを分析するApp Review Analyzerの設定方法と機能を紹介します。AIエージェントを使用してレビューデータを分析し、アプリのユーザーエクスペリエンスを向上させます","ko":"애플리케이션 리뷰 분석기의 기능과 설정 방법을 알아보세요. AI Tools를 사용하여 애플리케이션 리뷰 데이터를 분석하고 애플리케이션의 사용자 경험을 향상시키세요","es":"Aprende a analizar datos de reseñas de aplicaciones en formato CSV y visualizarlos en gráficos con el analizador de reseñas de aplicaciones","fr":"Découvrez comment analyser les données de critiques d''applications au format CSV et les visualiser en graphiques avec l''outil d''analyse de critiques d''applic...","de":"Erfahren Sie, wie Sie Bewertungsdaten im CSV-Format analysieren und in Grafiken visualisieren können, mit dem App-Bewertungsanalyse-Tool","pt":"Aprenda a configurar o App Review Analyzer para análise de dados de avaliações de aplicativos e visualize tendências em gráficos","ru":"Узнайте, как настроить ИИ Агент App Review Analyzer для анализа данных отзывов приложений и визуализации тенденций","ar":"تعرف على كيفية إعداد Analyzer لتقارير التطبيقات لتحليل البيانات وتصور الاتجاهات في الرسومات"},"definition":{"en":"app-review-analyzer is a skill that analyzes and visualizes app store review CSV data, offering insights into review distributions, trends, and ratings.","zh":"应用评论分析器是一种AIエージェント工具，用于分析应用评论数据","ja":"App Review Analyzerは、アプリストアレビューデータを分析するAIエージェントの一種です","ko":"애플리케이션 리뷰 분석기는 애플리케이션 리뷰 데이터를 분석하는 AI Toolsの一種입니다","es":"El analizador de reseñas de aplicaciones es una herramienta que analiza y visualiza datos de reseñas de aplicaciones","fr":"L''outil d''analyse de critiques d''applications est un outil qui analyse et visualise les données de critiques d''applications","de":"Das App-Bewertungsanalyse-Tool ist ein Tool, das Bewertungsdaten von Apps analysiert und visualisiert","pt":"O que é App Review Analyzer? É uma ferramenta de análise de dados de avaliações de aplicativos","ru":"Что такое ИИ Агент App Review Analyzer? Это инструмент анализа данных отзывов приложений","ar":"ما هو Analyzer لتقارير التطبيقات؟ هو أداة تحليل بيانات تقارير التطبيقات"},"features":{"en":["Analyzes CSV data with required columns: id, date, user_name, and title","Visualizes review distributions for better understanding of user feedback","Provides time-based trend analysis to identify patterns in reviews","Supports version-based rating analysis for comparing app updates","Extracts major keywords from review titles for enhanced insight"],"zh":["支持CSV数据格式","评分分布分析","时间别趋势分析","版本别评分分析","主要关键词分析"],"ja":["CSVデータ形式をサポート","評点分布分析","時間別トレンド分析","バージョン別評点分析","主要キーワード分析"],"ko":["CSV 데이터 형식 지원","评分 분포 분석","시간별 트렌드 분석","버전별 평가 분석","주요 키워드 분석"],"es":["Análisis de distribución de puntuaciones","Visualización de tendencias en función del tiempo","Análisis de puntuaciones por versión","Extracción de palabras clave importantes","Compatibilidad con datos CSV","Visualización de datos en gráficos"],"fr":["Analyse de la distribution des notes","Visualisation des tendances en fonction du temps","Analyse des notes par version","Extraction des mots-clés importants","Compatibilité avec les données CSV","Visualisation des données en graphiques"],"de":["Analyse der Bewertungsverteilung","Visualisierung von Trends über die Zeit","Analyse der Bewertungen nach Version","Extraktion wichtiger Schlüsselwörter","Kompatibilität mit CSV-Daten","Visualisierung von Daten in Grafiken"],"pt":["Análise de distribuição de avaliações","Análise de tendências por data e hora","Análise de avaliações por versão do aplicativo","Geração de gráficos para visualizar tendências","Suporte a dados CSV","Análise de palavras-chave principais"],"ru":["Анализ распределения оценок","Анализ тенденций по дате и времени","Анализ оценок по версии приложения","Генерация графиков для визуализации тенденций","Поддержка данных CSV","Анализ основных ключевых слов"],"ar":["تحليل توزيع التقييمات","تحليل الاتجاهات بالتاريخ والوقت","تحليل التقييمات حسب إصدار التطبيق","توليد الرسومات لتصور الاتجاهات","دعم بيانات CSV","تحليل الكلمات الرئيسية"]},"keywords":{"en":["how to use app-review-analyzer","app-review-analyzer setup guide","app-review-analyzer alternative","app-review-analyzer vs review tracker","app-review-analyzer install","what is app-review-analyzer","app-review-analyzer CSV analysis","app-review-analyzer for AI agents","app-review-analyzer tutorial"],"zh":["应用评论分析器","AIエージェント","应用评论数据分析","CSV数据格式","评分分布分析","时间别趋势分析","版本别评分分析"],"ja":["App Review Analyzer","AIエージェント","アプリストアレビューデータ分析","CSVデータ形式","評点分布分析","時間別トレンド分析","バージョン別評点分析"],"ko":["애플리케이션 리뷰 분석기","AI Tools","애플리케이션 리뷰 데이터 분석","CSV 데이터 형식","评分 분포 분석","시간별 트렌드 분석","버전별 평가 분석"],"es":["analizador de reseñas de aplicaciones","herramienta de análisis de reseñas","análisis de datos de reseñas","visualización de datos en gráficos","CSV","reseñas de aplicaciones","evaluación de aplicaciones","análisis de tendencias","palabras clave importantes"],"fr":["outil d''analyse de critiques d''applications","analyse de données de critiques","visualisation de données en graphiques","CSV","critiques d''applications","évaluation d''applications","analyse de tendances","mots-clés importants","outil de développement"],"de":["App-Bewertungsanalyse-Tool","Bewertungsdatenanalyse","Datenvisualisierung in Grafiken","CSV","App-Bewertungen","App-Evaluierung","Trendanalyse","wichtige Schlüsselwörter","Entwicklungstool","AI-Tool","Künstliche Intelligenz"],"pt":["App Review Analyzer","análise de dados de avaliações","visualização de tendências","gráficos de avaliações","dados CSV","palavras-chave principais","otimização de aplicativos","análise de desempenho de aplicativos"],"ru":["ИИ Агент App Review Analyzer","анализ данных отзывов","визуализация тенденций","графики оценок","данные CSV","основные ключевые слова","оптимизация приложений","анализ производительности приложений"],"ar":["Analyzer لتقارير التطبيقات","تحليل بيانات تقارير التطبيقات","تصور الاتجاهات","رسومات تقييمات","بيانات CSV","الكلمات الرئيسية","تحسين أداء التطبيقات","تحليل أداء التطبيقات"]}},"owner":"buddypia","repo":"kaiju-voice","repoPath":"buddypia/kaiju-voice","stars":0,"forks":0,"updatedAt":"2026-02-26T12:06:38Z","topics":[],"category":"community","skillMd":{"name":"app-review-analyzer","description":"アプリストア レビュー CSV データを分析して視覚化するスキル。ユーザーがアプリストア レビュー CSV ファイルを提供するか レビュー 分析を要求する時に使用する。CSV は id, date, user_name, title, content, rating, app_version 列を含まなければならない。","bodyPreview":"# App Review Analyzer\n\n## Overview\n\nアプリストア レビュー CSV データを分析してグラフで視覚化するスキル。評点 分布、時間別 トレンド、バージョン別 評点、主要 キーワード 等を分析する。\n\n## CSV データ 形式\n\n分析 対象 CSV は 次の 列を含まなければならない:\n\n| 列          | タイプ        | 説明                          |\n| ----------- | ------------- | ----------------------------- |\n| id          | integer       | レビュー 固有 ID              |\n| date        | datetime      | 作成 日時 (タイムゾーン 含む) |\n| user_name   | string        | ユーザー名                    |\n| title       | string        | レビュー タイトル","body":"# App Review Analyzer\n\n## Overview\n\nアプリストア レビュー CSV データを分析してグラフで視覚化するスキル。評点 分布、時間別 トレンド、バージョン別 評点、主要 キーワード 等を分析する。\n\n## CSV データ 形式\n\n分析 対象 CSV は 次の 列を含まなければならない:\n\n| 列          | タイプ        | 説明                          |\n| ----------- | ------------- | ----------------------------- |\n| id          | integer       | レビュー 固有 ID              |\n| date        | datetime      | 作成 日時 (タイムゾーン 含む) |\n| user_name   | string        | ユーザー名                    |\n| title       | string        | レビュー タイトル             |\n| content     | string        | レビュー 内容                 |\n| rating      | integer (1-5) | 評点                          |\n| app_version | string        | アプリ バージョン             |\n\n## 分析 ワークフロー\n\n### Step 1: CSV ファイル ロード および 検証\n\n1. ユーザーが 提供した CSV ファイル パス 確認\n2. `scripts/analyze_reviews.py` スクリプト 実行\n3. データ 形式 検証 および 基本 統計 出力\n\n### Step 2: 分析 実行\n\nスクリプトを 実行して 次の 分析を 実行する:\n\n```bash\npython3 /path/to/skill/scripts/analyze_reviews.py <csv_path> <output_dir>\n```\n\n### Step 3: 結果 解釈\n\n生成された グラフと 統計を 元に インサイトを 提供する:\n\n- **評点 分布**: 全般的な ユーザー 満足度 把握\n- **時間別 トレンド**: アプリ 品質 変化 推移\n- **バージョン別 評点**: 特定 バージョンの 問題点 識別\n- **否定 レビュー 分析**: 主要 不満 事項 把握\n\n## 分析 項目\n\n### 1. 基本 統計\n\n- 総 レビュー 数\n- 平均 評点\n- 評点別 分布\n\n### 2. 視覚化 グラフ\n\n- 評点 分布 棒 グラフ\n- 月別/週別 レビュー トレンド\n- バージョン別 平均 評点\n- 評点別 レビュー 数 パイ チャート\n\n### 3. テキスト 分析\n\n- 否定 レビュー (1-2点) 主要 キーワード\n- 肯定 レビュー (4-5点) 主要 キーワード\n\n## Resources\n\n### scripts/\n\n`analyze_reviews.py` - レビュー 分析 および 視覚化 スクリプト\n\n使用法:\n\n```bash\npython3 scripts/analyze_reviews.py <csv_path> [output_dir]\n```\n\n- `csv_path`: 分析する CSV ファイル パス\n- `output_dir`: グラフ 保存 ディレクトリ (デフォルト値: CSV ファイルと 同じ ディレクトリ)\n\n出力 ファイル:\n\n- `rating_distribution.png`: 評点 分布 グラフ\n- `monthly_trend.png`: 月別 レビュー トレンド\n- `version_rating.png`: バージョン別 平均 評点\n- `analysis_report.txt`: 分析 要約 レポート\n"},"lastSynced":"2026-03-07T03:51:08.326Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing advanced CSV data visualization capabilities for app store reviews.","zh":"非常适合需要高级 CSV 数据可视化功能的数据分析代理，特别是用于应用商店评论。","ja":"データ分析エージェントがアプリストアレビューの高度なCSVデータ可視化機能を必要とする場合に最適です。","ko":"데이터 분석 에이전트가 앱 스토어 리뷰에 대한 고급 CSV 데이터 시각화 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para agentes de análisis de datos que necesitan capacidades avanzadas de visualización de datos CSV para reseñas de tiendas de aplicaciones.","fr":"Parfait pour les agents d''analyse de données nécessitant des capacités de visualisation de données CSV avancées pour les avis de magasin d''applications.","de":"Perfekt für Data-Analytics-Agents, die erweiterte CSV-Datenvisualisierungsfunktionen für App-Store-Bewertungen benötigen.","pt":"Perfeito para Agentes de Análise de Dados que precisam de capacidades avançadas de visualização de dados CSV para análise de revisões da loja de aplicativos.","ru":"Идеально для агентов анализа данных, которым необходимы расширенные возможности визуализации данных CSV для анализа обзоров магазина приложений.","ar":"مثالي للوكلاء الذين يحتاجون إلى قدرات متقدمة لتصور بيانات CSV لتحليل التعليقات في متجر التطبيقات."},"recommendation":{"en":"Empowers agents to analyze app store review CSV data, providing insightful visualizations of review distributions, time-based trends, and version-based ratings using datetime and integer data types.","zh":"赋予代理分析应用商店评论的 CSV 数据的能力，提供有关评论分布、基于时间的趋势和基于版本的评分的深入可视化，使用 datetime 和 integer 数据类型。","ja":"エージェントにアプリストアレビューのCSVデータを分析する機能を提供し、datetimeとintegerデータ型を使用してレビューディストリビューション、時間ベースのトレンド、バージョンベースの評価の洞察fulな視覚化を提供します。","ko":"에이전트가 앱 스토어 리뷰의 CSV 데이터를 분석하여 리뷰 배포, 시간 기반 트렌드 및 버전 기반 평가에 대한 시각화를 제공하는 기능을 부여합니다. datetime 및 정수 데이터 유형을 사용합니다.","es":"Habilita a los agentes a analizar datos de reseñas de la tienda de aplicaciones CSV, proporcionando visualizaciones reveladoras de distribuciones de reseñas, tendencias basadas en el tiempo y calificaciones basadas en la versión utilizando tipos de datos datetime e integer.","fr":"Permet aux agents d''analyser les données d''avis de magasin d''applications CSV, fournissant des visualisations révélatrices de distributions d''avis, de tendances basées sur le temps et de notes basées sur la version en utilisant les types de données datetime et integer.","de":"Ermächtigt Agents, App-Store-Bewertungs-CSV-Daten zu analysieren und aussagekräftige Visualisierungen von Bewertungsverteilungen, zeitbasierten Trends und versionsbasierten Bewertungen unter Verwendung von datetime- und Integer-Datentypen bereitzustellen.","pt":"Habilita os agentes a analisar dados de revisão da loja de aplicativos em CSV, fornecendo visualizações instrutivas das distribuições de revisões, tendências baseadas no tempo e avaliações baseadas na versão usando tipos de dados datetime e integer.","ru":"Наделяет агентов возможностью анализировать данные обзоров магазина приложений в формате CSV, обеспечивая информативные визуализации распределения обзоров, тенденций во времени и оценок на основе версии с использованием типов данных datetime и integer.","ar":"يمنح الوكلاء القدرة على تحليل بيانات التعليقات من متجر التطبيقات في صيغة CSV ، مما يوفر تصورات مفيدة لتوزيع التعليقات والتوجهات الزمنية والتقييمات المعتمدة على الإصدار باستخدام أنواع بيانات datetime وinteger."},"useCases":{"en":["Analyzing review trends over time","Generating visualizations of version-based ratings","Identifying key keywords in user reviews"],"zh":["随时间分析评论趋势","生成基于版本的评分可视化","在用户评论中确定关键字"],"ja":["時間軸に沿ったレビュートレンドを分析する","バージョンベースの評価の視覚化を生成する","ユーザーレビューに含まれるキーワードを特定する"],"ko":["시간에 따른 리뷰 트렌드 분석","버전 기반 평가의 시각화를 생성","사용자 리뷰에서 키워드를 식별"],"es":["Análisis de tendencias de reseñas en el tiempo","Generación de visualizaciones de calificaciones basadas en la versión","Identificación de palabras clave clave en reseñas de usuarios"],"fr":["Analyse des tendances d''avis au fil du temps","Génération de visualisations de notes basées sur la version","Identification des mots clés clés dans les avis des utilisateurs"],"de":["Analyse von Bewertungstrends im Laufe der Zeit","Generierung von Visualisierungen von versionsbasierten Bewertungen","Identifizierung von Schlüsselwörtern in Benutzerbewertungen"],"pt":["Analisar tendências de revisões ao longo do tempo","Gerar visualizações de avaliações baseadas na versão","Identificar palavras-chave importantes nas revisões dos usuários"],"ru":["Анализ тенденций обзоров во времени","Генерация визуализаций оценок на основе версии","Определение ключевых слов в обзорах пользователей"],"ar":["تحليل اتجاهات التعليقات بمرور الوقت","генерация تصورات لتقييمات الإصدار","تحديد الكلمات الرئيسية في تعليقات المستخدمين"]},"limitations":{"en":["Requires CSV data with specific columns (id, date, user_name, title)","Limited to app store review data analysis"],"zh":["需要具有特定列（id、日期、用户名、标题）的 CSV 数据","仅限应用商店评论数据分析"],"ja":["特定の列（ID、日付、ユーザー名、タイトル）を持つCSVデータが必要","アプリストアレビューデータ分析のみに限定"],"ko":["특정 열（id, 날짜, 사용자 이름, 제목）을 가진 CSV 데이터가 필요","앱 스토어 리뷰 데이터 분석에만 محدود"],"es":["Requiere datos CSV con columnas específicas (id, fecha, nombre de usuario, título)","Limitado al análisis de datos de reseñas de la tienda de aplicaciones"],"fr":["Nécessite des données CSV avec des colonnes spécifiques (id, date, nom d''utilisateur, titre)","Limité à l''analyse des données d''avis de magasin d''applications"],"de":["Benötigt CSV-Daten mit bestimmten Spalten (ID, Datum, Benutzername, Titel)","Begrenzt auf die Analyse von App-Store-Bewertungsdaten"],"pt":["Requer dados CSV com colunas específicas (id, data, nome_do_usuário, título)","Limitado à análise de dados de revisão da loja de aplicativos"],"ru":["Требует данных CSV с определенными столбцами (id, дата, имя_пользователя, заголовок)","Ограничен анализом данных обзоров магазина приложений"],"ar":["يتطلب بيانات CSV مع أعمدة محددة (id، date، user_name، title)","محدود بالتحليل البياني لبيانات التعليقات في متجر التطبيقات"]},"version":4},"contentHash":"d18a052492e0dd01d5365415fce4543f6022963518ef18a581cfc20b5bc9b688","qualityScore":33}');
