INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MixxMasterMike123/auctionet-extension/auction-catalog', 'auction-catalog', 'MixxMasterMike123', 'auctionet-extension', 'community', 'auction-catalog MixxMasterMike123 auctionet-extension community The auction-catalog skill assists developers in applying correct cataloging conventions for quality rules, AI prompts, and validation logic. It benefits developers working with the Auctionet AI Cataloging Assistant Chrome Extension. Auction Catalog skill提供了标题格式规则和分类说明，帮助开发者优化AI Cataloging Assistant Chrome扩展 Auction Catalogスキルは、タイトル形式のルールやカテゴリの説明を提供し、開発者がAIエージェントカタログアシスタントChrome拡張を最適化できるようにします 경매 카탈로그 스킬은 제목 형식 규칙 및 분류 설명을 제공하여 개발자가 AI 카탈로그 조력자 Chrome 확장을 최적화할 수 있도록 합니다 Auction Catalog es una extensión de Chrome que utiliza agentes de AI para aplicar convenciones de catalogación correctas L''Auction Catalog est une extension Chrome qui utilise des outils d''IA pour appliquer des conventions de catalogage correctes Auction Catalog ist eine Chrome-Erweiterung, die KI-Tools verwendet, um korrekte Katalogisierungskonventionen anzuwenden O Assistente de Catalogação de Leilão é uma extensão do Chrome que ajuda a catalogar itens de leilão de forma eficiente ИИ Агент для каталогизации аукциона - это расширение Chrome, которое помогает эффективно каталогизировать лоты مساعد فهرسة المزاد هو ملحق للكروم يساعد في فهرسة عناصر المزاد بفعالية how to use auction-catalog auction-catalog setup guide auction-catalog alternative auction-catalog vs cataloging tools auction-catalog install what is auction-catalog auction-catalog for developers auction-catalog chrome extension auction cataloging best practices Auction Catalog AI Cataloging Assistant Chrome扩展 标题格式规则 分类说明 Furniture Möbler AIエージェント cataloging Applies title formatting rules for categories like Furniture (Möbler) Excludes wood type from titles and includes style, period, and designer information Supports argument-based focus on specific categories or topics using $ARGUMENTS Provides cataloging conventions for modifying quality rules and AI prompts Enhances validation logic in the Auctionet AI Cataloging Assistant Chrome Extension auction-catalog is a skill that provides reference for cataloging conventions, including title formatting rules for categories like furniture, to ensure accurate and consistent cataloging.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sabaronnie/AI-Driven-Cronut-CEO-Agent/conut-location', 'community', 'sabaronnie', 'AI-Driven-Cronut-CEO-Agent', 'sabaronnie/AI-Driven-Cronut-CEO-Agent', 'conut-location', 0, 0, 33, '2026-02-28T18:55:54Z', '2026-03-07T03:56:07.051Z', '6059b6bffcf0a403a6fbe3421f8fba7e2d2a3a01843f854249d6c4c7ef15ea66', '{"id":"sabaronnie/AI-Driven-Cronut-CEO-Agent/conut-location","name":"conut-location","description":{"en":"The conut-location skill provides AI agents with a Python ML module to recommend optimal branch locations. It benefits business operations by providing data-driven location suggestions.","zh":"Conut位置推荐技能使用Python ML模块，提供精确的分支位置推荐。通过运行Python脚本，实现特定地区或人口以上的位置推荐","ja":"コナット ロケーションレコメンダー スキルは、Python MLモジュールを使用して、正確な支店ロケーションの推薦を提供します。スクリプトを実行して、特定の地域または人口以上のロケーションの推薦を実現します","ko":"conut 위치 추천 스킬은 Python ML 모듈을 사용하여 정확한 지점 위치 추천을 제공합니다. Python 脚本을 실행하여 특정 지역 또는 인구 이상의 위치 추천을 실현합니다","es":"Conut Location es un skill que proporciona recomendaciones de ubicación de sucursales utilizando Python y CLI.","fr":"Conut Location est un skill qui fournit des recommandations d''emplacement de succursales en utilisant Python et CLI.","de":"Conut Location ist ein Skill, der Empfehlungen zur Filialenverortung mit Python und CLI bereitstellt.","pt":"O Conut-Location é uma habilidade que fornece recomendações de localização de filiais com Python. Execute o módulo ML para obter decisões informadas.","ru":"Conut-Location - это навык, который предоставляет рекомендации по расположению филиалов с помощью Python. Выполняйте модуль ML, чтобы принимать обоснованные решения.","ar":"Conut-Location هو مهارة يوفر توصيات الموقع الفرعي باستخدام Python. تشغيل وحدة ML للحصول على قرارات مستنيرة."},"seo":{"title":{"en":"Conut-Location: Branch Location Recommender Setup Guide |...","zh":"Conut 位置推荐设置指南 - 使用Python ML模块","ja":"コナット ロケーションレコメンダー スキル - AIエージェントの設定方法","ko":"conut 위치 추천 스킬 설정 가이드 - Python ML 모듈 사용","es":"Conut Location: Guía de Configuración para Agentes de Int...","fr":"Conut Location : Guide d''Installation pour les Outils d''I...","de":"Conut Location: Einrichtungsleitfaden für KI-Agents","pt":"Guia de Configuração do Conut-Location: Recomendação de L...","ru":"Установка и Настройка Conut-Location: Рекомендации по Рас...","ar":"دليل إعداد Conut-Location: توصيات الموقع الفرعي باستخدام ..."},"description":{"en":"Discover how to use conut-location to get data-driven branch location recommendations. Run the Python ML module with ease and optimize your business decisions.","zh":"了解Conut位置推荐技能的设置方法和最佳实践，使用Python ML模块实现精确的分支位置推荐","ja":"コナット ロケーションレコメンダー スキルの設定方法とベストプラクティスを紹介。Python MLモジュールを使用して、正確な支店ロケーションの推薦を実現します","ko":"conut 위치 추천 스킬의 설정 방법과最佳实践을 알아보세요. Python ML 모듈을 사용하여 정확한 지점 위치 추천을 실현합니다","es":"Aprende a configurar Conut Location para obtener recomendaciones de ubicación de sucursales con Python y CLI","fr":"Découvrez comment configurer Conut Location pour obtenir des recommandations d''emplacement de succursales avec Python et CLI","de":"Erfahren Sie, wie Sie Conut Location für Empfehlungen zur Filialenverortung mit Python und CLI einrichten","pt":"Aprenda a configurar o Conut-Location para obter recomendações de localização de filiais com Python. Descubra como executar o módulo ML para tomar decisões i...","ru":"Узнайте, как настроить Conut-Location, чтобы получить рекомендации по расположению филиалов с помощью Python. Ознакомьтесь с выполнением модуля ML для принят...","ar":"تعلم كيفية إعداد Conut-Location للحصول على توصيات الموقع الفرعي باستخدام Python. اكتشف كيفية تشغيل وحدة ML لاتخاذ قرارات مستنيرة."},"definition":{"en":"conut-location is a skill that utilizes a Python ML module to recommend branch locations based on specific parameters such as governorate and population.","zh":"Conut位置推荐技能是一种使用Python ML模块的AI工具，提供精确的分支位置推荐","ja":"コナット ロケーションレコメンダー スキルは、Python MLモジュールを使用するAIエージェントであり、正確な支店ロケーションの推薦を提供します","ko":"conut 위치 추천 스킬은 Python ML 모듈을 사용하는 AI 도구로서 정확한 지점 위치 추천을 제공합니다","es":"Conut Location es un agente de inteligencia artificial que recomienda ubicaciones de sucursales","fr":"Conut Location est un outil d''intelligence artificielle qui recommande des emplacements de succursales","de":"Conut Location ist ein KI-Agent, der Empfehlungen zur Filialenverortung gibt","pt":"O Conut-Location é uma habilidade de IA que fornece recomendações de localização de filiais com base em dados e algoritmos de aprendizado de máquina.","ru":"Conut-Location - это навык ИИ, который предоставляет рекомендации по расположению филиалов на основе данных и алгоритмов машинного обучения.","ar":"Conut-Location هو مهارة ذكاء اصطناعي يوفر توصيات الموقع الفرعي بناءً على البيانات وخوارزميات التعلم الآلي."},"features":{"en":["Runs the Python ML module via the `python3 scripts/run_tool.py` command","Supports location recommendations for specific governorates using JSON input","Filters areas based on minimum population requirements","Utilizes the `get_branch_location_recommendation` function for customized results","Executes commands in a bash environment for seamless integration"],"zh":["使用Python ML模块实现精确的分支位置推荐","支持特定地区的位置推荐","支持人口以上的位置推荐","通过运行Python脚本实现位置推荐","使用CLI命令行工具运行Python脚本"],"ja":["Python MLモジュールを使用して、正確な支店ロケーションの推薦を実現","特定の地域のロケーションの推薦をサポート","人口以上のロケーションの推薦をサポート","スクリプトを実行して、ロケーションの推薦を実現","CLIコマンドラインツールを使用して、Pythonスクリプトを実行"],"ko":["Python ML 모듈을 사용하여 정확한 지점 위치 추천을 실현","특정 지역의 위치 추천을 지원","인구 이상의 위치 추천을 지원","Python 脚本을 실행하여 위치 추천을 실현","CLI 명령줄 도구를 사용하여 Python 脚本을 실행"],"es":["Utiliza Python para proporcionar recomendaciones de ubicación","Soporta CLI para una ejecución fácil","Permite especificar un governadorado para las recomendaciones","Filtrado por población mínima","Ejecución de scripts personalizados con Python","Integración con herramientas de desarrollo"],"fr":["Utilise Python pour fournir des recommandations d''emplacement","Prend en charge CLI pour une exécution facile","Permet de spécifier un gouvernorat pour les recommandations","Filtrage par population minimale","Exécution de scripts personnalisés avec Python","Intégration avec des outils de développement"],"de":["Verwendet Python, um Empfehlungen zur Filialenverortung zu geben","Unterstützt CLI für eine einfache Ausführung","Ermöglicht die Angabe eines Gouvernorats für die Empfehlungen","Filterung nach Mindestbevölkerung","Ausführung von benutzerdefinierten Skripten mit Python","Integration mit Entwicklungstools"],"pt":["Execução do módulo ML com Python","Recomendações de localização de filiais personalizadas","Suporte a governadorias específicas","Filtragem de áreas por população mínima","Integração com CLI para execução fácil","Utilização de scripts Python para automação"],"ru":["Выполнение модуля ML с помощью Python","Персонализированные рекомендации по расположению филиалов","Поддержка конкретных губернаторств","Фильтрация областей по минимальному населению","Интеграция с CLI для легкого выполнения","Использование скриптов Python для автоматизации"],"ar":["تشغيل وحدة ML باستخدام Python","توصيات الموقع الفرعي المخصصة","دعم المحافظات المحددة","تصفية المناطق حسب السكان الأقل","التكامل مع CLI لتشغيل سهل","استخدام البرامج النصية Python للتحكم الآلي"]},"keywords":{"en":["how to use conut-location","conut-location setup guide","what is conut-location","conut-location alternative","conut-location vs other location recommenders","install conut-location","python ml module for location recommendation","branch location optimization","governorate-based location suggestions"],"zh":["Conut位置推荐","Python ML模块","AI工具","分支位置推荐","特定地区位置推荐","人口以上位置推荐","Python脚本","CLI命令行工具"],"ja":["コナット ロケーションレコメンダー","Python MLモジュール","AIエージェント","支店ロケーションの推薦","特定の地域のロケーションの推薦","人口以上のロケーションの推薦","Pythonスクリプト","CLIコマンドラインツール"],"ko":["conut 위치 추천","Python ML 모듈","AI 도구","지점 위치 추천","특정 지역 위치 추천","인구 이상 위치 추천","Python 脚本","CLI 명령줄 도구"],"es":["Conut Location","agentes de inteligencia artificial","recomendaciones de ubicación","Python","CLI","governadorado","población mínima","desarrollo de software","herramientas de desarrollo"],"fr":["Conut Location","outils d''intelligence artificielle","recommandations d''emplacement","Python","CLI","gouvernorat","population minimale","développement de logiciels","outils de développement"],"de":["Conut Location","KI-Agents","Empfehlungen zur Filialenverortung","Python","CLI","Gouvernorat","Mindestbevölkerung","Software-Entwicklung","Entwicklungstools"],"pt":["Conut-Location","recomendação de localização de filiais","Python para IA","módulo ML","governadorias","população mínima","CLI","scripts Python","automatização"],"ru":["Conut-Location","рекомендации по расположению филиалов","Python для ИИ","модуль ML","губернаторства","минимальное население","CLI","скрипты Python","автоматизация"],"ar":["Conut-Location","توصيات الموقع الفرعي","Python للذكاء الاصطناعي","وحدة ML","المحافظات","السكان الأقل","CLI","البرامج النصية Python","التحكم الآلي"]}},"owner":"sabaronnie","repo":"AI-Driven-Cronut-CEO-Agent","repoPath":"sabaronnie/AI-Driven-Cronut-CEO-Agent","stars":0,"forks":0,"updatedAt":"2026-02-28T18:55:54Z","topics":[],"category":"community","skillMd":{"name":"conut-location","description":"Recommends where in Lebanon Conut should open a new branch using Ridge Regression and market gap analysis across 24 areas. Use when asked about where to open, best location, market gap, underserved areas, competitor density, location recommendation, or which Lebanese area to expand into.","bodyPreview":"# Conut Branch Location Recommender Skill\n\nYou are the Conut Chief of Operations AI agent. When asked about where to open a new branch or location recommendations, you MUST run the Python ML module — never guess from general knowledge.\n\n## How to run\n\n```bash\npython3 scripts/run_tool.py get_branch_location_recommendation\n```\n\nFor a specific governorate:\n\n```bash\npython3 scripts/run_tool.py get_branch_location_recommendation ''{\"governorate\": \"Beirut\"}''\n```\n\nFor areas above a minimum population:","body":"# Conut Branch Location Recommender Skill\n\nYou are the Conut Chief of Operations AI agent. When asked about where to open a new branch or location recommendations, you MUST run the Python ML module — never guess from general knowledge.\n\n## How to run\n\n```bash\npython3 scripts/run_tool.py get_branch_location_recommendation\n```\n\nFor a specific governorate:\n\n```bash\npython3 scripts/run_tool.py get_branch_location_recommendation ''{\"governorate\": \"Beirut\"}''\n```\n\nFor areas above a minimum population:\n\n```bash\npython3 scripts/run_tool.py get_branch_location_recommendation ''{\"min_population\": 50000}''\n```\n\nCustom number of results:\n\n```bash\npython3 scripts/run_tool.py get_branch_location_recommendation ''{\"top_n\": 10}''\n```\n\n## Available parameters\n\n- `top_n` (integer): Number of top locations to return (default: 5).\n- `governorate` (string): Filter by governorate. Examples: \"Beirut\", \"Mount Lebanon\", \"North Lebanon\". Omit for all.\n- `min_population` (integer): Minimum population threshold. Omit for all areas.\n\n## How to interpret and present results\n\nThe script uses **Polynomial Ridge Regression** (degree 2) trained on 24 Lebanese areas to predict expected competitor count from population, social activity, traffic, university presence, and tourism. It then compares expected vs actual competitors to find market gaps.\n\nData sources:\n- Curated dataset of 24 Lebanese areas (CAS 2018-19, World Population Review, Yelleb, BAM Lebanon, TripAdvisor)\n- Population, social activity index, traffic index, coffee shops, sweet/bakery shops, university presence, tourism score, rent index\n\nKey fields per recommendation:\n- **area / governorate**: Location name and region\n- **final_score**: Overall opportunity score (0-100), higher is better\n- **market_gap**: Expected competitors minus actual — positive = underserved\n- **demand_proxy**: Weighted demand score from population, social activity, traffic, universities, tourism\n- **population**: Area population\n- **total_competitors**: Actual coffee + sweet/bakery shops in the area\n\nFinal score weights:\n- Gap score (40%), Demand score (25%), Affordability (15%), Growth potential (20%)\n\nExcluded locations: Tyre, Jnah (Beirut), and Batroun (existing Conut branches).\n\nWhen presenting results:\n1. Lead with the top recommended locations and their scores\n2. Explain why each location ranks high (gap, demand, affordability)\n3. Mention model accuracy (R², MAE)\n4. Highlight areas to avoid (oversaturated, negative gaps)\n5. Note that existing branch locations are excluded from recommendations\n"},"lastSynced":"2026-03-07T03:56:07.051Z","agentAnalysis":{"suitability":{"en":"Perfect for Location-Based AI Agents needing data-driven branch location recommendations via Python ML modules.","zh":"适合需要通过Python ML模块进行数据驱动的分支位置推荐的基于位置的AI代理。","ja":"Python MLモジュールを使用したデータドリブンの支店ロケーション推奨が必要なロケーションベースのAIエージェントに最適です。","ko":"Python ML 모듈을 사용하여 데이터 주도형 지사 위치 추천이 필요한 위치 기반 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de Inteligencia Artificial basados en ubicación que necesitan recomendaciones de ubicación de sucursales basadas en datos a través de módulos de Python ML.","fr":"Parfait pour les agents d''intelligence artificielle basés sur l''emplacement nécessitant des recommandations d''emplacement de succursale basées sur les données via des modules Python ML.","de":"Perfekt für standortbasierte KI-Agents, die datengetriebene Empfehlungen für die Standortverteilung von Filialen über Python-ML-Module benötigen.","pt":"Perfeito para Agentes de IA baseados em localização que precisam de recomendações de localização de filiais baseadas em dados via módulos de ML do Python.","ru":"Идеально подходит для агентов ИИ, основанных на местоположении, которым необходимы рекомендации по местоположению филиалов на основе данных через модули ML Python.","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يعتمدون على الموقع وهم بحاجة إلى توصيات الموقع الفرعي القائم على البيانات من خلال وحدات ML Python."},"recommendation":{"en":"Empowers agents to provide optimal branch location suggestions using Python''s machine learning capabilities, supporting specific governorate recommendations and population-based filtering through JSON input parameters.","zh":"赋予代理提供最优分支位置建议的能力，利用Python的机器学习能力，支持特定省份的推荐和通过JSON输入参数的人口基于过滤。","ja":"Pythonの機械学習機能を利用して、特定の県の推奨やJSON入力パラメータによる人口ベースのフィルタリングをサポートし、最適な支店ロケーションの提案をエージェントに提供する能力を付与します。","ko":"Python의 기계 학습 기능을 활용하여 특정 도의 추천 및 JSON 입력 매개 변수를 통해 인구 기반 필터링을 지원하며, 에이전트가 최적의 지사 위치를 제안할 수 있는 능력을 부여합니다.","es":"Permite a los agentes proporcionar sugerencias óptimas de ubicación de sucursales utilizando las capacidades de aprendizaje automático de Python, que admiten recomendaciones de gobernación específicas y filtrado basado en población a través de parámetros de entrada JSON.","fr":"Permet aux agents de fournir des suggestions d''emplacement de succursale optimales en utilisant les capacités d''apprentissage automatique de Python, qui prennent en charge des recommandations de gouvernorat spécifiques et un filtrage basé sur la population via des paramètres d''entrée JSON.","de":"Ermöglicht es den Agents, optimale Empfehlungen für die Standortverteilung von Filialen zu liefern, indem sie die maschinellen Lernfähigkeiten von Python nutzen, die spezifische Gouverneurs-Empfehlungen und filtern basierend auf der Bevölkerung durch JSON-Eingabeparameter unterstützen.","pt":"Habilita os agentes a fornecer sugestões de localização de filiais ótimas usando as capacidades de aprendizado de máquina do Python, suportando recomendações de governadoria específicas e filtragem baseada em população por meio de parâmetros de entrada JSON.","ru":"Наделяет агентов возможностью предоставлять оптимальные рекомендации по местоположению филиалов, используя возможности машинного обучения Python, поддерживая конкретные рекомендации губернаторства и фильтрацию на основе населения через входные параметры JSON.","ar":"يمكن الوكلاء من تقديم اقتراحات موقع فرعي مثالية باستخدام قدرات التعلم الآلي لبيثون، ودعم توصيات المحافظة النوعية والتنقية القائمة على السكان من خلال 매개̈ترات الإدخال JSON."},"useCases":{"en":["Automating branch location recommendations","Analyzing population density for optimal placement","Filtering locations by governorate"],"zh":["自动化分支位置推荐","分析人口密度以实现最佳放置","通过省份筛选位置"],"ja":["支店ロケーションの推奨を自動化する","人口密度を分析して最適な配置を行う","県別にロケーションをフィルタリングする"],"ko":["지사 위치 추천 자동화","인구 밀도 분석을 통한 최적의 배치","도 별 위치 필터링"],"es":["Automatizar las recomendaciones de ubicación de sucursales","Analizar la densidad de población para una colocación óptima","Filtrar ubicaciones por gobernación"],"fr":["Automatiser les recommandations d''emplacement de succursale","Analyser la densité de population pour un placement optimal","Filtrer les emplacements par gouvernorat"],"de":["Automatisieren der Empfehlungen für die Standortverteilung von Filialen","Analysieren der Bevölkerungsdichte für eine optimale Platzierung","Filtern von Standorten nach Gouverneur"],"pt":["Automatizar recomendações de localização de filiais","Analizar densidade populacional para colocação ótima","Filtrar locais por governadoria"],"ru":["Автоматизировать рекомендации по местоположению филиалов","Анализировать плотность населения для оптимального размещения","Фильтровать местоположения по губернаторству"],"ar":["أتمتة توصيات موقع الفرع","تحليل الكثافة السكانية للوضع المثالي","تصفية المواقع حسب المحافظة"]},"limitations":{"en":["Requires Python 3 environment","Needs specific JSON input format for governorate and population filtering"],"zh":["需要Python 3环境","需要特定的JSON输入格式以进行省份和人口筛选"],"ja":["Python 3環境が必要","県別および人口ベースのフィルタリングを行うために特定のJSON入力形式が必要"],"ko":["Python 3 환경 필요","도 및 인구 기반 필터링을 위해 특정 JSON 입력 형식 필요"],"es":["Requiere entorno Python 3","Necesita formato de entrada JSON específico para el filtrado de gobernación y población"],"fr":["Nécessite un environnement Python 3","A besoin d''un format d''entrée JSON spécifique pour le filtrage du gouvernorat et de la population"],"de":["Benötigt Python 3-Umgebung","Benötigt spezifisches JSON-Eingabeformat für die Filterung von Gouverneur und Bevölkerung"],"pt":["Requer ambiente Python 3","Necessita de formato de entrada JSON específico para filtragem por governadoria e população"],"ru":["Требуется среда Python 3","Необходим конкретный формат входных параметров JSON для фильтрации по губернаторству и населению"],"ar":["يتطلب بيئة بايثون 3","يحتاج إلى تنسيق مدخل JSON محدد لتصفية الحاكم والpopulation"]},"version":4},"contentHash":"6059b6bffcf0a403a6fbe3421f8fba7e2d2a3a01843f854249d6c4c7ef15ea66","qualityScore":33}');
