INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sabaronnie/AI-Driven-Cronut-CEO-Agent/conut-location', 'conut-location', 'sabaronnie', 'AI-Driven-Cronut-CEO-Agent', 'community', 'conut-location sabaronnie AI-Driven-Cronut-CEO-Agent community The conut-location skill provides AI agents with a Python ML module to recommend optimal branch locations. It benefits business operations by providing data-driven location suggestions. Conut位置推荐技能使用Python ML模块，提供精确的分支位置推荐。通过运行Python脚本，实现特定地区或人口以上的位置推荐 コナット ロケーションレコメンダー スキルは、Python MLモジュールを使用して、正確な支店ロケーションの推薦を提供します。スクリプトを実行して、特定の地域または人口以上のロケーションの推薦を実現します conut 위치 추천 스킬은 Python ML 모듈을 사용하여 정확한 지점 위치 추천을 제공합니다. Python 脚本을 실행하여 특정 지역 또는 인구 이상의 위치 추천을 실현합니다 Conut Location es un skill que proporciona recomendaciones de ubicación de sucursales utilizando Python y CLI. Conut Location est un skill qui fournit des recommandations d''emplacement de succursales en utilisant Python et CLI. Conut Location ist ein Skill, der Empfehlungen zur Filialenverortung mit Python und CLI bereitstellt. O Conut-Location é uma habilidade que fornece recomendações de localização de filiais com Python. Execute o módulo ML para obter decisões informadas. Conut-Location - это навык, который предоставляет рекомендации по расположению филиалов с помощью Python. Выполняйте модуль ML, чтобы принимать обоснованные решения. Conut-Location هو مهارة يوفر توصيات الموقع الفرعي باستخدام Python. تشغيل وحدة ML للحصول على قرارات مستنيرة. how to use conut-location conut-location setup guide what is conut-location conut-location alternative conut-location vs other location recommenders install conut-location python ml module for location recommendation branch location optimization governorate-based location suggestions Conut位置推荐 Python ML模块 AI工具 分支位置推荐 特定地区位置推荐 人口以上位置推荐 Python脚本 CLI命令行工具 Runs the Python ML module via the `python3 scripts/run_tool.py` command Supports location recommendations for specific governorates using JSON input Filters areas based on minimum population requirements Utilizes the `get_branch_location_recommendation` function for customized results Executes commands in a bash environment for seamless integration conut-location is a skill that utilizes a Python ML module to recommend branch locations based on specific parameters such as governorate and population.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shuhei-fujita/receipt-organizer/receipt-organizer', 'community', 'shuhei-fujita', 'receipt-organizer', 'shuhei-fujita/receipt-organizer', 'receipt-organizer', 0, 0, 33, '2026-02-28T11:04:01Z', '2026-03-07T03:56:28.351Z', 'b2024f3209c2beccc2d7df51e27c30906efcb5ab07fc229ec4351026e9f9a1b4', '{"id":"shuhei-fujita/receipt-organizer/receipt-organizer","name":"receipt-organizer","description":{"en":"The receipt-organizer skill automates receipt management by renaming and categorizing files in a specified folder, including Gmail receipts. It benefits users by streamlining their receipt organization process.","zh":"receipt-organizer 是一个自动整理领收单的工具，支持 Gmail 邮件导入和自定义分类","ja":"領収書整理スキルは、指定フォルダの領収書ファイルをリネーム・振り分けし、Gmail の領収書メールも取り込む","ko":"영수증 정리 도구는 자동으로 영수증을 분류하고 Gmail 메일을 가져옵니다","es":"Receipt Organizer es una herramienta de AI que organiza tus facturas y emails en carpetas personalizadas utilizando tecnologías de renombramiento y clasificación automática","fr":"Receipt Organizer est un outil d''IA qui organise vos reçus et emails dans des dossiers personnalisés en utilisant des technologies de renommage et de classification automatique","de":"Receipt Organizer ist ein AI-Tool, das Ihre Quittungen und E-Mails in benutzerdefinierten Ordnern organisiert, indem es Technologien zur automatischen Umbenennung und Klassifizierung verwendet","pt":"O Organizador de Recibos é uma ferramenta que ajuda a gerenciar recibos, renomeando e categorizando arquivos em pastas específicas.","ru":"ИИ Агент для организации квитанций - это инструмент, который помогает управлять квитанциями, переименовывая и категоризируя файлы в определенные папки.","ar":"مصفف الإيصالات هو أداة تساعد في إدارة الإيصالات، من خلال إعادة تسمية وتصنيف الملفات في مجلدات محددة."},"seo":{"title":{"en":"receipt-organizer: Automated Receipt Management Setup Gui...","zh":"receipt-organizer 设置指南：自动整理领收单","ja":"領収書整理スキル Setup Guide：フォルダ自動整理","ko":"영수증 정리 도구 설정 가이드: 자동 분류","es":"Guía de configuración de Receipt Organizer - Herramienta ...","fr":"Guide d''installation de Receipt Organizer - Outil d''organ...","de":"Einrichtungsanleitung für Receipt Organizer - Werkzeug zu...","pt":"Guia de Configuração do Organizador de Recibos","ru":"Настройка ИИ Агента для Организации Квитанций","ar":"دليل إعداد مصفف الإيصالات"},"description":{"en":"Discover how receipt-organizer simplifies receipt management. Learn to automate receipt renaming and categorization. Get started with our setup guide today!","zh":"使用 receipt-organizer 自动整理领收单，支持 Gmail 邮件导入和自定义分类","ja":"領収書整理スキルでフォルダを自動整理し、Gmail の領収書メールも取り込む","ko":"영수증 정리 도구를 사용하여 자동 분류하고 Gmail 메일을 가져옵니다","es":"Aprende a configurar Receipt Organizer, una herramienta de AI que organiza tus facturas y emails de forma automática","fr":"Découvrez comment installer Receipt Organizer, un outil d''IA qui organise vos reçus et emails de manière automatique","de":"Erfahren Sie, wie Sie Receipt Organizer einrichten, ein AI-Tool, das Ihre Quittungen und E-Mails automatisch organisiert","pt":"Aprenda a configurar o Organizador de Recibos para gerenciar seus recibos de forma eficiente, com renomeação e categorização automáticas.","ru":"Узнайте, как настроить ИИ Агент для организации квитанций, с автоматическим переименованием и категоризацией.","ar":"تعلم كيفية إعداد مصفف الإيصالات لتنظيم إيصالاتك بفعالية، مع إعادة تسمية وتصنيف آليين."},"definition":{"en":"receipt-organizer is a skill that automates the organization of receipts by renaming and categorizing files based on predefined categories and a custom naming convention.","zh":"receipt-organizer 是一个自动整理领收单的 AI 工具","ja":"領収書整理スキルは、領収書を自動整理する AI エージェント","ko":"영수증 정리 도구는 영수증을 자동으로 분류하는 AI 도구","es":"Receipt Organizer es una herramienta de AI que automatiza la organización de facturas y emails","fr":"Receipt Organizer est un outil d''IA qui automatise l''organisation de reçus et emails","de":"Receipt Organizer ist ein AI-Tool, das die Organisation von Quittungen und E-Mails automatisiert","pt":"O que é um Organizador de Recibos? É uma ferramenta que automatiza a renomeação e categorização de recibos.","ru":"Что такое ИИ Агент для организации квитанций? Это инструмент, который автоматизирует переименование и категоризацию квитанций.","ar":"ما هو مصفف الإيصالات؟ هو أداة ت 자동 إعادة تسمية وتصنيف الإيصالات."},"features":{"en":["Renames receipt files using a custom YYYYMMDD_店名_内容.拡張子 naming convention","Categorizes receipts into predefined folders such as 通信費・ITサービス, 教育・研修, and 交通費・旅費","Imports Gmail receipts for unified management","Allows customization of folder categories and naming rules","Supports various file formats, including PDF"],"zh":["自动整理领收单","支持 Gmail 邮件导入","自定义分类","命名规则：YYYYMMDD_店名_内容.拡張子","支持多种文件格式"],"ja":["フォルダ自動整理","Gmail の領収書メール取り込み","カスタマイズ可能なカテゴリ","命名規則：YYYYMMDD_店名_内容.拡張子","多種類のファイル形式対応"],"ko":["자동 영수증 분류","Gmail 메일 가져오기","사용자 정의 분류","命名 규칙：YYYYMMDD_店名_内容.拡張子","多种 파일 형식 지원"],"es":["Organización automática de facturas y emails en carpetas personalizadas","Renombramiento de archivos utilizando el formato YYYYMMDD_店名_内容.拡張子","Clasificación de facturas en categorías predefinidas como comunicaciones, educación y transporte","Integración con Gmail para la organización de emails de facturas","Personalización de la estructura de carpetas y categorías según las necesidades del usuario"],"fr":["Organisation automatique de reçus et emails dans des dossiers personnalisés","Renommage de fichiers en utilisant le format YYYYMMDD_店名_内容.拡張子","Classification de reçus dans des catégories prédéfinies comme communications, éducation et transport","Intégration avec Gmail pour l''organisation d''emails de reçus","Personnalisation de la structure de dossiers et de catégories selon les besoins de l''utilisateur"],"de":["Automatische Organisation von Quittungen und E-Mails in benutzerdefinierten Ordnern","Umbenennung von Dateien im Format YYYYMMDD_店名_内容.拡張子","Klassifizierung von Quittungen in vordefinierten Kategorien wie Kommunikation, Bildung und Verkehr","Integration mit Gmail für die Organisation von E-Mails mit Quittungen","Anpassung der Ordnerstruktur und Kategorien an die Bedürfnisse des Benutzers"],"pt":["Renomeação automática de arquivos de recibos","Categorização em pastas específicas (ex: comunicações, educação, transporte)","Integração com o Gmail para importar recibos por e-mail","Suporte a arquivos PDF","Nomeação de pastas personalizadas"],"ru":["Автоматическое переименование файлов квитанций","Категоризация в определенные папки (например, связь, образование, транспорт)","Интеграция с Gmail для импорта квитанций по электронной почте","Поддержка файлов PDF","Переименование папок на заказ"],"ar":["إعادة تسمية آلية لملفات الإيصالات","التصنيف في مجلدات محددة (على سبيل المثال، اتصالات، تعليم، نقل)","التكامل مع جيميل لاستيراد الإيصالات عبر البريد الإلكتروني","دعم ملفات PDF","تسمية مجلدات مخصصة"]},"keywords":{"en":["how to use receipt-organizer","receipt-organizer setup guide","automated receipt management","receipt-organizer alternative","receipt organization best practices","gmail receipt integration"],"zh":["receipt-organizer","AI 工具","自动整理领收单","Gmail 邮件导入","自定义分类","命名规则","多种文件格式","领收单管理"],"ja":["領収書整理スキル","AI エージェント","フォルダ自動整理","Gmail の領収書メール取り込み","カスタマイズ可能なカテゴリ","命名規則","多種類のファイル形式","領収書管理"],"ko":["영수증 정리 도구","AI 도구","자동 영수증 분류","Gmail 메일 가져오기","사용자 정의 분류","命名 규칙","多种 파일 형식","영수증 관리"],"es":["herramientas de AI para organización de facturas","organización automática de emails","clasificación de facturas","renombramiento de archivos","integración con Gmail","personalización de carpetas","Receipt Organizer","herramientas de productividad para desarrolladores"],"fr":["outils d''IA pour l''organisation de reçus","organisation automatique d''emails","classification de reçus","renommage de fichiers","intégration avec Gmail","personnalisation de dossiers","Receipt Organizer","outils de productivité pour développeurs"],"de":["AI-Tools für die Organisation von Quittungen","automatische Organisation von E-Mails","Klassifizierung von Quittungen","Umbenennung von Dateien","Integration mit Gmail","Anpassung von Ordnern","Receipt Organizer","Produktivitätstools für Entwickler"],"pt":["organizador de recibos","gerenciamento de recibos","renomeação automática","categorização de arquivos","integração com Gmail","arquivos PDF","pastas personalizadas"],"ru":["ИИ Агент для организации квитанций","управление квитанциями","автоматическое переименование","категоризация файлов","интеграция с Gmail","файлы PDF","папки на заказ"],"ar":["مصفف الإيصالات","إدارة الإيصالات","إعادة تسمية آلية","التصنيف الملفات","التكامل مع جيميل","ملفات PDF","مجلدات مخصصة"]}},"owner":"shuhei-fujita","repo":"receipt-organizer","repoPath":"shuhei-fujita/receipt-organizer","stars":0,"forks":0,"updatedAt":"2026-02-28T11:04:01Z","topics":[],"category":"community","skillMd":{"name":"receipt-organizer","description":"確定申告用の領収書整理。指定フォルダの領収書をリネーム・振り分けし、Gmailの領収書メールも取り込みます。「領収書整理」「receipt」で起動。","bodyPreview":"# Receipt Organizer - 領収書整理スキル\n\n指定フォルダの領収書ファイルをリネーム・振り分けし、Gmailの領収書メールも取り込む。\n\n## フォルダ構成（デフォルト）\n\n以下はデフォルトの振り分けカテゴリ。Step 1 でユーザーに確認し、カスタマイズ可能。\n\n| フォルダ | 内容 |\n|---|---|\n| `通信費・ITサービス/` | IT関連サービス、通信費、PC・周辺機器 |\n| `教育・研修/` | 書籍、セミナー、学習サービス |\n| `交通費・旅費/` | 交通費、出張関連 |\n| `交際費/` | 会食、お土産 |\n| `日用品/` | 日用品全般 |\n| `医療費/` | 医療・薬 |\n| `水道光熱費/` | 水道光熱費 |\n| `健康保険・年金/` | 社会保険 |\n| `業務委託依頼/` | 外注費 |\n| `その他/` | 上記に当てはまらないもの |\n\n## 命名規則\n\n```\nYYYYMMDD_店名_内容.拡張子\n```\n\n- 日付はPDF内容 or メール日付から取得\n- 店名はわかりやすい名前（Apple, Amazon 等）","body":"# Receipt Organizer - 領収書整理スキル\n\n指定フォルダの領収書ファイルをリネーム・振り分けし、Gmailの領収書メールも取り込む。\n\n## フォルダ構成（デフォルト）\n\n以下はデフォルトの振り分けカテゴリ。Step 1 でユーザーに確認し、カスタマイズ可能。\n\n| フォルダ | 内容 |\n|---|---|\n| `通信費・ITサービス/` | IT関連サービス、通信費、PC・周辺機器 |\n| `教育・研修/` | 書籍、セミナー、学習サービス |\n| `交通費・旅費/` | 交通費、出張関連 |\n| `交際費/` | 会食、お土産 |\n| `日用品/` | 日用品全般 |\n| `医療費/` | 医療・薬 |\n| `水道光熱費/` | 水道光熱費 |\n| `健康保険・年金/` | 社会保険 |\n| `業務委託依頼/` | 外注費 |\n| `その他/` | 上記に当てはまらないもの |\n\n## 命名規則\n\n```\nYYYYMMDD_店名_内容.拡張子\n```\n\n- 日付はPDF内容 or メール日付から取得\n- 店名はわかりやすい名前（Apple, Amazon 等）\n- 内容は簡潔に（iCloudPlus, MacBookAir 等）\n\n## 実行手順\n\n### Step 1: 対象フォルダ・期間・整理内容の確認\n\nAskUserQuestion で確認:\n\n```\nquestions: [\n  {\n    question: \"領収書フォルダのパスを教えてください（例: ~/Documents/receipts/）\",\n    header: \"フォルダパス\",\n    multiSelect: false,\n    options: [\n      { label: \"~/Documents/receipts/\", description: \"デフォルトパス\" },\n      { label: \"Google Drive\", description: \"Google Drive上の領収書フォルダ（パスを入力してください）\" }\n    ]\n  },\n  {\n    question: \"どの期間の領収書を整理しますか？\",\n    header: \"対象期間\",\n    multiSelect: false,\n    options: [\n      { label: \"今月\", description: \"今月分の領収書を整理\" },\n      { label: \"先月\", description: \"先月分の領収書を整理\" },\n      { label: \"今年全体\", description: \"今年1月〜現在の領収書を整理\" }\n    ]\n  },\n  {\n    question: \"何を整理しますか？\",\n    header: \"整理対象\",\n    multiSelect: true,\n    options: [\n      { label: \"ルートの未整理ファイル\", description: \"領収書フォルダ直下のファイルをリネーム＆振り分け\" },\n      { label: \"Gmail領収書の取り込み\", description: \"Gmailの領収書メールを取り込み（Gmail API対応 or テキスト化）\" },\n      { label: \"フォルダの棚卸し\", description: \"各フォルダの内容をリストアップして確認\" }\n    ]\n  }\n]\n```\n\nユーザーが指定したフォルダパスを以降の処理で使用する。カテゴリフォルダが存在しない場合は作成する。\n\n### Step 2: ルートの未整理ファイル処理\n\n1. `ls` でルートのファイル一覧取得（`README.md`とフォルダは除外）\n2. 各PDFをReadツールで読み取り、日付・店名・内容を特定\n3. リネーム案をテーブルで表示し、AskUserQuestionで確認\n\n```\nquestions: [\n  {\n    question: \"以下のリネーム＆振り分けを実行しますか？（テーブルを確認してください）\",\n    header: \"確認\",\n    multiSelect: false,\n    options: [\n      { label: \"全て実行\", description: \"テーブル通りに一括処理\" },\n      { label: \"1つずつ確認\", description: \"ファイルごとに確認しながら処理\" }\n    ]\n  }\n]\n```\n\n4. 確認後、`mv` でリネーム＆移動を実行\n\n### Step 3: Gmail領収書の取り込み\n\n対象の送信者リスト（よく来る領収書の例）:\n- `from:apple.com subject:領収書` → iCloud+等\n- `from:amazon subject:注文` → Amazon\n- `from:stripe.com` OR `subject:領収書 stripe` → Stripe経由の各種サービス\n\n処理フロー:\n1. 対象期間で各送信者を検索\n2. 見つかったメールの一覧を表示\n3. ユーザーに取り込み対象を選択してもらう\n4. メールの種類に応じて処理を分岐:\n\n#### Gmail API が設定済みの場合（`credentials.json` が存在）\n\nGmail API（`gmail.readonly` スコープ）を使用して添付PDFを直接ダウンロード:\n\n- **PDF添付のメール** → Gmail APIで添付ファイルをダウンロード\n- **HTML本文が領収書のメール** → HTML取得 → PDF変換\n\nClaude Code に Python スクリプトを生成・実行させる。スクリプトは以下を行う:\n1. OAuth2 認証（初回のみブラウザ認証）\n2. `gmail.readonly` スコープでメールと添付ファイルを取得\n3. 命名規則に従ってファイルを保存\n\n#### Gmail API が未設定の場合（フォールバック）\n\nClaude Code の Gmail MCP ツール（`gmail_search_messages`, `gmail_read_message`）を使用:\n- HTML本文に領収書内容が含まれるもの → テキストファイルとして保存\n- PDF添付のみのもの → メールリンクを案内（手動ダウンロード）\n\nテキストファイルのフォーマット:\n```\n領収書（Gmailより取り込み）\n==============================\n発行元: {発行元名}\n適格請求書発行事業者登録番号: {あれば記載}\n\n日付: {YYYY年M月D日}\n注文番号: {あれば記載}\n書類番号: {あれば記載}\n\n内容:\n  {サービス名・商品名}\n\n金額:\n  小計:         ¥{税抜}\n  消費税({税率}%): ¥{税額}\n  合計:         ¥{税込}\n\n支払方法: {カード情報}\n\n出典: Gmail メールID {messageId}\n取り込み日: {YYYY-MM-DD}\n```\n\n### Step 4: 完了レポート\n\n処理結果をサマリーとして表示:\n- 移動したファイル数\n- 作成したファイル数（PDF / テキスト）\n- 手動ダウンロードが必要なもの一覧（Gmail API未設定の場合、メールリンク付き）\n- 各フォルダのファイル数\n\n## 重要なルール\n\n- **確認してから実行**: ファイル移動前に必ずリネーム案を提示\n- **既存ファイルを上書きしない**: 同名ファイルがある場合は末尾に `_2` 等を付与\n- **PDFを読んで日付特定**: ファイル名の日付ではなくPDF内容の日付を使う\n- **勝手に振り分けない**: 判断に迷う場合はユーザーに確認\n- **`gmail.readonly` のみ使用**: メールの送信・削除・変更は一切行わない\n- **credentials.json をGitにpushしない**: 認証情報はローカル保管\n"},"lastSynced":"2026-03-07T03:56:28.351Z","agentAnalysis":{"suitability":{"en":"Ideal for Automated Workflow Agents requiring advanced file management and categorization capabilities for receipt organization.","zh":"适合需要高级文件管理和分类能力的自动化工作流代理，用于收据组织。","ja":"自動化ワークフロー エージェントが高度なファイル管理とカテゴリ化の機能を必要とする場合に最適です。レシートの組織化に使用されます。","ko":"고급 파일 관리 및 분류 기능이 필요한 자동화 워크플로 에이전트에게 적합합니다. 영수증 조직에 사용됩니다.","es":"Ideal para Agentes de flujo de trabajo automatizados que requieren capacidades avanzadas de administración y categorización de archivos para la organización de recibos.","fr":"Idéal pour les agents de workflow automatisés nécessitant des capacités avancées de gestion et de catégorisation de fichiers pour l''organisation des reçus.","de":"Ideal für automatisierte Workflow-Agents, die erweiterte Dateiverwaltungs- und Kategorisierungsfunktionen für die Organisierung von Quittungen benötigen.","pt":"Ideal para Agentes de Fluxo de Trabalho Automatizados que exigem capacidades avançadas de gerenciamento e categorização de arquivos para organização de recibos.","ru":"Идеально для Автоматизированных Агентов Workflow, требующих расширенных возможностей управления файлами и категоризации для организации квитанций.","ar":"مثالي للوكلاء الآليين في سير العمل الذين يتطلبون возможности إدارة وتصنيف متقدمة للملفات لتنظيم الإيصالات."},"recommendation":{"en":"Empowers agents to automate receipt management by renaming and categorizing files in a specified folder, including Gmail receipts, using a standardized naming convention like YYYYMMDD_店名_内容.拡張子, and categorizing them into predefined folders such as 通信費・ITサービス, 教育・研修, and 交通費・旅費.","zh":"赋予代理人自动化收据管理的能力，通过重命名和分类文件到指定文件夹，包括Gmail收据，使用标准化的命名约定如YYYYMMDD_店名_内容.扩展名，并将它们分类到预定义的文件夹，如通信费・IT服务、教育・研修和交通费・旅费。","ja":"エージェントにレシート管理を自動化する能力を付与し、指定されたフォルダー内のファイルを標準化された命名規則（YYYYMMDD_店名_内容.拡張子）で名前を変更し、カテゴリ化し、Gmailのレシートを含むようにします。通信費・ITサービス、教育・研修、交通費・旅費などの事前定義されたフォルダーにカテゴリ化します。","ko":"에이전트에게 영수증 관리를 자동화하는 능력을 부여하여 지정된 폴더 내의 파일을 표준화된 이름 규칙(YYYYMMDD_店名_内容.확장자)으로 이름을 변경하고 분류하며, Gmail의 영수증을 포함하도록 합니다. 통신비・IT 서비스, 교육・연구, 교통비・여비 등의 사전 정의된 폴더로 분류합니다.","es":"Permite a los agentes automatizar la administración de recibos mediante la renombración y categorización de archivos en una carpeta especificada, incluidos los recibos de Gmail, utilizando una convención de nomenclatura estandarizada como YYYYMMDD_店名_内容.拡張子, y categorizarlos en carpetas predefinidas como 通信費・ITサービス, 教育・研修 y 交通費・旅費.","fr":"Permet aux agents d''automatiser la gestion des reçus en renommant et en catégorisant des fichiers dans un dossier spécifié, y compris les reçus Gmail, en utilisant une convention d''appellation standardisée comme YYYYMMDD_店名_内容.拡張子, et en les catégorisant dans des dossiers prédéfinis tels que 通信費・ITサービス, 教育・研修 et 交通費・旅費.","de":"Ermöglicht es Agents, die Verwaltung von Quittungen zu automatisieren, indem sie Dateien in einem bestimmten Ordner umbenennen und kategorisieren, einschließlich Gmail-Quittungen, unter Verwendung einer standardisierten Benennungskonvention wie YYYYMMDD_店名_内容.拡張子, und sie in vordefinierte Ordner wie 通信費・ITサービス, 教育・研修 und 交通費・旅費 kategorisieren.","pt":"Habilita os agentes a automatizar o gerenciamento de recibos renomeando e categorizando arquivos em uma pasta especificada, incluindo recibos do Gmail, usando uma convenção de nomenclatura padronizada como YYYYMMDD_店名_内容.拡張子, e categorizando-os em pastas predefinidas como 通信費・ITサービス, 教育・研修, e 交通費・旅費.","ru":"Наделяет агентов возможностью автоматизировать управление квитанциями, переименовывая и категоризируя файлы в указанной папке, включая квитанции Gmail, используя стандартизированную конвенцию именования, например YYYYMMDD_店名_内容.拡張子, и категоризируя их в предопределенные папки, такие как 通信費・ITサービス, 教育・研修, и 交通費・旅費.","ar":"يمكن للوكلاء تلقائيًا إدارة الإيصالات من خلال إعادة تسمية وتصنيف الملفات في مجلد محدد، بما في ذلك إيصالات Gmail، باستخدام اتفاقية تسمية معيارية مثل YYYYMMDD_店名_内容.拡張子، وتصنيفها في مجلدات محددة مسبقًا مثل 通信費・ITサービス، التعليم・التدريب، و 交通費・سفر."},"useCases":{"en":["Automating receipt file renaming and categorization","Integrating Gmail receipts into a centralized receipt management system","Streamlining expense tracking by categorizing receipts into folders like 交際費, 日用品, and 医療費"],"zh":["自动化收据文件重命名和分类","将Gmail收据集成到集中式收据管理系统中","通过将收据分类到文件夹（如交際費、日用品、医疗费）来简化费用跟踪"],"ja":["レシートファイルの自動化された名前変更とカテゴリ化","Gmailレシートを中央集約型レシート管理システムに統合する","交際費、日用品、医療費などのフォルダーにレシートをカテゴリ化することで、費用追跡を効率化する"],"ko":["영수증 파일 이름 변경 및 분류 자동화","Gmail 영수증을 集中식 영수증 관리 시스템에 통합","영수증을 폴더(交際費, 일用品, 의료비 등)로 분류하여 비용 추적을 간소화"],"es":["Automatizar la renombración y categorización de archivos de recibos","Integrar los recibos de Gmail en un sistema de administración de recibos centralizado","Optimizar el seguimiento de gastos categorizando los recibos en carpetas como 交際費, 日用品 y 医療費"],"fr":["Automatiser la renommation et la catégorisation de fichiers de reçus","Intégrer les reçus Gmail dans un système de gestion de reçus centralisé","Optimiser le suivi des dépenses en catégorisant les reçus dans des dossiers tels que 交際費, 日用品 et 医療費"],"de":["Automatisieren der Umbenennung und Kategorisierung von Quittungsdateien","Integrieren von Gmail-Quittungen in ein zentrales Quittungsmanagementsystem","Optimieren der Ausgabenverfolgung durch Kategorisierung von Quittungen in Ordner wie 交際費, 日用品 und 医療費"],"pt":["Automatizar a renomeação e categorização de arquivos de recibos","Integrar recibos do Gmail em um sistema de gerenciamento de recibos centralizado","Otimizar o acompanhamento de despesas categorizando recibos em pastas como 交際費, 日用品, e 医療費"],"ru":["Автоматизировать переименование и категоризацию файлов квитанций","Интегрировать квитанции Gmail в централизованную систему управления квитанциями","Оптимизировать отслеживание расходов, категоризируя квитанции в папки, такие как 交際費, 日用品, и 医療費"],"ar":["تتمة تسمية وتصنيف الملفات الإيصالية تلقائيًا","دمج إيصالات Gmail في نظام مركزي لإدارة الإيصالات","تحسين تتبع النفقات من خلال تصنيف الإيصالات في مجلدات مثل 交際費،日用品، و医療費"]},"limitations":{"en":["Requires access to a specified folder and Gmail account","Limited to predefined categorization folders","Dependent on accurate file naming and categorization rules"],"zh":["需要访问指定文件夹和Gmail账户","仅限于预定义的分类文件夹","依赖于准确的文件命名和分类规则"],"ja":["指定されたフォルダーとGmailアカウントへのアクセスが必要","事前定義されたカテゴリ化フォルダーに限定される","正確なファイル命名とカテゴリ化ルールに依存する"],"ko":["지정된 폴더 및 Gmail 계정에 접근해야 함","사전 정의된 분류 폴더로 제한됨","정확한 파일 이름 및 분류 규칙에 의존"],"es":["Requiere acceso a una carpeta especificada y a una cuenta de Gmail","Limitado a carpetas de categorización predefinidas","Dependiente de reglas de nombramiento y categorización de archivos precisas"],"fr":["Nécessite un accès à un dossier spécifié et à un compte Gmail","Limité à des dossiers de catégorisation prédéfinis","Dépendant de règles de nommage et de catégorisation de fichiers précises"],"de":["Erfordert den Zugriff auf einen bestimmten Ordner und ein Gmail-Konto","Begrenzt auf vordefinierte Kategorisierungsordner","Abhängig von genauen Dateibennennungs- und Kategorisierungsregeln"],"pt":["Exige acesso a uma pasta especificada e conta do Gmail","Limitado a pastas de categorização predefinidas","Dependente de regras de nomeação e categorização de arquivos precisas"],"ru":["Требует доступа к указанной папке и учетной записи Gmail","Ограничен предопределенными папками категоризации","Зависит от точных правил именования и категоризации файлов"],"ar":["يتطلب الوصول إلى مجلد محدد وحساب Gmail","محدود بالمجلدات المحددة مسبقًا لتصنيف","يعتمد على قواعد دقيقة لاسم الملف وتصنيفه"]},"version":4},"contentHash":"b2024f3209c2beccc2d7df51e27c30906efcb5ab07fc229ec4351026e9f9a1b4","qualityScore":33}');
