INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shuhei-fujita/receipt-organizer/receipt-organizer', 'receipt-organizer', 'shuhei-fujita', 'receipt-organizer', 'community', 'receipt-organizer shuhei-fujita receipt-organizer community The receipt-organizer skill automates receipt management by renaming and categorizing files in a specified folder, including Gmail receipts. It benefits users by streamlining their receipt organization process. receipt-organizer 是一个自动整理领收单的工具，支持 Gmail 邮件导入和自定义分类 領収書整理スキルは、指定フォルダの領収書ファイルをリネーム・振り分けし、Gmail の領収書メールも取り込む 영수증 정리 도구는 자동으로 영수증을 분류하고 Gmail 메일을 가져옵니다 Receipt Organizer es una herramienta de AI que organiza tus facturas y emails en carpetas personalizadas utilizando tecnologías de renombramiento y clasificación automática Receipt Organizer est un outil d''IA qui organise vos reçus et emails dans des dossiers personnalisés en utilisant des technologies de renommage et de classification automatique Receipt Organizer ist ein AI-Tool, das Ihre Quittungen und E-Mails in benutzerdefinierten Ordnern organisiert, indem es Technologien zur automatischen Umbenennung und Klassifizierung verwendet O Organizador de Recibos é uma ferramenta que ajuda a gerenciar recibos, renomeando e categorizando arquivos em pastas específicas. ИИ Агент для организации квитанций - это инструмент, который помогает управлять квитанциями, переименовывая и категоризируя файлы в определенные папки. مصفف الإيصالات هو أداة تساعد في إدارة الإيصالات، من خلال إعادة تسمية وتصنيف الملفات في مجلدات محددة. how to use receipt-organizer receipt-organizer setup guide automated receipt management receipt-organizer alternative receipt organization best practices gmail receipt integration receipt-organizer AI 工具 自动整理领收单 Gmail 邮件导入 自定义分类 命名规则 多种文件格式 领收单管理 Renames receipt files using a custom YYYYMMDD_店名_内容.拡張子 naming convention Categorizes receipts into predefined folders such as 通信費・ITサービス, 教育・研修, and 交通費・旅費 Imports Gmail receipts for unified management Allows customization of folder categories and naming rules Supports various file formats, including PDF receipt-organizer is a skill that automates the organization of receipts by renaming and categorizing files based on predefined categories and a custom naming convention.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xvaara/sleepwalkers/vueuse', 'community', 'xvaara', 'sleepwalkers', 'xvaara/sleepwalkers', 'vueuse', 0, 1, 33, '2026-02-24T18:13:49Z', '2026-03-07T03:56:39.446Z', '02db40c83174af56b6707aa6f4ed1b9596ab27796d5c7b4b3b95b71af9f78ce6', '{"id":"xvaara/sleepwalkers/vueuse","name":"vueuse","description":{"en":"vueuse provides a collection of essential Vue Composition utilities for efficient development. It benefits Vue 3 developers by offering pre-built composables for common patterns","zh":"VueUse是一组必备的Vue Composition工具，提供了便捷的安装和使用方式","ja":"VueUseは必須のVue Compositionツール群であり、簡単なインストールと使用方法を提供する","ko":"VueUse는 필수적인 Vue Composition 도구 모음으로 간단한 설치와 사용 방법을 제공합니다","es":"VueUse es una colección de utilidades esenciales para la composición de Vue, compatible con Vue 3.5+.","fr":"VueUse est un ensemble d''utilitaires essentiels pour la composition de Vue, compatible avec Vue 3.5+.","de":"VueUse ist eine Sammlung von wesentlichen Utilitys für die Vue-Komposition, kompatibel mit Vue 3.5+.","pt":"O VueUse é uma coleção de utilitários essenciais para a composição Vue, permitindo que os desenvolvedores criem aplicações mais eficientes.","ru":"VueUse - это коллекция необходимых утилит для композиции Vue, giúpая разработчикам создавать более эффективные приложения.","ar":"VueUse هو مجموعة من الأدوات الأساسية لتركيبات Vue، مما يسمح للمطورين بإنشاء تطبيقات أكثر كفاءة."},"seo":{"title":{"en":"vueuse: Essential Vue Composition Utilities Setup Guide |...","zh":"VueUse 安装和使用指南 - AI工具集成","ja":"VueUse のセットアップガイド - AIエージェントとの連携","ko":"VueUse 설치 및 사용법 - AI 도구 통합","es":"Guía de configuración de VueUse para desarrolladores","fr":"Guide de mise en place de VueUse pour les développeurs","de":"VueUse-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração do VueUse para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке VueUse","ar":"إعداد أداة VueUse للوفاء بمتطلبات التطوير"},"description":{"en":"Discover how to harness the power of vueuse for your Vue 3 projects. Learn how to install and integrate vueuse with Nuxt for streamlined development","zh":"了解VueUse的功能和特点，发现如何将其与Vue 3和Nuxt集成，提高开发效率","ja":"VueUseの特徴と機能を学び、Vue 3とNuxtとの統合方法を発見して開発効率を向上させる","ko":"VueUse의 기능과 특징을 알아보고 Vue 3와 Nuxt와의 통합 방법을 발견하여 개발 효율을 높여보세요","es":"Aprende a instalar y utilizar VueUse con Vue 3 y Nuxt para mejorar tu desarrollo frontend","fr":"Découvrez comment installer et utiliser VueUse avec Vue 3 et Nuxt pour améliorer votre développement frontend","de":"Erfahren Sie, wie Sie VueUse mit Vue 3 und Nuxt installieren und verwenden, um Ihre Frontend-Entwicklung zu verbessern","pt":"Aprenda a configurar o VueUse com nossos recursos e dicas de especialistas para desenvolvedores","ru":"ИИ Агенты: Узнайте, как настроить VueUse для разработки приложений Vue.js","ar":"اكتشف كيفية إعداد VueUse لتحقيق متطلبات التطوير بسهولة"},"definition":{"en":"vueuse is a collection of essential Vue Composition utilities designed to simplify development for Vue 3 applications","zh":"VueUse是一组为Vue提供的 Composition API 实用工具","ja":"VueUseはVueのためのComposition APIユーティリティ群である","ko":"VueUse는 Vue를 위한 Composition API 유틸리티جموع입니다","es":"VueUse es una biblioteca de utilidades para la composición de Vue que proporciona patrones predefinidos","fr":"VueUse est une bibliothèque d''utilitaires pour la composition de Vue qui fournit des modèles prédéfinis","de":"VueUse ist eine Bibliothek von Utilitys für die Vue-Komposition, die vorgefertigte Muster bereitstellt","pt":"O que é VueUse? É uma coleção de utilitários para a composição Vue.","ru":"Что такое VueUse? Это коллекция утилит для композиции Vue.","ar":"ما هو VueUse؟ هو مجموعة من الأدوات لتركيبات Vue."},"features":{"en":["Supports Vue 3.5+ with stable version 14.x","Easy installation via pnpm with @vueuse/core","Seamless integration with Nuxt using @vueuse/nuxt module","Auto-imports composables for convenient use in Nuxt projects","Covers most common patterns, reducing the need for custom composables"],"zh":["支持Vue 3.5+版本","提供了便捷的安装和使用方式","与Nuxt集成，自动导入组件","包含了多种常用的Composition实用工具","支持通过pnpm进行安装"],"ja":["Vue 3.5+をサポート","簡単なインストールと使用方法を提供","Nuxtとの統合、コンポーネントの自動インポート","一般的なCompositionユーティリティを含む","pnpmを通じてのインストールをサポート"],"ko":["Vue 3.5+ 버전 지원","간단한 설치와 사용 방법 제공","Nuxt와의 통합, 컴포넌트 자동导入","일반적인 Composition 유틸리티 포함","pnpm을 통한 설치 지원"],"es":["Compatibilidad con Vue 3.5+","Instalación sencilla con pnpm","Integración con Nuxt para auto-importar composables","Colección de utilidades esenciales para la composición de Vue","Patrones predefinidos para agilizar el desarrollo"],"fr":["Compatibilité avec Vue 3.5+","Installation simple avec pnpm","Intégration avec Nuxt pour l''auto-importation de composables","Collection d''utilitaires essentiels pour la composition de Vue","Modèles prédéfinis pour accélérer le développement"],"de":["Kompatibilität mit Vue 3.5+","Einfache Installation mit pnpm","Integration mit Nuxt für die Auto-Importierung von Composables","Sammlung von wesentlichen Utilitys für die Vue-Komposition","Vorgefertigte Muster für die Beschleunigung der Entwicklung"],"pt":["Instalação simples com pnpm add @vueuse/core","Suporte a Nuxt com módulo @vueuse/nuxt","Auto-importação de composáveis com Nuxt","Compatibilidade com Vue 3.5+","Coleção de utilitários essenciais para composição Vue"],"ru":["Простая установка с помощью pnpm add @vueuse/core","Поддержка Nuxt с модулем @vueuse/nuxt","Автоимпорт композиций с Nuxt","Совместимость с Vue 3.5+","Коллекция необходимых утилит для композиции Vue"],"ar":["تثبيت بسيط باستخدام pnpm add @vueuse/core","دعم Nuxt مع الوحدة @vueuse/nuxt","استيراد تلقائي لتركيبات Vue مع Nuxt","توافق مع Vue 3.5+","مجموعة من الأدوات الأساسية لتركيبات Vue"]},"keywords":{"en":["how to use vueuse","vueuse install","vueuse setup guide","vueuse vs vuex","vueuse alternative","what is vueuse","vueuse nuxt integration","vue composition utilities"],"zh":["VueUse","Vue Composition","Vue 3","Nuxt","pnpm","AI工具","Vue开发工具","前端开发框架"],"ja":["VueUse","Vue Composition","Vue 3","Nuxt","pnpm","AIエージェント","Vue開発ツール","フロントエンド開発フレームワーク"],"ko":["VueUse","Vue Composition","Vue 3","Nuxt","pnpm","AI 도구","Vue 개발 도구","프론트엔드 개발 프레임워크"],"es":["vueuse","vue 3","nuxt","composición de vue","utilidades de vue","desarrollo frontend","herramientas de desarrollo","pnpm","instalación de vueuse"],"fr":["vueuse","vue 3","nuxt","composition de vue","utilitaires de vue","développement frontend","outils de développement","pnpm","installation de vueuse"],"de":["vueuse","vue 3","nuxt","vue-komposition","vue-utilitys","frontend-entwicklung","entwicklungstools","pnpm","installation von vueuse"],"pt":["VueUse","configuração VueUse","desenvolvimento Vue","utilitários Vue","Nuxt","pnpm","Vue 3.5+","composição Vue"],"ru":["VueUse","настройка VueUse","разработка Vue","утилиты Vue","Nuxt","pnpm","Vue 3.5+","композиция Vue"],"ar":["VueUse","إعداد VueUse","تطوير Vue","أدوات Vue","Nuxt","pnpm","Vue 3.5+","تركيبات Vue"]}},"owner":"xvaara","repo":"sleepwalkers","repoPath":"xvaara/sleepwalkers","stars":0,"forks":1,"updatedAt":"2026-02-24T18:13:49Z","topics":[],"category":"community","skillMd":{"name":"vueuse","description":"Use when working with VueUse composables - provides reactive utilities for state, browser APIs, sensors, network, animations. Check VueUse before writing custom composables - most patterns already implemented.","bodyPreview":"# VueUse\n\nCollection of essential Vue Composition utilities. Check VueUse before writing custom composables - most patterns already implemented.\n\n**Current stable:** VueUse 14.x for Vue 3.5+\n\n## Installation\n\n**Vue 3:**\n\n```bash\npnpm add @vueuse/core\n```\n\n**Nuxt:**\n\n```bash\npnpm add @vueuse/nuxt @vueuse/core\n```\n\n```ts\n// nuxt.config.ts\nexport default defineNuxtConfig({\n  modules: [''@vueuse/nuxt''],\n})\n```\n\nNuxt module auto-imports composables - no import needed.\n\n## Categories\n\n| Category   | Ex","body":"# VueUse\n\nCollection of essential Vue Composition utilities. Check VueUse before writing custom composables - most patterns already implemented.\n\n**Current stable:** VueUse 14.x for Vue 3.5+\n\n## Installation\n\n**Vue 3:**\n\n```bash\npnpm add @vueuse/core\n```\n\n**Nuxt:**\n\n```bash\npnpm add @vueuse/nuxt @vueuse/core\n```\n\n```ts\n// nuxt.config.ts\nexport default defineNuxtConfig({\n  modules: [''@vueuse/nuxt''],\n})\n```\n\nNuxt module auto-imports composables - no import needed.\n\n## Categories\n\n| Category   | Examples                                                   |\n| ---------- | ---------------------------------------------------------- |\n| State      | useLocalStorage, useSessionStorage, useRefHistory          |\n| Elements   | useElementSize, useIntersectionObserver, useResizeObserver |\n| Browser    | useClipboard, useFullscreen, useMediaQuery                 |\n| Sensors    | useMouse, useKeyboard, useDeviceOrientation                |\n| Network    | useFetch, useWebSocket, useEventSource                     |\n| Animation  | useTransition, useInterval, useTimeout                     |\n| Component  | useVModel, useVirtualList, useTemplateRefsList             |\n| Watch      | watchDebounced, watchThrottled, watchOnce                  |\n| Reactivity | createSharedComposable, toRef, toReactive                  |\n| Array      | useArrayFilter, useArrayMap, useSorted                     |\n| Time       | useDateFormat, useNow, useTimeAgo                          |\n| Utilities  | useDebounce, useThrottle, useMemoize                       |\n\n## Quick Reference\n\nLoad composable files based on what you need:\n\n| Working on...        | Load file                                              |\n| -------------------- | ------------------------------------------------------ |\n| Finding a composable | [references/composables.md](references/composables.md) |\n| Specific composable  | `composables/<name>.md`                                |\n\n## Loading Files\n\n**Consider loading these reference files based on your task:**\n\n- [ ] [references/composables.md](references/composables.md) - if searching for VueUse composables by category or functionality\n\n**DO NOT load all files at once.** Load only what''s relevant to your current task.\n\n## Common Patterns\n\n**State persistence:**\n\n```ts\nconst state = useLocalStorage(''my-key'', { count: 0 })\n```\n\n**Mouse tracking:**\n\n```ts\nconst { x, y } = useMouse()\n```\n\n**Debounced ref:**\n\n```ts\nconst search = ref('''')\nconst debouncedSearch = refDebounced(search, 300)\n```\n\n**Shared composable (singleton):**\n\n```ts\nconst useSharedMouse = createSharedComposable(useMouse)\n```\n\n## SSR Gotchas\n\nMany VueUse composables use browser APIs unavailable during SSR.\n\n**Check with `isClient`:**\n\n```ts\nimport { isClient } from ''@vueuse/core''\n\nif (isClient) {\n  // Browser-only code\n  const { width } = useWindowSize()\n}\n```\n\n**Wrap in onMounted:**\n\n```ts\nconst width = ref(0)\n\nonMounted(() => {\n  // Only runs in browser\n  const { width: w } = useWindowSize()\n  width.value = w.value\n})\n```\n\n**Use SSR-safe composables:**\n\n```ts\n// These check isClient internally\nconst mouse = useMouse() // Returns {x: 0, y: 0} on server\nconst storage = useLocalStorage(''key'', ''default'') // Uses default on server\n```\n\n**`@vueuse/nuxt` auto-handles SSR** - composables return safe defaults on server.\n\n## Target Element Refs\n\nWhen targeting component refs instead of DOM elements:\n\n```ts\nimport type { MaybeElementRef } from ''@vueuse/core'' // ❌ Won''t work\n\n// Use MaybeElementRef pattern\nimport { unrefElement } from ''@vueuse/core''\n\n// Component ref needs .$el to get DOM element\nconst compRef = ref<ComponentInstance>()\nconst { width } = useElementSize(compRef)\n\nconst el = computed(() => unrefElement(compRef)) // Gets .$el\nconst { width } = useElementSize(el) // ✅ Works\n```\n\n**Or access `$el` directly:**\n\n```ts\nconst compRef = ref<ComponentInstance>()\n\nonMounted(() => {\n  const el = compRef.value?.$el as HTMLElement\n  const { width } = useElementSize(el)\n})\n```\n"},"lastSynced":"2026-03-07T03:56:39.446Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents leveraging Vue 3 Composition utilities for efficient development.","zh":"非常适合使用 Vue 3 Composition 实用程序进行高效开发的前端代理。","ja":"Vue 3 Composition ユーティリティを使用して効率的な開発を行うフロントエンド エージェントに最適です。","ko":"Vue 3 Composition 유틸리티를 사용하여 효율적인 개발을 수행하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que utilizan las utilidades de composición de Vue 3 para un desarrollo eficiente.","fr":"Parfait pour les agents Frontend qui utilisent les utilités de composition de Vue 3 pour un développement efficace.","de":"Perfekt für Frontend-Agents, die die Kompositions-Utilities von Vue 3 für eine effiziente Entwicklung nutzen.","pt":"Perfeito para Agentes Frontend que utilizam utilitários de composição do Vue 3 para desenvolvimento eficiente.","ru":"Идеально для агентов Frontend, использующих утилиты Composition Vue 3 для эффективной разработки.","ar":"مثالي للوكلاء الأمامية الذين يستخدمون أدوات التركيب من Vue 3 من أجل التطوير الفعال."},"recommendation":{"en":"Empowers agents to utilize pre-built composables for common patterns, streamlining development with VueUse''s essential utilities, including auto-imports with Nuxt modules and compatibility with Vue 3.5+.","zh":"赋予代理使用预构建的组合式组件来实现常见模式，通过 VueUse 的基本实用程序简化开发，包括与 Nuxt 模块的自动导入和与 Vue 3.5+ 的兼容性。","ja":"エージェントが事前ビルド済みの組み合わせ可能なコンポーネントを使用して一般的なパターンを実現できるようにし、VueUse の基本ユーティリティを使用して開発を簡素化し、Nuxt モジュールとの自動インポートや Vue 3.5+ との互換性を提供します。","ko":"에이전트가 사전 빌드된 조합 가능한 컴포넌트를 사용하여 일반적인 패턴을 구현할 수 있도록 하여 VueUse 의 기본 유틸리티를 사용하여 개발을 간소화하고 Nuxt 모듈과 자동 가져오기 및 Vue 3.5+ 와의 호환성을 제공합니다.","es":"Permite a los agentes utilizar composables preconstruidos para patrones comunes, simplificando el desarrollo con las utilidades esenciales de VueUse, incluyendo autoimportaciones con módulos de Nuxt y compatibilidad con Vue 3.5+.","fr":"Permet aux agents d''utiliser des composables préconstruits pour des modèles courants, simplifiant le développement avec les utilités essentielles de VueUse, y compris les autoimportations avec les modules Nuxt et la compatibilité avec Vue 3.5+.","de":"Ermöglicht es den Agenten, vorgefertigte Composables für gängige Muster zu nutzen, um die Entwicklung mit den wesentlichen Utilities von VueUse zu rationalisieren, einschließlich Auto-Importen mit Nuxt-Modulen und Kompatibilität mit Vue 3.5+.","pt":"Habilita os agentes a utilizarem composables pré-construídos para padrões comuns, simplificando o desenvolvimento com as utilidades essenciais do VueUse, incluindo auto-importações com módulos Nuxt e compatibilidade com Vue 3.5+.","ru":"Наделяет агентов возможностью использовать предварительно созданные composables для общих шаблонов, упрощая разработку с помощью основных утилит VueUse, включая автоматические импорты с модулями Nuxt и совместимость с Vue 3.5+.","ar":"يمنح الوكلاء القدرة على استخدام composables تم إنشاؤها مسبقًا لنماذج مشتركة، وتبسيط التطوير باستخدام أدوات VueUse الأساسية، بما في ذلك الاستيراد التلقائي مع وحدات Nuxt والتوافق مع Vue 3.5+."},"useCases":{"en":["Automating common Vue 3 patterns with pre-built composables","Generating optimized Vue Composition utilities","Debugging Vue 3 applications with VueUse''s core utilities"],"zh":["使用预构建的组合式组件自动化常见的 Vue 3 模式","生成优化的 Vue Composition 实用程序","使用 VueUse 的核心实用程序调试 Vue 3 应用程序"],"ja":["事前ビルド済みの組み合わせ可能なコンポーネントを使用して一般的な Vue 3 パターンを自動化する","最適化された Vue Composition ユーティリティを生成する","VueUse のコア ユーティリティを使用して Vue 3 アプリケーションをデバッグする"],"ko":["사전 빌드된 조합 가능한 컴포넌트를 사용하여 일반적인 Vue 3 패턴을 자동화하는 것","최적화된 Vue Composition 유틸리티를 생성하는 것","VueUse 의 핵심 유틸리티를 사용하여 Vue 3 애플리케이션을 디버깅하는 것"],"es":["Automatizar patrones comunes de Vue 3 con composables preconstruidos","Generar utilidades de composición de Vue optimizadas","Depurar aplicaciones de Vue 3 con las utilidades principales de VueUse"],"fr":["Automatiser les modèles courants de Vue 3 avec des composables préconstruits","Générer des utilités de composition de Vue optimisées","Déboguer les applications Vue 3 avec les utilités de base de VueUse"],"de":["Automatisieren von gängigen Vue-3-Mustern mit vorgefertigten Composables","Erzeugen von optimierten Vue-Kompositions-Utilities","Debuggen von Vue-3-Anwendungen mit den Kern-Utilities von VueUse"],"pt":["Automatizar padrões comuns do Vue 3 com composables pré-construídos","Gerar utilitários de composição do Vue otimizados","Depurar aplicações do Vue 3 com utilitários core do VueUse"],"ru":["Автоматизировать общие шаблоны Vue 3 с предварительно созданными composables","Генерировать оптимизированные утилиты Composition Vue","Отладить приложения Vue 3 с помощью основных утилит VueUse"],"ar":["تأتمتة أنماط Vue 3 الشائعة مع composables تم إنشاؤها مسبقًا","генерировать أدوات تركيب Vue متقدمة","تصحيح أخطاء تطبيقات Vue 3 باستخدام أدوات VueUse الأساسية"]},"limitations":{"en":["Requires Vue 3.5+ compatibility","Nuxt module installation needed for auto-imports"],"zh":["需要 Vue 3.5+ 兼容性","需要 Nuxt 模块安装以实现自动导入"],"ja":["Vue 3.5+ との互換性が必要","自動インポートを行うために Nuxt モジュールのインストールが必要"],"ko":["Vue 3.5+ 와의 호환성이 필요","자동 가져오기를 위해 Nuxt 모듈 설치가 필요"],"es":["Requiere compatibilidad con Vue 3.5+","Se necesita instalación de módulos de Nuxt para autoimportaciones"],"fr":["Nécessite une compatibilité avec Vue 3.5+","L''installation de modules Nuxt est nécessaire pour les autoimportations"],"de":["Benötigt Kompatibilität mit Vue 3.5+","Nuxt-Modul-Installation erforderlich für Auto-Importe"],"pt":["Exige compatibilidade com Vue 3.5+","Necessário instalar módulo Nuxt para auto-importações"],"ru":["Требует совместимости с Vue 3.5+","Необходимо установить модуль Nuxt для автоматических импортов"],"ar":["يتطلب توافقًا مع Vue 3.5+","يتطلب تثبيت وحدة Nuxt من أجل الاستيراد التلقائي"]},"version":4},"contentHash":"02db40c83174af56b6707aa6f4ed1b9596ab27796d5c7b4b3b95b71af9f78ce6","qualityScore":33}');
