INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xvaara/sleepwalkers/vueuse', 'vueuse', 'xvaara', 'sleepwalkers', 'community', 'vueuse xvaara sleepwalkers community vueuse provides a collection of essential Vue Composition utilities for efficient development. It benefits Vue 3 developers by offering pre-built composables for common patterns VueUse是一组必备的Vue Composition工具，提供了便捷的安装和使用方式 VueUseは必須のVue Compositionツール群であり、簡単なインストールと使用方法を提供する VueUse는 필수적인 Vue Composition 도구 모음으로 간단한 설치와 사용 방법을 제공합니다 VueUse es una colección de utilidades esenciales para la composición de Vue, compatible con Vue 3.5+. VueUse est un ensemble d''utilitaires essentiels pour la composition de Vue, compatible avec Vue 3.5+. VueUse ist eine Sammlung von wesentlichen Utilitys für die Vue-Komposition, kompatibel mit Vue 3.5+. O VueUse é uma coleção de utilitários essenciais para a composição Vue, permitindo que os desenvolvedores criem aplicações mais eficientes. VueUse - это коллекция необходимых утилит для композиции Vue, giúpая разработчикам создавать более эффективные приложения. VueUse هو مجموعة من الأدوات الأساسية لتركيبات Vue، مما يسمح للمطورين بإنشاء تطبيقات أكثر كفاءة. how to use vueuse vueuse install vueuse setup guide vueuse vs vuex vueuse alternative what is vueuse vueuse nuxt integration vue composition utilities VueUse Vue Composition Vue 3 Nuxt pnpm AI工具 Vue开发工具 前端开发框架 Supports Vue 3.5+ with stable version 14.x Easy installation via pnpm with @vueuse/core Seamless integration with Nuxt using @vueuse/nuxt module Auto-imports composables for convenient use in Nuxt projects Covers most common patterns, reducing the need for custom composables vueuse is a collection of essential Vue Composition utilities designed to simplify development for Vue 3 applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('martinsson/checkin-automation/adapter-contract-testing', 'community', 'martinsson', 'checkin-automation', 'martinsson/checkin-automation', 'adapter-contract-testing', 0, 0, 33, '2026-03-01T13:25:05Z', '2026-03-07T04:04:03.438Z', 'a3333cd0a5bbc2e8068faed3bbb1076b99ab8d37b0ec8ac2536a4ef6b16fbcce', '{"id":"martinsson/checkin-automation/adapter-contract-testing","name":"adapter-contract-testing","description":{"en":"adapter-contract-testing is a technique for keeping simulators honest by running abstract tests against both real adapters and simulators. It benefits developers by ensuring API consistency.","zh":"适配器契约测试是一种保持模拟器诚实的技术，使用抽象测试类来验证真实适配器和模拟器的行为一致性","ja":"適配器契約テストは、シミュレーターと実アダプターの動作の一致性を保つための技術です","ko":"어댑터 계약 테스트는 시뮬레이터와 실제 어댑터의 동작 일관성을 유지하기 위한 기술입니다","es":"La técnica de testing de contrato de adaptador asegura la compatibilidad entre simuladores y APIs reales. Aprende a implementarla con Python","fr":"La technique de testing de contrat d''adaptateur assure la compatibilité entre les simulateurs et les API réelles. Découvrez comment la mettre en œuvre avec Python","de":"Die Technik des Contract-Testings für Adapter stellt die Kompatibilität zwischen Simulatoren und echten APIs sicher. Erfahren Sie, wie Sie sie mit Python implementieren","pt":"O teste de contrato de adaptador é uma técnica para manter simulações honestas, garantindo a compatibilidade entre adaptadores e simulações","ru":"Тестирование контракта адаптера - это техника для поддержания честных симуляций, обеспечивающая совместимость между адаптерами и симуляциями","ar":"اختبار عقد المُحول هو تقنية لضمان صحة المحاكاة، وضمان التوافق بين المُحول والمحاكاة"},"seo":{"title":{"en":"adapter-contract-testing: Simulator Validation Setup Guid...","zh":"适配器契约测试Setup Guide - 保持模拟器诚实","ja":"Adapter Contract Testingベストプラクティス - AIエージェントの正確性を確保","ko":"어댑터 계약 테스트 Setup Guide - 시뮬레이터의 안정성을 보장","es":"Guía de configuración de adapter-contract-testing para de...","fr":"Configurer l''adapter-contract-testing pour les développeurs","de":"Einrichten von adapter-contract-testing für Entwickler","pt":"Guia de Configuração para Teste de Contrato de Adaptador","ru":"Настройка ИИ Агентов: Тестирование Контракта Адаптера","ar":"إعداد أداة اختبار عقد المُحول"},"description":{"en":"Ensure API consistency with adapter-contract-testing. Learn how to validate simulators and adapters with this technique. Get started now!","zh":"了解适配器契约测试的技术细节，使用Python实现模拟器和真实适配器的行为一致性","ja":"AIエージェントの適配器契約テストについて学ぶ - シミュレーターと実アダプターの動作の一致性を保つ","ko":"어댑터 계약 테스트의 기술적인 측면을 알아보세요 - 시뮬레이터와 실제 어댑터의 동작 일관성을 유지","es":"Aprende a implementar la técnica de testing de contrato de adaptador para mantener simuladores honestos y asegurar la compatibilidad con APIs reales","fr":"Découvrez comment mettre en œuvre la technique de testing de contrat d''adaptateur pour maintenir des simulateurs honnêtes et assurer la compatibilité avec le...","de":"Erfahren Sie, wie Sie die Technik des Contract-Testings für Adapter implementieren, um Simulatoren ehrlich zu halten und die Kompatibilität mit echten APIs s...","pt":"Aprenda a configurar o teste de contrato de adaptador para manter simulações honestas e garantir a compatibilidade entre adaptadores e simulações","ru":"Узнайте, как настроить тестирование контракта адаптера для поддержания честных симуляций и обеспечения совместимости между адаптерами и симуляциями с помощью...","ar":"تعرف على كيفية إعداد اختبار عقد المُحول لضمان صحة المحاكاة وضمان التوافق بين المُحول والمحاكاة"},"definition":{"en":"adapter-contract-testing is a software testing technique that validates the behavior of adapters and simulators by running the same abstract test class against both.","zh":"适配器契约测试是一种软件测试技术，用于验证模拟器和真实适配器的行为一致性","ja":"適配器契約テストは、シミュレーターと実アダプターの動作の一致性を保つためのソフトウェアテスト技術です","ko":"어댑터 계약 테스트는 시뮬레이터와 실제 어댑터의 동작 일관성을 유지하기 위한 소프트웨어 테스트 기술입니다","es":"El testing de contrato de adaptador es una técnica para mantener simuladores honestos","fr":"Le testing de contrat d''adaptateur est une technique pour maintenir des simulateurs honnêtes","de":"Das Contract-Testing für Adapter ist eine Technik, um Simulatoren ehrlich zu halten","pt":"Teste de contrato de adaptador é uma técnica de teste que garante a compatibilidade entre adaptadores e simulações","ru":"Тестирование контракта адаптера - это техника тестирования, обеспечивающая совместимость между адаптерами и симуляциями","ar":"اختبار عقد المُحول هو تقنية اختبار تضمن التوافق بين المُحول والمحاكاة"},"features":{"en":["Runs abstract test classes against both real adapters and simulators","Ensures identical behavior between adapters and simulators","Uses Python abstract base classes (ABC) for contract definition","Supports testing of API changes and simulator drift","Provides a canonical structure for contract testing","Utilizes GitHub-hosted papers for technique documentation"],"zh":["使用抽象测试类来验证真实适配器和模拟器的行为一致性","支持Python语言实现","可以检测真实API的变化或模拟器的偏差","提供了contracts/foo_contract.py的共享规范类","实现了FooContract抽象类来定义创建方法"],"ja":["抽象テストクラスを使用してシミュレーターと実アダプターの動作の一致性を検証","Python言語をサポート","実APIの変更やシミュレーターの偏差を検出可能","contracts/foo_contract.pyの共有仕様クラスを提供","FooContract抽象クラスを実装して作成メソッドを定義"],"ko":["추상 테스트 클래스를 사용하여 시뮬레이터와 실제 어댑터의 동작 일관성을 검증","Python 언어를 지원","실제 API의 변경이나 시뮬레이터의 편차를 감지할 수 있습니다","contracts/foo_contract.py의 공유 규격 클래스를 제공","FooContract 추상 클래스를 구현하여 생성 메서드를 정의"],"es":["Técnica de testing para mantener simuladores honestos","Compatibilidad con APIs reales y simuladas","Implementación con Python y ABC","Uso de abstractmethod para definir contratos","Integración con GitHub para papers y documentación"],"fr":["Technique de testing pour maintenir des simulateurs honnêtes","Compatibilité avec les API réelles et simulées","Mise en œuvre avec Python et ABC","Utilisation de abstractmethod pour définir des contrats","Intégration avec GitHub pour les documents et la documentation"],"de":["Technik des Testings, um Simulatoren ehrlich zu halten","Kompatibilität mit echten und simulierten APIs","Implementierung mit Python und ABC","Verwendung von abstractmethod zur Definition von Verträgen","Integration mit GitHub für Paper und Dokumentation"],"pt":["Utiliza a mesma classe de teste abstrata para adaptadores e simulações","Garante a compatibilidade entre adaptadores e simulações","Detecta mudanças no API ou drifts na simulação","Utiliza Python para implementação","Segue o padrão de contrato (canonical structure)"],"ru":["Использует одну и ту же абстрактную класс теста для адаптеров и симуляций","Гарантирует совместимость между адаптерами и симуляциями","Обнаруживает изменения в API или дрифты в симуляции","Использует Python для реализации","Следует паттерну контракта (canonical structure)"],"ar":["يستخدم نفس الفئة الاختبارية المجردة للمُحول والمحاكاة","يضمن التوافق بين المُحول والمحاكاة","يكتشف التغييرات في واجهة البرمجة أو الانجراف في المحاكاة","يستخدم بايثون للتنفيذ","يتبع نمط العقد (canonical structure)"]},"keywords":{"en":["how to use adapter-contract-testing","adapter-contract-testing vs mocking","adapter-contract-testing setup guide","what is adapter-contract-testing","adapter-contract-testing alternative","adapter-contract-testing install","adapter-contract-testing python","adapter-contract-testing simulator validation","adapter-contract-testing API testing"],"zh":["适配器契约测试","模拟器测试","真实适配器测试","Python测试","抽象测试类","contracts/foo_contract.py","FooContract抽象类"],"ja":["適配器契約テスト","シミュレーターテスト","実アダプターテスト","Pythonテスト","抽象テストクラス","contracts/foo_contract.py","FooContract抽象クラス","AIエージェント"],"ko":["어댑터 계약 테스트","시뮬레이터 테스트","실제 어댑터 테스트","Python 테스트","추상 테스트 클래스","contracts/foo_contract.py","FooContract 추상 클래스","AI 에이전트"],"es":["adapter-contract-testing","testing de contrato de adaptador","simuladores honestos","APIs reales","Python","ABC","abstractmethod","GitHub"],"fr":["adapter-contract-testing","testing de contrat d''adaptateur","simulateurs honnêtes","API réelles","Python","ABC","abstractmethod","GitHub"],"de":["adapter-contract-testing","Contract-Testing für Adapter","Simulatoren ehrlich halten","echte APIs","Python","ABC","abstractmethod","GitHub"],"pt":["teste de contrato de adaptador","simulações honestas","compatibilidade entre adaptadores e simulações","python","teste de api","padrão de contrato","desenvolvimento de software"],"ru":["тестирование контракта адаптера","честные симуляции","совместимость между адаптерами и симуляциями","python","тестирование api","паттерн контракта","разработка программного обеспечения"],"ar":["اختبار عقد المُحول","محاكاة صحيحة","توافق بين المُحول والمحاكاة","بايثون","اختبار واجهة البرمجة","نمط العقد","تطوير البرمجيات"]}},"owner":"martinsson","repo":"checkin-automation","repoPath":"martinsson/checkin-automation","stars":0,"forks":0,"updatedAt":"2026-03-01T13:25:05Z","topics":[],"category":"community","skillMd":{"name":"adapter-contract-testing","description":"Reference guide for writing adapter contract tests in this project. Use when creating or reviewing tests for ports/adapters (SmoobuGateway, RequestMemory, ReservationCache, etc.)","bodyPreview":"# Adapter Contract Testing\n\n## What it is\n\nA technique to keep simulators honest. The same abstract test class is run against **both** the real adapter and the simulator, proving they behave identically. If the real API changes or a simulator drifts, a test fails.\n\nSee: https://github.com/adapter-contract-testing/adapter-contract-testing-papers\n\n## The pattern (canonical structure)\n\n```python\n# contracts/foo_contract.py  — the shared spec\nclass FooContract(ABC):\n    @abstractmethod\n    def creat","body":"# Adapter Contract Testing\n\n## What it is\n\nA technique to keep simulators honest. The same abstract test class is run against **both** the real adapter and the simulator, proving they behave identically. If the real API changes or a simulator drifts, a test fails.\n\nSee: https://github.com/adapter-contract-testing/adapter-contract-testing-papers\n\n## The pattern (canonical structure)\n\n```python\n# contracts/foo_contract.py  — the shared spec\nclass FooContract(ABC):\n    @abstractmethod\n    def create_foo(self) -> Foo: ...   # only one abstract method\n\n    def test_something(self):\n        foo = self.create_foo()\n        ...\n\n# test_foo.py  — one class per implementation, nothing else\nclass TestRealFoo(FooContract):\n    def create_foo(self): return RealFoo(...)\n\nclass TestSimulatorFoo(FooContract):\n    def create_foo(self): return SimulatorFoo(...)\n```\n\n## Rules\n\n1. **One abstract method** — `create_foo()` (or `create_gateway()` etc.). No other setup plumbing.\n\n2. **Two concrete subclasses** — real adapter + simulator. One file per port, not spread across multiple files.\n\n3. **No `pytest.skip` in subclasses** — if a test needs pre-existing data, `create_foo()` must return a pre-seeded instance. A skip means the subclass doesn''t honour the contract.\n\n4. **No simulator-only test classes** — simulator-specific behaviour (internal state, edge cases unique to the fake) goes in standalone `test_` functions in the same file, not in a third contract subclass.\n\n5. **The contract IS the port spec** — every behaviour the pipeline relies on must have a test here. If you can''t write a contract test for it, question whether it belongs on the port at all.\n\n## Example from this codebase\n\n```python\n# tests/contracts/smoobu_gateway_contract.py\nclass SmoobuGatewayContract(ABC):\n    @abstractmethod\n    def create_gateway(self) -> SmoobuGateway: ...\n\n    def test_get_threads_non_empty(self):\n        page = self.create_gateway().get_threads(1)\n        assert len(page.threads) > 0\n\n# tests/test_smoobu_contract.py\nclass TestSimulatorSmoobuContract(SmoobuGatewayContract):\n    def create_gateway(self):\n        gw = SimulatorSmoobuGateway()\n        # Pre-seed so ALL contract tests pass without skips\n        gw.inject_active_reservation(...)\n        gw.inject_guest_message(...)\n        return gw\n\nclass TestSmoobuClientContract(SmoobuGatewayContract):\n    @pytest.mark.skipif(not API_KEY, reason=\"no credentials\")\n    def create_gateway(self): return SmoobuClient(API_KEY)\n```\n\n## What goes where\n\n| Location | Content |\n|---|---|\n| `tests/contracts/<port>_contract.py` | Abstract contract class, all tests |\n| `tests/test_<port>.py` | Two concrete subclasses (real + simulator); standalone simulator-specific tests as plain functions |\n"},"lastSynced":"2026-03-07T04:04:03.438Z","agentAnalysis":{"suitability":{"en":"Perfect for API Testing Agents needing to ensure simulator honesty and API consistency through abstract contract testing.","zh":"非常适合需要确保模拟器诚实性和API一致性的API测试代理，通过抽象契约测试。","ja":"シミュレータの誠実性とAPIの一貫性を確保する必要があるAPIテストエージェントに最適です。抽象的な契約テストを通じて。","ko":"시ミュ레이터의誠実性과 API 일관성을 보장해야 하는 API 테스트 에이전트에게 적합합니다. 추상적인 계약 테스트를 통해.","es":"Perfecto para Agentes de Pruebas de API que necesitan garantizar la honestidad del simulador y la coherencia de la API a través de pruebas de contrato abstractas.","fr":"Parfait pour les agents de test d''API ayant besoin de garantir l''honnêteté du simulateur et la cohérence de l''API via des tests de contrat abstraits.","de":"Perfekt für API-Testagenten, die die Ehrlichkeit des Simulators und die Konsistenz der API durch abstrakte Vertragstests sicherstellen müssen.","pt":"Perfeito para agentes de teste de API que precisam garantir a honestidade do simulador e a consistência da API por meio de teste de contrato abstrato.","ru":"Идеально подходит для агентов тестирования API, которым необходимо обеспечить честность симулятора и согласованность API посредством абстрактного контрактного тестирования.","ar":"مثالي لعميل اختبار واجهة برمجة التطبيقات الذي يحتاج إلى ضمان صحة المحاكي وثبات واجهة برمجة التطبيقات من خلال اختبار العقد المجرد."},"recommendation":{"en":"Empowers agents to run abstract tests against both real adapters and simulators, ensuring identical behavior and detecting API changes or simulator drifts through Python''s abstract base classes (ABC) and contract testing libraries.","zh":"赋予代理运行抽象测试的能力，针对真实适配器和模拟器，确保行为的一致性，并通过Python的抽象基类（ABC）和契约测试库检测API更改或模拟器漂移。","ja":"エージェントに抽象的なテストを実行する能力を与え、実際のアダプターとシミュレータの両方に対して同一の動作を保証し、Pythonの抽象基底クラス（ABC）と契約テストライブラリを通じてAPIの変更やシミュレータのドリフトを検出します。","ko":"에이전트가 추상적인 테스트를 실행할 수 있는 능력을 부여하여 실제 어댑터와 시뮬레이터 모두에 대해 동일한 동작을 보장하고, Python의 추상 기본 클래스(ABC)와 계약 테스트 라이브러리를 통해 API 변경이나 시뮬레이터의漂移을 감지합니다.","es":"Habilita a los agentes a ejecutar pruebas abstractas tanto en adaptadores reales como en simuladores, garantizando un comportamiento idéntico y detectando cambios en la API o desviaciones en el simulador a través de las clases base abstractas de Python (ABC) y bibliotecas de pruebas de contrato.","fr":"Permet aux agents d''exécuter des tests abstraits à la fois sur des adaptateurs réels et des simulateurs, garantissant un comportement identique et détectant les modifications de l''API ou les dérives du simulateur via les classes de base abstraites Python (ABC) et les bibliothèques de tests de contrat.","de":"Ermächtigt die Agenten, abstrakte Tests sowohl gegen reale Adapter als auch gegen Simulatoren durchzuführen, wodurch ein identisches Verhalten sichergestellt und Änderungen an der API oder Abweichungen im Simulator mithilfe der abstrakten Basisklassen von Python (ABC) und Vertragstestbibliotheken erkannt werden.","pt":"Permite que os agentes executem testes abstratos contra adaptadores reais e simuladores, garantindo comportamento idêntico e detectando alterações na API ou deriva nos simuladores por meio de classes base abstratas do Python (ABC) e bibliotecas de teste de contrato.","ru":"Позволяет агентам запускать абстрактные тесты как для реальных адаптеров, так и для симуляторов, обеспечивая идентичное поведение и обнаруживая изменения API или отклонения симулятора с помощью абстрактных базовых классов Python (ABC) и библиотек контрактного тестирования.","ar":"يمكّن الوكيل من تشغيل الاختبارات المجردة على المحاكيات الفعلية وعلى المحاكيات، مما يضمن سلوكا متطابقة واكتشاف التغييرات في واجهة برمجة التطبيقات أو انحرافات المحاكي من خلال الفئات الأساسية المجردة في بايثون (ABC) ومكتبات اختبار العقد."},"useCases":{"en":["Automating contract testing for API adapters","Debugging simulator inconsistencies","Validating API behavior against contracts"],"zh":["为API适配器自动化契约测试","调试模拟器不一致性","验证API行为是否符合契约"],"ja":["APIアダプターの契約テストを自動化する","シミュレータの不一致性をデバッグする","契約に対するAPIの動作を検証する"],"ko":["API 어댑터의 계약 테스트를 자동화하는 것","시뮬레이터의 불일치성을 디버깅하는 것","계약에 대한 API 동작을 검증하는 것"],"es":["Automatización de pruebas de contrato para adaptadores de API","Depuración de inconsistencias del simulador","Validación del comportamiento de la API frente a contratos"],"fr":["Automatisation des tests de contrat pour les adaptateurs d''API","Débogage des incohérences du simulateur","Validation du comportement de l''API par rapport aux contrats"],"de":["Automatisierung von Vertragstests für API-Adapter","Fehlerbehebung bei Simulatorinkonsistenzen","Validierung des API-Verhaltens gegenüber Verträgen"],"pt":["Automatizar teste de contrato para adaptadores de API","Depurar inconsistências do simulador","Validar comportamento da API contra contratos"],"ru":["Автоматизировать контрактное тестирование для адаптеров API","Отлаживать несоответствия симулятора","Проверять поведение API на соответствие контрактам"],"ar":["أتمتة اختبار العقد للمحاكيات واجهة برمجة التطبيقات","تصحيح أخطاء عدم الاتساق في المحاكي","تحقق من سلوك واجهة برمجة التطبيقات مقابل العقود"]},"limitations":{"en":["Requires Python environment","Limited to adapters and simulators with compatible abstract test classes"],"zh":["需要Python环境","仅限于具有兼容抽象测试类的适配器和模拟器"],"ja":["Python環境が必要","互換性のある抽象テストクラスを持つアダプターとシミュレータに限定される"],"ko":["Python 환경이 필요","호환되는 추상 테스트 클래스를 가진 어댑터와 시뮬레이터에 한정"],"es":["Requiere un entorno de Python","Limitado a adaptadores y simuladores con clases de prueba abstractas compatibles"],"fr":["Nécessite un environnement Python","Limité aux adaptateurs et simulateurs avec des classes de test abstraites compatibles"],"de":["Benötigt eine Python-Umgebung","Begrenzt auf Adapter und Simulatoren mit kompatiblen abstrakten Testklassen"],"pt":["Requer ambiente Python","Limitado a adaptadores e simuladores com classes de teste abstratas compatíveis"],"ru":["Требуется среда Python","Ограничен адаптерами и симуляторами с совместимыми абстрактными классами тестирования"],"ar":["يتطلب بيئة بايثون","محدود بمحاكيات واجهة برمجة التطبيقات والمحاكيات ذات الفئات المجردة المتوافقة للاختبار"]},"version":4},"contentHash":"a3333cd0a5bbc2e8068faed3bbb1076b99ab8d37b0ec8ac2536a4ef6b16fbcce","qualityScore":33}');
