INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('martinsson/checkin-automation/adapter-contract-testing', 'adapter-contract-testing', 'martinsson', 'checkin-automation', 'community', 'adapter-contract-testing martinsson checkin-automation community adapter-contract-testing is a technique for keeping simulators honest by running abstract tests against both real adapters and simulators. It benefits developers by ensuring API consistency. 适配器契约测试是一种保持模拟器诚实的技术，使用抽象测试类来验证真实适配器和模拟器的行为一致性 適配器契約テストは、シミュレーターと実アダプターの動作の一致性を保つための技術です 어댑터 계약 테스트는 시뮬레이터와 실제 어댑터의 동작 일관성을 유지하기 위한 기술입니다 La técnica de testing de contrato de adaptador asegura la compatibilidad entre simuladores y APIs reales. Aprende a implementarla con Python La technique de testing de contrat d''adaptateur assure la compatibilité entre les simulateurs et les API réelles. Découvrez comment la mettre en œuvre avec Python Die Technik des Contract-Testings für Adapter stellt die Kompatibilität zwischen Simulatoren und echten APIs sicher. Erfahren Sie, wie Sie sie mit Python implementieren O teste de contrato de adaptador é uma técnica para manter simulações honestas, garantindo a compatibilidade entre adaptadores e simulações Тестирование контракта адаптера - это техника для поддержания честных симуляций, обеспечивающая совместимость между адаптерами и симуляциями اختبار عقد المُحول هو تقنية لضمان صحة المحاكاة، وضمان التوافق بين المُحول والمحاكاة how to use adapter-contract-testing adapter-contract-testing vs mocking adapter-contract-testing setup guide what is adapter-contract-testing adapter-contract-testing alternative adapter-contract-testing install adapter-contract-testing python adapter-contract-testing simulator validation adapter-contract-testing API testing 适配器契约测试 模拟器测试 真实适配器测试 Python测试 抽象测试类 contracts/foo_contract.py FooContract抽象类 Runs abstract test classes against both real adapters and simulators Ensures identical behavior between adapters and simulators Uses Python abstract base classes (ABC) for contract definition Supports testing of API changes and simulator drift Provides a canonical structure for contract testing Utilizes GitHub-hosted papers for technique documentation adapter-contract-testing is a software testing technique that validates the behavior of adapters and simulators by running the same abstract test class against both.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('atiilla/Claude-Pentest-Agent-Ecosystem/ioc', 'community', 'atiilla', 'Claude-Pentest-Agent-Ecosystem', 'atiilla/Claude-Pentest-Agent-Ecosystem', 'ioc', 0, 0, 33, '2026-03-01T21:51:31Z', '2026-03-07T04:08:04.812Z', '02d20b10b3123921f8db6225cd44845bc28a2f94eeca012fe7af2d9bf587e2eb', '{"id":"atiilla/Claude-Pentest-Agent-Ecosystem/ioc","name":"ioc","description":{"en":"The ioc skill is a comprehensive collection of security agents for red teaming, blue teaming, and security development operations, benefiting security professionals. It extracts and enriches indicators from various sources.","zh":"IOC是一种综合的安全代理集合，用于红队、蓝队和安全开发运维，能够提取和丰富指标","ja":"IOCは、レッドチーム、ブルーチーム、セキュリティ開発オペレーションに使用される、専門的なセキュリティエージェントのコレクションであり、指標を抽出し、豊富化することができます","ko":"IOC는 레드 팀, 블루 팀 및 보안 개발 운영을 위한 종합적인 보안 에이전트 모음으로 지표를 추출하고 풍부하게 할 수 있습니다","es":"IOC es una colección de agentes de seguridad especializados para red teaming, blue teaming y desarrollo de operaciones de seguridad","fr":"IOC est une collection d''agents de sécurité spécialisés pour le red teaming, le blue teaming et le développement d''opérations de sécurité","de":"IOC ist eine umfassende Sammlung von Sicherheitsagenten für Red Teaming, Blue Teaming und Sicherheitsentwicklungsoperationen","pt":"O agente IOC é uma coleção abrangente de agentes de segurança especializados para red teaming, blue teaming e operações de desenvolvimento de segurança.","ru":"Агент ИИ IOC - это комплексная коллекция специализированных агентов безопасности для красной команды, синей команды и операций по разработке безопасности.","ar":"وكيل IOC هو مجموعة شاملة من وكلاء الأمن المتخصصين للفريق الأحمر والفريق الأزرق وعمليات تطوير الأمن."},"seo":{"title":{"en":"ioc: Indicator of Compromise Extraction and Enrichment | ...","zh":"IOC_setup_guide","ja":"IOCセットアップガイド","ko":"IOC 설정 가이드","es":"Guía de configuración de IOC para seguridad cibernética","fr":"Guide de mise en place d''IOC pour la cybersécurité","de":"IOC-Setup-Leitfaden für Cyber-Sicherheit","pt":"Guia de Configuração IOC: Extração e Enriquecimento de In...","ru":"Настройка ИИ Агентов IOC: Извлечение и обогащение индикат...","ar":"دليل إعداد IOC: استخراج وتحسين المؤشرات"},"description":{"en":"Unlock the power of ioc with our comprehensive guide. Learn how to extract and enrich indicators from any source and boost your security operations today!","zh":"了解IOC的工作原理，包括从各种源提取和丰富指标，以及与威胁情报的关联","ja":"IOCのしくみを学び、様々なソースからの指標の抽出と豊富化、脅威インテリの関連付けについて","ko":"IOC의 작동 방식에 대해 알아보고 다양한 소스에서 지표를 추출하고 풍부하게 하는 방법 및 위협 인텔과 연관성에 대해","es":"Descubre cómo configurar y utilizar IOC para mejorar la seguridad cibernética con nuestra guía detallada","fr":"Découvrez comment configurer et utiliser IOC pour améliorer la cybersécurité avec notre guide détaillé","de":"Erfahren Sie, wie Sie IOC konfigurieren und verwenden, um die Cyber-Sicherheit zu verbessern, mit unserer detaillierten Anleitung","pt":"Aprenda a extrair e enriquecer indicadores de segurança com o agente IOC, incluindo tipos de IOC e enriquecimento com inteligência de ameaças.","ru":"Узнайте, как извлекать и обогащать индикаторы безопасности с помощью агента ИИ IOC, включая типы IOC и обогащение с помощью интеллекта угроз.","ar":"تعرف على كيفية استخراج وتحسين المؤشرات الأمنية باستخدام وكيل IOC ، بما في ذلك أنواع IOC وتحسينها بالاستخبارات المتنقلة."},"definition":{"en":"ioc is a specialized security agent for extracting and enriching indicators of compromise from reports, logs, and samples, normalizing and validating them for security operations.","zh":"IOC指标是从各种源提取和丰富的安全相关数据，包括IP、域名、URL、哈希等","ja":"IOC指標とは、様々なソースからのセキュリティ関連データの抽出と豊富化されたものであり、IP、ドメイン、URL、ハッシュ等を含みます","ko":"IOC 지표는 다양한 소스에서 추출 및 풍부화된 보안 관련 데이터로 IP, 도메인, URL, 해시 등을 포함합니다","es":"IOC significa Indicadores de Compromiso, una tecnología que extrae y enriquece indicadores de seguridad","fr":"IOC signifie Indicateurs de Compromission, une technologie qui extrait et enrichit les indicateurs de sécurité","de":"IOC bedeutet Indikatoren für Kompromittierung, eine Technologie, die Sicherheitsindikatoren extrahiert und anreichert","pt":"O que é IOC? É um agente de segurança que extrai e enriquece indicadores de segurança de qualquer fonte.","ru":"Что такое ИИ IOC? Это агент безопасности, который извлекает и обогащает индикаторы безопасности из любого источника.","ar":"ما هو وكيل IOC؟ هو وكيل أمن يستخرج ويحسن المؤشرات الأمنية من أي مصدر."},"features":{"en":["Extracts IOCs from reports, logs, and samples","Normalizes and validates indicators using WHOIS and threat intel from VT and AbuseIPDB","Enriches indicators with IPv4/IPv6, domains, URLs, hashes, and other metadata","Correlates infrastructure and exports in multiple formats","Supports specific IOC types such as MD5, SHA1, and SHA256 hashes"],"zh":["从各种源提取IOC指标，包括报告、日志、样本","对指标进行标准化和验证","使用威胁情报（VT、AbuseIPDB、WHOIS）对指标进行丰富化","支持IPv4/IPv6、域名、URL、哈希（MD5/SHA1/SHA256）等指标类型","能够将指标导出为多种格式"],"ja":["レポート、ログ、サンプル等の様々なソースからのIOC指標の抽出","指標の標準化と検証","脅威インテリ（VT、AbuseIPDB、WHOIS）を使用した指標の豊富化","IPv4/IPv6、ドメイン、URL、ハッシュ（MD5/SHA1/SHA256）等の指標タイプをサポート","指標を複数の形式でエクスポート可能"],"ko":["다양한 소스(报告, 로그, 샘플)에서 IOC 지표 추출","지표의 표준화 및 검증","위협 인텔(VT, AbuseIPDB, WHOIS)을 사용한 지표의 풍부화","IPv4/IPv6, 도메인, URL, 해시(MD5/SHA1/SHA256) 등 지표 유형 지원","지표를 여러 형식으로 내보내기 가능"],"es":["Extracción de IOCs de cualquier fuente","Normalización y validación de indicadores"," Enriquecimiento con inteligencia de amenazas","Correlación de infraestructura","Exportación en múltiples formatos"],"fr":["Extraction d''IOC à partir de n''importe quelle source","Normalisation et validation des indicateurs","Enrichissement avec l''intelligence des menaces","Corrélation d''infrastructure","Exportation dans plusieurs formats"],"de":["Extraktion von IOCs aus beliebigen Quellen","Normalisierung und Validierung von Indikatoren","Anreicherung mit Bedrohungsintelligenz","Korrelation von Infrastruktur","Export in mehreren Formaten"],"pt":["Extração de indicadores de segurança de qualquer fonte","Normalização e validação de indicadores","Enriquecimento com inteligência de ameaças","Correlação de infraestrutura","Exportação em múltiplos formatos"],"ru":["Извлечение индикаторов безопасности из любого источника","Нормализация и валидация индикаторов","Обогащение с помощью интеллекта угроз","Корреляция инфраструктуры","Экспорт в нескольких форматах"],"ar":["استخراج المؤشرات الأمنية من أي مصدر","تطبيع وتأكيد المؤشرات","تحسين بالاستخبارات المتنقلة","ارتباط البنية التحتية","تصدير بالصيغ المتعددة"]},"keywords":{"en":["how to use ioc","ioc alternative","ioc setup guide","what is ioc","ioc vs threat intelligence","ioc install","ioc security operations","ioc extraction and enrichment","ioc indicator of compromise"],"zh":["IOC指标","安全代理","红队","蓝队","安全开发运维","威胁情报","VT","AbuseIPDB","WHOIS"],"ja":["IOC指標","セキュリティエージェント","レッドチーム","ブルーチーム","セキュリティ開発オペレーション","脅威インテリ","VT","AbuseIPDB","WHOIS"],"ko":["IOC 지표","보안 에이전트","레드 팀","블루 팀","보안 개발 운영","위협 인텔","VT","AbuseIPDB","WHOIS"],"es":["IOC","seguridad cibernética","red teaming","blue teaming","desarrollo de operaciones de seguridad","indicadores de compromiso","inteligencia de amenazas","correlación de infraestructura"],"fr":["IOC","cybersécurité","red teaming","blue teaming","développement d''opérations de sécurité","indicateurs de compromission","intelligence des menaces","corrélation d''infrastructure"],"de":["IOC","Cyber-Sicherheit","Red Teaming","Blue Teaming","Sicherheitsentwicklungsoperationen","Indikatoren für Kompromittierung","Bedrohungsintelligenz","Korrelation von Infrastruktur"],"pt":["IOC","segurança cibernética","inteligência de ameaças","red teaming","blue teaming","desenvolvimento de segurança","extração de indicadores","enriquecimento de indicadores"],"ru":["ИИ IOC","кибербезопасность","интеллект угроз","красная команда","синяя команда","разработка безопасности","извлечение индикаторов","обогащение индикаторов"],"ar":["وكيل IOC","أمن السيبراني","استخبارات المتنقلة","الفريق الأحمر","الفريق الأزرق","تطوير الأمن","استخراج المؤشرات","تحسين المؤشرات"]}},"owner":"atiilla","repo":"Claude-Pentest-Agent-Ecosystem","repoPath":"atiilla/Claude-Pentest-Agent-Ecosystem","stars":0,"forks":0,"updatedAt":"2026-03-01T21:51:31Z","topics":[],"category":"community","skillMd":{"name":"ioc","description":"IOC extraction, enrichment, and threat intelligence correlation","bodyPreview":"# IOC Intelligence\n\nExtract and enrich indicators:\n- Extract IOCs from any source (reports, logs, samples)\n- Normalize and validate indicators\n- Enrich with threat intel (VT, AbuseIPDB, WHOIS)\n- Correlate infrastructure\n- Export in multiple formats\n\n## IOC Types\nIPv4/IPv6, domains, URLs, hashes (MD5/SHA1/SHA256), emails, registry keys, file paths, mutexes\n\n## Required Context\n1. **Source**: File path, text, or paste content\n2. **IOC Types**: All or specific types\n3. **Enrichment**: Basic (WHOIS)","body":"# IOC Intelligence\n\nExtract and enrich indicators:\n- Extract IOCs from any source (reports, logs, samples)\n- Normalize and validate indicators\n- Enrich with threat intel (VT, AbuseIPDB, WHOIS)\n- Correlate infrastructure\n- Export in multiple formats\n\n## IOC Types\nIPv4/IPv6, domains, URLs, hashes (MD5/SHA1/SHA256), emails, registry keys, file paths, mutexes\n\n## Required Context\n1. **Source**: File path, text, or paste content\n2. **IOC Types**: All or specific types\n3. **Enrichment**: Basic (WHOIS) or full (VT, Shodan)\n4. **Output**: JSON, CSV, STIX, MISP\n\n## Example\n```\n/ioc\nSource: threat_report.pdf\nEnrichment: Full\nOutput: JSON\n```\n"},"lastSynced":"2026-03-07T04:08:04.812Z","agentAnalysis":{"suitability":{"en":"Perfect for Cybersecurity Agents needing advanced Indicator of Compromise (IOC) extraction and enrichment capabilities.","zh":"非常适合需要高级指标提取和增强功能的网络安全代理","ja":"サイバーセキュリティエージェントが高度なインシデント情報の抽出と強化機能を必要とする場合に最適","ko":"고급 지표 추출 및 강화 기능이 필요한 사이버 보안 에이전트에 적합","es":"Perfecto para Agentes de Ciberseguridad que necesitan capacidades avanzadas de extracción y enriquecimiento de Indicadores de Compromiso (IOC).","fr":"Parfait pour les agents de cybersécurité ayant besoin de capacités avancées d''extraction et d''enrichissement d''Indicateurs de Compromission (IOC).","de":"Perfekt für Cybersicherheitsagenten, die erweiterte Funktionen zur Extraktion und Anreicherung von Kompromissindikatoren (IOC) benötigen.","pt":"Perfeito para Agentes de Cibersegurança que necessitam de capacidades avançadas de extração e enriquecimento de Indicadores de Comprometimento (IOC).","ru":"Идеально подходит для агентов кибербезопасности, которым необходимы расширенные возможности извлечения и обогащения индикаторов компрометации (IOC).","ar":"مثالي لوكلاء الأمن السيبراني الذين يحتاجون إلى قدرات متقدمة لاستخراج وتحسين مؤشرات التعرض (IOC)."},"recommendation":{"en":"Empowers agents to extract and enrich IOCs from various sources, including reports, logs, and samples, utilizing threat intel from VT, AbuseIPDB, and WHOIS, and correlating infrastructure for comprehensive security analysis.","zh":"赋予代理提取和增强来自各种来源的指标，包括报告、日志和样本，利用来自VT、AbuseIPDB和WHOIS的威胁情报，并用于综合安全分析的相关基础设施","ja":"エージェントがVT、AbuseIPDB、WHOISからの脅威インテリジェンスを利用して、レポート、ログ、サンプルなどの様々なソースからのインシデント情報を抽出、強化し、包括的なセキュリティ分析のための関連インフラストラクチャを関連付けることを可能にします","ko":"에이전트가 다양한 소스(보고서, 로그, 샘플 등)에서 IOC를 추출하고 강화하며, VT, AbuseIPDB 및 WHOIS의 위협 정보를 사용하여 종합적인 보안 분석을 위한 관련 기반 시설을 상호 연결할 수 있도록 합니다","es":"Habilita a los agentes a extraer y enriquecer IOCs de varias fuentes, incluyendo informes, registros y muestras, utilizando inteligencia de amenazas de VT, AbuseIPDB y WHOIS, y correlacionando infraestructura para un análisis de seguridad integral.","fr":"Permet aux agents d''extraire et d''enrichir les IOC à partir de différentes sources, notamment des rapports, des journaux et des échantillons, en utilisant les informations de menace de VT, AbuseIPDB et WHOIS, et en corrélant les infrastructures pour une analyse de sécurité globale.","de":"Ermächtigt Agenten, IOCs aus verschiedenen Quellen wie Berichten, Protokollen und Proben zu extrahieren und zu bereichern, indem sie Bedrohungsdaten von VT, AbuseIPDB und WHOIS nutzen und Infrastrukturen korrelieren, um eine umfassende Sicherheitsanalyse durchzuführen.","pt":"Habilita agentes a extrair e enriquecer IOCs de várias fontes, incluindo relatórios, logs e amostras, utilizando inteligência de ameaças do VT, AbuseIPDB e WHOIS, e correlacionando infraestrutura para análise de segurança abrangente.","ru":"Предоставляет агентам возможность извлекать и обогащать IOC из различных источников, включая отчеты, журналы и образцы, используя интеллект угроз от VT, AbuseIPDB и WHOIS, и коррелируя инфраструктуру для всестороннего анализа безопасности.","ar":"يمنح الوكلاء القدرة على استخراج وتحسين مؤشرات التعرض من مصادر مختلفة، بما في ذلك التقارير والسجلات والعينات، وذلك باستخدام متطلبات الذكاء التهديدي من VT وAbuseIPDB وWHOIS، وتوضيح البنية التحتية لتحليل أمني شامل."},"useCases":{"en":["Extracting IOCs from threat intelligence reports","Enriching indicators with threat intel for enhanced security context","Correlating infrastructure for advanced threat hunting and incident response"],"zh":["从威胁情报报告中提取IOC","使用威胁情报增强指标以获得增强的安全背景","相关基础设施用于高级威胁狩猎和事件响应"],"ja":["脅威インテリジェンスレポートからのインシデント情報の抽出","脅威インテリジェンスを使用した指標の強化によるセキュリティコンテキストの強化","高級な脅威ハンティングとインシデントレスポンスのための関連インフラストラクチャの関連付け"],"ko":["위협 정보 보고서에서 IOC 추출","위협 정보를 사용하여 지표 강화 및 보안 contexto 향상","고급 위협 사냥 및 인시던트 대응을 위한 관련 기반 시설 상호 연결"],"es":["Extraer IOCs de informes de inteligencia de amenazas","Enriquecer indicadores con inteligencia de amenazas para un contexto de seguridad mejorado","Correlacionar infraestructura para una caza de amenazas avanzada y respuesta a incidentes"],"fr":["Extraire les IOC des rapports d''intelligence de menace","Enrichir les indicateurs avec l''intelligence de menace pour un contexte de sécurité amélioré","Corréler les infrastructures pour une chasse aux menaces avancée et une réponse aux incidents"],"de":["Extrahieren von IOCs aus Bedrohungsberichten","Anreichern von Indikatoren mit Bedrohungsdaten für einen verbesserten Sicherheitskontext","Korrelieren von Infrastrukturen für fortschrittliches Bedrohungsjagen und Reaktion auf Vorfälle"],"pt":["Extração de IOCs de relatórios de inteligência de ameaças","Enriquecimento de indicadores com inteligência de ameaças para contexto de segurança melhorado","Correlação de infraestrutura para caça de ameaças avançada e resposta a incidentes"],"ru":["Извлечение IOC из отчетов об интеллекте угроз","Обогащение индикаторов интеллектом угроз для улучшения контекста безопасности","Корреляция инфраструктуры для расширенной охоты на угрозы и реагирования на инциденты"],"ar":["استخراج مؤشرات التعرض من تقارير ذكاء التهديدات","تحسين المؤشرات بذكاء التهديدات لسياق أمني محسّن","رسم العلاقة بين البنية التحتية لصيد التهديدات المتقدمة والاستجابة للحوادث"]},"limitations":{"en":["Requires source input (file path, text, or paste content)","Limited to specific IOC types (IPv4/IPv6, domains, URLs, hashes, emails, registry keys, file paths, mutexes)"],"zh":["需要源输入（文件路径、文本或粘贴内容）","仅限于特定的IOC类型（IPv4/IPv6、域名、URL、哈希、电子邮件、注册表键、文件路径、互斥体）"],"ja":["入力元（ファイルパス、テキスト、またはペーストコンテンツ）が必要","特定のIOCタイプ（IPv4/IPv6、ドメイン、URL、ハッシュ、メール、レジストリキー、ファイルパス、ミューテックス）のみに限定"],"ko":["소스 입력(파일 경로, 텍스트 또는 붙여넣기 내용) 필요","특정 IOC 유형(IPv4/IPv6, 도메인, URL, 해시, 이메일, 레지스트리 키, 파일 경로, 뮤텍스)으로 제한"],"es":["Requiere entrada de fuente (ruta de archivo, texto o contenido de pegado)","Limitado a tipos de IOC específicos (IPv4/IPv6, dominios, URLs, hashes, correos electrónicos, claves de registro, rutas de archivo, mutex)"],"fr":["Nécessite une entrée de source (chemin de fichier, texte ou contenu collé)","Limité à des types d''IOC spécifiques (IPv4/IPv6, domaines, URL, hachages, courriels, clés de registre, chemins de fichier, mutex)"],"de":["Benötigt Quelleneingabe (Dateipfad, Text oder Inhalt zum Einfügen)","Begrenzt auf bestimmte IOC-Typen (IPv4/IPv6, Domänen, URLs, Hashes, E-Mails, Registrierungsschlüssel, Dateipfade, Mutex)"],"pt":["Requer entrada de origem (caminho do arquivo, texto ou conteúdo colado)","Limitado a tipos de IOC específicos (IPv4/IPv6, domínios, URLs, hashes, emails, chaves de registro, caminhos de arquivos, mutexes)"],"ru":["Требуется входной ввод (путь к файлу, текст или содержимое вставки)","Ограничен конкретными типами IOC (IPv4/IPv6, домены, URL, хеши, электронные почты, ключи реестра, пути к файлам, мьютексы)"],"ar":["يتطلب إدخال مصدر (مسار الملف أو النص أو محتوى اللصق)","محدود بنوع معين من مؤشرات التعرض (IPv4/IPv6، نطاقات، عناوين URL، وجوه التجزئة، البريد الإلكتروني، مفاتيح السجل، مسارات الملفات، المفتاح المتعدد)"]},"version":4},"contentHash":"02d20b10b3123921f8db6225cd44845bc28a2f94eeca012fe7af2d9bf587e2eb","qualityScore":33}');
