INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('atiilla/Claude-Pentest-Agent-Ecosystem/ioc', 'ioc', 'atiilla', 'Claude-Pentest-Agent-Ecosystem', 'community', 'ioc atiilla Claude-Pentest-Agent-Ecosystem community The ioc skill is a comprehensive collection of security agents for red teaming, blue teaming, and security development operations, benefiting security professionals. It extracts and enriches indicators from various sources. IOC是一种综合的安全代理集合，用于红队、蓝队和安全开发运维，能够提取和丰富指标 IOCは、レッドチーム、ブルーチーム、セキュリティ開発オペレーションに使用される、専門的なセキュリティエージェントのコレクションであり、指標を抽出し、豊富化することができます IOC는 레드 팀, 블루 팀 및 보안 개발 운영을 위한 종합적인 보안 에이전트 모음으로 지표를 추출하고 풍부하게 할 수 있습니다 IOC es una colección de agentes de seguridad especializados para red teaming, blue teaming y desarrollo de operaciones de seguridad IOC est une collection d''agents de sécurité spécialisés pour le red teaming, le blue teaming et le développement d''opérations de sécurité IOC ist eine umfassende Sammlung von Sicherheitsagenten für Red Teaming, Blue Teaming und Sicherheitsentwicklungsoperationen O agente IOC é uma coleção abrangente de agentes de segurança especializados para red teaming, blue teaming e operações de desenvolvimento de segurança. Агент ИИ IOC - это комплексная коллекция специализированных агентов безопасности для красной команды, синей команды и операций по разработке безопасности. وكيل IOC هو مجموعة شاملة من وكلاء الأمن المتخصصين للفريق الأحمر والفريق الأزرق وعمليات تطوير الأمن. how to use ioc ioc alternative ioc setup guide what is ioc ioc vs threat intelligence ioc install ioc security operations ioc extraction and enrichment ioc indicator of compromise IOC指标 安全代理 红队 蓝队 安全开发运维 威胁情报 VT AbuseIPDB WHOIS Extracts IOCs from reports, logs, and samples Normalizes and validates indicators using WHOIS and threat intel from VT and AbuseIPDB Enriches indicators with IPv4/IPv6, domains, URLs, hashes, and other metadata Correlates infrastructure and exports in multiple formats Supports specific IOC types such as MD5, SHA1, and SHA256 hashes ioc is a specialized security agent for extracting and enriching indicators of compromise from reports, logs, and samples, normalizing and validating them for security operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('artmsilva/stitches-rsc/create-theme', 'community', 'artmsilva', 'stitches-rsc', 'artmsilva/stitches-rsc', 'create-theme', 0, 0, 33, '2026-01-28T00:26:57Z', '2026-03-07T04:09:12.669Z', '7ddf5072c22e565797d1f96017f0d65d6bb6eadaa06d370769eed71c8a4cb666', '{"id":"artmsilva/stitches-rsc/create-theme","name":"create-theme","description":{"en":"The create-theme skill generates properly structured and typed theme configurations for Stitches RSC, benefiting React developers. It enables the creation of design tokens organized by scale.","zh":"创建主题配置，包括设计令牌、颜色、间距和字体大小等，用于 Stitches RSC","ja":"Stitches RSC 用のテーマ構成を作成します。デザイン トークン、色、スペース、フォント サイズなどを含みます","ko":"Stitches RSC용 테마 구성 생성, 디자인 토큰, 색상, 간격 및 글꼴 크기 포함","es":"Create-theme es una herramienta para crear temas personalizados para Stitches RSC, compatible con React Server Components","fr":"Create-theme est un outil pour créer des thèmes personnalisés pour Stitches RSC, compatible avec React Server Components","de":"Create-theme ist ein Tool zum Erstellen benutzerdefinierter Themes für Stitches RSC, kompatibel mit React Server Components","pt":"O Create-Theme é uma ferramenta para criar temas personalizados para Stitches RSC, incluindo design tokens e escalas","ru":"Create-Theme - это инструмент для создания тем для Stitches RSC, включая токены дизайна и масштабы","ar":"Create-Theme هو أداة لإنشاء Темات مخصصة ل Stitches RSC، بما في ذلك رموز التصميم والاسكاليات"},"seo":{"title":{"en":"create-theme: Zero-Runtime Stitches.js Setup Guide | AI A...","zh":"创建主题设置指南 - Zero-runtime Stitches.js 替代品","ja":"テーマ作成ガイド - React サーバーコンポーネント用の Stitches.js 代替","ko":"테마 생성 가이드 - Zero-runtime Stitches.js 대체 React 서버 컴포넌트","es":"Guía de configuración de create-theme para Stitches RSC","fr":"Guide de mise en place de create-theme pour Stitches RSC","de":"Einrichtungsleitfaden für create-th