INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('artmsilva/stitches-rsc/create-theme', 'create-theme', 'artmsilva', 'stitches-rsc', 'community', 'create-theme artmsilva stitches-rsc community The create-theme skill generates properly structured and typed theme configurations for Stitches RSC, benefiting React developers. It enables the creation of design tokens organized by scale. 创建主题配置，包括设计令牌、颜色、间距和字体大小等，用于 Stitches RSC Stitches RSC 用のテーマ構成を作成します。デザイン トークン、色、スペース、フォント サイズなどを含みます Stitches RSC용 테마 구성 생성, 디자인 토큰, 색상, 간격 및 글꼴 크기 포함 Create-theme es una herramienta para crear temas personalizados para Stitches RSC, compatible con React Server Components Create-theme est un outil pour créer des thèmes personnalisés pour Stitches RSC, compatible avec React Server Components Create-theme ist ein Tool zum Erstellen benutzerdefinierter Themes für Stitches RSC, kompatibel mit React Server Components O Create-Theme é uma ferramenta para criar temas personalizados para Stitches RSC, incluindo design tokens e escalas Create-Theme - это инструмент для создания тем для Stitches RSC, включая токены дизайна и масштабы Create-Theme هو أداة لإنشاء Темات مخصصة ل Stitches RSC، بما في ذلك رموز التصميم والاسكاليات how to use create-theme create-theme alternative create-theme vs Stitches.js create-theme install create-theme setup guide what is create-theme create-theme for React Server Components Stitches RSC theme configuration zero-runtime theming for React Stitches RSC 创建主题 零运行时 React 服务器组件 设计令牌 颜色 间距 字体大小 AIエージェント 前端开发 Generates theme configurations using the createStitches function from @stitches-rsc/react Supports design tokens organized by scale, including colors, space, fontSizes, and fonts Creates properly structured and typed theme configurations for Stitches RSC Enables the configuration of design tokens using TypeScript Integrates with React Server Components for efficient theming create-theme is a zero-runtime Stitches.js replacement for React Server Components, used for generating theme configurations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tongsh6/idea-refinery/manage-gitflow-release', 'community', 'tongsh6', 'idea-refinery', 'tongsh6/idea-refinery', 'manage-gitflow-release', 0, 0, 33, '2026-03-03T19:40:42Z', '2026-03-07T04:12:08.634Z', '322e1db15f9325e9fc200ea25f705d5c9b321b6581e2528c54e4eef4f0a5db7c', '{"id":"tongsh6/idea-refinery/manage-gitflow-release","name":"manage-gitflow-release","description":{"en":"The manage-gitflow-release skill automates Git Flow releases using python3 scripts, benefiting developers by streamlining their workflow.","zh":"使用 Git Flow 管理发布版本，包括删除合并的功能分支和保留发布分支","ja":"Git Flow リリースを管理するためのスクリプトを使用し、プロジェクトの効率を上げる","ko":"Git Flow 릴리즈 관리를 위한 스크립트를 사용하여 프로젝트의 효율성을 높여보세요","es":"Manage-gitflow-release es una herramienta para automatizar flujos de trabajo de GitFlow con scripts de Python. Utiliza el comando gitflow_release.py para gestionar tus releases","fr":"Manage-gitflow-release est un outil pour automatiser les flux de travail GitFlow avec des scripts Python. Utilisez la commande gitflow_release.py pour gérer vos versions","de":"Manage-gitflow-release ist ein Tool zur Automatisierung von GitFlow-Arbeitsabläufen mit Python-Skripten. Verwenden Sie den Befehl gitflow_release.py, um Ihre Releases zu verwalten","pt":"O manage-gitflow-release é uma ferramenta para gerenciar releases do Gitflow. Use o script para automatizar tarefas","ru":"Manage-gitflow-release - инструмент для управления выпусками Gitflow. Используйте скрипт для автоматизации задач","ar":"manage-gitflow-release هو أداة لإدارة الإصدارات في Gitflow. استخدم السكريبت لتحقيق أقصى استفادة"},"seo":{"title":{"en":"manage-gitflow-release: Git Flow Automation Setup Guide |...","zh":"管理 Git Flow 发布的最佳实践","ja":"Git Flow リリースを管理するためのセットアップガイド - AIエージェント","ko":"Git Flow 릴리즈 관리를 위한 전문가 가이드","es":"Guía de configuración para manage-gitflow-release con Git...","fr":"Configurer manage-gitflow-release pour une gestion effica...","de":"Einrichtung von manage-gitflow-release für GitFlow-Verwal...","pt":"Guia de Configuração do manage-gitflow-release para Desen...","ru":"Настройка manage-gitflow-release: Руководство для Разрабо...","ar":"دليل إعداد manage-gitflow-release للاستفادة القصوى من أدو..."},"description":{"en":"Discover how to automate Git Flow releases with manage-gitflow-release. Learn to use python3 scripts and optimize your workflow today!","zh":"了解如何使用 Git Flow 管理发布版本，包括删除合并的功能分支和保留发布分支","ja":"Git Flow リリースを管理するためのテクニックを学び、プロジェクトの効率を上げる - AIエージェント","ko":"Git Flow 릴리즈 관리를 위한 전문가 기술을 배워 보세요","es":"Aprende a utilizar manage-gitflow-release para automatizar tus flujos de trabajo de GitFlow con scripts de Python","fr":"Découvrez comment utiliser manage-gitflow-release pour automatiser vos flux de travail GitFlow avec des scripts Python","de":"Erfahren Sie, wie Sie manage-gitflow-release verwenden, um Ihre GitFlow-Arbeitsabläufe mit Python-Skripten zu automatisieren","pt":"Aprenda a usar o script de release do Gitflow para gerenciar suas versões com eficiência. Descubra como configurar o manage-gitflow-release","ru":"Узнайте, как использовать скрипт Gitflow для управления выпусками. Настройка manage-gitflow-release для ИИ Агентов","ar":"اكتشف كيفية استخدام سكريبت إصدار Gitflow لتحقيق أقصى استفادة من أدوات الـ AI. دليل على إعداد manage-gitflow-release"},"definition":{"en":"manage-gitflow-release is a skill that automates Git Flow releases using a python3 script, managing feature and release branches.","zh":"Git Flow 发布管理是一种使用 Git Flow 工作流管理发布版本的方法","ja":"Git Flow リリース管理とは、Git Flow ワークフローを使用してリリースバージョンを管理する方法です - AIエージェント","ko":"Git Flow 릴리즈 관리는 Git Flow 워크플로우를 사용하여 릴리즈 버전을 관리하는 방법입니다","es":"Manage-gitflow-release es una herramienta de automatización para GitFlow que utiliza scripts de Python","fr":"Manage-gitflow-release est un outil d''automatisation pour GitFlow qui utilise des scripts Python","de":"Manage-gitflow-release ist ein Automatisierungstool für GitFlow, das Python-Skripte verwendet","pt":"O manage-gitflow-release é uma ferramenta de linha de comando para gerenciar releases do Gitflow","ru":"Manage-gitflow-release - это консольная утилита для управления выпусками Gitflow","ar":"manage-gitflow-release هو أداة سطر الأوامر لإدارة الإصدارات في Gitflow"},"features":{"en":["Uses python3 scripts to automate Git Flow releases","Deletes merged feature/* branches","Keeps release/* branches","Utilizes the gitflow_release.py script for automation","Supports custom flags for flexible workflow management","Runs via the command line using bash"],"zh":["使用 Python 脚本管理发布版本","删除合并的功能分支","保留发布分支","使用 Git Flow 工作流管理项目","支持命令行接口（CLI）"],"ja":["Python スクリプトを使用してリリースバージョンを管理する","マージされた機能ブランチを削除する","リリースブランチを保持する","Git Flow ワークフローを使用してプロジェクトを管理する","コマンドラインインターフェース（CLI）をサポートする"],"ko":["Python 스크립트를 사용하여 릴리즈 버전을 관리합니다","병합된 기능 브랜치를 삭제합니다","릴리즈 브랜치를保持합니다","Git Flow 워크플로우를 사용하여 프로젝트를 관리합니다","명령줄 인터페이스（CLI）를 지원합니다"],"es":["Automatización de flujos de trabajo de GitFlow","Uso de scripts de Python para gestionar releases","Eliminación de ramas feature/* fusionadas","Mantenimiento de ramas release/*","Integración con herramientas de desarrollo como Git","Compatibilidad con línea de comandos (CLI) para ejecutar scripts"],"fr":["Automatisation des flux de travail GitFlow","Utilisation de scripts Python pour gérer les versions","Suppression des branches feature/* fusionnées","Maintenance des branches release/*","Intégration avec des outils de développement comme Git","Compatibilité avec la ligne de commande (CLI) pour exécuter des scripts"],"de":["Automatisierung von GitFlow-Arbeitsabläufen","Verwendung von Python-Skripten zur Verwaltung von Releases","Löschung von fusionierten feature/*-Zweigen","Beibehaltung von release/*-Zweigen","Integration mit Entwicklungstools wie Git","Kompatibilität mit der Befehlszeile (CLI) zur Ausführung von Skripten"],"pt":["Uso de script de release do Gitflow","Suporte para ações de release personalizadas","Exclusão automática de branches de recurso mesclados","Manutenção de branches de release","Integração com o Python 3","Uso de flags para personalizar o comportamento do script"],"ru":["Использование скрипта выпуска Gitflow","Поддержка пользовательских действий выпуска","Автоматическое удаление слитых веток функций","Сохранение веток выпуска","Интеграция с Python 3","Использование флагов для настройки поведения скрипта"],"ar":["استخدام سكريبت إصدار Gitflow","دعم لإجراءات الإصدار المخصصة","حذف تلقائي للفروع المزودة","الحفاظ على فروع الإصدار","التكامل مع بايثون 3","استخدام الأعلام لتحقيق أقصى استفادة من سلوك السكريبت"]},"keywords":{"en":["how to use manage-gitflow-release","manage-gitflow-release setup guide","git flow automation tools","manage-gitflow-release alternative","manage-gitflow-release vs gitflow","automating git flow releases","manage-gitflow-release install","gitflow release management","what is manage-gitflow-release"],"zh":["Git Flow 发布管理","Git Flow 工作流","Python 脚本","命令行接口","功能分支管理","发布分支管理","AI 工具","代码管理"],"ja":["Git Flow リリース管理","Git Flow ワークフロー","Python スクリプト","コマンドラインインターフェース","機能ブランチ管理","リリースブランチ管理","AIエージェント","コード管理"],"ko":["Git Flow 릴리즈 관리","Git Flow 워크플로우","Python 스크립트","명령줄 인터페이스","기능 브랜치 관리","릴리즈 브랜치 관리","AI 도구","코드 관리"],"es":["manage-gitflow-release","gitflow","automatización de flujos de trabajo","scripts de python","gestión de releases","herramientas de desarrollo","git","CLI","línea de comandos"],"fr":["manage-gitflow-release","gitflow","automatisation des flux de travail","scripts python","gestion des versions","outils de développement","git","CLI","ligne de commande"],"de":["manage-gitflow-release","gitflow","automatisierung von arbeitsabläufen","python-skripte","verwaltung von releases","entwicklungstools","git","CLI","befehlszeile"],"pt":["manage-gitflow-release","gitflow release","script de release","gerenciamento de versões","ferramentas de desenvolvimento","python 3","linha de comando","desenvolvedores","guias de configuração"],"ru":["manage-gitflow-release","gitflow выпуск","скрипт выпуска","управление версиями","инструменты разработки","python 3","консоль","разработчики","руководства по настройке","ИИ Агенты"],"ar":["manage-gitflow-release","إصدار gitflow","سكريبت إصدار","إدارة الإصدارات","أدوات التطوير","بايثون 3","سطر الأوامر","مطورون","دلائل الإعداد","أدوات الـ AI"]}},"owner":"tongsh6","repo":"idea-refinery","repoPath":"tongsh6/idea-refinery","stars":0,"forks":0,"updatedAt":"2026-03-03T19:40:42Z","topics":[],"category":"community","skillMd":{"name":"manage-gitflow-release","description":"Manage project GitFlow branch operations with main -> feature -> develop -> release -> main.","bodyPreview":"Use project script:\n\n```bash\npython3 scripts/release/gitflow_release.py <action> [flags]\n```\n\nPolicy:\n\n- delete merged `feature/*`\n- keep `release/*`","body":"Use project script:\n\n```bash\npython3 scripts/release/gitflow_release.py <action> [flags]\n```\n\nPolicy:\n\n- delete merged `feature/*`\n- keep `release/*`\n"},"lastSynced":"2026-03-07T04:12:08.634Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents leveraging Python3 for streamlined Git Flow release management.","zh":"适用于利用Python3进行流畅的Git Flow发布管理的开发代理。","ja":"Python3を使用したスムーズなGit Flowリリース管理に最適化された開発エージェントに適しています。","ko":"Python3를 사용하여 효율적인 Git Flow 릴리스 관리를하는 개발 에이전트에게 적합합니다.","es":"Ideal para agentes de desarrollo que utilizan Python3 para una gestión de versiones de Git Flow optimizada.","fr":"Idéal pour les agents de développement qui utilisent Python3 pour une gestion de version de Git Flow optimisée.","de":"Ideal für Entwicklungsmittel, die Python3 für eine optimierte Git-Flow-Veröffentlichungsverwaltung nutzen.","pt":"Ideal para Agentes de Desenvolvimento que utilizam Python3 para gerenciamento de lançamento de Git Flow simplificado.","ru":"Идеально подходит для агентов разработки, использующих Python3 для упрощенного управления выпусками Git Flow.","ar":"مثالي لعميل التطوير الذين يستخدمون Python3 لإدارة إصدار Git Flow المُبسّط."},"recommendation":{"en":"Empowers agents to automate Git Flow releases using python3 scripts, streamlining workflow with features like deleting merged feature branches and keeping release branches, all while utilizing Git Flow protocols and python3 scripting.","zh":"使代理能够使用python3脚本自动执行Git Flow发布，通过删除合并的功能分支和保留发布分支等功能来简化工作流，同时利用Git Flow协议和python3脚本。","ja":"エージェントがpython3スクリプトを使用してGit Flowリリースを自動化できるようにし、Git Flowプロトコルとpython3スクリプトを利用しながら、結合された機能ブランチの削除やリリースブランチの保留などの機能でワークフローを簡素化します。","ko":"에이전트가 python3 스크립트를 사용하여 Git Flow 릴리스를 자동화할 수 있도록 하여 Git Flow 프로토콜 및 python3 스크립트를 사용하여 워크플ロー를簡素화합니다. 기능 분기 삭제 및 릴리스 분기 보존 등의 기능을 제공합니다.","es":"Permite a los agentes automatizar las versiones de Git Flow utilizando scripts de python3, simplificando el flujo de trabajo con características como la eliminación de ramas de características fusionadas y el mantenimiento de ramas de lanzamiento, todo mientras se utilizan los protocolos de Git Flow y la programación de python3.","fr":"Permet aux agents d''automatiser les versions de Git Flow en utilisant des scripts python3, en simplifiant le flux de travail avec des fonctionnalités telles que la suppression des branches de fonctionnalités fusionnées et le maintien des branches de publication, le tout en utilisant les protocoles Git Flow et la programmation python3.","de":"Ermöglicht es Agenten, Git-Flow-Veröffentlichungen mithilfe von python3-Skripten zu automatisieren, den Arbeitsablauf mit Funktionen wie dem Löschen von zusammengeführten Feature-Branches und dem Beibehalten von Release-Branches zu strukturieren, und zwar unter Verwendung von Git-Flow-Protokollen und python3-Skripten.","pt":"Habilita os agentes a automatizar lançamentos do Git Flow usando scripts python3, simplificando o fluxo de trabalho com recursos como exclusão de branches de recursos mesclados e manutenção de branches de lançamento, tudo isso utilizando protocolos do Git Flow e script python3.","ru":"Позволяет агентам автоматизировать выпуски Git Flow с помощью скриптов python3, оптимизируя рабочий процесс с функциями, такими как удаление объединенных веток функций и сохранение веток выпусков, все это при использовании протоколов Git Flow и скриптов python3.","ar":"يمنح الوكلاء القدرة على توفير إصدارات Git Flow باستخدام نصوص برمجة python3، ويبسط تدفق العمل بميزات مثل حذف فروع الميزات المدمجة والحفاظ على فروع الإصدار، كل ذلك باستخدام بروتوكولات Git Flow ونصوص برمجة python3."},"useCases":{"en":["Automating Git Flow releases","Deleting merged feature branches","Managing release branches with Git Flow protocols"],"zh":["自动执行Git Flow发布","删除合并的功能分支","使用Git Flow协议管理发布分支"],"ja":["Git Flowリリースの自動化","マージされた機能ブランチの削除","Git Flowプロトコルを使用したリリースブランチの管理"],"ko":["Git Flow 릴리스 자동화","병합된 기능 분기 삭제","Git Flow 프로토콜을 사용한 릴리스 분기 관리"],"es":["Automatización de versiones de Git Flow","Eliminación de ramas de características fusionadas","Administración de ramas de lanzamiento con protocolos de Git Flow"],"fr":["Automatisation des versions de Git Flow","Suppression des branches de fonctionnalités fusionnées","Gestion des branches de publication avec les protocoles Git Flow"],"de":["Automatisierung von Git-Flow-Veröffentlichungen","Löschen von zusammengeführten Feature-Branches","Verwaltung von Release-Branches mit Git-Flow-Protokollen"],"pt":["Automatizar lançamentos do Git Flow","Excluir branches de recursos mesclados","Gerenciar branches de lançamento com protocolos do Git Flow"],"ru":["Автоматизация выпусков Git Flow","Удаление объединенных веток функций","Управление ветками выпусков с помощью протоколов Git Flow"],"ar":["توفير إصدارات Git Flow","حذف فروع الميزات المدمجة","إدارة فروع الإصدار باستخدام بروتوكولات Git Flow"]},"limitations":{"en":["Requires python3 environment","Git Flow must be initialized","Limited to managing Git Flow releases"],"zh":["需要python3环境","Git Flow必须初始化","仅限于管理Git Flow发布"],"ja":["python3環境が必要","Git Flowを初期化する必要がある","Git Flowリリースの管理のみ"],"ko":["python3 환경 필요","Git Flow 초기화 필요","Git Flow 릴리스 관리에만 제한"],"es":["Requiere entorno de python3","Git Flow debe estar inicializado","Limitado a la administración de versiones de Git Flow"],"fr":["Nécessite un environnement python3","Git Flow doit être initialisé","Limité à la gestion des versions de Git Flow"],"de":["Benötigt python3-Umgebung","Git Flow muss initialisiert werden","Begrenzt auf die Verwaltung von Git-Flow-Veröffentlichungen"],"pt":["Requer ambiente python3","Git Flow deve ser inicializado","Limitado ao gerenciamento de lançamentos do Git Flow"],"ru":["Требуется среда python3","Git Flow должен быть инициализирован","Ограничен управлением выпусками Git Flow"],"ar":["يتطلب بيئة python3","يجب 초기 Git Flow","محدود لإدارة إصدارات Git Flow"]},"version":4},"contentHash":"322e1db15f9325e9fc200ea25f705d5c9b321b6581e2528c54e4eef4f0a5db7c","qualityScore":33}');
