INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Travis-Gilbert/apply.thelandbank.org/htmx-patterns', 'htmx-patterns', 'Travis-Gilbert', 'apply.thelandbank.org', 'community', 'htmx-patterns Travis-Gilbert apply.thelandbank.org community htmx-patterns is a skill that enables developers to integrate HTMX with Django, allowing for server-rendered HTML fragments and progressive enhancement. It benefits developers building dynamic web applications. HTMX patterns for Django enable server-rendered HTML fragments and progressive enhancement HTMX patterns for Django provide minimal client-side complexity and JSON-free responses HTMX patterns for Django offer partial templates and enhanced user experience htmx-patterns es un enfoque para mejorar la experiencia del usuario en Django mediante el renderizado de HTML en el servidor Les modèles htmx sont une approche pour améliorer l''expérience utilisateur dans Django en utilisant le rendu HTML serveur htmx-Muster sind ein Ansatz, um die Benutzererfahrung in Django durch serverseitiges HTML-Rendering zu verbessern Os padrões htmx são uma abordagem para melhorar a experiência do usuário em aplicações web Django. Шаблоны htmx — это подход к улучшению пользовательского опыта в веб-приложениях Django для ИИ Агентов. أنماط htmx هي وسيلة لتحسين تجربة المستخدم في تطبيقات الويب Django لأدوات الذكاء الاصطناعي. how to use htmx-patterns with Django what is htmx-patterns htmx-patterns alternative to AJAX htmx-patterns vs React htmx-patterns install guide htmx-patterns setup for Django developers HTMX patterns Django 服务器端渲染 HTML片段 逐步增强 AIエージェント django-htmx partial templates Server renders HTML fragments, not JSON, for efficient data transfer Utilizes partial templates (_partial.html) for HTMX responses Employs progressive enhancement for pages that work without JavaScript Leverages django-htmx middleware for HTMX detection in views Uses request.htmx for conditional rendering of templates htmx-patterns is a set of techniques for using HTMX with Django, emphasizing server-rendered HTML fragments, partial templates, and minimal client-side complexity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('imvanzen/strava-kudosik/codebase-analysis', 'community', 'imvanzen', 'strava-kudosik', 'imvanzen/strava-kudosik', 'codebase-analysis', 0, 0, 33, '2026-02-23T06:04:57Z', '2026-03-07T04:13:21.431Z', 'a4f64554bd9823ea686974c7eaa1ee49a2bda2e4c46afe04601fb732ec4a0daa', '{"id":"imvanzen/strava-kudosik/codebase-analysis","name":"codebase-analysis","description":{"en":"The codebase-analysis skill helps developers analyze their codebase in a structured way, focusing on architecture, patterns, and dependencies. It benefits developers looking to optimize their codebase.","zh":"代码库分析技能，帮助您结构化地分析代码库，检查仓库结构、依赖、脚本、架构等","ja":"コードベース分析スキルは、リポジトリ構造、依存関係、スクリプト、Architectureなどを確認するために使用されます","ko":"코드베이스 분석 스킬은 저장소 구조, 의존성, 스크립트, 아키텍처 등을 확인하는 데 사용됩니다","es":"El análisis de codebase es un proceso que ayuda a los desarrolladores a evaluar y mejorar la calidad de su código. Nuestra guía cubre aspectos como la arquitectura, patrones, estilo de código y pruebas.","fr":"L''analyse de codebase est un processus qui aide les développeurs à évaluer et améliorer la qualité de leur code. Notre guide couvre des aspects tels que l''architecture, les modèles, le style de code et les tests.","de":"Die Codebase-Analyse ist ein Prozess, der Entwicklern hilft, die Qualität ihres Codes zu bewerten und zu verbessern. Unsere Anleitung behandelt Aspekte wie Architektur, Muster, Code-Stil und Tests.","pt":"Análise de codebase é um processo que ajuda a entender a estrutura e a qualidade do código, verificando arquitetura e dependências","ru":"Анализ кодовой базы - это процесс, который помогает понять структуру и качество кода, проверив архитектуру и зависимости","ar":"تحليل قاعدة الشفرة هو عملية تساعد على فهم هيكل و جودة الكود، من خلال التحقق من البنية والاعتماديات"},"seo":{"title":{"en":"Codebase-Analysis: Setup Guide for AI Agents","zh":"代码库分析最佳实践","ja":"コードベース分析設定ガイド - AIエージェント","ko":"코드베이스 분석 가이드 - AI 도구","es":"Guía de Análisis de Codebase: Mejores Prácticas para Desa...","fr":"Guide d''Analyse de Codebase: Bonnes Pratiques pour les Dé...","de":"Codebase-Analyse-Setup: Best Practices für Entwickler","pt":"Guia de Análise de Codebase: Melhores Práticas para Desen...","ru":"ИИ Агенты: Руководство по Анализу Кодовой Базы","ar":"دليل تحليل قاعدة الشفرة: إرشادات لتحسين الكود"},"description":{"en":"Discover how to analyze your codebase efficiently with our codebase-analysis skill. Learn how to track progress and optimize your repository structure, depen...","zh":"代码库分析技能，帮助您结构化地分析代码库，检查仓库结构、依赖、脚本、架构等","ja":"コードベース分析スキルを使用して、リポジトリ構造、依存関係、スクリプト、Architectureなどを確認します - AIエージェント","ko":"코드베이스 분석 스킬을 사용하여 저장소 구조, 의존성, 스크립트, 아키텍처 등을 확인하세요 - AI 도구","es":"Aprende a analizar tu codebase de manera estructurada con nuestra guía. Mejora la arquitectura, patrones, estilo de código y más.","fr":"Découvrez comment analyser votre codebase de manière structurée avec notre guide. Améliorez l''architecture, les modèles, le style de code et plus.","de":"Erfahren Sie, wie Sie Ihre Codebase strukturiert analysieren können. Verbessern Sie die Architektur, Muster, Code-Stil und mehr.","pt":"Aprenda a analisar sua codebase de forma estruturada, verificando arquitetura, padrões e dependências","ru":"Получите максимум от анализа кодовой базы, проверив архитектуру, паттерны и зависимости","ar":"تعلم كيفية تحليل قاعدة الشفرة الخاصة بك بطريقة منسقة، وتحقق من البنية والأنماط والاعتماديات"},"definition":{"en":"Codebase-analysis is a skill that enables developers to examine their codebase''s structure, dependencies, and architecture in a systematic approach.","zh":"代码库分析是指分析代码库的结构、依赖、脚本、架构等","ja":"コードベース分析とは、リポジトリ構造、依存関係、スクリプト、Architectureなどを分析することです","ko":"코드베이스 분석은 저장소 구조, 의존성, 스크립트, 아키텍처 등을 분석하는 것을 의미합니다","es":"Análisis de codebase es el proceso de evaluar y mejorar la estructura y calidad de un proyecto de código","fr":"L''analyse de codebase est le processus d''évaluation et d''amélioration de la structure et de la qualité d''un projet de code","de":"Codebase-Analyse ist der Prozess der Bewertung und Verbesserung der Struktur und Qualität eines Code-Projekts","pt":"Análise de codebase é uma técnica de avaliação do código fonte de um projeto","ru":"Анализ кодовой базы - это метод оценки исходного кода проекта","ar":"تحليل قاعدة الشفرة هو تقنية لتقييم код المصدر لمشروع"},"features":{"en":["Checks repository structure for optimization","Analyzes dependencies for potential issues","Examines available scripts for automation opportunities","Evaluates high-level architecture for scalability","Tracks analysis progress using a step-by-step checklist"],"zh":["检查仓库结构","分析依赖","检查可用脚本","检查高级架构","跟踪分析进度"],"ja":["リポジトリ構造の確認","依存関係の分析","利用可能なスクリプトの確認","高レベルアーキテクチャの確認","分析進度の追跡"],"ko":["저장소 구조 확인","의존성 분석","사용 가능한 스크립트 확인","고급 아키텍처 확인","분석 진행 상황 추적"],"es":["Análisis de la estructura del repositorio","Verificación de dependencias","Revisión de scripts disponibles","Evaluación de la arquitectura de alto nivel","Análisis de la separación de módulos","Revisión del enfoque de pruebas"],"fr":["Analyse de la structure du référentiel","Vérification des dépendances","Révision des scripts disponibles","Évaluation de l''architecture de haut niveau","Analyse de la séparation des modules","Révision de l''approche de tests"],"de":["Analyse der Repository-Struktur","Überprüfung von Abhängigkeiten","Überprüfung verfügbarer Skripte","Bewertung der Hocharchitektur","Analyse der Modultrennung","Überprüfung des Testansatzes"],"pt":["Verificação da estrutura do repositório","Análise de dependências","Verificação de scripts disponíveis","Análise da arquitetura de alto nível","Verificação da separação de módulos","Análise da abordagem de teste"],"ru":["Проверка структуры репозитория","Анализ зависимостей","Проверка доступных скриптов","Анализ высокоуровневой архитектуры","Проверка разделения модулей","Анализ подхода к тестированию"],"ar":["التحقق من هيكل المستودع","تحليل الاعتماديات","التحقق من البرامج النصية المتاحة","تحليل البنية على مستوى عال","التحقق من فصل الوحدات","تحليل نهج الاختبار"]},"keywords":{"en":["how to use codebase-analysis","codebase-analysis setup guide","codebase-analysis alternative","codebase-analysis vs sonarqube","codebase-analysis install","what is codebase-analysis","codebase-analysis best practices"],"zh":["代码库分析","代码库结构","依赖分析","脚本检查","架构分析","代码库优化","AI工具","代码分析"],"ja":["コードベース分析","リポジトリ構造","依存関係分析","スクリプト確認","アーキテクチャ分析","コードベース最適化","AIエージェント","コード分析"],"ko":["코드베이스 분석","저장소 구조","의존성 분석","스크립트 확인","아키텍처 분석","코드베이스 최적화","AI 도구","코드 분석"],"es":["análisis de codebase","mejores prácticas de código","arquitectura de software","patrones de diseño","estilo de código","pruebas de software","herramientas de análisis de código","desarrollo de software","ingeniería de software"],"fr":["analyse de codebase","bonnes pratiques de code","architecture de logiciel","modèles de conception","style de code","tests de logiciel","outils d''analyse de code","développement de logiciel","ingénierie de logiciel"],"de":["Codebase-Analyse","Best Practices für Code","Software-Architektur","Entwurfsmuster","Code-Stil","Software-Tests","Code-Analyse-Tools","Software-Entwicklung","Software-Ingeneering"],"pt":["análise de codebase","melhores práticas de código","desenvolvimento de software","análise de dependências","arquitetura de software","testes de software","ferramentas de desenvolvimento","otimização de código","qualidade de código"],"ru":["ИИ Агенты","анализ кодовой базы","лучшие практики кода","разработка программного обеспечения","анализ зависимостей","архитектура программного обеспечения","тестирование программного обеспечения","инструменты разработки","оптимизация кода","качество кода"],"ar":["أدوات الذكاء الاصطناعي","تحليل قاعدة الشفرة","إرشادات الكود","تطوير البرمجيات","تحليل الاعتماديات","هيكلة البرمجيات","اختبار البرمجيات","أدوات التطوير","تحسين الكود","جودة الكود"]}},"owner":"imvanzen","repo":"strava-kudosik","repoPath":"imvanzen/strava-kudosik","stars":0,"forks":0,"updatedAt":"2026-02-23T06:04:57Z","topics":[],"category":"community","skillMd":{"name":"codebase-analysis","description":"Analyse the codebase of the system. Look for dependencies. Understand how the business logic is implemented. Look for duplications.","bodyPreview":"# Codebase Analysis\n\nThis skill helps you analyse the codebase in a structured way, getting the most out of it. It focuses on architecture, patterns, code style, module separation, testing approach, dependencies and infrastructure.\n\n## Codebase Analysis Process\n\nUse the checklist below and track your progress:\n\n```\nAnalysis progress:\n- [ ] Step 1: Check repository structure\n- [ ] Step 2: Check dependencies\n- [ ] Step 3: Check available scripts\n- [ ] Step 4: Check high level architecture\n- [ ] St","body":"# Codebase Analysis\n\nThis skill helps you analyse the codebase in a structured way, getting the most out of it. It focuses on architecture, patterns, code style, module separation, testing approach, dependencies and infrastructure.\n\n## Codebase Analysis Process\n\nUse the checklist below and track your progress:\n\n```\nAnalysis progress:\n- [ ] Step 1: Check repository structure\n- [ ] Step 2: Check dependencies\n- [ ] Step 3: Check available scripts\n- [ ] Step 4: Check high level architecture\n- [ ] Step 5: Check backend code\n- [ ] Step 6: Check frontend code\n- [ ] Step 7: Check infrastructure code\n- [ ] Step 8: Check third party integrations\n- [ ] Step 9: Check testing approach\n- [ ] Step 10: Check the security approach\n- [ ] Step 11: Look for potential improvements\n- [ ] Step 12: Check for deadcode and duplications\n```\n\n**Step 1: Check repository structure**\n\nGo through the whole repository to identify and understand the structure of the repository. \nFind out what type of repository we work with. Is it monorepo or single system repository.\nFind out what type of the system in contains - frontend apps, backend apps, shared packages, infrastructure etc.\nFind out where dependencies and scripts files are stored.\nFind out where tests are stored (e2e, unit, integration).\nFind out where are the most crucial directories for each system.\n\n**Step 2: Check dependencies**\n\nAnalyse all dependencies.\nMake sure to fully understand what frameworks, libraries, authentication systems etc. are used.\nMake sure to note which dependencies are out of date and could be an issue later on.\n\n**Step 3: Check available scripts**\n\nCheck all available scripts.\nFind out what app running scripts we have.\nFind out what quality assurance scripts we have (tests, linting, formatting etc.)\nUnderstand the remaining scripts.\n\n**Step 4: Check high level architecture**\n\nUnderstand how the app architecture looks like based on the services, integrations and libraries.\nCreate a diagram of the architecture you can figure out based on the code itself.\nMake sure to understand the internal and external communication patterns and practices used.\n\n**Step 5: Check backend code**\n\nCheck what backend technology we use.\nCheck what framework we use.\nCheck how the code architecture looks like - MVC, CQRS, DDD, Hexagonal Architecture, Layered architecture etc.\nCheck if the code is divided based on a module (all module related code is in a single parent directory and has its own controllers, entities etc) or based on responsibilities (or controllers in a single directory etc.)\nUnderstand the database schema and the pattern used (is it ORM, direct SQL etc.).\nMake sure to understand what library we use for database communication.\nUnderstand how the backend is deployed.\nUnderstand how the authentication and authorisation works.\n\n**Step 6: Check frontend code**\n\nCheck what framework we use.\nUnderstand what communication pattern (REST, Websocket, Graphql etc) we use.\nUnderstand what UI libraries we use.\nUnderstand what additional libraries we use for authentication, queries and other common areas.\nUnderstand the code architecture. Do we follow matomic design or other approach.\nUnderstand how the app is deployed.\n\n**Step 7: Check infrastructure code**\n\nCheck how we manage infrastructure (IaC or manual). What technology we use for infrastructure?\nHow the app is deployed? Cloud, on-premise etc.\nUnderstand if app is containerised.\nMake sure to understand how scalable the infrastructure is.\n\n**Step 8: Check third party integrations**\n\nCheck what third parties we use.\nList all of the 3rd party libraries and their purpose in a system.\nUnderstand how tightly they integrate into the system and how hard it will be to exchange them in the future.\n\n**Step 9: Check testing approach**\n\nCheck what type of tests we have (e2e, unit, integration, contract etc.)\nUnderstand the testing strategy. Do we test everything, only controller, only endpoints, only backend, only frontend etc.\nUnderstand the current test coverage\n\n**Step 10: Check the security approach**\n\nCheck what security approach the repository has.\nUnderstand how authentication and authorisation is implemented.\nWhat type of security 3rd parties and libraries we use.\nCheck how secure the database and endpoints are.\nFind out which endpoints are publicly accessible.\nRate the general security approach.\n\n**Step 11: Look for potential improvements**\n\nBased on all findings, propose potential improvements.\nDivide them into Critical, To be implemented but not critical, Nice to have.\n\nSave the results into a separate structure document.\nEach step should be covered in separate section.\n\n**Step 12: Check for deadcode and duplications**\n\nAnalyse imports and dependencies to find out if there are any dead code or duplications in the codebase.\nLook for unused imports, functions, components, files etc.\nLook for duplicated code, functions, components etc. that can be extracted to a common place and reused.\nLook for components that are very similar and can be merged into one with some configuration.\nLook for code that is only used in their own test files and can be moved there or removed if not used at all outside of tests.\n\n## Large codebase\n\nThe process might take a while and because of that create a document containing a section for each step.\n\nDuring the processing make sure to update the document over the time."},"lastSynced":"2026-03-07T04:13:21.431Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing comprehensive architecture and dependency analysis capabilities.","zh":"非常适合需要全面架构和依赖分析能力的代码审查代理。","ja":"コードレビュー代理が包括的なアーキテクチャと依存関係分析機能を必要とする場合に最適です。","ko":"전체적인 아키텍처와 의존성 분석 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan capacidades de análisis de arquitectura y dependencias exhaustivas.","fr":"Parfait pour les agents de révision de code nécessitant des capacités d''analyse d''architecture et de dépendances complètes.","de":"Perfekt für Code-Review-Agenten, die umfassende Architektur- und Abhängigkeitsanalysefunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de capacidades de análise de arquitetura e dependência abrangentes.","ru":"Идеально подходит для агентов кодового обзора, которым необходимы возможности комплексного анализа архитектуры и зависимостей.","ar":"مثالي لعميل استعراض الشفرة الذي يحتاج إلى قدرات تحليلية شاملة للهيكل والمعتمديات."},"recommendation":{"en":"Empowers agents to analyze repository structures, check dependencies, and evaluate high-level architecture using modular separation and testing approaches, focusing on code style and infrastructure.","zh":"赋予代理分析仓库结构、检查依赖关系、使用模块化分离和测试方法评估高级架构的能力，专注于代码风格和基础设施。","ja":"エージェントに、リポジトリ構造を分析し、依存関係を確認し、モジュラー分離とテストアプローチを使用して、高レベルアーキテクチャを評価する能力を与え、コードスタイルとインフラストラクチャに焦点を当てます。","ko":"에이전트가 저장소 구조를 분석하고 의존성을 확인하며 모듈 별 분리 및 테스트 접근 방식을 사용하여 고급 아키텍처를 평가하는 기능을 제공하며 코드 스타일 및 인프라에 중점을 둡니다.","es":"Habilita a los agentes a analizar estructuras de repositorio, verificar dependencias y evaluar la arquitectura de alto nivel utilizando enfoques de separación y prueba modulares, centrándose en el estilo de código y la infraestructura.","fr":"Permet aux agents d''analyser les structures de référentiel, de vérifier les dépendances et d''évaluer l''architecture de haut niveau en utilisant des approches de séparation et de test modulaires, en se concentrant sur le style de code et l''infrastructure.","de":"Ermöglicht es Agenten, Repository-Strukturen zu analysieren, Abhängigkeiten zu überprüfen und die Hocharchitektur mithilfe modularen Trennungs- und Testansätzen zu bewerten, wobei der Fokus auf Code-Stil und Infrastruktur liegt.","pt":"Habilita os agentes a analisar estruturas de repositório, verificar dependências e avaliar a arquitetura de alto nível usando abordagens de separação modular e teste, com foco no estilo de código e infraestrutura.","ru":"Наделяет агентов возможностью анализировать структуры репозиториев, проверять зависимости и оценивать высокоуровневую архитектуру с использованием подходов модульного разделения и тестирования, сосредоточив внимание на стиле кода и инфраструктуре.","ar":"يمنح العميل القدرة على تحليل هياكل المستودع، وفحص الاعتمادية، وتقييم الهيكل على مستوى عال باستخدام نهج الفصل الوحداتي واختبارات التركيز على نمط الشفرة والبنية التحتية."},"useCases":{"en":["Analyzing repository structures for optimization","Evaluating dependencies for potential security vulnerabilities","Assessing high-level architecture for scalability"],"zh":["为优化而分析仓库结构","为潜在安全漏洞评估依赖关系","为可扩展性评估高级架构"],"ja":["最適化のためにリポジトリ構造を分析する","潜在的なセキュリティ脆弱性のために依存関係を評価する","拡張性のために高レベルアーキテクチャを評価する"],"ko":["최적화를 위해 저장소 구조를 분석함"," 잠재적인 보안 취약점을 위해 의존성을 평가함"," 확장성을 위해 고급 아키텍처를 평가함"],"es":["Análisis de estructuras de repositorio para optimización","Evaluación de dependencias para posibles vulnerabilidades de seguridad","Evaluación de la arquitectura de alto nivel para escalabilidad"],"fr":["Analyse des structures de référentiel pour l''optimisation","Évaluation des d