INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('imvanzen/strava-kudosik/codebase-analysis', 'codebase-analysis', 'imvanzen', 'strava-kudosik', 'community', 'codebase-analysis imvanzen strava-kudosik community The codebase-analysis skill helps developers analyze their codebase in a structured way, focusing on architecture, patterns, and dependencies. It benefits developers looking to optimize their codebase. 代码库分析技能，帮助您结构化地分析代码库，检查仓库结构、依赖、脚本、架构等 コードベース分析スキルは、リポジトリ構造、依存関係、スクリプト、Architectureなどを確認するために使用されます 코드베이스 분석 스킬은 저장소 구조, 의존성, 스크립트, 아키텍처 등을 확인하는 데 사용됩니다 El análisis de codebase es un proceso que ayuda a los desarrolladores a evaluar y mejorar la calidad de su código. Nuestra guía cubre aspectos como la arquitectura, patrones, estilo de código y pruebas. L''analyse de codebase est un processus qui aide les développeurs à évaluer et améliorer la qualité de leur code. Notre guide couvre des aspects tels que l''architecture, les modèles, le style de code et les tests. Die Codebase-Analyse ist ein Prozess, der Entwicklern hilft, die Qualität ihres Codes zu bewerten und zu verbessern. Unsere Anleitung behandelt Aspekte wie Architektur, Muster, Code-Stil und Tests. Análise de codebase é um processo que ajuda a entender a estrutura e a qualidade do código, verificando arquitetura e dependências Анализ кодовой базы - это процесс, который помогает понять структуру и качество кода, проверив архитектуру и зависимости تحليل قاعدة الشفرة هو عملية تساعد على فهم هيكل و جودة الكود، من خلال التحقق من البنية والاعتماديات how to use codebase-analysis codebase-analysis setup guide codebase-analysis alternative codebase-analysis vs sonarqube codebase-analysis install what is codebase-analysis codebase-analysis best practices 代码库分析 代码库结构 依赖分析 脚本检查 架构分析 代码库优化 AI工具 代码分析 Checks repository structure for optimization Analyzes dependencies for potential issues Examines available scripts for automation opportunities Evaluates high-level architecture for scalability Tracks analysis progress using a step-by-step checklist Codebase-analysis is a skill that enables developers to examine their codebase''s structure, dependencies, and architecture in a systematic approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('muhammadcaeed/aegis/tenancy-enforcer', 'community', 'muhammadcaeed', 'aegis', 'muhammadcaeed/aegis', 'tenancy-enforcer', 0, 0, 33, '2026-03-04T11:55:28Z', '2026-03-07T04:14:48.867Z', '63d102c3ac1fb2667fa44903c2ce7d3e9c7fa3a73cc003513950218fa31a6b92', '{"id":"muhammadcaeed/aegis/tenancy-enforcer","name":"tenancy-enforcer","description":{"en":"The tenancy-enforcer skill manages guard duty visibility and household payments for multi-tenant communities, ensuring secure MongoDB queries for developers.","zh":"Tenancy Enforcer 是一个多租户社区平台，用于管理守卫职责、家庭月付款、验证工作流和角色范围内的通知","ja":"Tenancy Enforcer は、マルチテナントコミュニティプラットフォームであり、ガード職務、家庭月々の支払い、検証ワークフロー、およびロールスコープ内の通知を管理する","ko":"테넌시 엑서사이저는 멀티 테넌트 커뮤니티 플랫폼으로서, 가드 직무, 가구 월간 지불, 검증 워크플로 및 역할 범위 내의 알림을 관리한다","es":"Tenancy-enforcer es un skill de plataforma de comunidad multi-tenant que gestiona la visibilidad de las guardias, pagos mensuales y notificaciones","fr":"Tenancy-enforcer est un skill de plateforme de communauté multi-locataires qui gère la visibilité des gardes, les paiements mensuels et les notifications","de":"Tenancy-enforcer ist ein Skill für Multi-Tenant-Community-Plattformen, der die Sichtbarkeit von Wachdiensten, monatlichen Zahlungen und Benachrichtigungen verwaltet","pt":"O tenancy-enforcer é uma ferramenta de segurança para plataformas de multi-tenancy, garantindo que todas as consultas de banco de dados incluam o communityId","ru":"ИИ Агент tenancy-enforcer - это инструмент безопасности для мульти-арендаторных платформ, обеспечивающий включение communityId во все запросы базы данных","ar":"tenancy-enforcer هو أداة أمان لمنصات الايجارات المتعددة، يضمن تضمين communityId في جميع استفسارات قاعدة البيانات"},"seo":{"title":{"en":"tenancy-enforcer: MongoDB Query Enforcement for AI Agents...","zh":"Tenancy Enforcer 设置指南：多租户社区平台安全解决方案","ja":"Tenancy Enforcer のベストプラク