INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('muhammadcaeed/aegis/tenancy-enforcer', 'tenancy-enforcer', 'muhammadcaeed', 'aegis', 'community', 'tenancy-enforcer muhammadcaeed aegis community The tenancy-enforcer skill manages guard duty visibility and household payments for multi-tenant communities, ensuring secure MongoDB queries for developers. Tenancy Enforcer 是一个多租户社区平台，用于管理守卫职责、家庭月付款、验证工作流和角色范围内的通知 Tenancy Enforcer は、マルチテナントコミュニティプラットフォームであり、ガード職務、家庭月々の支払い、検証ワークフロー、およびロールスコープ内の通知を管理する 테넌시 엑서사이저는 멀티 테넌트 커뮤니티 플랫폼으로서, 가드 직무, 가구 월간 지불, 검증 워크플로 및 역할 범위 내의 알림을 관리한다 Tenancy-enforcer es un skill de plataforma de comunidad multi-tenant que gestiona la visibilidad de las guardias, pagos mensuales y notificaciones Tenancy-enforcer est un skill de plateforme de communauté multi-locataires qui gère la visibilité des gardes, les paiements mensuels et les notifications Tenancy-enforcer ist ein Skill für Multi-Tenant-Community-Plattformen, der die Sichtbarkeit von Wachdiensten, monatlichen Zahlungen und Benachrichtigungen verwaltet O tenancy-enforcer é uma ferramenta de segurança para plataformas de multi-tenancy, garantindo que todas as consultas de banco de dados incluam o communityId ИИ Агент tenancy-enforcer - это инструмент безопасности для мульти-арендаторных платформ, обеспечивающий включение communityId во все запросы базы данных tenancy-enforcer هو أداة أمان لمنصات الايجارات المتعددة، يضمن تضمين communityId في جميع استفسارات قاعدة البيانات how to use tenancy-enforcer tenancy-enforcer setup guide MongoDB query security multi-tenant community platform tenancy-enforcer alternative tenancy-enforcer vs competitor implementing tenancy-enforcer for AI agents tenancy-enforcer install secure MongoDB queries Tenancy Enforcer 多租户社区平台 MongoDB 查询 社区 ID 安全解决方案 AIエージェント 多租户安全 Enforces communityId filtering for MongoDB queries (find, update, delete) Supports repository method creation with communityId inclusion Implements service layer logic for role-scoped notifications Adds new indexes to schemas for efficient query execution Creates aggregate pipelines for complex data processing tenancy-enforcer is a multi-tenant community platform enforcing secure MongoDB queries with communityId filtering');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('matthabermehl/generation-b-kids-books/pr-driver', 'community', 'matthabermehl', 'generation-b-kids-books', 'matthabermehl/generation-b-kids-books', 'pr-driver', 0, 0, 33, '2026-03-05T03:52:58Z', '2026-03-07T04:16:38.953Z', 'e0667662e5d5b81ccdb369d911fd512090c0d316b382ad1d33dc4e581f098fc7', '{"id":"matthabermehl/generation-b-kids-books/pr-driver","name":"pr-driver","description":{"en":"The pr-driver skill ensures task quality for AI agents by validating JSON files and running bash scripts. It benefits developers by streamlining the quality assurance process.","zh":"PR驱动器是一种代码质量检查和提交工具，用于提高代码质量和自动化提交流程","ja":"PRドライバーはコード品質チェックとコミットの自動化ツールです","ko":"PR 드라이버는 코드 품질을 확인하고 커밋 프로세스를 자동화하는 도구입니다","es":"El pr-driver es una habilidad para agentes de IA que automatiza tareas de revisión de código.","fr":"Le pr-driver est une compétence pour les outils d''IA qui automatise les tâches de révision de code.","de":"Der pr-driver ist eine Fähigkeit für KI-Agenten, die Code-Überprüfungsaufgaben automatisiert.","pt":"O pr-driver é uma ferramenta para ajudar desenvolvedores a criar PRs de alta qualidade, com verificações de qualidade e templates de descrição de PR","ru":"Пр-драйвер - это инструмент, помогающий разработчикам создавать PR высокого качества, с проверками качества и шаблонами описания PR для ИИ Агентов","ar":"pr-driver هو أداة لمساعدة المطورين على إنشاء طلبات Pull Request عالية الجودة، مع فحص الجودة وقوالب وصف PR"},"seo":{"title":{"en":"pr-driver: Quality Assurance Setup Guide | AI Agent Skill","zh":"PR驱动器_SETUP指南 - 代码质量检查和提交","ja":"PRドライバーの設定方法 - コード品質チェックとコミット","ko":"PR 드라이버 설정 가이드 - 코드 품질 검사 및 제출","es":"Guía de configuración de pr-driver para agentes de IA","fr":"Guide de configuration de pr-driver pour les outils d''IA","de":"Einrichtungsleitfaden für pr-driver in KI-Agenten","pt":"Guia de Configuração do pr-driver: Melhores Práticas para...","ru":"Настройка пр-драйвера: Руководство по лучшим практикам дл...","ar":"دليل إعداد pr-driver: أفضل الممارسات للمطورين"},"description":{"en":"Learn how to implement pr-driver for AI agents, ensuring task quality with bash scripts and JSON validation. Get started now!","zh":"学习如何设置PR驱动器以提高代码质量和自动化提交流程。了解PR驱动器的功能和优点","ja":"PRドライバーを設定してコード品質を向上させ、コミットプロセスを自動化する方法を学びます。PRドライバーの機能と利点について詳しく知る","ko":"PR 드라이버를 설정하여 코드 품질을 향상시키고 커밋 프로세스를 자동화하는 방법을 알아보세요. PR 드라이버의 기능과 이점에 대해 자세히 알아보세요","es":"Aprende a configurar pr-driver para agentes de IA con nuestra guía paso a paso","fr":"Découvrez comment configurer pr-driver pour les outils d''IA avec notre guide étape par étape","de":"Erfahren Sie, wie Sie pr-driver für KI-Agenten mit unserem Schritt-für-Schritt-Leitfaden konfigurieren","pt":"Aprenda a configurar o pr-driver com nossas dicas e melhores práticas para desenvolvedores, incluindo verificações de qualidade e templates de descrição de PR","ru":"Узнайте, как настроить пр-драйвер с помощью наших советов и лучших практик для разработчиков ИИ Агентов, включая проверки качества и шаблоны описания PR","ar":"تعرف على كيفية إعداد pr-driver باستخدام نصائحنا وأفضل الممارسات للمطورين، بما في ذلك فحص الجودة وقوالب وصف PR"},"definition":{"en":"pr-driver is a skill that automates quality checks for AI agents using bash scripts and JSON validation, ensuring tasks meet specific criteria.","zh":"PR驱动器是一种自动化工具，用于检查代码质量和提交代码","ja":"PRドライバーはコード品質をチェックし、コミットする自動化ツールです","ko":"PR 드라이버는 코드 품질을 확인하고 커밋하는 자동화 도구입니다","es":"El pr-driver es una herramienta de automatización de revisión de código para agentes de IA","fr":"Le pr-driver est un outil d''automatisation de révision de code pour les outils d''IA","de":"Der pr-driver ist ein Automatisierungstool für Code-Überprüfung in KI-Agenten","pt":"O pr-driver é uma ferramenta de desenvolvimento que ajuda a criar PRs de alta qualidade","ru":"Пр-драйвер - это инструмент разработки, помогающий создавать PR высокого качества для ИИ Агентов","ar":"pr-driver هو أداة تطوير تساعد على إنشاء طلبات Pull Request عالية الجودة"},"features":{"en":["Validates tasks using `.agent/feature_list.json` files","Runs quality checks with `bash scripts/agent/quality.sh`","Provides a PR description template using `.codex/skills/pr-driver/templates/pr.md`","Supports git commands for status and diff checks","Includes a suggested flow for quality assurance using `git status`, `git diff --stat`, and `bash scripts/agent/quality.sh`"],"zh":["支持bash脚本执行","集成git状态检查","自动化代码质量检查","支持PR提交模板","提供代码变更统计"],"ja":["bashスクリプトの実行をサポート","gitステータスチェックを統合","コード品質チェックの自動化","PR 제출テンプレートをサポート","コード変更統計を提供"],"ko":["bash 스크립트 실행 지원","git 상태 확인 통합","코드 품질 확인 자동화","PR 제출 템플릿 지원","코드 변경 통계 제공"],"es":["Ejecución de scripts de bash para la calidad del código","Verificación de la tarea en `.agent/feature_list.json`","Uso de `git status` y `git diff --stat` para el seguimiento de cambios","Plantilla de descripción de PR para un proceso de revisión más eficiente","Análisis de riesgos y mitigaciones para una implementación segura"],"fr":["Exécution de scripts bash pour la qualité du code","Vérification de la tâche dans `.agent/feature_list.json`","Utilisation de `git status` et `git diff --stat` pour le suivi des modifications","Modèle de description de PR pour un processus de révision plus efficace","Analyse des risques et des mitigations pour une mise en œuvre sécurisée"],"de":["Ausführung von Bash-Skripten für die Code-Qualität","Überprüfung der Aufgabe in `.agent/feature_list.json`","Verwendung von `git status` und `git diff --stat` für die Änderungsverfolgung","Vorlage für die PR-Beschreibung für einen effizienteren Überprüfungsprozess","Risiko- und Minderungsanalyse für eine sichere Implementierung"],"pt":["Verificação de qualidade com bash scripts/agent/quality.sh","Uso de templates de descrição de PR em .codex/skills/pr-driver/templates/pr.md","Suporte a git status e git diff --stat","Verificação de evidências de PASS em .agent/feature_list.json"],"ru":["Проверка качества с помощью bash scripts/agent/quality.sh","Использование шаблонов описания PR в .codex/skills/pr-driver/templates/pr.md","Поддержка git status и git diff --stat для ИИ Агентов","Проверка доказательств PASS в .agent/feature_list.json"],"ar":["فحص الجودة باستخدام bash scripts/agent/quality.sh","استخدام قوالب وصف PR في .codex/skills/pr-driver/templates/pr.md","دعم git status و git diff --stat","فحص أدلة PASS في .agent/feature_list.json"]},"keywords":{"en":["how to use pr-driver","pr-driver setup guide","pr-driver alternative","pr-driver vs other quality assurance tools","pr-driver install","what is pr-driver","pr-driver for AI agents","quality assurance with pr-driver","pr-driver bash scripts","pr-driver JSON validation"],"zh":["PR驱动器","代码质量检查","自动化提交","git状态检查","bash脚本执行","PR提交模板","代码变更统计","AI工具","代码自动化"],"ja":["PRドライバー","コード品質チェック","自動コミット","gitステータスチェック","bashスクリプト実行","PR提出テンプレート","コード変更統計","AIエージェント","コード自動化"],"ko":["PR 드라이버","코드 품질 확인","자동 커밋","git 상태 확인","bash 스크립트 실행","PR 제출 템플릿","코드 변경 통계","AI 도구","코드 자동화"],"es":["pr-driver","agentes de IA","automatización de revisión de código","bash scripts","git status","git diff","plantilla de descripción de PR","análisis de riesgos"],"fr":["pr-driver","outils d''IA","automatisation de révision de code","scripts bash","git status","git diff","modèle de description de PR","analyse des risques"],"de":["pr-driver","KI-Agenten","Automatisierung der Code-Überprüfung","Bash-Skripte","git status","git diff","Vorlage für die PR-Beschreibung","Risikoanalyse"],"pt":["pr-driver","desenvolvimento de software","ferramentas de desenvolvimento","verificação de qualidade","templates de descrição de PR","git status","git diff --stat","bash scripts"],"ru":["пр-драйвер","разработка программного обеспечения","инструменты разработки","проверка качества","шаблоны описания PR","git status","git diff --stat","bash скрипты","ИИ Агенты"],"ar":["pr-driver","تطوير البرمجيات","أدوات التطوير","فحص الجودة","قوالب وصف PR","git status","git diff --stat","bash scripts","أدوات الذكاء الاصطناعي"]}},"owner":"matthabermehl","repo":"generation-b-kids-books","repoPath":"matthabermehl/generation-b-kids-books","stars":0,"forks":0,"updatedAt":"2026-03-05T03:52:58Z","topics":[],"category":"community","skillMd":{"name":"pr-driver","description":">","bodyPreview":"## Before you start\n- Ensure the task is passing and evidenced in `.agent/feature_list.json`\n- Ensure `bash scripts/agent/quality.sh` passes\n\n## Suggested flow\n```bash\ngit status\nbash scripts/agent/quality.sh\ngit diff --stat\n```\n\n## PR description template\nUse `.codex/skills/pr-driver/templates/pr.md` as your starting point.\nFill in:\n- what changed (1-5 bullets)\n- why\n- evidence (exact commands + PASS)\n- risks + mitigations\n- rollback plan (if applicable)","body":"## Before you start\n- Ensure the task is passing and evidenced in `.agent/feature_list.json`\n- Ensure `bash scripts/agent/quality.sh` passes\n\n## Suggested flow\n```bash\ngit status\nbash scripts/agent/quality.sh\ngit diff --stat\n```\n\n## PR description template\nUse `.codex/skills/pr-driver/templates/pr.md` as your starting point.\nFill in:\n- what changed (1-5 bullets)\n- why\n- evidence (exact commands + PASS)\n- risks + mitigations\n- rollback plan (if applicable)\n"},"lastSynced":"2026-03-07T04:16:38.953Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated JSON validation and bash script execution for quality assurance.","zh":"非常适合需要自动化JSON验证和bash脚本执行的代码审查代理，以确保质量保证。","ja":"コードレビュー代理が自動化されたJSON検証とbashスクリプトの実行を必要とする場合に最適です。","ko":"코드 리뷰 에이전트가 자동화된 JSON 유효성 검사와 bash 스크립트 실행을 필요로 하는 경우에 적합합니다.","es":"Perfecto para los agentes de revisión de código que necesitan una validación automática de JSON y ejecución de scripts de bash para aseguramiento de la calidad.","fr":"Parfait pour les agents de revue de code nécessitant une validation automatique de JSON et une exécution de scripts de bash pour l''assurance de la qualité.","de":"Perfekt für Code-Review-Agents, die eine automatisierte JSON-Validierung und eine Ausführung von Bash-Skripten für Qualitätsicherung benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de validação automática de JSON e execução de scripts bash para garantia de qualidade.","ru":"Идеально подходит для агентов проверки кода, которым требуется автоматическая проверка JSON и выполнение скриптов bash для обеспечения качества.","ar":"مثالي لعميل مراجعة الشفرة الذين يحتاجون إلى التحقق التلقائي من JSON وتنفيذ سكريبتات bash لتأمين جودة"},"recommendation":{"en":"Empowers agents to validate JSON files and run bash scripts for streamlined quality assurance, leveraging `.agent/feature_list.json` and `bash scripts/agent/quality.sh` for enhanced reliability and accuracy.","zh":"赋予代理验证JSON文件和运行bash脚本的能力，用于简化质量保证，利用`.agent/feature_list.json`和`bash scripts/agent/quality.sh`以提高可靠性和准确性。","ja":"エージェントにJSONファイルを検証し、bashスクリプトを実行する能力を与え、`.agent/feature_list.json`と`bash scripts/agent/quality.sh`を利用して、品質保証を簡素化し、信頼性と精度を高めます。","ko":"에이전트가 JSON 파일을 검증하고 bash 스크립트를 실행할 수 있는 능력을 부여하여 품질 보증을 간소화하고 `.agent/feature_list.json` 및 `bash scripts/agent/quality.sh`를 활용하여 신뢰성과 정확도를 높입니다.","es":"Habilita a los agentes a validar archivos JSON y ejecutar scripts de bash para una aseguramiento de la calidad optimizado, aprovechando `.agent/feature_list.json` y `bash scripts/agent/quality.sh` para una mayor confiabilidad y precisión.","fr":"Permet aux agents de valider les fichiers JSON et d''exécuter des scripts de bash pour une assurance de la qualité optimisée, en exploitant `.agent/feature_list.json` et `bash scripts/agent/quality.sh` pour une fiabilité et une précision accrues.","de":"Ermächtigt die Agenten, JSON-Dateien zu validieren und Bash-Skripte für eine optimierte Qualitätsicherung auszuführen, indem sie `.agent/feature_list.json` und `bash scripts/agent/quality.sh` für eine erhöhte Zuverlässigkeit und Genauigkeit nutzen.","pt":"Habilita os agentes a validar arquivos JSON e executar scripts bash para garantia de qualidade otimizada, aproveitando `.agent/feature_list.json` e `bash scripts/agent/quality.sh` para confiabilidade e precisão aprimoradas.","ru":"Наделяет агентов возможностью проверять файлы JSON и выполнять скрипты bash для оптимизированной проверки качества, используя `.agent/feature_list.json` и `bash scripts/agent/quality.sh` для повышения надежности и точности.","ar":"يمنح العميل القدرة على التحقق من صحة ملفات JSON وتنفيذ سكريبتات bash لتأمين جودة مرتّبة، مستفيداً من `.agent/feature_list.json` و `bash scripts/agent/quality.sh` لتعزيز الموثوقية والدقة"},"useCases":{"en":["Validating JSON files for task quality assurance","Automating bash script execution for continuous integration","Streamlining quality assurance processes with `.codex/skills/pr-driver/templates/pr.md` templates"],"zh":["用于任务质量保证的JSON文件验证","用于持续集成的自动化bash脚本执行","使用`.codex/skills/pr-driver/templates/pr.md`模板简化质量保证流程"],"ja":["タスクの品質保証のためにJSONファイルを検証する","継続的インテグレーションのためにbashスクリプトを自動実行する","`.codex/skills/pr-driver/templates/pr.md`テンプレートを使用して品質保証プロセスを簡素化する"],"ko":["작업 품질 보증을 위한 JSON 파일 검증","지속적 통합을 위한 자동화된 bash 스크립트 실행","`.codex/skills/pr-driver/templates/pr.md` 템플릿을 사용하여 품질 보증 프로세스를 간소화하는 것"],"es":["Validar archivos JSON para aseguramiento de la calidad de las tareas","Automatizar la ejecución de scripts de bash para la integración continua","Optimizar los procesos de aseguramiento de la calidad con plantillas `.codex/skills/pr-driver/templates/pr.md`"],"fr":["Valider les fichiers JSON pour l''assurance de la qualité des tâches","Automatiser l''exécution de scripts de bash pour l''intégration continue","Optimiser les processus d''assurance de la qualité avec des modèles `.codex/skills/pr-driver/templates/pr.md`"],"de":["JSON-Dateien für die Qualitätsicherung von Aufgaben validieren","Die Ausführung von Bash-Skripten für die kontinuierliche Integration automatisieren","Die Qualitätsicherungsprozesse mit Vorlagen `.codex/skills/pr-driver/templates/pr.md` optimieren"],"pt":["Validar arquivos JSON para garantia de qualidade de tarefas","Automatizar a execução de scripts bash para integração contínua","Otimizar processos de garantia de qualidade com modelos `.codex/skills/pr-driver/templates/pr.md`"],"ru":["Проверка файлов JSON для обеспечения качества задач","Автоматизация выполнения скриптов bash для непрерывной интеграции","Оптимизация процессов обеспечения качества с помощью шаблонов `.codex/skills/pr-driver/templates/pr.md`"],"ar":["التحقق من صحة ملفات JSON لتأمين جودة المهام","تأتمتة تنفيذ سكريبتات bash للتكامل المستمر","تسهيل عمليات تأمين الجودة باستخدام قوالب `.codex/skills/pr-driver/templates/pr.md`"]},"limitations":{"en":["Requires `.agent/feature_list.json` file","Needs `bash scripts/agent/quality.sh` script to pass","Limited to Git-based version control systems"],"zh":[".agent/feature_list.json文件是必需的","需要bash scripts/agent/quality.sh脚本才能通过","仅限于基于Git的版本控制系统"],"ja":[".agent/feature_list.jsonファイルが必要","bash scripts/agent/quality.shスクリプトが必要","Gitベースのバージョン管理システムのみに限定"],"ko":[".agent/feature_list.json 파일이 필요합니다","bash scripts/agent/quality.sh 스크립트가 통과하기 위해 필요합니다","Git 기반 버전 관리 시스템에만 제한"],"es":["Requiere el archivo `.agent/feature_list.json`","Necesita que el script `bash scripts/agent/quality.sh` pase","Limitado a sistemas de control de versiones basados en Git"],"fr":["Nécessite le fichier `.agent/feature_list.json`","A besoin que le script `bash scripts/agent/quality.sh` passe","Limité aux systèmes de contrôle de version basés sur Git"],"de":["Benötigt die Datei `.agent/feature_list.json`","Benötigt, dass das Skript `bash scripts/agent/quality.sh` erfolgreich ist","Eingeschränkt auf Git-basierte Versionskontrollsysteme"],"pt":["Requer arquivo `.agent/feature_list.json`","Necessita de script `bash scripts/agent/quality.sh` para passar","Limitado a sistemas de controle de versão baseados em Git"],"ru":["Требует файла `.agent/feature_list.json`","Требует скрипта `bash scripts/agent/quality.sh` для прохождения","Ограничен системами контроля версий на основе Git"],"ar":["يتطلب ملف `.agent/feature_list.json`","يحتاج إلى سكريبت `bash scripts/agent/quality.sh` للنجاح","محدود بنظم التحكم في الإصدارات المستندة إلى Git"]},"version":4},"contentHash":"e0667662e5d5b81ccdb369d911fd512090c0d316b382ad1d33dc4e581f098fc7","qualityScore":33}');
