INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('matthabermehl/generation-b-kids-books/pr-driver', 'pr-driver', 'matthabermehl', 'generation-b-kids-books', 'community', 'pr-driver matthabermehl generation-b-kids-books community The pr-driver skill ensures task quality for AI agents by validating JSON files and running bash scripts. It benefits developers by streamlining the quality assurance process. PR驱动器是一种代码质量检查和提交工具，用于提高代码质量和自动化提交流程 PRドライバーはコード品質チェックとコミットの自動化ツールです PR 드라이버는 코드 품질을 확인하고 커밋 프로세스를 자동화하는 도구입니다 El pr-driver es una habilidad para agentes de IA que automatiza tareas de revisión de código. Le pr-driver est une compétence pour les outils d''IA qui automatise les tâches de révision de code. Der pr-driver ist eine Fähigkeit für KI-Agenten, die Code-Überprüfungsaufgaben automatisiert. O pr-driver é uma ferramenta para ajudar desenvolvedores a criar PRs de alta qualidade, com verificações de qualidade e templates de descrição de PR Пр-драйвер - это инструмент, помогающий разработчикам создавать PR высокого качества, с проверками качества и шаблонами описания PR для ИИ Агентов pr-driver هو أداة لمساعدة المطورين على إنشاء طلبات Pull Request عالية الجودة، مع فحص الجودة وقوالب وصف PR how to use pr-driver pr-driver setup guide pr-driver alternative pr-driver vs other quality assurance tools pr-driver install what is pr-driver pr-driver for AI agents quality assurance with pr-driver pr-driver bash scripts pr-driver JSON validation PR驱动器 代码质量检查 自动化提交 git状态检查 bash脚本执行 PR提交模板 代码变更统计 AI工具 代码自动化 Validates tasks using `.agent/feature_list.json` files Runs quality checks with `bash scripts/agent/quality.sh` Provides a PR description template using `.codex/skills/pr-driver/templates/pr.md` Supports git commands for status and diff checks Includes a suggested flow for quality assurance using `git status`, `git diff --stat`, and `bash scripts/agent/quality.sh` pr-driver is a skill that automates quality checks for AI agents using bash scripts and JSON validation, ensuring tasks meet specific criteria.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pelchers/SessionSaver/managing-study-sessions', 'community', 'pelchers', 'SessionSaver', 'pelchers/SessionSaver', 'managing-study-sessions', 0, 0, 33, '2026-03-05T07:35:25Z', '2026-03-07T04:18:10.277Z', '3338895124dd2574fba053ff50ede3f8b5ed1f2cedf8b6947d38bb7c6d6fa16a', '{"id":"pelchers/SessionSaver/managing-study-sessions","name":"managing-study-sessions","description":{"en":"Managing-study-sessions is an evidence-based study session planning and tracking system that optimizes learning through proven techniques. It benefits students and learners by providing personalized study plans and progress tracking.","zh":"AIエージェント学习管理工具提供Pomodoro技巧、间隔重复和学习计划生成等功能，帮助开发者优化学习效果","ja":"AIエージェントを使用した学習セッション管理は、Pomodoro技巧や間隔復習等の機能を提供し、開発者の学習効果を向上させる","ko":"AI 에이전트를 이용한 학습 세션 관리는 Pomodoro 기법, 간격 반복, 학습 계획 생성 등 기능을 제공하여 개발자의 학습 효과를 향상시킵니다","es":"El sistema de gestión de sesiones de estudio utiliza técnicas como Pomodoro y repetición espaciada para optimizar el aprendizaje","fr":"Le système de gestion de sessions d''étude utilise des techniques comme Pomodoro et répétition espacée pour optimiser l''apprentissage","de":"Das Lernsitzungs-Management-System verwendet Techniken wie Pomodoro und Spaced Repetition, um das Lernen zu optimieren","pt":"O skill de gerenciamento de sessões de estudo utiliza técnicas comprovadas como Pomodoro e Spaced Repetition para otimizar o aprendizado","ru":"ИИ Агент для управления сессиями обучения использует технику Помодоро и алгоритм SM-2 для оптимального повторения","ar":"الوكلاء الذكية لإدارة جلسات الدراسة تستخدم تقنية Помодоро و خوارزمية SM-2 لمراجعة الأمثلة بفعالية"},"seo":{"title":{"en":"Managing-Study-Sessions: Evidence-Based Study Planner for...","zh":"AIエージェント学习管理工具设置指南","ja":"AIエージェントを使用した学習セッション管理ベストプラクティス","ko":"AI 에이전트를 이용한 학습 세션 관리 가이드","es":"Guía de configuración de sesión de estudio con Pomodoro y...","fr":"Guide de mise en place de sessions d''étude avec Pomodoro ...","de":"Einrichtungsleitfaden für Lernsitzungen mit Pomodoro- und...","pt":"Guia de Configuração de Sessões de Estudo com Técnica Pom...","ru":"ИИ Агенты для Управления Сессиями Обучения: Руководство","ar":"دليل إعداد جلسات الدراسة باستخدام تقنية Помодоро"},"description":{"en":"Unlock efficient learning with managing-study-sessions. Discover how to optimize your study sessions with Pomodoro technique, spaced repetition, and progress...","zh":"使用AIエージェント学习管理工具，优化学习效果，提高学习效率。了解Pomodoro技巧、间隔重复和学习计划生成等功能","ja":"AIエージェントを使用して学習セッションを管理し、学習効果を最大化する。Pomodoro技巧や間隔復習等の機能を活用してみましょう","ko":"AI 에이전트를 이용하여 학습 세션을 관리하고 학습 효과를 최대화하세요. Pomodoro 기법, 간격 반복, 학습 계획 생성 등 기능을 활용해보세요","es":"Optimiza tus sesiones de estudio con nuestro sistema de planificación y seguimiento basado en técnicas comprobadas y análisis de progreso","fr":"Optimisez vos sessions d''étude avec notre système de planification et de suivi basé sur des techniques éprouvées et des analyses de progrès","de":"Optimieren Sie Ihre Lernsitzungen mit unserem Planungs- und Verlaufsanalyse-System basierend auf bewährten Techniken und Fortschrittsanalysen","pt":"Aprenda a gerenciar sessões de estudo com técnicas comprovadas e análise de progresso para otimizar o aprendizado","ru":"Узнайте, как управлять сессиями обучения с помощью техники Помодоро и алгоритма SM-2 для оптимального повторения","ar":"تعلم كيفية إدارة جلسات الدراسة باستخدام تقنية Помодоро و خوارزمية SM-2 لمراجعة الأمثلة بفعالية"},"definition":{"en":"Managing-study-sessions is an AI agent skill that integrates Pomodoro technique, spaced repetition, and study plan generation to optimize learning outcomes.","zh":"AIエージェント学习管理工具是一种使用Pomodoro技巧、间隔重复和学习计划生成等功能来优化学习效果的工具","ja":"AIエージェントを使用した学習セッション管理は、Pomodoro技巧や間隔復習等の機能を使用して学習効果を最大化する手法","ko":"AI 에이전트를 이용한 학습 세션 관리는 Pomodoro 기법, 간격 반복, 학습 계획 생성 등 기능을 사용하여 학습 효과를 최대화하는 방법입니다","es":"Un sistema de gestión de sesiones de estudio es una herramienta de inteligencia artificial que ayuda a planificar y seguir el progreso de los estudios","fr":"Un système de gestion de sessions d''étude est un outil d''intelligence artificielle qui aide à planifier et à suivre les progrès des études","de":"Ein Lernsitzungs-Management-System ist ein künstliches Intelligenz-Tool, das dabei hilft, Lernsitzungen zu planen und den Fortschritt zu verfolgen","pt":"O que é gerenciamento de sessões de estudo? É um sistema de planejamento e acompanhamento de estudos baseado em técnicas comprovadas","ru":"Что такое управление сессиями обучения? Это система планирования и отслеживания обучения на основе проверенных техник","ar":"ما هو إدارة جلسات الدراسة؟ هو نظام تخطيط ومراقبة الدراسة يستند إلى تقنيات محكمة"},"features":{"en":["Pomodoro technique integration with 25-min focus + 5-min breaks","Spaced repetition using SM-2 algorithm for optimal review timing","Study plan generation with personalized schedules based on goals","Progress tracking with time spent, topics covered, and mastery level"],"zh":["Pomodoro技巧集成：25分钟专注+5分钟休息","间隔重复：SM-2算法实现最优复习时机","学习计划生成：根据目标生成个人化学习计划","进度跟踪：记录学习时间、覆盖主题、掌握程度"],"ja":["Pomodoro技巧統合：25分間集中+5分間休憩","間隔復習：SM-2アルゴリズムによる最適な復習時期","学習計画生成：目標に基づいた個人化学習計画","進度追跡：学習時間、カバーしたトピック、習得レベルを記録"],"ko":["Pomodoro 기법 통합：25분 집중+5분 휴식","간격 반복：SM-2 알고리즘을 통한 최적의 복습 시기","학습 계획 생성：목표에 आध거한 개인화된 학습 계획","진도 추적：학습 시간, 커버된 주제, 숙달 정도를 기록"],"es":["Integración de la técnica Pomodoro con 25 minutos de enfoque y 5 minutos de pausa","Repetición espaciada con algoritmo SM-2 para una revisión óptima","Generación de planes de estudio personalizados basados en objetivos","Seguimiento del progreso con análisis de tiempo dedicado, temas cubiertos y nivel de dominio"],"fr":["Intégration de la technique Pomodoro avec 25 minutes de concentration et 5 minutes de pause","Répétition espacée avec algorithme SM-2 pour une révision optimale","Génération de plans d''étude personnalisés basés sur les objectifs","Suivi des progrès avec analyse du temps consacré, des sujets couverts et du niveau de maîtrise"],"de":["Integrations der Pomodoro-Technik mit 25 Minuten Fokus und 5 Minuten Pause","Spaced Repetition mit SM-2-Algorithmus für optimale Wiederholung","Generierung von individuellen Lernplänen basierend auf Zielen","Verlaufsanalyse mit Zeitmessung, Themenabdeckung und Beherrschungsgrad"],"pt":["Integração da técnica Pomodoro para sessões de estudo focadas","Algoritmo SM-2 para repetição espaçada e revisão otimizada","Geração de planos de estudo personalizados com base em metas","Acompanhamento de progresso com análise de tempo gasto e tópicos cobertos"],"ru":["Интеграция техники Помодоро для сосредоточенных сессий обучения","Алгоритм SM-2 для оптимального повторения и обзора","Генерация персонализированных планов обучения на основе целей","Отслеживание прогресса с анализом потраченного времени и охваченных тем"],"ar":["دمج تقنية Помодоро لجلسات الدراسة المركزة","خوارزمية SM-2 لمراجعة الأمثلة بفعالية ومراجعة الأمثلة","توليد خطط الدراسة المخصصة بناءً على الأهداف","مراقبة التقدم مع تحليل الوقت المستغرق والمواضيع المغطاة"]},"keywords":{"en":["how to use managing-study-sessions","what is managing-study-sessions","managing-study-sessions alternative","managing-study-sessions vs traditional studying","managing-study-sessions install guide","managing-study-sessions setup for AI agents","evidence-based study planning","Pomodoro technique for learning","spaced repetition algorithm"],"zh":["AIエージェント学习管理","Pomodoro技巧","间隔重复","学习计划生成","进度跟踪","AI工具学习","开发者学习管理"],"ja":["AIエージェント学習セッション管理","Pomodoro技巧","間隔復習","学習計画生成","進度追跡","AIエージェント学習","開発者学習管理"],"ko":["AI 에이전트 학습 세션 관리","Pomodoro 기법","간격 반복","학습 계획 생성","진도 추적","AI 에이전트 학습","개발자 학습 관리"],"es":["herramientas de inteligencia artificial para el aprendizaje","gestión de sesiones de estudio","técnica Pomodoro","repetición espaciada","planificación de estudios","análisis de progreso","aprendizaje óptimo"],"fr":["outils d''intelligence artificielle pour l''apprentissage","gestion de sessions d''étude","technique Pomodoro","répétition espacée","planification des études","analyse de progrès","apprentissage optimal"],"de":["künstliche Intelligenz-Tools für das Lernen","Lernsitzungs-Management","Pomodoro-Technik","Spaced Repetition","Lernplanung","Fortschrittsanalyse","optimales Lernen"],"pt":["gerenciamento de sessões de estudo","técnica Pomodoro","Spaced Repetition","planejamento de estudos","análise de progresso","aprendizado eficaz"],"ru":["управление сессиями обучения","техника Помодоро","пространное повторение","планирование обучения","отслеживание прогресса","эффективное обучение"],"ar":["إدارة جلسات الدراسة","تقنية Помодоро","المراجعة بفعالية","تخطيط الدراسة","مراقبة التقدم","التعلم الفعال"]}},"owner":"pelchers","repo":"SessionSaver","repoPath":"pelchers/SessionSaver","stars":0,"forks":0,"updatedAt":"2026-03-05T07:35:25Z","topics":[],"category":"community","skillMd":{"name":"managing-study-sessions","description":"Plans and tracks study sessions using Pomodoro technique, spaced repetition scheduling (SM-2 algorithm), study plan generation, progress tracking, break optimization, and focus time analytics. Use when organizing study time, building study schedules, tracking learning progress, or optimizing retention through spaced repetition.","bodyPreview":"# Managing Study Sessions\n\nEvidence-based study session planning and tracking system that optimizes learning through proven techniques and progress analytics.\n\n## What This Skill Does\n\nManages all aspects of effective study sessions:\n\n- **Pomodoro technique integration**: 25-min focus + 5-min breaks\n- **Spaced repetition**: SM-2 algorithm for optimal review timing\n- **Study plan generation**: Personalized schedules based on goals\n- **Progress tracking**: Time spent, topics covered, mastery level","body":"# Managing Study Sessions\n\nEvidence-based study session planning and tracking system that optimizes learning through proven techniques and progress analytics.\n\n## What This Skill Does\n\nManages all aspects of effective study sessions:\n\n- **Pomodoro technique integration**: 25-min focus + 5-min breaks\n- **Spaced repetition**: SM-2 algorithm for optimal review timing\n- **Study plan generation**: Personalized schedules based on goals\n- **Progress tracking**: Time spent, topics covered, mastery levels\n- **Break optimization**: Strategic rest for sustained focus\n- **Focus analytics**: Productivity insights and improvements\n\n## Quick Start\n\n### Plan Study Session\n\n```bash\nnode scripts/plan-session.js topic.json session-plan.md --duration 120\n```\n\n### Calculate Spaced Repetition\n\n```bash\nnode scripts/calculate-spaced-repetition.js flashcards.json schedule.json\n```\n\n### Track Progress\n\n```bash\nnode scripts/track-progress.js session-log.json progress-report.md\n```\n\n---\n\n## Study Session Workflow\n\n```mermaid\ngraph TD\n    A[Set Learning Goals] --> B[Create Study Plan]\n    B --> C[Start Pomodoro Timer]\n\n    C --> D[Focus Session: 25 min]\n    D --> E[Short Break: 5 min]\n\n    E --> F{Completed 4 Pomodoros?}\n    F -->|No| C\n    F -->|Yes| G[Long Break: 15-30 min]\n\n    G --> H[Log Progress]\n    H --> I[Update Spaced Repetition]\n\n    I --> J{Goals Achieved?}\n    J -->|No| C\n    J -->|Yes| K[Session Complete]\n\n    K --> L[Analyze Performance]\n```\n\n---\n\n## Pomodoro Technique\n\n### Classic Pomodoro Structure\n\n```\nSession 1: ██████████████████████████ (25 min) → ████ (5 min break)\nSession 2: ██████████████████████████ (25 min) → ████ (5 min break)\nSession 3: ██████████████████████████ (25 min) → ████ (5 min break)\nSession 4: ██████████████████████████ (25 min) → ████████████ (15 min break)\n\nRepeat cycle...\n```\n\n### Pomodoro Session Template\n\n```markdown\n## Study Session: [Topic]\n**Date**: 2024-03-15\n**Total Time**: 2 hours (4 Pomodoros)\n\n### Pomodoro 1 (9:00-9:25)\n**Task**: Read Chapter 5, Sections 5.1-5.2\n**Completed**: ✓\n**Distractions**: 0\n**Focus Level**: 4/5\n\n**Break (9:25-9:30)**: 5 minutes\n**Activity**: Stretch, water\n\n### Pomodoro 2 (9:30-9:55)\n**Task**: Take notes on Section 5.2\n**Completed**: ✓\n**Distractions**: 2 (phone notifications)\n**Focus Level**: 3/5\n\n**Break (9:55-10:00)**: 5 minutes\n\n### Pomodoro 3 (10:00-10:25)\n**Task**: Create flashcards from notes\n**Completed**: ✓\n**Distractions**: 0\n**Focus Level**: 5/5\n\n**Break (10:25-10:30)**: 5 minutes\n\n### Pomodoro 4 (10:30-10:55)\n**Task**: Practice problems 1-5\n**Completed**: ⚠️  (Completed 3/5)\n**Distractions**: 1\n**Focus Level**: 4/5\n\n**Long Break (10:55-11:10)**: 15 minutes\n**Activity**: Walk outside, snack\n\n---\n\n**Session Summary**:\n- Total Pomodoros: 4\n- Total Focus Time: 100 minutes\n- Average Focus Level: 4/5\n- Total Distractions: 3\n- Completion Rate: 87.5%\n```\n\n### Modified Pomodoro Variations\n\n**Extended Pomodoro** (for deep work):\n- Focus: 50 minutes\n- Break: 10 minutes\n- Long break: 30 minutes (after 2 sessions)\n\n**Short Pomodoro** (for difficult material):\n- Focus: 15 minutes\n- Break: 3 minutes\n- Long break: 10 minutes (after 4 sessions)\n\n**Flexible Pomodoro** (task-based):\n- Focus: Until subtask complete (max 45 min)\n- Break: Proportional (1 min per 5 min work)\n\n---\n\n## Spaced Repetition System\n\n### SM-2 Algorithm\n\n**Core Principle**: Review material at increasing intervals based on recall quality\n\n**Formula**:\n```\nIf quality ≥ 3:\n    interval = previous_interval × easiness_factor\n    easiness_factor = max(1.3, ef + (0.1 - (5 - quality) × (0.08 + (5 - quality) × 0.02)))\n\nIf quality < 3:\n    interval = 1 day (reset)\n    repetition = 0 (restart)\n```\n\n### Quality Ratings (0-5)\n\n- **5**: Perfect recall, easy\n- **4**: Correct, with hesitation\n- **3**: Correct, with difficulty\n- **2**: Incorrect, but familiar\n- **1**: Incorrect, guess\n- **0**: Complete blackout\n\n### Spaced Repetition Schedule\n\n```mermaid\ntimeline\n    title Flashcard Review Schedule (Starting March 1)\n    March 1 : First Review\n            : Quality: 4\n    March 2 : Second Review (1 day)\n            : Quality: 5\n    March 5 : Third Review (3 days)\n            : Quality: 4\n    March 12 : Fourth Review (7 days)\n             : Quality: 5\n    March 29 : Fifth Review (17 days)\n             : Quality: 5\n    May 9 : Sixth Review (41 days)\n```\n\n### Spaced Repetition Tracking\n\n```javascript\nconst flashcard = {\n  id: \"fc_001\",\n  front: \"What is a neural network?\",\n  back: \"Computing system inspired by biological neural networks\",\n  history: [\n    { date: \"2024-03-01\", quality: 4, interval: 1, easinessFactor: 2.5 },\n    { date: \"2024-03-02\", quality: 5, interval: 3, easinessFactor: 2.6 },\n    { date: \"2024-03-05\", quality: 4, interval: 7, easinessFactor: 2.5 },\n    { date: \"2024-03-12\", quality: 5, interval: 17, easinessFactor: 2.6 }\n  ],\n  nextReview: \"2024-03-29\",\n  masteryLevel: \"proficient\"  // learning → proficient → mastered\n};\n```\n\n### Daily Review Schedule\n\n```markdown\n## Today''s Review: March 15, 2024\n\n### Due Today (8 cards)\n1. Neural network definition - [Review]\n2. Backpropagation algorithm - [Review]\n3. Gradient descent formula - [Review]\n4. Overfitting definition - [Review]\n5. Training vs test set - [Review]\n6. Activation functions - [Review]\n7. Loss function types - [Review]\n8. Regularization purpose - [Review]\n\n### Upcoming (Next 3 Days)\n- March 16: 5 cards\n- March 17: 3 cards\n- March 18: 7 cards\n\n### Overdue (2 cards)\n- Supervised learning (2 days overdue) - [Priority Review]\n- Feature engineering (1 day overdue) - [Priority Review]\n\n**Estimated Time**: 25 minutes (10 cards × 2.5 min avg)\n```\n\n---\n\n## Study Plan Generation\n\n### Weekly Study Plan Template\n\n```markdown\n# Week 3 Study Plan: Machine Learning Fundamentals\n**Period**: March 15-21, 2024\n**Goal**: Complete Chapter 5, Master 50 flashcards\n\n## Monday (2 hours)\n- **9:00-9:25**: Read Section 5.1 📖\n- **9:30-9:55**: Take notes 📝\n- **10:00-10:25**: Create flashcards 🃏\n- **10:30-10:55**: Review yesterday''s cards (SR) 🔄\n\n## Tuesday (2 hours)\n- **9:00-9:25**: Read Section 5.2 📖\n- **9:30-9:55**: Watch lecture video 🎥\n- **10:00-10:25**: Practice problems 1-5 ✏️\n- **10:30-10:55**: Review flashcards (SR) 🔄\n\n## Wednesday (1.5 hours)\n- **9:00-9:25**: Read Section 5.3 📖\n- **9:30-9:55**: Concept map creation 🗺️\n- **10:00-10:25**: Quiz practice 📋\n\n## Thursday (2 hours)\n- **9:00-9:25**: Review notes from sections 5.1-5.3 📝\n- **9:30-9:55**: Practice problems 6-10 ✏️\n- **10:00-10:25**: Create summary sheet 📄\n- **10:30-10:55**: Flashcard review (SR) 🔄\n\n## Friday (2 hours)\n- **9:00-9:25**: Chapter 5 comprehensive review 🔍\n- **9:30-9:55**: Practice exam questions 🎓\n- **10:00-10:25**: Identify weak areas 🎯\n- **10:30-10:55**: Targeted practice 💪\n\n## Saturday (1 hour)\n- **10:00-10:25**: Flashcard marathon (SR) 🔄\n- **10:30-10:55**: Optional: Additional practice ➕\n\n## Sunday (Rest/Light Review)\n- **Evening**: 15-minute flashcard review 🔄\n\n---\n\n**Total Planned Time**: 10.5 hours\n**Focus Distribution**:\n- Reading: 30%\n- Practice: 25%\n- Review (SR): 25%\n- Note-taking/Synthesis: 20%\n```\n\n### Semester Study Plan\n\n```mermaid\ngantt\n    title Semester Study Plan\n    dateFormat  YYYY-MM-DD\n    section Weeks 1-4\n    Chapter 1-2           :2024-01-15, 14d\n    Midterm 1 Prep        :2024-01-29, 7d\n    section Weeks 5-8\n    Chapter 3-4           :2024-02-05, 14d\n    Project Phase 1       :2024-02-12, 14d\n    section Weeks 9-12\n    Chapter 5-6           :2024-02-26, 14d\n    Midterm 2 Prep        :2024-03-11, 7d\n    section Weeks 13-16\n    Chapter 7-8           :2024-03-18, 14d\n    Project Phase 2       :2024-03-25, 14d\n    Final Exam Prep       :2024-04-08, 7d\n    Final Exam            :milestone, 2024-04-15, 0d\n```\n\n---\n\n## Progress Tracking\n\n### Topic Mastery Levels\n\n```javascript\nconst topicProgress = {\n  \"Neural Networks\": {\n    status: \"learning\",           // not-started, learning, proficient, mastered\n    timeSpent: 450,                // minutes\n    flashcardsCreated: 23,\n    flashcardsMastered: 15,\n    practiceProblemsCompleted: 8,\n    practiceProblemsCorrect: 6,\n    accuracy: 0.75,\n    lastReviewed: \"2024-03-14\",\n    nextReview: \"2024-03-16\",\n    confidenceLevel: 7,            // 1-10\n    notes: \"Need more practice with backpropagation\"\n  }\n};\n```\n\n### Progress Visualization\n\n```mermaid\ngantt\n    title Learning Progress: Machine Learning Course\n    dateFormat  YYYY-MM-DD\n    section Chapter 1\n    Completed           :done, 2024-01-15, 7d\n    section Chapter 2\n    Completed           :done, 2024-01-22, 7d\n    section Chapter 3\n    Completed           :done, 2024-01-29, 7d\n    section Chapter 4\n    In Progress         :active, 2024-02-05, 4d\n    section Chapter 5\n    Not Started         :2024-02-09, 7d\n```\n\n### Study Analytics Dashboard\n\n```markdown\n# Study Analytics: Week of March 15-21\n\n## Time Investment\n- **Total Study Time**: 12.5 hours\n- **Target**: 10 hours ✅\n- **Focus Time**: 10 hours (80%)\n- **Break Time**: 2.5 hours (20%)\n\n## Productivity Metrics\n- **Pomodoros Completed**: 30\n- **Average Focus Level**: 4.2/5\n- **Distractions**: 8 total (0.27 per Pomodoro)\n- **Peak Focus Hours**: 9-11 AM\n\n## Learning Progress\n- **Flashcards Reviewed**: 87\n- **New Cards Created**: 23\n- **Cards Mastered**: 15\n- **Average Recall Quality**: 4.1/5\n\n## Topic Coverage\n- ✅ Chapter 5 Reading (100%)\n- ✅ Practice Problems (80%)\n- ⚠️  Concept Maps (60%)\n- ❌ Quiz Preparation (30%)\n\n## Weak Areas Identified\n1. Backpropagation algorithm (accuracy: 60%)\n2. Gradient descent optimization (accuracy: 70%)\n3. Overfitting vs underfitting (accuracy: 75%)\n\n## Next Week Goals\n- [ ] Complete Chapter 6\n- [ ] Master 20 new flashcards\n- [ ] Achieve 85%+ on practice quiz\n- [ ] Review all weak areas\n```\n\n---\n\n## Break Optimization\n\n### Break Activities by Duration\n\n**Micro-breaks (1-2 minutes)**:\n- Eye exercises (20-20-20 rule: every 20 min, look 20 feet away for 20 sec)\n- Stand and stretch\n- Deep breathing\n- Drink water\n\n**Short breaks (5 minutes)**:\n- Walk around room\n- Light stretching\n- Healthy snack\n- Quick tidying\n- Social media (limited)\n\n**Long breaks (15-30 minutes)**:\n- Walk outside\n- Exercise/yoga\n- Full meal\n- Power nap (20 min)\n- Call friend/family\n\n**Avoid During Breaks**:\n- ❌ Work-related content\n- ❌ Heavy meals (causes drowsiness)\n- ❌ Stressful news/social media\n- ❌ Starting new complex tasks\n\n### Break Effectiveness Matrix\n\n| Activity | Energy Restoration | Mental Clarity | Recommended Frequency |\n|----------|-------------------|----------------|----------------------|\n| Walking outside | ⭐⭐⭐ | ⭐⭐⭐ | Every 2-3 Pomodoros |\n| Light stretching | ⭐⭐⭐ | ⭐⭐ | Every Pomodoro |\n| Power nap | ⭐⭐⭐ | ⭐⭐⭐ | Once daily (if needed) |\n| Hydration | ⭐⭐ | ⭐⭐⭐ | Every Pomodoro |\n| Healthy snack | ⭐⭐ | ⭐⭐ | Every 3-4 Pomodoros |\n| Social media | ⭐ | ⭐ | Avoid if possible |\n\n---\n\n## Focus Time Optimization\n\n### Peak Performance Times\n\n**Identify Your Chronotype**:\n\n**Morning Lark** (peak: 8-12 PM):\n- Schedule difficult material in morning\n- Use afternoon for review and practice\n- Earlier sleep/wake schedule\n\n**Night Owl** (peak: 4-10 PM):\n- Warm-up with easier tasks in morning\n- Save demanding work for afternoon/evening\n- Later sleep/wake schedule\n\n**Hummingbird** (flexible):\n- Multiple shorter study sessions\n- Adapt to circumstances\n- Mix difficult and easy throughout day\n\n### Environmental Optimization\n\n**Physical Environment**:\n- ✅ Clean, organized workspace\n- ✅ Good lighting (natural light preferred)\n- ✅ Comfortable temperature (68-72°F)\n- ✅ Ergonomic seating\n- ✅ Minimal visual distractions\n\n**Digital Environment**:\n- ✅ Close unnecessary tabs/apps\n- ✅ Use website blockers during Pomodoros\n- ✅ Phone on silent/airplane mode\n- ✅ Notifications disabled\n- ✅ Study music/white noise (if helpful)\n\n### Distraction Management\n\n**Before Session**:\n```markdown\n## Pre-Study Checklist\n- [ ] Phone on silent, face-down\n- [ ] Close social media tabs\n- [ ] Water bottle filled\n- [ ] Bathroom break taken\n- [ ] Study materials prepared\n- [ ] Timer set\n- [ ] Goals written down\n```\n\n**During Session**:\n- **Distraction Log**: Write down distractions without acting on them\n- **Two-Minute Rule**: If it takes <2 min, do it during break\n- **Scheduled Worry Time**: Set aside 15 min later to address concerns\n\n---\n\n## Study Session Templates\n\n### Exam Preparation Session\n\n```markdown\n# Exam Prep Session: Midterm 2\n**Date**: March 20, 2024\n**Exam Date**: March 25, 2024\n**Duration**: 3 hours\n\n## Session Structure\n\n### Hour 1: Active Recall (3 Pomodoros)\n- **Pomodoro 1**: Practice quiz (no notes)\n- **Pomodoro 2**: Review incorrect answers\n- **Pomodoro 3**: Flashcard sprint (50 cards)\n\n### Hour 2: Problem Solving (3 Pomodoros)\n- **Pomodoro 4**: Practice problems set 1\n- **Pomodoro 5**: Practice problems set 2\n- **Pomodoro 6**: Review solutions\n\n### Hour 3: Synthesis (2 Pomodoros)\n- **Pomodoro 7**: Create concept map of all topics\n- **Pomodoro 8**: Identify and study weak areas\n\n**Long Break**: 30 minutes (lunch)\n\n**Optional Hour 4**: Spaced repetition review\n```\n\n### Deep Learning Session\n\n```markdown\n# Deep Learning Session: New Chapter\n**Date**: March 15, 2024\n**Topic**: Chapter 5 - Neural Networks\n**Duration**: 2 hours\n\n## Session Goals\n1. Read and understand Sections 5.1-5.2\n2. Create comprehensive notes\n3. Generate 20 flashcards\n4. Complete 3 practice problems\n\n## Pomodoro Breakdown\n- **Pomodoro 1-2**: Active reading with annotations\n- **Pomodoro 3**: Note-taking and synthesis\n- **Pomodoro 4**: Flashcard creation\n- **Pomodoro 5**: Practice problems\n- **Pomodoro 6**: Review and self-quiz\n\n**Success Criteria**:\n- [ ] Can explain main concepts without notes\n- [ ] Created quality flashcards for all key terms\n- [ ] Solved practice problems correctly\n```\n\n---\n\n## Advanced Features\n\nFor detailed information:\n- **Spaced Repetition Science**: `resources/spaced-repetition-science.md`\n- **Study Techniques Guide**: `resources/study-techniques.md`\n- **Focus Optimization**: `resources/focus-optimization.md`\n- **Session Templates**: `resources/session-templates.md`\n\n## References\n\n- Pomodoro Technique (Francesco Cirillo)\n- SM-2 Algorithm (SuperMemo)\n- Spaced Repetition research (Ebbinghaus, Piotr Woźniak)\n- Peak Performance research (circadian rhythms)\n- Cognitive Load Theory for learning optimization\n\n"},"lastSynced":"2026-03-07T04:18:10.277Z","agentAnalysis":{"suitability":{"en":"Ideal for Education-focused AI Agents seeking to enhance student learning outcomes through personalized study session management.","zh":"适用于专注于教育的AI代理，旨在通过个性化的学习课程管理来提高学生的学习成果。","ja":"教育に焦点を当てたAIエージェントに適しており、個別の学習セッション管理を通じて学生の学習成果を向上させることを目指しています。","ko":"교육에 중점을 둔 AI 에이전트에게 적합하며, 개인화된 학습 세션 관리를 통해 학생들의 학습 성과를 향상시키는 것을 목표로 합니다.","es":"Ideal para Agentes de IA con enfoque en Educación que buscan mejorar los resultados de aprendizaje de los estudiantes a través de la gestión de sesiones de estudio personalizadas.","fr":"Idéal pour les Agents d''IA axés sur l''Éducation qui cherchent à améliorer les résultats d''apprentissage des étudiants grâce à une gestion de sessions d''étude personnalisées.","de":"Ideal für Bildungsorientierte KI-Agents, die die Lernergebnisse der Schüler durch personalisierte Lernsitzungsmanagement verbessern möchten.","pt":"Ideal para Agentes de IA com foco em Educação que buscam melhorar os resultados de aprendizado dos alunos por meio de gerenciamento de sessões de estudo personalizadas.","ru":"Идеально для AI-агентов, ориентированных на образование, стремящихся повысить результаты обучения студентов за счет персонализированного управления учебными сессиями.","ar":"مثالي لعميل الذكاء الاصطناعي ذي التركيز على التعليم الذي يسعى لتعزيز نتائج التعلم الطلابي من خلال إدارة جلسات الدراسة المخصصة."},"recommendation":{"en":"Empowers agents to generate optimized study plans using the Pomodoro technique and SM-2 algorithm for spaced repetition, while tracking progress through time spent, topics covered, and mastery level analytics.","zh":"赋予代理生成使用番茄工作法和SM-2算法进行间隔重复的优化学习计划的能力，同时通过花费时间、覆盖的主题和掌握级别分析来跟踪进度。","ja":"エージェントに、ポモドーロテクニックとSM-2アルゴリズムを使用して間隔復習を行う最適化された学習計画を生成する能力を与え、かつ、時間の経過、カバーしたトピック、習得レベル分析を通じて進度を追跡します。","ko":"에이전트에게 포모도로 기법과 SM-2 알고리즘을 사용하여 간격 반복을 수행하는 최적화된 학습 계획을 생성하는 능력을 부여하며,同時에 시간 경과, 다루어진 주제, 마스터 레벨 분석을 통해 진행 상황을 추적합니다.","es":"Habilita a los agentes a generar planes de estudio optimizados utilizando la técnica Pomodoro y el algoritmo SM-2 para la repetición espaciada, mientras rastrea el progreso a través del tiempo dedicado, temas cubiertos y análisis de nivel de dominio.","fr":"Permet aux agents de générer des plans d''étude optimisés en utilisant la technique Pomodoro et l''algorithme SM-2 pour la répétition espacée, tout en suivant les progrès grâce au temps passé, aux sujets couverts et à l''analyse du niveau de maîtrise.","de":"Ermöglicht es den Agents, optimierte Lernpläne zu generieren, indem die Pomodoro-Technik und der SM-2-Algorithmus für die verteilte Wiederholung verwendet werden, während der Fortschritt über die verbrachte Zeit, die behandelten Themen und die Analyse des Beherrschungsgrades nachverfolgt wird.","pt":"Habilita os agentes a gerar planos de estudo otimizados usando a técnica Pomodoro e o algoritmo SM-2 para repetição espaçada, ao mesmo tempo em que rastreia o progresso por meio do tempo gasto, tópicos abordados e análise de nível de domínio.","ru":"Наделяет агентов возможностью генерировать оптимизированные планы обучения с использованием техники Помодоро и алгоритма SM-2 для间隔 повторения, а также отслеживать прогресс по времени, затраченному на изучение тем и аналитике уровня освоения.","ar":"يمنح الوكيل القدرة على توليد خطط دراسية محسنة باستخدام تقنية بومودورو و خوارزمية SM-2 للتعزيز المتباعد، مع تتبع التقدم من خلال الوقت المستغرق والمواضيع التي غطيت وتحليل مستوى الإتقان."},"useCases":{"en":["Automating study schedule generation based on individual learning goals","Implementing spaced repetition for efficient review and retention","Tracking student progress and adjusting study plans accordingly"],"zh":["基于个人学习目标自动生成学习时间表","实施间隔重复以实现高效的复习和保留","跟踪学生进度并相应地调整学习计划"],"ja":["個々の学習目標に基づいて学習スケジュールを自動生成する","間隔復習を実施して効率的な復習と保持を実現する","学生の進度を追跡し、学習計画をそれに応じて調整する"],"ko":["개인 학습 목표에 따라 학습 일정 자동 생성하기","간격 반복을 구현하여 효율적인 복습과 보유를 달성하기","학생들의 진행 상황을 추적하고 학습 계획을 그에 따라 조정하기"],"es":["Automatización de la generación de horarios de estudio basada en objetivos de aprendizaje individuales","Implementación de la repetición espaciada para una revisión y retención eficientes","Seguimiento del progreso de los estudiantes y ajuste de los planes de estudio en consecuencia"],"fr":["Automation de la génération d''horaires d''étude basée sur les objectifs d''apprentissage individuels","Mise en œuvre de la répétition espacée pour une révision et une rétention efficaces","Suivi des progrès des étudiants et ajustement des plans d''étude en conséquence"],"de":["Automatisierung der Erstellung von Lernplänen basierend auf individuellen Lernzielen","Implementierung der verteilten Wiederholung für eine effiziente Überprüfung und Behaltens","Verfolgung der Lernfortschritte der Schüler und Anpassung der Lernpläne entsprechend"],"pt":["Automatizar a geração de cronogramas de estudo com base em objetivos de aprendizado individuais","Implementar repetição espaçada para revisão e retenção eficientes","Rastrear o progresso do aluno e ajustar os planos de estudo conforme necessário"],"ru":["Автоматизировать генерацию учебного графика на основе индивидуальных целей обучения","Реализовать интервальное повторение для эффективного обзора и запоминания","Отслеживать прогресс студента и корректировать планы обучения соответственно"],"ar":["تحسين الجدولة الدراسية تلقائيا بناء على أهداف التعلم الفردية","تنفيذ التكرار المتباعد من أجل المراجعة والاحتفاظ الفعالين","تتبع تقدم الطالب وتعديل خطط الدراسة وفقا لذلك"]},"limitations":{"en":["Requires integration with student data and learning objectives","Dependent on accurate time tracking and user engagement"],"zh":["需要与学生数据和学习目标集成","依赖于准确的时间跟踪和用户参与"],"ja":["学生データや学習目標との統合が必要","正確な時間の追跡やユーザーのエンゲージメントに依存する"],"ko":["학생 데이터 및 학습 목표와의 통합이 필요함","정확한 시간 추적 및 사용자 참여에 의존함"],"es":["Requiere integración con datos de estudiantes y objetivos de aprendizaje","Dependiente de un seguimiento de tiempo preciso y de la participación del usuario"],"fr":["Nécessite une intégration avec les données des étudiants et les objectifs d''apprentissage","Dépendante d''un suivi du temps précis et de l''engagement de l''utilisateur"],"de":["Erfordert die Integration mit Schülerdaten und Lernzielen","Abhängig von einer genauen Zeiterfassung und der Nutzerbeteiligung"],"pt":["Exige integração com dados do aluno e objetivos de aprendizado","Depende de rastreamento de tempo preciso e engajamento do usuário"],"ru":["Требует интеграции со студенческими данными и целями обучения","Зависит от точного отслеживания времени и вовлеченности пользователя"],"ar":["يتطلب تكامل البيانات الطلابية وأهداف التعلم","يعتمد على تتبع دقيق للزمن ومشاركة المستخدم"]},"version":4},"contentHash":"3338895124dd2574fba053ff50ede3f8b5ed1f2cedf8b6947d38bb7c6d6fa16a","qualityScore":33}');
