INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pelchers/SessionSaver/managing-study-sessions', 'managing-study-sessions', 'pelchers', 'SessionSaver', 'community', 'managing-study-sessions pelchers SessionSaver community Managing-study-sessions is an evidence-based study session planning and tracking system that optimizes learning through proven techniques. It benefits students and learners by providing personalized study plans and progress tracking. AIエージェント学习管理工具提供Pomodoro技巧、间隔重复和学习计划生成等功能，帮助开发者优化学习效果 AIエージェントを使用した学習セッション管理は、Pomodoro技巧や間隔復習等の機能を提供し、開発者の学習効果を向上させる AI 에이전트를 이용한 학습 세션 관리는 Pomodoro 기법, 간격 반복, 학습 계획 생성 등 기능을 제공하여 개발자의 학습 효과를 향상시킵니다 El sistema de gestión de sesiones de estudio utiliza técnicas como Pomodoro y repetición espaciada para optimizar el aprendizaje Le système de gestion de sessions d''étude utilise des techniques comme Pomodoro et répétition espacée pour optimiser l''apprentissage Das Lernsitzungs-Management-System verwendet Techniken wie Pomodoro und Spaced Repetition, um das Lernen zu optimieren O skill de gerenciamento de sessões de estudo utiliza técnicas comprovadas como Pomodoro e Spaced Repetition para otimizar o aprendizado ИИ Агент для управления сессиями обучения использует технику Помодоро и алгоритм SM-2 для оптимального повторения الوكلاء الذكية لإدارة جلسات الدراسة تستخدم تقنية Помодоро و خوارزمية SM-2 لمراجعة الأمثلة بفعالية how to use managing-study-sessions what is managing-study-sessions managing-study-sessions alternative managing-study-sessions vs traditional studying managing-study-sessions install guide managing-study-sessions setup for AI agents evidence-based study planning Pomodoro technique for learning spaced repetition algorithm AIエージェント学习管理 Pomodoro技巧 间隔重复 学习计划生成 进度跟踪 AI工具学习 开发者学习管理 Pomodoro technique integration with 25-min focus + 5-min breaks Spaced repetition using SM-2 algorithm for optimal review timing Study plan generation with personalized schedules based on goals Progress tracking with time spent, topics covered, and mastery level Managing-study-sessions is an AI agent skill that integrates Pomodoro technique, spaced repetition, and study plan generation to optimize learning outcomes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Jimmy-Jung/claude_symbiote/solid', 'community', 'Jimmy-Jung', 'claude_symbiote', 'Jimmy-Jung/claude_symbiote', 'solid', 0, 0, 33, '2026-02-16T07:34:44Z', '2026-03-07T04:19:05.490Z', 'c78a69ab375c4b736da973aa1320d93f1ad4ea12dcce481aff052b1a24443af3', '{"id":"Jimmy-Jung/claude_symbiote/solid","name":"solid","description":{"en":"The SOLID skill helps developers write maintainable and scalable iOS code by applying object-oriented design principles, including dependency management and responsibility separation.","zh":"SOLID 原则是 iOS 面向对象设计的指导方针，帮助开发者编写可维护和可扩展的代码","ja":"SOLID 原則は iOS オブジェクト指向設計のガイドラインであり、開発者がメンテナンス可能で拡張可能なコードを書くのに役立ちます","ko":"SOLID 원칙은 iOS 객체지향 설계의 가이드라인으로 개발자가 유지보수 가능하고 확장 가능한 코드를 작성하도록 도와줍니다","es":"SOLID es un conjunto de principios de diseño de objetos que ayudan a escribir código iOS mantenible y escalable. Aprende a aplicar SRP, OCP, LSP, ISP y DIP.","fr":"SOLID est un ensemble de principes de conception d''objets qui aident à écrire du code iOS maintenable et évolutif. Apprenez à appliquer SRP, OCP, LSP, ISP et DIP.","de":"SOLID ist eine Sammlung von Objekt-Design-Prinzipien, die helfen, wartbaren und skalierbaren iOS-Code zu schreiben. Erfahren Sie, wie Sie SRP, OCP, LSP, ISP und DIP anwenden.","pt":"O SOLID é um conjunto de princípios para desenvolvimento de software que visam melhorar a maintainabilidade e escalabilidade do código. Ele inclui princípios como SRP, OCP, LSP, ISP e DIP.","ru":"SOLID - это набор принципов разработки программного обеспечения, направленных на улучшение поддерживаемости и масштабируемости кода. Он включает принципы SRP, OCP, LSP, ISP и DIP.","ar":"SOLID هو مجموعة من المبادئ لتعزيز صيانة وتوسيع 코드 البرامج. تشمل مبادئ SRP و OCP و LSP و ISP و DIP."},"seo":{"title":{"en":"SOLID: iOS Object-Oriented Design Guide for AI Agents","zh":"SOLID 原则应用指南 - iOS 面向对象设计最佳实践","ja":"SOLID 原則の適用 - iOS オブジェクト指向設計ガイド","ko":"SOLID 원칙 적용 가이드 - iOS 객체지향 설계 베스트 프랙티스","es":"Guía de configuración de SOLID para desarrollo de iOS","fr":"Guide de mise en œuvre de SOLID pour le développement iOS","de":"SOLID-Setup-Anleitung für iOS-Entwicklung","pt":"Guia de Configuração SOLID: Princípios de Desenvolvimento...","ru":"ИИ Агенты: SOLID Принципы для Разработки iOS","ar":"دليل تكوين SOLID: مبادئ تصميم iOS"},"description":{"en":"Unlock maintainable and scalable iOS code with SOLID principles - learn how to apply SRP, OCP, LSP, ISP, and DIP for better design","zh":"了解如何应用 SOLID 原则来编写可维护和可扩展的 iOS 代码，包括依赖管理、责任分离和扩展性设计","ja":"SOLID 原則を適用してメンテナンス可能で拡張可能な iOS コードを書く方法を学びます。依存関係管理、責任分離、拡張性設計などを含みます","ko":"SOLID 원칙을 적용하여 유지보수 가능하고 확장 가능한 iOS 코드를 작성하는 방법을 알아보세요. 의존성 관리, 책임 분리, 확장성을 고려한 설계를 지원합니다","es":"Aprende a aplicar los principios SOLID para escribir código iOS mantenible y escalable. Descubre cómo gestionar dependencias y separar responsabilidades.","fr":"Découvrez comment appliquer les principes SOLID pour écrire du code iOS maintenable et évolutif. Apprenez à gérer les dépendances et à séparer les responsabi...","de":"Erfahren Sie, wie Sie die SOLID-Prinzipien anwenden, um wartbare und skalierbare iOS-Code zu schreiben. Lernen Sie, wie Sie Abhängigkeiten verwalten und Vera...","pt":"Aprenda a aplicar os princípios SOLID para desenvolver código iOS maintainável e escalável. Descubra como gerenciar dependências e separar responsabilidades.","ru":"Узнайте, как применять принципы SOLID для разработки поддерживаемого и масштабируемого кода iOS. Откройте для себя, как управлять зависимостями и разделять о...","ar":"تعلم كيفية تطبيق مبادئ SOLID لكتابة код iOS قابل للصيانة والتحديث. اكتشف كيفية إدارة التبعيات وفصل المسؤوليات."},"definition":{"en":"SOLID is a set of object-oriented design principles for iOS development, including SRP, OCP, LSP, ISP, and DIP, aiming to improve code maintainability and scalability.","zh":"SOLID 原则是一套面向对象设计的原则，包括单一责任原则、开闭原则、里氏替换原则、接口分离原则和依赖反转原则","ja":"SOLID 原則はオブジェクト指向設計の原則のセットであり、単一責任原則、開閉原則、リースコフ置換原則、インターフェース分離原則、依存反転原則を含みます","ko":"SOLID 원칙은 객체지향 설계의 원칙으로 SRP, OCP, LSP, ISP, DIP를 포함합니다","es":"SOLID es un acrónimo que representa los principios de Single Responsibility, Open-Closed, Liskov Substitution, Interface Segregation y Dependency Inversion.","fr":"SOLID est un acronyme qui représente les principes de Single Responsibility, Open-Closed, Liskov Substitution, Interface Segregation et Dependency Inversion.","de":"SOLID ist ein Akronym, das die Prinzipien von Single Responsibility, Open-Closed, Liskov Substitution, Interface Segregation und Dependency Inversion repräsentiert.","pt":"SOLID é um acrônimo que representa os princípios de desenvolvimento de software: Single Responsibility Principle, Open-Closed Principle, Liskov Substitution Principle, Interface Segregation Principle e Dependency Inversion Principle.","ru":"SOLID - это акроним, представляющий принципы разработки программного обеспечения: принцип единой ответственности, принцип открытости-закрытости, принцип замены Лискова, принцип разделения интерфейса и принцип инверсии зависимостей.","ar":"SOLID هو اختصار لمبادئ برمجة البرمجيات: مبدأ المسؤولية الواحدة، مبدأ الانفتاح-الغلق، مبدأ استبدال لاسكوف، مبدأ تجزئة الواجهة ومبدأ عكس التبعية."},"features":{"en":["Applies Single Responsibility Principle (SRP) for modular design","Supports Open-Closed Principle (OCP) for extensibility","Ensures Liskov Substitution Principle (LSP) for subtype compatibility","Implements Interface Segregation Principle (ISP) for minimal interfaces","Follows Dependency Inversion Principle (DIP) for high-level module independence"],"zh":["单一责任原则（SRP）","开闭原则（OCP）","里氏替换原则（LSP）","接口分离原则（ISP）","依赖反转原则（DIP）"],"ja":["単一責任原則（SRP）","開閉原則（OCP）","リースコフ置換原則（LSP）","インターフェース分離原則（ISP）","依存反転原則（DIP）"],"ko":["SRP（단일 책임 원칙）","OCP（개방 폐쇄 원칙）","LSP（리스코프 치환 원칙）","ISP（인터페이스 분리 원칙）","DIP（의존성 역전 원칙）"],"es":["Aplicación de los principios SRP, OCP, LSP, ISP y DIP","Gestión de dependencias y separación de responsabilidades","Diseño de objetos escalables y mantenibles","Uso de patrones de diseño para mejorar la calidad del código","Mejora de la legibilidad y mantenibilidad del código"],"fr":["Application des principes SRP, OCP, LSP, ISP et DIP","Gestion des dépendances et séparation des responsabilités","Conception d''objets évolutifs et maintenables","Utilisation de patrons de conception pour améliorer la qualité du code","Amélioration de la lisibilité et de la maintenabilité du code"],"de":["Anwendung der Prinzipien SRP, OCP, LSP, ISP und DIP","Verwaltung von Abhängigkeiten und Trennung von Verantwortungen","Entwurf von Objekten, die wartbar und skalierbar sind","Verwendung von Entwurfsmustern, um die Code-Qualität zu verbessern","Verbesserung der Lesbarkeit und Wartbarkeit des Codes"],"pt":["Aplicação dos princípios SRP, OCP, LSP, ISP e DIP","Gerenciamento de dependências e separação de responsabilidades","Desenvolvimento de código iOS maintainável e escalável","Utilização de referências para detalhes de cada princípio","Exemplos de código iOS para ilustrar cada princípio"],"ru":["Применение принципов SRP, OCP, LSP, ISP и DIP","Управление зависимостями и разделение ответственности","Разработка поддерживаемого и масштабируемого кода iOS","Использование ссылок для подробностей каждого принципа","Примеры кода iOS для иллюстрации каждого принципа"],"ar":["تطبيق مبادئ SRP و OCP و LSP و ISP و DIP","إدارة التبعيات وفصل المسؤوليات","كتابة код iOS قابل للصيانة والتحديث","استخدام المراجع لتفاصيل كل مبدأ","أمثلة من код iOS لتوضيح كل مبدأ"]},"keywords":{"en":["SOLID principles iOS","how to use SOLID in iOS development","SOLID vs MVC","SOLID setup guide for iOS","what is SOLID in object-oriented design","SOLID alternative for iOS development","SRP OCP LSP ISP DIP examples"],"zh":["SOLID 原则","iOS 面向对象设计","依赖管理","责任分离","扩展性设计","AIエージェント","面向对象编程"],"ja":["SOLID 原則","iOS オブジェクト指向設計","依存関係管理","責任分離","拡張性設計","AIエージェント","オブジェクト指向プログラミング"],"ko":["SOLID 원칙","iOS 객체지향 설계","의존성 관리","책임 분리","확장성 설계","AI 에이전트","객체지향 프로그래밍"],"es":["SOLID principios","diseño de objetos","iOS desarrollo","código mantenible","escalable","SRP","OCP","LSP","ISP","DIP"],"fr":["principes SOLID","conception d''objets","développement iOS","code maintenable","évolutif","SRP","OCP","LSP","ISP","DIP"],"de":["SOLID-Prinzipien","Objekt-Design","iOS-Entwicklung","wartbarer Code","skalierbar","SRP","OCP","LSP","ISP","DIP"],"pt":["SOLID","desenvolvimento de software","princípios de desenvolvimento","código iOS","maintainabilidade","escalabilidade","gerenciamento de dependências","separação de responsabilidades"],"ru":["SOLID","разработка программного обеспечения","принципы разработки","код iOS","поддерживаемость","масштабируемость","управление зависимостями","разделение ответственности"],"ar":["SOLID","برمجة البرمجيات","مبادئ البرمجة","كود iOS","صيانة","تحديث","إدارة التبعيات","فصل المسؤوليات"]}},"owner":"Jimmy-Jung","repo":"claude_symbiote","repoPath":"Jimmy-Jung/claude_symbiote","stars":0,"forks":0,"updatedAt":"2026-02-16T07:34:44Z","topics":[],"category":"community","skillMd":{"name":"solid","description":"SOLID 원칙 기반 iOS 객체지향 설계. 의존성 관리, 확장성, 유지보수성을 위한 5가지 핵심 원칙 적용. Use when designing class hierarchies, applying design patterns, reviewing object-oriented code structure, or applying SOLID principles during architecture design and refactoring.","bodyPreview":"# SOLID 원칙 - iOS 객체지향 설계 가이드\n\nSOLID 원칙을 적용하여 유지보수 가능하고 확장 가능한 iOS 코드를 작성한다.\n의존성 관리, 책임 분리, 확장성을 고려한 설계를 지원한다.\n\n## 상세 원칙 참조\n\n각 원칙의 상세 내용, iOS 예제, 안티패턴, 리팩토링 방법은 references 디렉토리를 참고한다:\n\n| 원칙 | 참조 파일 | 핵심 |\n|------|-----------|------|\n| SRP | `references/srp.md` | 모듈은 하나의 Actor에게만 책임 |\n| OCP | `references/ocp.md` | 확장에 열리고 수정에 닫힘 |\n| LSP | `references/lsp.md` | 하위 타입은 상위 타입 대체 가능 |\n| ISP | `references/isp.md` | 사용하지 않는 인터페이스에 의존 금지 |\n| DIP | `references/dip.md` | 고수준이 저수준에 의존하지 않음 |\n\n## 객체지향의 본질\n\n핵","body":"# SOLID 원칙 - iOS 객체지향 설계 가이드\n\nSOLID 원칙을 적용하여 유지보수 가능하고 확장 가능한 iOS 코드를 작성한다.\n의존성 관리, 책임 분리, 확장성을 고려한 설계를 지원한다.\n\n## 상세 원칙 참조\n\n각 원칙의 상세 내용, iOS 예제, 안티패턴, 리팩토링 방법은 references 디렉토리를 참고한다:\n\n| 원칙 | 참조 파일 | 핵심 |\n|------|-----------|------|\n| SRP | `references/srp.md` | 모듈은 하나의 Actor에게만 책임 |\n| OCP | `references/ocp.md` | 확장에 열리고 수정에 닫힘 |\n| LSP | `references/lsp.md` | 하위 타입은 상위 타입 대체 가능 |\n| ISP | `references/isp.md` | 사용하지 않는 인터페이스에 의존 금지 |\n| DIP | `references/dip.md` | 고수준이 저수준에 의존하지 않음 |\n\n## 객체지향의 본질\n\n핵심은 의존성 역전(Dependency Inversion)이다.\n- Runtime 흐름: 고수준 → 저수준\n- Source Code 의존성: 저수준 → 고수준 (역전!)\n- 고수준 정책을 저수준 세부사항으로부터 보호한다.\n\n## 적용 워크플로우\n\n### 1단계: 설계 전 체크리스트\n\n```\n□ Actor를 식별했는가? (SRP)\n□ 변경 가능한 지점을 파악했는가? (OCP)\n□ 추상화가 필요한 곳을 찾았는가? (DIP)\n□ 인터페이스가 비대한가? (ISP)\n□ 상속 관계가 적절한가? (LSP)\n```\n\n### 2단계: 코드 작성 중 체크리스트\n\n```\n□ 클래스가 여러 Actor를 섬기고 있는가? (SRP 위반)\n□ 새 기능 추가 시 기존 코드를 수정하는가? (OCP 위반)\n□ protocol에 구체 클래스를 직접 의존하는가? (DIP 위반)\n□ protocol에 사용하지 않는 메서드가 있는가? (ISP 위반)\n□ 하위 타입이 상위 타입의 계약을 위반하는가? (LSP 위반)\n```\n\n### 3단계: 리팩토링 우선순위\n\n```\n우선순위 1: DIP 위반 → protocol 도입으로 의존성 역전\n우선순위 2: SRP 위반 → Actor별로 책임 분리\n우선순위 3: OCP 위반 → protocol + 구현체로 확장\n우선순위 4: ISP 위반 → protocol 분리\n우선순위 5: LSP 위반 → 상속 대신 composition 고려\n```\n\n## iOS에서 SOLID 적용 요약\n\n### Repository 패턴 (DIP + SRP + OCP)\n\n```swift\n// DIP: 추상화에 의존\nprotocol UserRepository {\n    func fetchUser(id: String) async throws -> User\n    func saveUser(_ user: User) async throws\n}\n\n// SRP: 네트워크 데이터 소스는 네트워크만 책임\nclass NetworkUserRepository: UserRepository {\n    private let apiClient: APIClient\n    \n    init(apiClient: APIClient) {\n        self.apiClient = apiClient\n    }\n    \n    func fetchUser(id: String) async throws -> User {\n        try await apiClient.request(.getUser(id))\n    }\n    \n    func saveUser(_ user: User) async throws {\n        try await apiClient.request(.updateUser(user))\n    }\n}\n\n// OCP: 새로운 저장소 추가 시 기존 코드 수정 불필요\nclass CachedUserRepository: UserRepository {\n    private let cache: Cache\n    \n    func fetchUser(id: String) async throws -> User {\n        try cache.get(id)\n    }\n    \n    func saveUser(_ user: User) async throws {\n        try cache.set(user, key: user.id)\n    }\n}\n\n// UseCase는 추상화에만 의존 (DIP)\nclass FetchUserUseCase {\n    private let repository: UserRepository\n    \n    init(repository: UserRepository) {\n        self.repository = repository\n    }\n    \n    func execute(id: String) async throws -> User {\n        try await repository.fetchUser(id: id)\n    }\n}\n```\n\n## 안티패턴 감지\n\n### Massive View Controller (SRP + DIP 위반)\n\n```swift\n// ❌ 나쁜 예\nclass ProductListViewController: UIViewController {\n    func fetchProducts() {\n        URLSession.shared.dataTask(with: url) { data, _, _ in\n            // JSON 파싱, 할인 계산, UI 업데이트 모두 여기서\n        }\n    }\n}\n\n// ✅ 좋은 예\nclass ProductListViewController: UIViewController {\n    private let viewModel: ProductListViewModel\n    // UI만 담당\n}\n```\n\n### 구체 클래스 직접 의존 (DIP 위반)\n\n```swift\n// ❌ 나쁜 예\nclass OrderService {\n    let database = MySQLDatabase()\n}\n\n// ✅ 좋은 예\nclass OrderService {\n    private let repository: OrderRepository // protocol 의존\n    \n    init(repository: OrderRepository) {\n        self.repository = repository\n    }\n}\n```\n\n### Fat Interface (ISP 위반)\n\n```swift\n// ❌ 나쁜 예\nprotocol DataSource {\n    func fetch() -> [Item]\n    func save(_ item: Item)\n    func delete(_ item: Item)\n    func search(_ query: String) -> [Item]\n}\n\n// ✅ 좋은 예\nprotocol Fetchable { func fetch() -> [Item] }\nprotocol Savable { func save(_ item: Item) }\nprotocol Deletable { func delete(_ item: Item) }\nprotocol Searchable { func search(_ query: String) -> [Item] }\n```\n\n## 실전 팁\n\n1. DIP부터 시작: 의존성 방향이 가장 중요\n2. Actor 찾기: SRP 적용의 시작점\n3. protocol 먼저: Swift는 protocol-oriented\n4. 점진적 적용: 한 번에 모두 적용하려 하지 말 것\n5. 테스트로 검증: SOLID 준수 여부는 테스트 용이성으로 확인\n"},"lastSynced":"2026-03-07T04:19:05.490Z","agentAnalysis":{"suitability":{"en":"Perfect for iOS Development Agents needing maintainable and scalable code through object-oriented design principles.","zh":"非常适合需要通过面向对象设计原则来维护和扩展代码的iOS开发代理。","ja":"iOS開発エージェントがオブジェクト指向設計原則を通じて保守可能でスケーラブルなコードを必要とする場合に最適です。","ko":"객체 지향 설계 원칙을 통해 유지 보수 가능하고 확장 가능한 코드가 필요한 iOS 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de iOS que necesitan código mantenible y escalable a través de principios de diseño orientados a objetos.","fr":"Parfait pour les agents de développement iOS ayant besoin de code maintenable et évolutif grâce aux principes de conception orientés objet.","de":"Perfekt für iOS-Entwicklungsagenten, die maintainable und skalierbaren Code durch objektorientierte Designprinzipien benötigen.","pt":"Perfeito para Agentes de Desenvolvimento iOS que necessitam de código mantível e escalável por meio de princípios de design orientado a objetos.","ru":"Идеально подходит для агентов по разработке iOS, которым необходим поддерживаемый и масштабируемый код посредством принципов объектно-ориентированного проектирования.","ar":"مثالي لعميل تطوير iOS الذين يحتاجون إلى رمز قابل للصيانة ومقابل للتحجيم من خلال مبادئ التصميم المتوجة نحو الكائن"},"recommendation":{"en":"Empowers agents to apply SOLID principles, including dependency management and responsibility separation, for writing maintainable and scalable iOS code, leveraging SRP, OCP, LSP, ISP, and DIP design patterns.","zh":"赋予代理应用SOLID原则的能力，包括依赖管理和职责分离，以编写维护和扩展iOS代码，利用SRP、OCP、LSP、ISP和DIP设计模式。","ja":"エージェントがSOLID原則を適用できるようにし、依存関係の管理や責任の分離を行い、SRP、OCP、LSP、ISP、DIPデザインパターンを利用して、保守可能でスケーラブルなiOSコードを記述できるようにします。","ko":"에이전트가 SOLID 원칙을 적용할 수 있도록 하여依存関係 관리와 책임 분리를 통해 SRP, OCP, LSP, ISP, DIP 디자인 패턴을 활용하여 유지 보수 가능하고 확장 가능한 iOS 코드를 작성할 수 있습니다.","es":"Habilita a los agentes a aplicar los principios SOLID, incluyendo la gestión de dependencias y la separación de responsabilidades, para escribir código iOS mantenible y escalable, aprovechando los patrones de diseño SRP, OCP, LSP, ISP y DIP.","fr":"Permet aux agents d''appliquer les principes SOLID, y compris la gestion des dépendances et la séparation des responsabilités, pour écrire du code iOS maintenable et évolutif, en exploitant les modèles de conception SRP, OCP, LSP, ISP et DIP.","de":"Ermächtigt Agenten, SOLID-Prinzipien anzuwenden, einschließlich Abhängigkeitsverwaltung und Verantwortlichkeitstrennung, um maintainable und skalierbaren iOS-Code zu schreiben, indem SRP, OCP, LSP, ISP und DIP-Designmuster genutzt werden.","pt":"Habilita os agentes a aplicar princípios SOLID, incluindo gerenciamento de dependências e separação de responsabilidades, para escrever código iOS mantível e escalável, aproveitando padrões de design SRP, OCP, LSP, ISP e DIP.","ru":"Наделяет агентов возможностью применять принципы SOLID, включая управление зависимостями и разделение ответственности, для написания поддерживаемого и масштабируемого кода iOS, используя шаблоны проектирования SRP, OCP, LSP, ISP и DIP.","ar":"يمنح العميل القدرة على تطبيق مبادئ SOLID ، بما في ذلك إدارة التبعيات و فصل المسؤولية ، لكتابة رمز iOS قابل للصيانة ومقابل للتحجيم ، مستفيداً من أنماط التصميم SRP و OCP و LSP و ISP و DIP"},"useCases":{"en":["Applying Single Responsibility Principle (SRP) for modular code","Implementing Open-Closed Principle (OCP) for extensible designs","Ensuring Liskov Substitution Principle (LSP) for subtype polymorphism","Applying Interface Segregation Principle (ISP) for client-specific interfaces","Following Dependency Inversion Principle (DIP) for high-level module independence"],"zh":["应用单一责任原则（SRP）进行模块化代码","实现开闭原则（OCP）进行可扩展的设计","确保里氏替换原则（LSP）进行子类型多态性","应用接口分离原则（ISP）进行客户端特定接口","遵循依赖反转原则（DIP）进行高级模块独立性"],"ja":["モジュラー化されたコードのために単一責任原則（SRP）を適用する","拡張可能な設計のために開放閉鎖原則（OCP）を実装する","サブタイプの多相性のためにリスコフ置換原則（LSP）を確保する","クライアント固有のインターフェイスのためにインターフェイス分離原則（ISP）を適用する","高レベルのモジュール独立性のために依存関係逆転原則（DIP）に従う"],"ko":["모듈화된 코드를 위한 단일 책임 원칙(SRP) 적용","확장 가능한 디자인을 위한 개방-폐쇄 원칙(OCP) 구현","서브타입 다형성을 위한 리스코프 치환 원칙(LSP) 확보","클라이언트 특정 인터페이스를 위한 인터페이스 분리 원칙(ISP) 적용","고급 모듈 독립성을 위한 의존성 역전 원칙(DIP) 준수"],"es":["Aplicar el principio de responsabilidad única (SRP) para código modular","Implementar el principio de abierto-cerrado (OCP) para diseños extensibles","Garantizar el principio de sustitución de Liskov (LSP) para polimorfismo de subtipos","Aplicar el principio de segregación de interfaces (ISP) para interfaces específicas del cliente","Seguir el principio de inversión de dependencias (DIP) para la independencia de módulos de alto nivel"],"fr":["Appliquer le principe de responsabilité unique (SRP) pour du code modulaire","Mettre en œuvre le principe ouvert-fermé (OCP) pour des conceptions extensibles","Assurer le principe de substitution de Liskov (LSP) pour le polymorphisme de sous-types","Appliquer le principe de ségrégation d''interfaces (ISP) pour des interfaces spécifiques au client","Suivre le principe d''inversion de dépendances (DIP) pour l''indépendance des modules de haut niveau"],"de":["Das Prinzip der einzigen Verantwortung (SRP) für modularen Code anwenden","Das Offen-Geschlossen-Prinzip (OCP) für erweiterbare Designs implementieren","Das Liskov-Substitutionsprinzip (LSP) für Subtyp-Polymorphismus sicherstellen","Das Prinzip der Schnittstellen-Segregation (ISP) für client-spezifische Schnittstellen anwenden","Dem Prinzip der Abhängigkeitsumkehr (DIP) für die Unabhängigkeit von Hochstelleneinheiten folgen"],"pt":["Aplicação do Princípio de Responsabilidade Única (SRP) para código modular","Implementação do Princípio Aberto-Fechado (OCP) para designs extensíveis","Garantia do Princípio de Substituição de Liskov (LSP) para polimorfismo de subtipo","Aplicação do Princípio de Segregação de Interface (ISP) para interfaces específicas do cliente","Seguindo o Princípio de Inversão de Dependência (DIP) para independência de módulos de alto nível"],"ru":["Применение принципа единой ответственности (SRP) для модульного кода","Реализация принципа открытого-закрытого (OCP) для расширяемых дизайнов","Обеспечение принципа замены Лискова (LSP) для полиморфизма подтипа","Применение принципа сегрегации интерфейса (ISP) для клиентских интерфейсов","Следование принципу инверсии зависимостей (DIP) для независимости модулей высокого уровня"],"ar":["تطبيق مبدأ المسؤولية الفريدة (SRP) لرمز موديولار","تنفيذ مبدأ مفتوح-مغلق (OCP) لأدوات التصميم القابلة للتوسيع","ضمان مبدأ استبدال لISKOV (LSP) للبوليمورفيزم الفرعي","تطبيق مبدأ تفرقة الواجهة (ISP) لواجهات العميل المحددة","اتباع مبدأ عكس التبعية (DIP) لاستقلال الوحدات عالية المستوى"]},"limitations":{"en":["Requires knowledge of object-oriented programming","Specific to iOS development","Needs understanding of SOLID principles"],"zh":["需要面向对象编程的知识","特定于iOS开发","需要理解SOLID原则"],"ja":["オブジェクト指向プログラミングの知識が必要","iOS開発に特化している","SOLID原則の理解が必要"],"ko":["객체 지향 프로그래밍에 대한 지식이 필요","iOS 개발에 특화","SOLID 원칙에 대한 이해가 필요"],"es":["Requiere conocimiento de programación orientada a objetos","Específico para el desarrollo de iOS","Necesita comprensión de los principios SOLID"],"fr":["Nécessite des connaissances en programmation orientée objet","Spécifique au développement iOS","Nécessite une compréhension des principes SOLID"],"de":["Benötigt Kenntnisse in objektorientierter Programmierung","Spezifisch für die iOS-Entwicklung","Benötigt das Verständnis der SOLID-Prinzipien"],"pt":["Requer conhecimento de programação orientada a objetos","Específico para desenvolvimento iOS","Necessita de compreensão dos princípios SOLID"],"ru":["Требует знания объектно-ориентированного программирования","Конкретно для разработки iOS","Требует понимания принципов SOLID"],"ar":["يتطلب معرفة بالبرمجة الموجهة نحو الكائن","محدد لتطوير iOS","يتطلب فهم مبادئ SOLID"]},"version":4},"contentHash":"c78a69ab375c4b736da973aa1320d93f1ad4ea12dcce481aff052b1a24443af3","qualityScore":33}');
