INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jimmy-Jung/claude_symbiote/solid', 'solid', 'Jimmy-Jung', 'claude_symbiote', 'community', 'solid Jimmy-Jung claude_symbiote community The SOLID skill helps developers write maintainable and scalable iOS code by applying object-oriented design principles, including dependency management and responsibility separation. SOLID 原则是 iOS 面向对象设计的指导方针，帮助开发者编写可维护和可扩展的代码 SOLID 原則は iOS オブジェクト指向設計のガイドラインであり、開発者がメンテナンス可能で拡張可能なコードを書くのに役立ちます SOLID 원칙은 iOS 객체지향 설계의 가이드라인으로 개발자가 유지보수 가능하고 확장 가능한 코드를 작성하도록 도와줍니다 SOLID es un conjunto de principios de diseño de objetos que ayudan a escribir código iOS mantenible y escalable. Aprende a aplicar SRP, OCP, LSP, ISP y DIP. SOLID est un ensemble de principes de conception d''objets qui aident à écrire du code iOS maintenable et évolutif. Apprenez à appliquer SRP, OCP, LSP, ISP et DIP. SOLID ist eine Sammlung von Objekt-Design-Prinzipien, die helfen, wartbaren und skalierbaren iOS-Code zu schreiben. Erfahren Sie, wie Sie SRP, OCP, LSP, ISP und DIP anwenden. O SOLID é um conjunto de princípios para desenvolvimento de software que visam melhorar a maintainabilidade e escalabilidade do código. Ele inclui princípios como SRP, OCP, LSP, ISP e DIP. SOLID - это набор принципов разработки программного обеспечения, направленных на улучшение поддерживаемости и масштабируемости кода. Он включает принципы SRP, OCP, LSP, ISP и DIP. SOLID هو مجموعة من المبادئ لتعزيز صيانة وتوسيع 코드 البرامج. تشمل مبادئ SRP و OCP و LSP و ISP و DIP. SOLID principles iOS how to use SOLID in iOS development SOLID vs MVC SOLID setup guide for iOS what is SOLID in object-oriented design SOLID alternative for iOS development SRP OCP LSP ISP DIP examples SOLID 原则 iOS 面向对象设计 依赖管理 责任分离 扩展性设计 AIエージェント 面向对象编程 Applies Single Responsibility Principle (SRP) for modular design Supports Open-Closed Principle (OCP) for extensibility Ensures Liskov Substitution Principle (LSP) for subtype compatibility Implements Interface Segregation Principle (ISP) for minimal interfaces Follows Dependency Inversion Principle (DIP) for high-level module independence SOLID is a set of object-oriented design principles for iOS development, including SRP, OCP, LSP, ISP, and DIP, aiming to improve code maintainability and scalability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xxl-novels/short-story-creator/manuscript-reviewer', 'community', 'xxl-novels', 'short-story-creator', 'xxl-novels/short-story-creator', 'manuscript-reviewer', 0, 0, 33, '2026-03-06T16:47:56Z', '2026-03-07T13:14:10.751Z', 'f05cca2d86f383baa5e1a58a1c2ceb5c5454049f2f049164e87ffee54caf249d', '{"id":"xxl-novels/short-story-creator/manuscript-reviewer","name":"manuscript-reviewer","description":{"en":"The manuscript-reviewer skill streamlines manuscript evaluation for developers, utilizing a 7-step workflow including format checks, AI detection, and multi-dimensional scoring. Ideal for literary platforms and publications.","zh":"稿件审稿工具是一种AI驱动的审稿平台，支持多种格式和平台的审稿","ja":"原稿レビューAIエージェントは、さまざまな形式とプラットフォームの原稿をレビューするためのAI駆動型プラットフォームです","ko":"원고 리뷰어는 다양한 형식과 플랫폼의 원고를 리뷰하는 AI 기반 플랫폼입니다","es":"El revisor de manuscritos es una herramienta de IA que ayuda a evaluar y mejorar la calidad de los textos","fr":"L''outil de révision de manuscrits est un outil de IA qui aide à évaluer et améliorer la qualité des textes","de":"Das Manuskript-Review-Tool ist ein KI-Tool, das bei der Bewertung und Verbesserung der Textqualität hilft","pt":"O manuscript-reviewer é uma ferramenta de revisão de manuscritos que utiliza 7 etapas de revisão e avaliação para garantir a qualidade dos manuscritos","ru":"ИИ Агент manuscript-reviewer - это инструмент редактирования рукописей, который использует 7 этапов проверки и оценки для обеспечения качества рукописей","ar":"مانوسكريبت-ريفيوير هو أداة لاستعراض المخطوطات التي تستخدم 7 مراحل من الاستعراض والتقييم لضمان جودة المخطوطات"},"seo":{"title":{"en":"manuscript-reviewer: AI-Powered Manuscript Review Setup G...","zh":"稿件审稿工具：Setup Guide","ja":"原稿レビューAIエージェント：ベストプラクティス","ko":"원고 리뷰어 설정 가이드","es":"Configuración de Revisión de Manuscritos con Agentes de IA","fr":"Guide d''Installation de l''Outil de Révision de Manuscrits","de":"Einrichtung des Manuskript-Review-Tools mit KI-Agenten","pt":"Guia de Configuração do manuscript-reviewer: Otimização d...","ru":"Настройка ИИ Агента manuscript-reviewer: Руководство по Н...","ar":"دليل إعداد manuscript-reviewer: تحسين تدفق عمل استعراض ال..."},"description":{"en":"Unlock efficient manuscript reviews with manuscript-reviewer! Discover how to leverage AI-driven workflows for 12-dimensional assessments and expert opinions","zh":"了解稿件审稿工具的工作流程和技术细节，提高您的审稿效率","ja":"原稿レビューAIエージェントの機能と設定方法をご紹介します","ko":"원고 리뷰어의 기능과 설정 방법을 알아보세요","es":"Aprende a configurar y utilizar el revisor de manuscritos con agentes de IA para mejorar la eficiencia en la revisión de textos","fr":"Découvrez comment installer et utiliser l''outil de révision de manuscrits pour améliorer la qualité de vos textes avec les agents de IA","de":"Erfahren Sie, wie Sie das Manuskript-Review-Tool mit KI-Agenten einrichten und nutzen können, um die Effizienz bei der Textüberprüfung zu steigern","pt":"Aprenda a configurar o manuscript-reviewer para otimizar o fluxo de trabalho de revisão de manuscritos, incluindo 7 etapas de revisão e avaliação","ru":"Узнайте, как настроить ИИ Агента manuscript-reviewer для оптимизации процесса редактирования рукописей, включающего 7 этапов проверки и оценки","ar":"تعلم كيفية إعداد manuscript-reviewer لتحسين تدفق عمل استعراض المخطوطات، بما في ذلك 7 مراحل من الاستعراض والتقييم"},"definition":{"en":"manuscript-reviewer is a specialized AI agent skill designed for evaluating manuscripts based on specific platform requirements, applying weighted assessments and generating detailed review reports","zh":"稿件审稿工具是一种利用AI技术对稿件进行审稿和评分的工具","ja":"原稿レビューAIエージェントは、AI技術を利用して原稿をレビューし、評価するツールです","ko":"원고 리뷰어는 AI 기술을 활용하여 원고를 리뷰하고 평가하는 도구입니다","es":"Un revisor de manuscritos es un agente de IA que evalúa textos según criterios como formato, estructura y contenido","fr":"Un outil de révision de manuscrits est un agent de IA qui évalue les textes en fonction de critères tels que le format, la structure et le contenu","de":"Ein Manuskript-Review-Tool ist ein KI-Agent, der Texte nach Kriterien wie Format, Struktur und Inhalt bewertet","pt":"O manuscript-reviewer é uma ferramenta de revisão de manuscritos que utiliza inteligência artificial para avaliar a qualidade dos manuscritos","ru":"ИИ Агент manuscript-reviewer - это инструмент редактирования рукописей, который использует искусственный интеллект для оценки качества рукописей","ar":"مانوسكريبت-ريفيوير هو أداة لاستعراض المخطوطات التي تستخدم الذكاء الاصطناعي لتقييم جودة المخطوطات"},"features":{"en":["Determines manuscript platform type for weighted assessment","Performs format initial checks for rapid filtering","Applies AI detection for deeper content analysis","Conducts 12-dimensional scoring for comprehensive evaluation","Generates expert opinions and saves review reports","Supports multiple literary platforms with customizable settings"],"zh":["支持多种平台的审稿，包括传统文学期刊、网络平台、 新媒体故事号和知乎盐选","采用12维度评分系统，全面评估稿件质量","支持快速淘汰项，提高审稿效率","提供详细的审稿报告，帮助作者改进稿件","支持综合评估模式，均衡权重"],"ja":["さまざまなプラットフォームの原稿をレビューすることをサポートします","12次元評価システムを採用し、原稿の品質を総合的に評価します","クイックリジェクションアイテムをサポートし、レビューエフィシエンシーを向上させます","詳細なレビューレポートを提供し、著者が原稿を改善するのを助けます","総合評価モードをサポートし、バランスをとった重み付けを実現します"],"ko":["다양한 플랫폼의 원고를 리뷰하는 것을 지원합니다","12차원 평가 시스템을採用하여 원고의 品質を総合的に 평가합니다","快速 리젝션 아이템을 지원하여 리뷰 효율을 향상시킵니다","詳細한 리뷰 리포트를 제공하여 작가가 원고를 개선하는 것을 도와줍니다","종합 평가 모드를 지원하여 균형 잡힌 가중치를 실현합니다"],"es":["Análisis de formato y estructura de textos","Detección de problemas de formato con AI","Evaluación de la calidad del contenido en 12 dimensiones","Generación de informes de revisión personalizados","Compatibilidad con diferentes plataformas de publicación","Modo de evaluación integral para textos sin especificación de plataforma"],"fr":["Analyse du format et de la structure des textes","Détection des problèmes de format avec l''IA","Évaluation de la qualité du contenu en 12 dimensions","Génération de rapports de révision personnalisés","Compatibilité avec différentes plateformes de publication","Mode d''évaluation intégrale pour les textes sans spécification de plateforme"],"de":["Analyse von Format und Struktur von Texten","Erkennung von Formatproblemen mit KI","Bewertung der Inhaltsqualität in 12 Dimensionen","Erstellung von individualisierten Review-Berichten","Kompatibilität mit verschiedenen Veröffentlichungsplattformen","Integriertes Bewertungsmodus für Texte ohne Plattformangabe"],"pt":["7 etapas de revisão e avaliação","Análise de formato e estrutura","Detecção de erros e inconsistências","Avaliação de criatividade e originalidade","Geração de relatórios de revisão personalizados","Integração com plataformas de publicação"],"ru":["7 этапов проверки и оценки","Анализ формата и структуры","Обнаружение ошибок и несоответствий","Оценка креативности и оригинальности","Генерация индивидуальных отчетов редактирования","Интеграция с платформами публикации"],"ar":["7 مراحل من الاستعراض والتقييم","تحليل الشكل والهيكل","اكتشاف الأخطاء والتناقضات","تقييم الإبداع والأصالة","توليد تقارير استعراض مخصصة","التكامل مع منصات النشر"]},"keywords":{"en":["how to use manuscript-reviewer","manuscript-reviewer setup guide","manuscript-reviewer alternative","manuscript-reviewer vs human reviewers","what is manuscript-reviewer","install manuscript-reviewer","manuscript-reviewer for literary publications","AI-powered manuscript review","manuscript-reviewer workflow optimization"],"zh":["稿件审稿工具","AI审稿","原稿レビュー","12维度评分","快速淘汰项","综合评估模式","原稿改进","AI技术","审稿平台"],"ja":["原稿レビューAIエージェント","AIレビュー","原稿評価","12次元評価","クイックリジェクション","総合評価モード","原稿改善","AI技術","レビュープラットフォーム"],"ko":["원고 리뷰어","AI 리뷰","원고 평가","12차원 평가","快速 리젝션","종합 평가 모드","원고 개선","AI 기술","리뷰 플랫폼"],"es":["revisor de manuscritos","agentes de IA para revisión de textos","herramientas de IA para escritores","evaluación de textos con AI","mejora de la calidad de los textos","revisión de manuscritos con tecnología de IA","plataformas de publicación compatibles con IA","informes de revisión personalizados"],"fr":["outils de révision de manuscrits","agents de IA pour la révision de textes","outils de IA pour écrivains","évaluation de textes avec l''IA","amélioration de la qualité des textes","révision de manuscrits avec technologie de IA","plateformes de publication compatibles avec l''IA","rapports de révision personnalisés"],"de":["Manuskript-Review-Tool","KI-Agenten für Textüberprüfung","KI-Tools für Schriftsteller","Textbewertung mit KI","Qualitätsverbesserung von Texten","Manuskript-Review mit KI-Technologie","Veröffentlichungsplattformen kompatibel mit KI","individualisierte Review-Berichte"],"pt":["manuscript-reviewer","revisão de manuscritos","inteligência artificial","edição de textos","publicação de livros","plataformas de publicação","ferramentas de revisão","otimização de fluxo de trabalho","qualidade de manuscritos"],"ru":["ИИ Агент manuscript-reviewer","редактирование рукописей","искусственный интеллект","редактирование текстов","публикация книг","платформы публикации","инструменты редактирования","оптимизация процесса","качество рукописей"],"ar":["مانوسكريبت-ريفيوير","استعراض المخطوطات","الذكاء الاصطناعي","تحرير النصوص","نشر الكتب","منصات النشر","أدوات الاستعراض","تحسين تدفق العمل","جودة المخطوطات"]}},"owner":"xxl-novels","repo":"short-story-creator","repoPath":"xxl-novels/short-story-creator","stars":0,"forks":0,"updatedAt":"2026-03-06T16:47:56Z","topics":[],"category":"community","skillMd":{"name":"manuscript-reviewer","description":"短篇小说审稿工作流技能，基于12维度评估框架和三审三校制度。触发场景：(1) 用户说审稿、审阅稿件、评估小说、审读文章，(2) 用户提供小说/故事文本请求评估，(3) 用户询问如何改进稿件质量，(4) 用户需要撰写审稿意见，(5) 用户问这个小说写得好不好。支持传统文学期刊、网络平台、新媒体故事号等不同平台标准。","bodyPreview":"# 短篇小说审稿工作流\n\n## 工作流程概览\n\n```\n1. 确定审稿平台类型 → 2. 格式初审 → 3. AI检测 → 4. 首段评估 → 5. 12维度评分 → 6. 撰写审稿意见 → 7. 保存审稿报告\n```\n\n## Step 1: 确定审稿平台类型\n\n首先询问用户目标平台，不同平台权重不同：\n\n| 平台类型 | 核心权重 | 审稿周期 | 字数偏好 |\n|---------|---------|---------|---------|\n| 传统文学期刊 | 深度(56%)+结构(54%) | 1-3个月 | 4000-8000字 |\n| 网络平台(番茄/起点) | 影响力(22%)+创意(15%)+格式(14%) | 2-7天 | 1-5万字 |\n| 新媒体故事号 | 标题+节奏+三观 | 3-7天 | 8000-15000字 |\n| 知乎盐选 | 完整性+改编潜力 | 7-15天 | 1-3万字 |\n\n若用户未指定，默认使用**综合评估模式**（均衡权重）。\n\n## Step 2: 格式初审（快速淘汰项）\n\n检查以下格式问题，任一项不合格即可快速退稿：\n\n```\n□ 文档","body":"# 短篇小说审稿工作流\n\n## 工作流程概览\n\n```\n1. 确定审稿平台类型 → 2. 格式初审 → 3. AI检测 → 4. 首段评估 → 5. 12维度评分 → 6. 撰写审稿意见 → 7. 保存审稿报告\n```\n\n## Step 1: 确定审稿平台类型\n\n首先询问用户目标平台，不同平台权重不同：\n\n| 平台类型 | 核心权重 | 审稿周期 | 字数偏好 |\n|---------|---------|---------|---------|\n| 传统文学期刊 | 深度(56%)+结构(54%) | 1-3个月 | 4000-8000字 |\n| 网络平台(番茄/起点) | 影响力(22%)+创意(15%)+格式(14%) | 2-7天 | 1-5万字 |\n| 新媒体故事号 | 标题+节奏+三观 | 3-7天 | 8000-15000字 |\n| 知乎盐选 | 完整性+改编潜力 | 7-15天 | 1-3万字 |\n\n若用户未指定，默认使用**综合评估模式**（均衡权重）。\n\n## Step 2: 格式初审（快速淘汰项）\n\n检查以下格式问题，任一项不合格即可快速退稿：\n\n```\n□ 文档格式：Word/文本格式是否规范\n□ 段落结构：是否长篇大论不分段（信息过载）\n□ 基础语言：错别字/病句是否过多（>5处/千字即不合格）\n□ 标题质量：是否具有吸引力（新媒体平台必需）\n```\n\n**判断**：格式问题占退稿原因的3%，但影响编辑第一印象。\n\n## Step 3: AI检测（2025年必备）\n\n检测稿件是否具有AI生成的五大特征：\n\n| 特征 | 表现 | 检测要点 |\n|-----|------|---------|\n| 华美空洞 | 形容词密集(>3个/句)、堆砌辞藻但缺乏内涵 | 首段是否过度修饰？ |\n| 逻辑矛盾 | 违反常识的细节（如\"公交车坐三天三夜\"） | 人设/情节是否突兀？ |\n| 节奏割裂 | 关键场景插入冗余细节 | 叙事是否有呼吸感？ |\n| 情节停滞 | 仅环境描写和名词解释，无法推进 | 是否有故事推进？ |\n| 情感缺失 | 文字拼凑缺乏人类情绪共鸣 | 是否有\"人味儿\"？ |\n\n**判断标准**：\n- 通过：无明显特征或仅1项轻微表现\n- 存疑：2-3项特征，需重点审查\n- 不通过：4项以上特征明显\n\n## Step 4: 首段评估（前400字决定命运）\n\n**首400字快速判断法**：\n\n1. 阅读首段（前150字）：是否\"华美空洞\"或逻辑矛盾\n2. 定位第400字：是否出现小高潮、小起伏或小亮点\n3. 判断开篇功能：是否快速引入主角、核心冲突、故事基调\n\n**开篇评估清单**：\n```\n□ 是否引发好奇/共鸣？\n□ 是否快速引入核心冲突？\n□ 是否设定了故事基调？\n□ 第400字处是否有亮点？\n```\n\n若首段已出现冗长环境描写、人名堆砌、信息过载，可直接标记\"结构问题-开头失当\"。\n\n## Step 5: 12维度深度评估\n\n详细评估标准见 [evaluation-dimensions.md](references/evaluation-dimensions.md)\n\n**快速评分表**（每项1-10分）：\n\n| 维度 | 权重 | 核心问题 | 评分 |\n|-----|------|---------|-----|\n| 影响力(Impact) | 22% | 首段吸引力、情感共鸣、记忆点 | __ |\n| 创意性(Creativity) | 15% | 主题新颖度、叙事创新 | __ |\n| 语言/文笔(Language) | 15% | 清晰度、抒情性、创新性 | __ |\n| 格式规范(Guidelines) | 14% | 遵循指南、排版整洁 | __ |\n| 润色(Polish) | 7% | 完成度、打磨程度 | __ |\n| 结构(Structure) | 8% | 叙事逻辑、节奏控制、开篇/结尾 | __ |\n| 深度(Depth) | 6% | 人物内心、主题挖掘 | __ |\n| 简洁性(Economy) | 5% | 无冗余、字字有用 | __ |\n| 真实性(Authenticity) | 4% | 情感诚实、自然真实 | __ |\n| 主题(Subject) | 3% | 独特题材、普世意义 | __ |\n| 语调(Voice) | 2% | 独特声音、与人物一致 | __ |\n| 对话(Dialogue) | 1% | 与叙述配合、格式正确 | __ |\n\n**加权总分计算**：\n```\n总分 = Σ(维度分 × 权重)\n```\n\n**决策阈值**：\n- ≥8分：建议录用\n- 6-8分：修改后重审\n- <6分：退稿\n\n## Step 6: 撰写审稿意见\n\n使用标准审稿意见模板，详见 [review-template.md](references/review-template.md)\n\n**审稿意见结构**：\n```\n一、总体评价（一句话 + 录用/修改/退稿）\n二、优势分析（按维度权重排序）\n三、主要问题（按严重性排序）\n四、修改建议（具体、可操作）\n五、AI检测结果\n六、推荐/不推荐\n```\n\n## Step 7: 保存审稿报告\n\n审稿完成后，将报告保存至小说所在目录的 `reports` 子目录中。\n\n**保存路径规则**：\n```\nnovels/{小说名称}/reports/审稿报告_{日期}.md\n```\n\n**示例**：\n```\nnovels/重生之代价/reports/审稿报告_2026-02-28.md\n```\n\n**操作步骤**：\n1. 检查 `reports` 目录是否存在，不存在则创建\n2. 使用 `YYYY-MM-DD` 格式命名文件\n3. 将完整审稿报告以 Markdown 格式保存\n\n**报告内容应包含**：\n- 审稿信息（作品名称、作者、题材、字数、审稿日期）\n- 格式初审结果\n- AI检测评估\n- 首段评估分析\n- 12维度评分表（含加权分计算）\n- 综合评估（优势/问题）\n- 修改建议（分优先级）\n- 平台适配建议\n- 审稿结论\n\n## 决策树（标准化判断）\n\n```\nSTART: 稿件提交\n    ↓\n[格式审查]\n├── 不符合平台要求 → 退稿（3%）\n└── 通过 → NEXT\n    ↓\n[AI检测]\n├── 五大特征明显 → 拒稿（AI稿）\n├── 存疑 → 复审重点审查\n└── 通过 → NEXT\n    ↓\n[首400字评估]\n├── 无亮点/逻辑矛盾 → 退稿（39% Impact不足）\n├── 有亮点但结构混乱 → 复审（54% Structure问题）\n└── 亮点+结构清晰 → NEXT\n    ↓\n[12维度快速评分]\n├── 深度<6分 or 创意<6分 → 退稿（56%+37%）\n├── 6-8分 → 修改后重审\n└── ≥8分 → 终审\n    ↓\n[终审综合权衡]\n├── 平台调性匹配 + 价值导向正确 → 录用\n└── 否则 → 退稿\n```\n\n## 常见退稿原因速查\n\n| 排名 | 原因 | 占比 | 快速识别 |\n|-----|------|-----|---------|\n| 1 | 深度不足 | 56% | 内心描写具体？人物动机合理？ |\n| 2 | 结构问题 | 54% | 首400字有亮点？叙事线性清晰？ |\n| 3 | 影响力不足 | 39% | 首段引发好奇/共鸣？ |\n| 4 | 创意不足 | 37% | 人物/情节有新意？颠覆常规？ |\n| 5 | 格式不规范 | 3% | 标题吸睛？段落清晰？ |\n\n## 平台标准差异\n\n详见 [platform-standards.md](references/platform-standards.md)\n\n**关键差异点**：\n- 传统期刊：文学性优先，\"故事优先\"原则\n- 网络平台：市场性导向，标题/节奏/爽点\n- 新媒体：流量优先，\"苏感\"人设、反转设计\n"},"lastSynced":"2026-03-07T13:14:10.751Z","agentAnalysis":{"suitability":{"en":"Perfect for Literary Analysis Agents needing advanced manuscript evaluation and multi-dimensional scoring capabilities.","zh":"适用于需要高级稿件评估和多维评分能力的文学分析代理","ja":"文学分析エージェントが高度な原稿評価と多次元評価機能を必要とする場合に適しています","ko":"문학 분석 에이전트가 고급 원고 평가 및 다차원 점수 기능을 필요로 할 때 적합합니다","es":"Perfecto para agentes de Análisis Literario que necesitan una evaluación avanzada de manuscritos y capacidades de puntuación multi-dimensional.","fr":"Parfait pour les agents d''Analyse Littéraire ayant besoin d''une évaluation de manuscrits avancée et de capacités de notation multi-dimensionnelles.","de":"Perfekt für Literaturanalyse-Agenten, die eine erweiterte Manuskriptauswertung und mehrdimensionale Bewertungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Análise Literária que necessitam de avaliação avançada de manuscritos e capacidades de pontuação multi-dimensional.","ru":"Идеально подходит для литературных аналитических агентов, которым требуются продвинутые возможности оценки рукописей и многомерного подсчета баллов.","ar":"مثالي لوكلاء التحليل الأدبي الذين يحتاجون إلى تقييم متقدم للكتابات والقدرات ذات التقييم المتعدد الأبعاد."},"recommendation":{"en":"Empowers agents to streamline manuscript evaluation using a 7-step workflow, including format checks, AI detection, and multi-dimensional scoring, leveraging platforms like 传统文学期刊, 网络平台, 新媒体故事号, and 知乎盐选 with core weights and audit cycles.","zh":"使代理能够使用7步工作流简化稿件评估，包括格式检查、AI检测和多维评分，利用传统文学期刊、网络平台、新媒体故事号和知乎盐选等平台，结合核心权重和审计周期","ja":"エージェントが7ステップのワークフローを使用して原稿の評価を簡素化することを可能にし、形式のチェック、AIの検出、多次元の評価を含み、伝統的な文学ジャーナル、ネットワークプラットフォーム、新しいメディアストーリー番号、知乎の選定などのプラットフォームを利用し、コアの重みと監査サイクルを利用する","ko":"에이전트가 7단계 워크플로를 사용하여 원고 평가를 간소화 할 수 있도록 하며, 형식 체크, AI 감지, 다차원 평가를 포함하며, 전통적인 문학 저널, 네트워크 플랫폼, 새로운 미디어 스토리 번호, 知乎의 선택 등과 같은 플랫폼을 활용하여 핵심 가중치와 감사 주기를 활용한다","es":"Habilita a los agentes a simplificar la evaluación de manuscritos utilizando un flujo de trabajo de 7 pasos, que incluye comprobaciones de formato, detección de IA y puntuación multi-dimensional, aprovechando plataformas como 传统文学期刊, 网络平台, 新媒体故事号 y 知乎盐选 con pesos básicos y ciclos de auditoría.","fr":"Permet aux agents de rationaliser l''évaluation des manuscrits en utilisant un flux de travail de 7 étapes, comprenant des vérifications de format, la détection d''IA et la notation multi-dimensionnelle, en exploitant des plateformes comme 传统文学期刊, 网络平台, 新媒体故事号 et 知乎盐选 avec des poids de base et des cycles d''audit.","de":"Ermächtigt die Agenten, die Manuskriptauswertung mithilfe eines 7-Schritt-Workflows zu rationalisieren, einschließlich Formatprüfungen, KI-Erkennung und mehrdimensionaler Bewertung, indem es Plattformen wie 传统文学期刊, 网络平台, 新媒体故事号 und 知乎盐选 mit Kerngewichten und Prüfungszyklen nutzt.","pt":"Habilita os agentes a racionalizar a avaliação de manuscritos usando um fluxo de trabalho de 7 etapas, incluindo verificação de formatos, detecção de IA e pontuação multi-dimensional, aproveitando plataformas como 传统文学期刊, 网络平台, 新媒体故事号 e 知乎盐选 com pesos centrais e ciclos de auditoria.","ru":"Наделяет агентов возможностью оптимизировать оценку рукописей с помощью 7-этапного рабочего процесса, включая проверку формата, обнаружение ИИ и многомерный подсчет баллов, используя платформы như 传统文学期刊, 网络平台, 新媒体故事号 и 知乎盐选 с основными весами и аудиторскими циклами.","ar":"يمنح الوكلاء القدرة على تسريع تقييم المخطوطات باستخدام سير عمل من 7 خطوات، بما في ذلك فحص التنسيق، وكشف المحتوى الذي تم إنشاؤه بواسطة الذكاء الاصطناعي، والتقييم المتعدد الأبعاد، مستفيدة من منصات مثل 传统文学期刊، 网络平台، 新媒体故事号 و 知乎盐选 مع الأوزان الأساسية ودورات التدقيق."},"useCases":{"en":["Automating manuscript format checks for literary platforms","Generating multi-dimensional scores for publications","Detecting AI-generated content in manuscripts"],"zh":["为文学平台自动化稿件格式检查","为出版物生成多维评分","在稿件中检测AI生成的内容"],"ja":["文学プラットフォームの原稿の形式チェックを自動化する","出版物の多次元評価を生成する","原稿の中でAIによって生成されたコンテンツを検出する"],"ko":["문학 플랫폼을 위한 원고 형식 체크 자동화","출판물의 다차원 점수 생성","원고 내에서 AI로 생성된 콘텐츠를 감지"],"es":["Automatización de comprobaciones de formato de manuscritos para plataformas literarias","Generación de puntuaciones multi-dimensionales para publicaciones","Detección de contenido generado por IA en manuscritos"],"fr":["Automatisation des vérifications de format de manuscrits pour les plateformes littéraires","Génération de notes multi-dimensionnelles pour les publications","Détection de contenu généré par l''IA dans les manuscrits"],"de":["Automatisierung von Formatprüfungen für Manuskripte auf literarischen Plattformen","Generierung von mehrdimensionalen Bewertungen für Veröffentlichungen","Erkennung von durch KI generiertem Inhalt in Manuskripten"],"pt":["Automatizar verificações de formato de manuscritos para plataformas literárias","Gerar pontuações multi-dimensionais para publicações","Detectar conteúdo gerado por IA em manuscritos"],"ru":["Автоматизировать проверку формата рукописей для литературных платформ","Генерировать многомерные баллы для публикаций","Обнаруживать содержание, сгенерированное ИИ, в рукописях"],"ar":["أتمتة فحص تنسيق المخطوطات لمنصات أدبية","генерация تقييمات متعددة الأبعاد للمنشورات","كشف المحتوى الذي تم إنشاؤه بواسطة الذكاء الاصطناعي في المخطوطات"]},"limitations":{"en":["Requires user input for target platform type","Limited to Chinese-language manuscripts","Dependent on 7-step workflow for evaluation"],"zh":["需要用户输入目标平台类型","仅限于中文稿件","依赖7步工作流进行评估"],"ja":["対象プラットフォームの種類をユーザーに入力する必要がある","中国語の原稿のみに限定される","7ステップのワークフローに依存して評価する"],"ko":["대상 플랫폼 유형에 대한 사용자 입력이 필요","중국어 원고에만 제한됨","7단계 워크플로우에 의존하여 평가"],"es":["Requiere una entrada de usuario para el tipo de plataforma de destino","Limitado a manuscritos en idioma chino","Dependiente del flujo de trabajo de 7 pasos para la evaluación"],"fr":["Nécessite une entrée utilisateur pour le type de plateforme cible","Limité aux manuscrits en langue chinoise","Dépendant du flux de travail de 7 étapes pour l''évaluation"],"de":["Benötigt eine Benutzereingabe für den Zielplattformtyp","Begrenzt auf chinesischsprachige Manuskripte","Abhängig vom 7-Schritt-Workflow für die Auswertung"],"pt":["Requer entrada do usuário para o tipo de plataforma de destino","Limitado a manuscritos em língua chinesa","Dependente do fluxo de trabalho de 7 etapas para avaliação"],"ru":["Требует ввода пользователя для типа целевой платформы","Ограничен китайскими рукописями","Зависит от 7-этапного рабочего процесса для оценки"],"ar":["يتطلب إدخال المستخدم لنوع المنصة المستهدفة","محدود بالمخطوطات الصينية","يعتمد على سير العمل من 7 خطوات للتقييم"]},"version":4},"contentHash":"f05cca2d86f383baa5e1a58a1c2ceb5c5454049f2f049164e87ffee54caf249d","qualityScore":33}');
