INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xxl-novels/short-story-creator/manuscript-reviewer', 'manuscript-reviewer', 'xxl-novels', 'short-story-creator', 'community', 'manuscript-reviewer xxl-novels short-story-creator community The manuscript-reviewer skill streamlines manuscript evaluation for developers, utilizing a 7-step workflow including format checks, AI detection, and multi-dimensional scoring. Ideal for literary platforms and publications. 稿件审稿工具是一种AI驱动的审稿平台，支持多种格式和平台的审稿 原稿レビューAIエージェントは、さまざまな形式とプラットフォームの原稿をレビューするためのAI駆動型プラットフォームです 원고 리뷰어는 다양한 형식과 플랫폼의 원고를 리뷰하는 AI 기반 플랫폼입니다 El revisor de manuscritos es una herramienta de IA que ayuda a evaluar y mejorar la calidad de los textos L''outil de révision de manuscrits est un outil de IA qui aide à évaluer et améliorer la qualité des textes Das Manuskript-Review-Tool ist ein KI-Tool, das bei der Bewertung und Verbesserung der Textqualität hilft O manuscript-reviewer é uma ferramenta de revisão de manuscritos que utiliza 7 etapas de revisão e avaliação para garantir a qualidade dos manuscritos ИИ Агент manuscript-reviewer - это инструмент редактирования рукописей, который использует 7 этапов проверки и оценки для обеспечения качества рукописей مانوسكريبت-ريفيوير هو أداة لاستعراض المخطوطات التي تستخدم 7 مراحل من الاستعراض والتقييم لضمان جودة المخطوطات how to use manuscript-reviewer manuscript-reviewer setup guide manuscript-reviewer alternative manuscript-reviewer vs human reviewers what is manuscript-reviewer install manuscript-reviewer manuscript-reviewer for literary publications AI-powered manuscript review manuscript-reviewer workflow optimization 稿件审稿工具 AI审稿 原稿レビュー 12维度评分 快速淘汰项 综合评估模式 原稿改进 AI技术 审稿平台 Determines manuscript platform type for weighted assessment Performs format initial checks for rapid filtering Applies AI detection for deeper content analysis Conducts 12-dimensional scoring for comprehensive evaluation Generates expert opinions and saves review reports Supports multiple literary platforms with customizable settings manuscript-reviewer is a specialized AI agent skill designed for evaluating manuscripts based on specific platform requirements, applying weighted assessments and generating detailed review reports');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('udecode/better-convex/ankane-readme-writer', 'community', 'udecode', 'better-convex', 'udecode/better-convex', 'ankane-readme-writer', 371, 27, 33, '2026-03-05T04:36:27Z', '2026-03-06T06:28:32.086Z', '43005a802f8a1659c03fc8a1227d12ee538b062a37bdd8b4261588433c656f1d', '{"id":"udecode/better-convex/ankane-readme-writer","name":"ankane-readme-writer","description":{"en":"The ankane-readme-writer skill generates properly formatted README files for Ruby gems, following the Ankane template structure. It benefits developers creating documentation for their gems.","zh":"ankane-readme-writer 是一个创建格式化 README 文件的 AI エージェント，支持 Better Auth、tRPC、Drizzle 和 TanStack Query","ja":"ankane-readme-writer は、Better Auth、tRPC、Drizzle、TanStack Query をサポートする README ファイルを作成する AI エージェント","ko":"ankane-readme-writer는 Better Auth, tRPC, Drizzle, TanStack Query를 지원하는 README 파일을 생성하는 AI 도구","es":"ankane-readme-writer es una herramienta para crear README bien formateados con tecnologías como Better Auth, tRPC, Drizzle y TanStack Query","fr":"ankane-readme-writer est un outil pour créer des fichiers README bien structurés avec des technologies comme Better Auth, tRPC, Drizzle et TanStack Query","de":"ankane-readme-writer ist ein Tool zum Erstellen gut strukturierter README-Dateien mit Technologien wie Better Auth, tRPC, Drizzle und TanStack Query","pt":"O ankane-readme-writer é uma ferramenta que cria READMEs formatados com suporte a Auth, tRPC, Drizzle e TanStack Query.","ru":"ankane-readme-writer - это инструмент, который создает README-файлы с поддержкой Auth, tRPC, Drizzle и TanStack Query.","ar":"ankane-readme-writer هو أداة لإنشاء ملفات README مع دعم المصادقة و tRPC و Drizzle و TanStack Query"},"seo":{"title":{"en":"ankane-readme-writer: README Setup Guide for AI Agents","zh":"ankane-readme-writer 快速入门指南","ja":"ankane-readme-writer のベストプラクティス","ko":"ankane-readme-writer 설정 가이드","es":"Guía de configuración de ankane-readme-writer para desarr...","fr":"Configurer ankane-readme-writer pour les meilleures prati...","de":"Einrichtungsanleitung für ankane-readme-writer: Authentif...","pt":"Guia de Configuração do ankane-readme-writer para Melhor ...","ru":"Руководство по настройке ankane-readme-writer для лучшей ...","ar":"دليل إعداد ankane-readme-writer لتحسين المصادقة"},"description":{"en":"Discover how ankane-readme-writer simplifies README creation for Ruby gems, following Ankane style guides. Get started with our expert guide and templates.","zh":"使用 ankane-readme-writer AI エージェント创建格式化的 README 文件，支持 Better Auth、tRPC、Drizzle 和 TanStack Query","ja":"ankane-readme-writer AIエージェントを使用して、Better Auth、tRPC、Drizzle、TanStack Query をサポートする README ファイルを作成","ko":"ankane-readme-writer AI 도구를 사용하여 Better Auth, tRPC, Drizzle, TanStack Query를 지원하는 README 파일을 생성","es":"Aprende a utilizar ankane-readme-writer para crear README bien formateados con Better Auth, tRPC, Drizzle y TanStack Query","fr":"Découvrez comment utiliser ankane-readme-writer pour créer des fichiers README conformes aux meilleures pratiques avec Better Auth, tRPC, Drizzle et TanStack...","de":"Entdecken Sie, wie Sie ankane-readme-writer einrichten, um gut strukturierte README-Dateien mit Better Auth, tRPC, Drizzle und TanStack Query zu erstellen","pt":"Aprenda a configurar o ankane-readme-writer para criar READMEs formatados com Auth, tRPC, Drizzle e TanStack Query","ru":"Узнайте, как настроить ankane-readme-writer для создания README-файлов с Auth, tRPC, Drizzle и TanStack Query","ar":"تعرف على كيفية إعداد ankane-readme-writer لإنشاء ملفات README مع المصادقة و tRPC و Drizzle و TanStack Query"},"definition":{"en":"ankane-readme-writer is a skill that automates the creation of README files for Ruby gems, adhering to the Ankane style guide.","zh":"ankane-readme-writer 是一个创建格式化 README 文件的 AI エージェント","ja":"ankane-readme-writer は README ファイルを作成する AI エージェント","ko":"ankane-readme-writer는 README 파일을 생성하는 AI 도구","es":"ankane-readme-writer es una herramienta de documentación que sigue la guía de estilo de Ankane","fr":"ankane-readme-writer est un outil de documentation qui suit la feuille de style d''Ankane","de":"ankane-readme-writer ist ein Dokumentations-Tool, das den Ankane-Stilguide befolgt","pt":"O que é ankane-readme-writer? É uma ferramenta de criação de READMEs que segue o guia de estilo Ankane.","ru":"Что такое ankane-readme-writer? Это инструмент для создания README-файлов, следующий руководству Ankane.","ar":"ما هو ankane-readme-writer؟ هو أداة لإنشاء ملفات README التي تتبع دليل Ankane"},"features":{"en":["Generates README files following the Ankane template structure","Supports creation of documentation for Ruby gems","Utilizes the Ankane style guide for formatting","Creates properly formatted README files for gems like ''turbo-search''","Integrates with other tools like Auth, tRPC, Drizzle, and TanStack Query","Follows best practices for README creation"],"zh":["支持 Better Auth","支持 tRPC","支持 Drizzle","支持 TanStack Query","创建格式化的 README 文件","遵循 Ankane 风格指南"],"ja":["Better Auth をサポート","tRPC をサポート","Drizzle をサポート","TanStack Query をサポート","フォーマット済みの README ファイルを作成","Ankane スタイル ガイドに準拠"],"ko":["Better Auth 지원","tRPC 지원","Drizzle 지원","TanStack Query 지원","README 파일 생성","Ankane 스타일 가이드 준수"],"es":["Soporte para Better Auth","Integración con tRPC","Compatibilidad con Drizzle","Uso de TanStack Query","Creación de README bien formateados","Seguimiento de la guía de estilo de Ankane"],"fr":["Prise en charge de Better Auth","Intégration avec tRPC","Compatibilité avec Drizzle","Utilisation de TanStack Query","Création de fichiers README bien structurés","Respect de la feuille de style d''Ankane"],"de":["Unterstützung für Better Auth","Integration mit tRPC","Kompatibilität mit Drizzle","Verwendung von TanStack Query","Erstellung gut strukturierter README-Dateien","Befolgung des Ankane-Stilguides"],"pt":["Suporte a Auth para autenticação","Integração com tRPC para comunicação","Compatibilidade com Drizzle para gerenciamento de estado","Suporte a TanStack Query para gerenciamento de dados"],"ru":["Поддержка Auth для аутентификации","Интеграция с tRPC для коммуникации","Совместимость с Drizzle для управления состоянием","Поддержка TanStack Query для управления данными"],"ar":["دعم المصادقة لتحقق الهوية","التكامل مع tRPC للاتصال","التوافق مع Drizzle لإدارة الحالة","دعم TanStack Query لإدارة البيانات"]},"keywords":{"en":["how to use ankane-readme-writer","what is ankane-readme-writer","ankane-readme-writer alternative","ankane-readme-writer vs readme generator","ankane-readme-writer install","ankane-readme-writer setup guide","ankane style guide","ruby gem documentation","README creation tools"],"zh":["ankane-readme-writer","AI エージェント","README 文件","Better Auth","tRPC","Drizzle","TanStack Query","Ankane 风格指南"],"ja":["ankane-readme-writer","AI エージェント","README ファイル","Better Auth","tRPC","Drizzle","TanStack Query","Ankane スタイル ガイド"],"ko":["ankane-readme-writer","AI 도구","README 파일","Better Auth","tRPC","Drizzle","TanStack Query","Ankane 스타일 가이드"],"es":["ankane-readme-writer","herramientas de documentación","Better Auth","tRPC","Drizzle","TanStack Query","guía de estilo de Ankane","README bien formateados","desarrollo de software","documentación de código"],"fr":["ankane-readme-writer","outils de documentation","Better Auth","tRPC","Drizzle","TanStack Query","feuille de style d''Ankane","fichiers README bien structurés","développement de logiciels","documentation de code"],"de":["ankane-readme-writer","Dokumentations-Tools","Better Auth","tRPC","Drizzle","TanStack Query","Ankane-Stilguide","gut strukturierte README-Dateien","Software-Entwicklung","Code-Dokumentation"],"pt":["ankane-readme-writer","criação de READMEs","Auth","tRPC","Drizzle","TanStack Query","ferramentas de desenvolvimento","guia de estilo Ankane"],"ru":["ankane-readme-writer","создание README-файлов","Auth","tRPC","Drizzle","TanStack Query","инструменты разработки","руководство Ankane"],"ar":["ankane-readme-writer","إنشاء ملفات README","المصادقة","tRPC","Drizzle","TanStack Query","أدوات التطوير","دليل Ankane"]}},"owner":"udecode","repo":"better-convex","repoPath":"udecode/better-convex","stars":371,"forks":27,"updatedAt":"2026-03-05T04:36:27Z","topics":[],"category":"community","skillMd":{"name":"ankane-readme-writer","description":"Creates or updates README files following Ankane-style template for Ruby gems. Use when writing gem documentation with imperative voice, concise prose, and standard section ordering.","bodyPreview":"<examples>\n<example>\nContext: User is creating documentation for a new Ruby gem.\nuser: \"I need to write a README for my new search gem called ''turbo-search''\"\nassistant: \"I''ll use the ankane-readme-writer agent to create a properly formatted README following the Ankane style guide\"\n<commentary>Since the user needs a README for a Ruby gem and wants to follow best practices, use the ankane-readme-writer agent to ensure it follows the Ankane template structure.</commentary>\n</example>\n<example>\nCont","body":"<examples>\n<example>\nContext: User is creating documentation for a new Ruby gem.\nuser: \"I need to write a README for my new search gem called ''turbo-search''\"\nassistant: \"I''ll use the ankane-readme-writer agent to create a properly formatted README following the Ankane style guide\"\n<commentary>Since the user needs a README for a Ruby gem and wants to follow best practices, use the ankane-readme-writer agent to ensure it follows the Ankane template structure.</commentary>\n</example>\n<example>\nContext: User has an existing README that needs to be reformatted.\nuser: \"Can you update my gem''s README to follow the Ankane style?\"\nassistant: \"Let me use the ankane-readme-writer agent to reformat your README according to the Ankane template\"\n<commentary>The user explicitly wants to follow Ankane style, so use the specialized agent for this formatting standard.</commentary>\n</example>\n</examples>\n\nYou are an expert Ruby gem documentation writer specializing in the Ankane-style README format. You have deep knowledge of Ruby ecosystem conventions and excel at creating clear, concise documentation that follows Andrew Kane''s proven template structure.\n\nYour core responsibilities:\n1. Write README files that strictly adhere to the Ankane template structure\n2. Use imperative voice throughout (\"Add\", \"Run\", \"Create\" - never \"Adds\", \"Running\", \"Creates\")\n3. Keep every sentence to 15 words or less - brevity is essential\n4. Organize sections in the exact order: Header (with badges), Installation, Quick Start, Usage, Options (if needed), Upgrading (if applicable), Contributing, License\n5. Remove ALL HTML comments before finalizing\n\nKey formatting rules you must follow:\n- One code fence per logical example - never combine multiple concepts\n- Minimal prose between code blocks - let the code speak\n- Use exact wording for standard sections (e.g., \"Add this line to your application''s **Gemfile**:\")\n- Two-space indentation in all code examples\n- Inline comments in code should be lowercase and under 60 characters\n- Options tables should have 10 rows or fewer with one-line descriptions\n\nWhen creating the header:\n- Include the gem name as the main title\n- Add a one-sentence tagline describing what the gem does\n- Include up to 4 badges maximum (Gem Version, Build, Ruby version, License)\n- Use proper badge URLs with placeholders that need replacement\n\nFor the Quick Start section:\n- Provide the absolute fastest path to getting started\n- Usually a generator command or simple initialization\n- Avoid any explanatory text between code fences\n\nFor Usage examples:\n- Always include at least one basic and one advanced example\n- Basic examples should show the simplest possible usage\n- Advanced examples demonstrate key configuration options\n- Add brief inline comments only when necessary\n\nQuality checks before completion:\n- Verify all sentences are 15 words or less\n- Ensure all verbs are in imperative form\n- Confirm sections appear in the correct order\n- Check that all placeholder values (like <gemname>, <user>) are clearly marked\n- Validate that no HTML comments remain\n- Ensure code fences are single-purpose\n\nRemember: The goal is maximum clarity with minimum words. Every word should earn its place. When in doubt, cut it out.\n"},"lastSynced":"2026-03-06T06:28:32.086Z","agentAnalysis":{"suitability":{"en":"Ideal for Ruby-focused AI Agents requiring automated documentation generation for gems.","zh":"适用于需要自动化文档生成的 Ruby 专注 AI 代理，特别适用于 gems。","ja":"Ruby に焦点を当てた AI エージェントが自動ドキュメント生成を必要とする gem に最適です。","ko":"자동화된 문서 생성이 필요한 Ruby에 중점을 둔 AI 에이전트에 적합하며, 특히 gem에 적합합니다.","es":"Ideal para agentes de IA enfocados en Ruby que requieren generación automatizada de documentación para gems.","fr":"Idéal pour les agents d''IA axés sur Ruby nécessitant une génération automatique de documentation pour les gems.","de":"Ideal für Ruby-fokussierte KI-Agenten, die eine automatisierte Generierung von Dokumentationen für Gems erfordern.","pt":"Ideal para Agentes de IA com foco em Ruby que exigem geração automatizada de documentação para gems.","ru":"Идеально для агентов ИИ с фокусом на Ruby, требующих автоматизированного создания документации для gems.","ar":"مثالي للوكلاء الذكيين الذين يركزون على Ruby ويحتاجون إلى إنشاء وثائق أتمتيكي لجيمز."},"recommendation":{"en":"Empowers agents to generate properly formatted README files following the Ankane template structure, utilizing Ruby gems and adhering to best practices for documentation, including support for the Ankane style guide and compatible with .md file formats.","zh":"赋予代理生成正确格式的 README 文件的能力，遵循 Ankane 模板结构，利用 Ruby gems 并遵循文档的最佳实践，包括对 Ankane 风格指南的支持和兼容 .md 文件格式。","ja":"Ankane テンプレート構造に従って、正しくフォーマットされた README ファイルを生成するエージェントの能力を与え、Ruby gems を利用し、文書化のベストプラクティスに従い、Ankane スタイルガイドのサポートおよび .md ファイル形式の互換性を提供します。","ko":"Ankane 템플릿 구조를 따르는 올바른 형식의 README 파일을 생성할 수 있는 에이전트의 능력을 부여하며, Ruby gems를 사용하며, 문서화의 최고의 관행을 준수하고, Ankane 스타일 가이드의 지원과 .md 파일 형식의 호환성을 제공합니다.","es":"Habilita a los agentes a generar archivos README correctamente formateados siguiendo la estructura de plantilla de Ankane, utilizando gems de Ruby y ajustándose a las mejores prácticas para la documentación, incluyendo soporte para la guía de estilo de Ankane y compatible con formatos de archivo .md.","fr":"Permet aux agents de générer des fichiers README correctement formatés en suivant la structure de modèle de Ankane, en utilisant des gems Ruby et en respectant les meilleures pratiques pour la documentation, y compris le support pour le guide de style de Ankane et compatible avec les formats de fichier .md.","de":"Ermächtigt die Agenten, richtig formatierte README-Dateien zu generieren, die der Ankane-Vorlagenstruktur folgen, Ruby-Gems verwenden und den besten Praktiken für die Dokumentation entsprechen, einschließlich Unterstützung für den Ankane-Stilguide und kompatibel mit .md-Dateiformaten.","pt":"Habilita agentes a gerar arquivos README formatados corretamente, seguindo a estrutura de template do Ankane, utilizando gems Ruby e seguindo as melhores práticas para documentação, incluindo suporte ao guia de estilo do Ankane e compatível com formatos de arquivo .md.","ru":"Наделяет агентов возможностью генерировать правильно отформатированные файлы README, следующими за структурой шаблона Ankane, используя Ruby gems и следуя лучшим практикам для документации, включая поддержку руководства по стилю Ankane и совместимых с форматами файлов .md.","ar":"يمنح الوكلاء القدرة على إنشاء ملفات README مصممة بشكل صحيح، متبعة هيكل قوالب Ankane، واستخدام جيمز Ruby، والالتزام بأفضل الممارسات لإنشاء الوثائق، بما في ذلك دعم دليل أسلوب Ankane والمتوافق مع تنسيقات الملفات .md."},"useCases":{"en":["Generating README files for new Ruby gems","Automating documentation for existing gems","Creating consistent documentation across multiple Ruby projects"],"zh":["为新的 Ruby gems 生成 README 文件","自动化现有 gems 的文档","跨多个 Ruby 项目创建一致的文档"],"ja":["新しい Ruby gems の README ファイルを生成する","既存の gems のドキュメントを自動化する","複数の Ruby プロジェクト全体で一貫したドキュメントを作成する"],"ko":["新的 Ruby gems의 README 파일을 생성","기존 gems의 문서를 자동화","여러 Ruby 프로젝트 전반에서 일관된 문서를 작성"],"es":["Generación de archivos README para nuevos gems de Ruby","Automatización de la documentación para gems existentes","Creación de documentación coherente en varios proyectos de Ruby"],"fr":["Génération de fichiers README pour de nouveaux gems Ruby","Automatisation de la documentation pour les gems existants","Création d''une documentation cohérente sur plusieurs projets Ruby"],"de":["Generierung von README-Dateien für neue Ruby-Gems","Automatisierung der Dokumentation für vorhandene Gems","Erstellung konsistenter Dokumentationen über mehrere Ruby-Projekte hinweg"],"pt":["Geração de arquivos README para novas gems Ruby","Automação da documentação para gems existentes","Criação de documentação consistente em vários projetos Ruby"],"ru":["Генерация файлов README для новых Ruby gems","Автоматизация документации для существующих gems","Создание согласованной документации в нескольких проектах Ruby"],"ar":["إنشاء ملفات README لجيمز Ruby الجديدة","أتمتة الوثائق لجيمز الحالية","إنشاء وثائق متسقة عبر مشاريع Ruby المتعددة"]},"limitations":{"en":["Limited to Ruby gems","Requires knowledge of Ankane template structure","Specific to README file generation"],"zh":["仅限于 Ruby gems","需要了解 Ankane 模板结构","特定于 README 文件生成"],"ja":["Ruby gems 限定","Ankane テンプレート構造の知識が必要","README ファイル生成専用"],"ko":["Ruby gems에만 국한","Ankane 템플릿 구조에 대한 지식이 필요","README 파일 생성 전용"],"es":["Limitado a gems de Ruby","Requiere conocimiento de la estructura de plantilla de Ankane","Específico para la generación de archivos README"],"fr":["Limité aux gems Ruby","Nécessite des connaissances de la structure de modèle de Ankane","Spécifique à la génération de fichiers README"],"de":["Begrenzt auf Ruby-Gems","Benötigt Kenntnisse der Ankane-Vorlagenstruktur","Spezifisch für die Generierung von README-Dateien"],"pt":["Limitado a gems Ruby","Exige conhecimento da estrutura de template do Ankane","Específico para geração de arquivos README"],"ru":["Ограничен Ruby gems","Требует знания структуры шаблона Ankane","Конкретно для генерации файлов README"],"ar":["محدود لجيمز Ruby","يتطلب معرفة هيكل قالب Ankane","محدد لإنشاء ملفات README"]},"version":4},"contentHash":"43005a802f8a1659c03fc8a1227d12ee538b062a37bdd8b4261588433c656f1d","qualityScore":33}');
