INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('udecode/better-convex/ankane-readme-writer', 'ankane-readme-writer', 'udecode', 'better-convex', 'community', 'ankane-readme-writer udecode better-convex community The ankane-readme-writer skill generates properly formatted README files for Ruby gems, following the Ankane template structure. It benefits developers creating documentation for their gems. ankane-readme-writer 是一个创建格式化 README 文件的 AI エージェント，支持 Better Auth、tRPC、Drizzle 和 TanStack Query ankane-readme-writer は、Better Auth、tRPC、Drizzle、TanStack Query をサポートする README ファイルを作成する AI エージェント ankane-readme-writer는 Better Auth, tRPC, Drizzle, TanStack Query를 지원하는 README 파일을 생성하는 AI 도구 ankane-readme-writer es una herramienta para crear README bien formateados con tecnologías como Better Auth, tRPC, Drizzle y TanStack Query ankane-readme-writer est un outil pour créer des fichiers README bien structurés avec des technologies comme Better Auth, tRPC, Drizzle et TanStack Query ankane-readme-writer ist ein Tool zum Erstellen gut strukturierter README-Dateien mit Technologien wie Better Auth, tRPC, Drizzle und TanStack Query O ankane-readme-writer é uma ferramenta que cria READMEs formatados com suporte a Auth, tRPC, Drizzle e TanStack Query. ankane-readme-writer - это инструмент, который создает README-файлы с поддержкой Auth, tRPC, Drizzle и TanStack Query. ankane-readme-writer هو أداة لإنشاء ملفات README مع دعم المصادقة و tRPC و Drizzle و TanStack Query how to use ankane-readme-writer what is ankane-readme-writer ankane-readme-writer alternative ankane-readme-writer vs readme generator ankane-readme-writer install ankane-readme-writer setup guide ankane style guide ruby gem documentation README creation tools ankane-readme-writer AI エージェント README 文件 Better Auth tRPC Drizzle TanStack Query Ankane 风格指南 Generates README files following the Ankane template structure Supports creation of documentation for Ruby gems Utilizes the Ankane style guide for formatting Creates properly formatted README files for gems like ''turbo-search'' Integrates with other tools like Auth, tRPC, Drizzle, and TanStack Query Follows best practices for README creation ankane-readme-writer is a skill that automates the creation of README files for Ruby gems, adhering to the Ankane style guide.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('videojs/v10/git', 'community', 'videojs', 'v10', 'videojs/v10', 'git', 140, 7, 33, '2026-02-24T21:34:39Z', '2026-03-06T06:29:35.940Z', '66850e063bcbffc6df67249e4a5db864c08ef3d992b083d76bcd3394840c6df1', '{"id":"videojs/v10/git","name":"git","description":{"en":"Git skill provides technical guidelines for Video.js 10, including commit and branch naming conventions. It benefits developers working with open-source media player frameworks.","zh":"Git 工作流最佳实践指南，涵盖提交、分支和 PR 标题的技术细节","ja":"Git ワークフローのベストプラクティスを紹介します。コミット、ブランチ、PR タイトルのテクニカルな詳細を含みます","ko":"Git 워크플로우 최고의 관행 가이드, 커밋, 브랜치 및 PR 제목의 기술적 세부 사항을 다룹니다","es":"Git es una herramienta fundamental para Video.js, proporcionando un flujo de trabajo eficiente para commits y ramas","fr":"Git est un outil essentiel pour Video.js, offrant un workflow efficace pour les commits et les branches","de":"Git ist ein grundlegendes Tool für Video.js, das einen effizienten Workflow für Commits und Branches bietet","pt":"O Git é uma ferramenta essencial para desenvolvedores. Aprenda a configurar o Git para projetos de desenvolvimento de software.","ru":"Git - это важнейший инструмент для разработчиков. Узнайте, как настроить Git для своих проектов.","ar":"جيت هو أداة أساسية للمطورين. تعلم كيفية إعداد جيت ل مشاريع تطوير البرمجيات."},"seo":{"title":{"en":"Git: Version Control Setup Guide | AI Agent Skill","zh":"Git 工作流最佳实践指南","ja":"Git ワークフロー設定ガイド","ko":"Git 워크플로우 세팅 가이드","es":"Guía de configuración de Git para Video.js","fr":"Guide de mise en route de Git pour Video.js","de":"Git-Setup-Leitfaden für Video.js","pt":"Guia de Configuração Git para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке Git","ar":"إعدادات جيت للמطورين: دليل إعداد"},"description":{"en":"Master Git workflow conventions with Video.js 10. Learn commit, branch, and PR best practices now!","zh":"了解 Git 工作流的技术细节，包括提交、分支和 PR 标题的最佳实践","ja":"Git ワークフローのテクニカルな詳細を学び、コミット、ブランチ、PR タイトルのベストプラクティスをマスターしよう","ko":"Git 워크플로우의 기술적 세부 사항을 изуч하고 커밋, 브랜치, PR 제목의 최고의 관행을 익히세요","es":"Aprende a utilizar Git con Video.js, incluyendo convenciones de flujo de trabajo y referencias para commits y ramas","fr":"Découvrez comment utiliser Git avec Video.js, y compris les conventions de workflow et les références pour les commits et les branches","de":"Erfahren Sie, wie Sie Git mit Video.js verwenden, einschließlich Workflow-Konventionen und Referenzen für Commits und Branches","pt":"Aprenda a configurar o Git para projetos de desenvolvimento de software com nosso guia passo a passo","ru":"Настройте Git для своих проектов с помощью нашего подробного руководства для разработчиков","ar":"تعلم كيفية إعداد جيت ل مشاريع تطوير البرمجيات مع دليلنا المفصل"},"definition":{"en":"git is a version control system that enables developers to manage changes in their codebase efficiently","zh":"Git 工作流是指使用 Git 进行版本控制的工作流程，包括提交、分支和 PR 的管理","ja":"Git ワークフローとは、Git を使用したバージョン管理のワークフローであり、コミット、ブランチ、PR の管理を含む","ko":"Git 워크플로우는 Git를 사용한 버전 관리의 워크플로우를 말하며, 커밋, 브랜치 및 PR 관리를 포함합니다","es":"Git es un sistema de control de versiones que permite a los desarrolladores colaborar en proyectos de software","fr":"Git est un système de contrôle de version qui permet aux développeurs de collaborer sur des projets de logiciel","de":"Git ist ein Versionskontrollsystem, das es Entwicklern ermöglicht, an Softwareprojekten zusammenzuarbeiten","pt":"O que é Git? Git é um sistema de controle de versão para rastrear alterações no código.","ru":"Что такое Git? Git - это система контроля версий для отслеживания изменений в коде.","ar":"ما هو جيت؟ جيت هو نظام التحكم في الإصدارات لتتبع التغييرات في الكود."},"features":{"en":["Generates commits using the format `type(scope): lowercase description`","Supports inferring scope via `references/scope.md`","Creates and updates PRs using `references/pr.md` guidelines","Names branches according to `type/short-description` convention","References commit guidelines via `references/commit.md`"],"zh":["提交消息格式：type(scope): lowercase description","分支命名规范：type/short-description","PR 标题格式：type(scope): lowercase description","Git 工作流最佳实践指南","提交、分支和 PR 的管理","Video.js 10 的 Git 工作流集成"],"ja":["コミットメッセージの形式：type(scope): lowercase description","ブランチ命名規則：type/short-description","PR タイトルの形式：type(scope): lowercase description","Git ワークフローのベストプラクティス","コミット、ブランチ、PR の管理","Video.js 10 の Git ワークフローの統合"],"ko":["커밋 메시지 형식: type(scope): lowercase description","브랜치 이름 규칙: type/short-description","PR 제목 형식: type(scope): lowercase description","Git 워크플로우 최고의 관행","커밋, 브랜치, PR 관리","Video.js 10의 Git 워크플로우 통합"],"es":["Convenciones de flujo de trabajo para commits y ramas","Referencias para commits, ramas y solicitudes de extracción","Soporte para descripciones de commits en minúsculas","Nombre de ramas con formato type/short-description","Títulos de solicitudes de extracción personalizadas"],"fr":["Conventions de workflow pour les commits et les branches","Références pour les commits, les branches et les demandes d''extraction","Prise en charge des descriptions de commits en minuscules","Nom de branche au format type/short-description","Titres de demandes d''extraction personnalisés"],"de":["Workflow-Konventionen für Commits und Branches","Referenzen für Commits, Branches und Pull-Requests","Unterstützung für Commit-Beschreibungen in Kleinschreibung","Branch-Namen im Format type/short-description","Benutzerdefinierte Pull-Request-Titel"],"pt":["Commits com descrições em minúsculas","Inferring scope para commits","Criação e atualização de PRs","Nomeação de branches com tipo e descrição","Uso de referências para commits e branches"],"ru":["Коммиты с описаниями в нижнем регистре","Определение области видимости для коммитов","Создание и обновление PR","Именование веток с типом и описанием","Использование ссылок для коммитов и веток"],"ar":["التزمات مع описанияات في الحروف الصغيرة","استنتاج نطاق لالتزمات","إنشاء و تحديث الطلبات الجديدة","تسمية الفروع مع نوع و وصف","استخدام المراجع للالتزمات و الفروع"]},"keywords":{"en":["how to use git with Video.js","git workflow conventions","git alternative to svn","git vs mercurial","git install guide","git setup for React","what is git used for","git commit best practices","git branch naming conventions"],"zh":["Git 工作流","Git最佳实践","提交消息格式","分支命名规范","PR 标题格式","Video.js 10","Git 工作流集成","版本控制","Git 管理"],"ja":["Git ワークフロー","Git ベストプラクティス","コミットメッセージの形式","ブランチ命名規則","PR タイトルの形式","Video.js 10","Git ワークフローの統合","バージョン管理","Git 管理"],"ko":["Git 워크플로우","Git 최고의 관행","커밋 메시지 형식","브랜치 이름 규칙","PR 제목 형식","Video.js 10","Git 워크플로우 통합","버전 관리","Git 관리"],"es":["git para video.js","convenciones de flujo de trabajo git","referencias para commits y ramas","solicitudes de extracción git","configuración de git para video.js","guias de git para desarrolladores"],"fr":["git pour video.js","conventions de workflow git","références pour les commits et les branches","demandes d''extraction git","configuration de git pour video.js","guides git pour les développeurs"],"de":["git für video.js","workflow-konventionen für git","referenzen für commits und branches","pull-requests git","git-konfiguration für video.js","git-anleitungen für entwickler"],"pt":["git para desenvolvedores","configuração git","guias de git","controle de versão git","commits git","branches git","PR git","desenvolvimento de software com git"],"ru":["ИИ Агенты git","настройка git","руководство по git","контроль версий git","коммиты git","ветки git","PR git","разработка программного обеспечения с git"],"ar":["جيت للمطورين","إعدادات جيت","دليل جيت","نظام التحكم في الإصدارات جيت","التزمات جيت","الفروع جيت","الطلبات الجديدة جيت","تطوير البرمجيات مع جيت"]}},"owner":"videojs","repo":"v10","repoPath":"videojs/v10","stars":140,"forks":7,"updatedAt":"2026-02-24T21:34:39Z","topics":[],"category":"community","skillMd":{"name":"git","description":">-","bodyPreview":"# Git\n\nGit workflow conventions for Video.js 10.\n\n## Reference Material\n\n| Task                  | Load                   |\n| --------------------- | ---------------------- |\n| Writing commits       | `references/commit.md` |\n| Inferring scope       | `references/scope.md`  |\n| Creating/updating PRs | `references/pr.md`     |\n| Naming branches       | `references/branch.md` |\n\n## Quick Reference\n\n**Commit:** `type(scope): lowercase description`\n\n**Branch:** `type/short-description`\n\n**PR Title:*","body":"# Git\n\nGit workflow conventions for Video.js 10.\n\n## Reference Material\n\n| Task                  | Load                   |\n| --------------------- | ---------------------- |\n| Writing commits       | `references/commit.md` |\n| Inferring scope       | `references/scope.md`  |\n| Creating/updating PRs | `references/pr.md`     |\n| Naming branches       | `references/branch.md` |\n\n## Quick Reference\n\n**Commit:** `type(scope): lowercase description`\n\n**Branch:** `type/short-description`\n\n**PR Title:** Same as commit (or `RFC:` / `Discovery:` prefix)\n\n## Process\n\n1. Create branch following naming convention\n2. Make changes\n3. Commit with conventional message\n4. Push and create PR with proper description\n\nFor the `/commit-pr` command, all steps after branching are automated.\n"},"lastSynced":"2026-03-06T06:29:35.940Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Management Agents needing standardized git workflow conventions.","zh":"适用于需要标准化git工作流约定的代码管理代理。","ja":"コード管理エージェントが標準化されたgitワークフローコンベンションを必要とする場合に適しています。","ko":"표준화된 git 워크플로우 규칙이 필요한 코드 관리 에이전트에 적합합니다.","es":"Perfecto para agentes de administración de código que necesitan convenciones de flujo de trabajo de git estandarizadas.","fr":"Parfait pour les agents de gestion de code nécessitant des conventions de workflow git standardisées.","de":"Perfekt für Code-Management-Agents, die standardisierte git-Workflow-Konventionen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Código que necessitam de convenções de workflow git padronizadas.","ru":"Идеально для агентов управления кодом, требующих стандартизированных конвенций рабочего процесса git.","ar":"مثالي لعميل إدارة الشفرة الذي يحتاج إلى اتفاقيات سير عمل جيت معيارية."},"recommendation":{"en":"Empowers agents to manage commits with descriptive naming conventions, infer scope, and create/update pull requests using markdown files like `commit.md`, `scope.md`, and `pr.md`, while following branch naming standards like `type/short-description`.","zh":"赋予代理管理提交的能力，使用描述性的命名约定，推断范围，并使用markdown文件（如`commit.md`、`scope.md`和`pr.md`）创建/更新拉取请求，同时遵循分支命名标准（如`type/short-description`）。","ja":"エージェントがコミットを管理する能力を付与し、説明的な命名規約を使用し、スコープを推論し、Markdownファイル（例：`commit.md`、`scope.md`、`pr.md`）を使用してプルリクエストを作成/更新し、ブランチ命名規約（例：`type/short-description`）に従う。","ko":"에이전트가 제출을 관리할 수 있는 능력을 부여하며, 설명적인 명명 규약을 사용하고, 범위를 추론하며, 마크다운 파일(예: `commit.md`, `scope.md`, `pr.md`)을 사용하여 풀 리퀘스트를 생성/업데이트하며, 분기 명명 규약(예: `type/short-description`)을 따릅니다.","es":"Permite a los agentes administrar confirmaciones con convenciones de nombres descriptivos, inferir el alcance y crear/actualizar solicitudes de extracción utilizando archivos de markdown como `commit.md`, `scope.md` y `pr.md`, siguiendo estándares de nombres de ramas como `type/short-description`.","fr":"Permet aux agents de gérer les validations avec des conventions de nommage descriptives, d''inférer la portée et de créer/mettre à jour des demandes d''extraction en utilisant des fichiers markdown comme `commit.md`, `scope.md` et `pr.md`, tout en suivant les normes de nommage de branche comme `type/short-description`.","de":"Ermöglicht es Agenten, Commits mit beschreibenden Benennungskonventionen zu verwalten, den Umfang abzuleiten und Pull-Requests mithilfe von Markdown-Dateien wie `commit.md`, `scope.md` und `pr.md` zu erstellen/aktualisieren, während sie Branch-Namensstandards wie `type/short-description` befolgen.","pt":"Habilita os agentes a gerenciar commits com convenções de nomenclatura descritiva, inferir escopo e criar/atualizar solicitações de pull usando arquivos markdown como `commit.md`, `scope.md` e `pr.md`, seguindo padrões de nomenclatura de branch como `type/short-description`.","ru":"Наделяет агентов возможностью управлять коммитами с помощью описательных конвенций именования, определять объем и создавать/обновлять запросы на включение с помощью файлов markdown, таких как `commit.md`, `scope.md` и `pr.md`, придерживаясь стандартов именования веток, таких как `type/short-description`.","ar":"يمنح الوكلاء إمكانية إدارة التعليقات باتباع اتفاقيات تسمية وصفية و استنتاج النطاق و إنشاء / تحديث طلبات السحب باستخدام ملفات markdown مثل `commit.md` و `scope.md` و `pr.md` ، مع اتباع معايير تسمية الفرع مثل `type/short-description`."},"useCases":{"en":["Standardizing commit messages with type and scope","Automating branch creation with descriptive names","Streamlining pull request management with clear titles"],"zh":["使用类型和范围标准化提交消息","使用描述性的名称自动创建分支","使用清晰的标题简化拉取请求管理"],"ja":["タイプとスコープを使用したコミットメッセージの標準化","説明的な名前を使用したブランチの自動作成","明確なタイトルを使用したプルリクエスト管理の簡素化"],"ko":["타입과 범위를 사용한 제출 메시지 표준화","설명적인 이름을 사용한 분기 자동 생성","명확한 제목을 사용한 풀 리퀘스트 관리 간소화"],"es":["Establecer un estándar para los mensajes de confirmación con tipo y alcance","Automatizar la creación de ramas con nombres descriptivos","Optimizar la administración de solicitudes de extracción con títulos claros"],"fr":["Standardiser les messages de validation avec le type et la portée","Automatiser la création de branches avec des noms descriptifs","Optimiser la gestion des demandes d''extraction avec des titres clairs"],"de":["Standardisieren von Commit-Mitteilungen mit Typ und Umfang","Automatisieren der Erstellung von Branches mit beschreibenden Namen","Optimieren des Pull-Request-Managements mit klaren Titeln"],"pt":["Padronizar mensagens de commit com tipo e escopo","Automatizar a criação de branch com nomes descritivos","Otimizar a gestão de solicitações de pull com títulos claros"],"ru":["Стандартизировать сообщения коммитов с типом и объемом","Автоматизировать создание веток с описательными именами","Оптимизировать управление запросами на включение с четкими заголовками"],"ar":["تقييس رسائل التعليقات مع النوع والنطاق","تأتمتة إنشاء الفروع بأسماء وصفية","تسهيل إدارة طلبات السحب مع عناوين واضحة"]},"limitations":{"en":["Requires access to git repository","Specific to Video.js 10 workflow conventions"],"zh":["需要访问git仓库","特定于Video.js 10工作流约定"],"ja":["gitリポジトリへのアクセスが必要","Video.js 10のワークフローコンベンションに特化"],"ko":["git 저장소에 대한 액세스가 필요","Video.js 10 워크플로우 규칙에 특정"],"es":["Requiere acceso al repositorio de git","Específico de las convenciones de flujo de trabajo de Video.js 10"],"fr":["Nécessite un accès au référentiel git","Spécifique aux conventions de workflow de Video.js 10"],"de":["Benötigt Zugriff auf das git-Repository","Spezifisch für die Workflow-Konventionen von Video.js 10"],"pt":["Requer acesso ao repositório git","Específico para convenções de workflow do Video.js 10"],"ru":["Требуется доступ к репозиторию git","Специфичен для конвенций рабочего процесса Video.js 10"],"ar":["يتطلب الوصول إلى مستودع جيت","محدد لاتفاقيات سير عمل فيديو.جس 10"]},"version":4},"contentHash":"66850e063bcbffc6df67249e4a5db864c08ef3d992b083d76bcd3394840c6df1","qualityScore":33}');
