INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('videojs/v10/git', 'git', 'videojs', 'v10', 'community', 'git videojs v10 community Git skill provides technical guidelines for Video.js 10, including commit and branch naming conventions. It benefits developers working with open-source media player frameworks. Git 工作流最佳实践指南，涵盖提交、分支和 PR 标题的技术细节 Git ワークフローのベストプラクティスを紹介します。コミット、ブランチ、PR タイトルのテクニカルな詳細を含みます Git 워크플로우 최고의 관행 가이드, 커밋, 브랜치 및 PR 제목의 기술적 세부 사항을 다룹니다 Git es una herramienta fundamental para Video.js, proporcionando un flujo de trabajo eficiente para commits y ramas Git est un outil essentiel pour Video.js, offrant un workflow efficace pour les commits et les branches Git ist ein grundlegendes Tool für Video.js, das einen effizienten Workflow für Commits und Branches bietet O Git é uma ferramenta essencial para desenvolvedores. Aprenda a configurar o Git para projetos de desenvolvimento de software. Git - это важнейший инструмент для разработчиков. Узнайте, как настроить Git для своих проектов. جيت هو أداة أساسية للمطورين. تعلم كيفية إعداد جيت ل مشاريع تطوير البرمجيات. how to use git with Video.js git workflow conventions git alternative to svn git vs mercurial git install guide git setup for React what is git used for git commit best practices git branch naming conventions Git 工作流 Git最佳实践 提交消息格式 分支命名规范 PR 标题格式 Video.js 10 Git 工作流集成 版本控制 Git 管理 Generates commits using the format `type(scope): lowercase description` Supports inferring scope via `references/scope.md` Creates and updates PRs using `references/pr.md` guidelines Names branches according to `type/short-description` convention References commit guidelines via `references/commit.md` git is a version control system that enables developers to manage changes in their codebase efficiently');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('oriolrius/pki-manager-web/Git', 'community', 'oriolrius', 'pki-manager-web', 'oriolrius/pki-manager-web', 'Git', 6, 2, 33, '2026-03-05T12:21:49Z', '2026-03-06T13:05:25.891Z', '96ca8e0dcceb728b10cbb849944d1dc26dea2564718ab892ae4fa782597e2eab', '{"id":"oriolrius/pki-manager-web/Git","name":"Git","description":{"en":"Git provides expert assistance with Git version control and collaborative workflows, benefiting developers and teams. It supports essential commands for repository setup and daily workflow.","zh":"Git 是一个版本控制系统，提供了存储库设置和日常工作流程的基本命令","ja":"Git はバージョン管理システムであり、リポジトリの設定と日常のワークフローに必要な基本的なコマンドを提供します","ko":"Git은 협업 워크플로우를 위한 버전 관리 시스템으로, 저장소 설정과 일상 작업 흐름의 기본 명령어를 제공합니다","es":"Git es un sistema de control de versiones que permite a los desarrolladores colaborar en proyectos de código abierto","fr":"Git est un système de contrôle de version qui permet aux développeurs de collaborer sur des projets de code ouvert","de":"Git ist ein Versionskontrollsystem, das es Entwicklern ermöglicht, an Open-Source-Projekten zusammenzuarbeiten","pt":"O Git é um sistema de controle de versão que permite gerenciar diferentes versões de um projeto. Aprenda a configurá-lo e utilizá-lo.","ru":"Git — это система версионного контроля, которая позволяет управлять различными версиями проекта. Узнайте, как настроить и использовать ее.","ar":"Git هو نظام التحكم في الإصدار الذي يسمح بإدارة إصدارات مختلفة من المشروع. تعلم كيفية إعداده وتشغيله."},"seo":{"title":{"en":"Git: Essential Commands Setup Guide | AI Agent Skill","zh":"Git 版本控制设置指南","ja":"Git のベストプラクティス - AIエージェント","ko":"Git 협업 워크플로우 가이드","es":"Guía de Configuración de Git: Mejores Prácticas para Desa...","fr":"Guide de Configuration de Git: Bonnes Pratiques pour Déve...","de":"Git-Konfigurationsleitfaden: Best Practices für Entwickler","pt":"Guia de Configuração Git: Melhores Práticas para Controle...","ru":"ИИ Агент Git: Настройка и Лучшие Практики для Версионного...","ar":"دليل إعداد Git: أفضل الممارسات للتحكم في الإصدار"},"description":{"en":"Unlock Git''s full potential with expert assistance on version control and collaborative workflows. Learn essential commands and best practices now!","zh":"了解 Git 版本控制的基本命令和工作流程，包括存储库设置和日常工作流程","ja":"Git の基本的なコマンドとワークフローをマスターする - AIエージェント","ko":"Git 협업 워크플로우를 위한 필수 명령어와 설정 가이드","es":"Aprenda a configurar y utilizar Git de manera efectiva con nuestra guía de mejores prácticas para desarrolladores","fr":"Découvrez comment configurer et utiliser Git de manière efficace avec notre guide de bonnes pratiques pour développeurs","de":"Erfahren Sie, wie Sie Git effektiv konfigurieren und nutzen können, mit unserem Leitfaden für Entwickler","pt":"Aprenda a configurar e utilizar o Git para controle de versão com nossas dicas e melhores práticas.","ru":"Узнайте, как настроить и использовать Git для версионного контроля с нашими советами и лучшими практиками.","ar":"تعلم كيفية إعداد وتشغيل Git للتحكم في الإصدار مع نصائحنا وأفضل الممارسات."},"definition":{"en":"Git is a version control system that enables collaborative workflows and secure repository management through commands like git init and git clone.","zh":"Git 是一个开源的版本控制系统","ja":"Git はオープンソースのバージョン管理システムです","ko":"Git은 오픈소스의 버전 관리 시스템입니다","es":"Git es un sistema de control de versiones que permite la gestión de diferentes versiones de un proyecto","fr":"Git est un système de contrôle de version qui permet la gestion de différentes versions d''un projet","de":"Git ist ein Versionskontrollsystem, das die Verwaltung verschiedener Versionen eines Projekts ermöglicht","pt":"O Git é um sistema de controle de versão distribuído que permite gerenciar diferentes versões de um projeto.","ru":"Git — это распределенная система версионного контроля, которая позволяет управлять различными версиями проекта.","ar":"Git هو نظام تحكم في الإصدار موزع يسمح بإدارة إصدارات مختلفة من المشروع."},"features":{"en":["Initializes new repositories with `git init` command","Clones remote repositories using `git clone <url>`","Supports interactive staging with `git add -p`","Commits changes with messages using `git commit -m \"message\"`","Lists remotes with `git remote -v` command"],"zh":["支持存储库设置，包括 `git init` 和 `git clone`","提供日常工作流程的基本命令，包括 `git status` 和 `git commit`","支持交互式 staging，包括 `git add -p`","支持远程存储库的设置，包括 `git remote add`"],"ja":["リポジトリの設定をサポート、包括 `git init` と `git clone`","日常のワークフローに必要な基本的なコマンドを提供、包括 `git status` と `git commit`","インタラクティブなステージングをサポート、包括 `git add -p`","リモートリポジトリの設定をサポート、包括 `git remote add`"],"ko":["저장소 설정을 지원, 포함 `git init` 및 `git clone`","일상 작업 흐름의 기본 명령어를 제공, 포함 `git status` 및 `git commit`","인터랙티브 스테이징을 지원, 포함 `git add -p`","원격 저장소의 설정을 지원, 포함 `git remote add`"],"es":["Inicialización de repositorios con `git init`","Clonación de repositorios remotos con `git clone`","Configuración de flujos de trabajo diarios con `git status` y `git add`","Creación de commits con `git commit -m`","Modificación de commits con `git commit --amend`"],"fr":["Initialisation de dépôts avec `git init`","Clonage de dépôts distants avec `git clone`","Configuration de flux de travail quotidiens avec `git status` et `git add`","Création de commits avec `git commit -m`","Modification de commits avec `git commit --amend`"],"de":["Initialisierung von Repositorien mit `git init`","Klonen von Remote-Repositorys mit `git clone`","Konfiguration von täglichen Workflows mit `git status` und `git add`","Erstellen von Commits mit `git commit -m`","Ändern von Commits mit `git commit --amend`"],"pt":["Inicialização de repositório com `git init`","Clonagem de repositório remoto com `git clone`","Adição de remoto com `git remote add`","Verificação de status com `git status`","Commit de alterações com `git commit`"],"ru":["Инициализация репозитория с помощью `git init`","Клонирование удаленного репозитория с помощью `git clone`","Добавление удаленного репозитория с помощью `git remote add`","Проверка статуса с помощью `git status`","Фиксация изменений с помощью `git commit`"],"ar":["تثبيت مستودع مع `git init`","استنساخ مستودع عن بعد مع `git clone`","إضافة مستودع عن بعد مع `git remote add`","التحقق من الحالة مع `git status`","التعهد بالتغييرات مع `git commit`"]},"keywords":{"en":["how to use Git","Git setup guide","Git alternative to SVN","Git vs Mercurial","Git install on Linux","Git repository management best practices"],"zh":["Git 版本控制","存储库设置","日常工作流程","基本命令","交互式 staging","远程存储库","AI工具","版本管理系统"],"ja":["Git バージョン管理","リポジトリ設定","日常のワークフロー","基本的なコマンド","インタラクティブなステージング","リモートリポジトリ","AIエージェント","バージョン管理システム"],"ko":["Git 버전 관리","저장소 설정","일상 작업 흐름","기본 명령어","인터랙티브 스테이징","원격 저장소","AI 도구","버전 관리 시스템"],"es":["git para desarrolladores","guias de configuración de git","mejores prácticas de git","control de versiones con git","colaboración en proyectos con git","git init","git clone","git status"],"fr":["git pour développeurs","guides de configuration de git","bonnes pratiques de git","contrôle de version avec git","collaboration sur des projets avec git","git init","git clone","git status"],"de":["git für entwickler","git-konfigurationsleitfäden","best practices für git","versionskontrolle mit git","zusammenarbeit an projekten mit git","git init","git clone","git status"],"pt":["git para iniciantes","guia de configuração git","melhores práticas git","controle de versão git","git para desenvolvedores","comandos git básicos"],"ru":["git для начинающих","руководство по настройке git","лучшие практики git","версионный контроль git","git для разработчиков","основные команды git"],"ar":["git لل مبتدئين","دليل إعداد git","أفضل الممارسات git","تحكم في الإصدار git","git للمطورين","أوامر git الأساسية"]}},"owner":"oriolrius","repo":"pki-manager-web","repoPath":"oriolrius/pki-manager-web","stars":6,"forks":2,"updatedAt":"2026-03-05T12:21:49Z","topics":["certificate-authority","certificate-management","cosmian","fastify","kms","pki","pki-manager","react","security","trpc","typescript","x509"],"category":"community","skillMd":{"name":"Git","description":"Expert guidance for Git version control operations including commits, branches, merging, rebasing, conflict resolution, and Git workflows. Use this when working with Git repositories, version control, or collaborative development.","bodyPreview":"# Git\n\nExpert assistance with Git version control and collaborative workflows.\n\n## Essential Commands\n\n### Repository Setup\n- `git init` - Initialize new repository\n- `git clone <url>` - Clone remote repository\n- `git remote add origin <url>` - Add remote\n- `git remote -v` - List remotes\n\n### Daily Workflow\n- `git status` - Check working tree status\n- `git add .` - Stage all changes\n- `git add -p` - Interactive staging\n- `git commit -m \"message\"` - Commit with message\n- `git commit --amend` - Am","body":"# Git\n\nExpert assistance with Git version control and collaborative workflows.\n\n## Essential Commands\n\n### Repository Setup\n- `git init` - Initialize new repository\n- `git clone <url>` - Clone remote repository\n- `git remote add origin <url>` - Add remote\n- `git remote -v` - List remotes\n\n### Daily Workflow\n- `git status` - Check working tree status\n- `git add .` - Stage all changes\n- `git add -p` - Interactive staging\n- `git commit -m \"message\"` - Commit with message\n- `git commit --amend` - Amend last commit\n- `git pull` - Fetch and merge from remote\n- `git push` - Push commits to remote\n\n### Branch Management\n- `git branch` - List local branches\n- `git branch -a` - List all branches (including remote)\n- `git branch <name>` - Create new branch\n- `git checkout <branch>` - Switch to branch\n- `git checkout -b <name>` - Create and switch to new branch\n- `git branch -d <name>` - Delete branch (safe)\n- `git branch -D <name>` - Force delete branch\n- `git push origin --delete <branch>` - Delete remote branch\n\n### Viewing History\n- `git log` - View commit history\n- `git log --oneline --graph` - Compact graphical history\n- `git log --author=\"name\"` - Filter by author\n- `git show <commit>` - Show commit details\n- `git diff` - Show unstaged changes\n- `git diff --staged` - Show staged changes\n- `git diff <branch1>..<branch2>` - Compare branches\n\n### Undoing Changes\n- `git restore <file>` - Discard working changes\n- `git restore --staged <file>` - Unstage file\n- `git reset HEAD~1` - Undo last commit (keep changes)\n- `git reset --hard HEAD~1` - Undo last commit (discard changes)\n- `git revert <commit>` - Create new commit that undoes changes\n- `git clean -fd` - Remove untracked files\n\n### Stashing\n- `git stash` - Stash current changes\n- `git stash list` - List stashes\n- `git stash pop` - Apply and remove last stash\n- `git stash apply` - Apply last stash (keep in list)\n- `git stash drop` - Delete last stash\n\n## Advanced Operations\n\n### Rebasing\n```bash\n# Rebase current branch onto main\ngit rebase main\n\n# Interactive rebase (squash, reorder, edit commits)\ngit rebase -i HEAD~3\n\n# Continue after resolving conflicts\ngit rebase --continue\n\n# Abort rebase\ngit rebase --abort\n```\n\n### Cherry-picking\n```bash\n# Apply specific commit to current branch\ngit cherry-pick <commit-hash>\n\n# Cherry-pick without committing\ngit cherry-pick -n <commit-hash>\n```\n\n### Merging\n```bash\n# Merge branch into current\ngit merge <branch>\n\n# Merge without fast-forward (create merge commit)\ngit merge --no-ff <branch>\n\n# Abort merge\ngit merge --abort\n```\n\n### Conflict Resolution\n```bash\n# Show conflicts\ngit status\n\n# After resolving conflicts in files\ngit add <resolved-file>\ngit commit\n\n# Use theirs/ours for entire file\ngit checkout --theirs <file>\ngit checkout --ours <file>\n```\n\n## Git Workflows\n\n### Feature Branch Workflow\n```bash\n# Create feature branch\ngit checkout -b feature/new-feature\n\n# Work and commit\ngit add .\ngit commit -m \"Add new feature\"\n\n# Update from main\ngit checkout main\ngit pull\ngit checkout feature/new-feature\ngit rebase main\n\n# Push feature branch\ngit push -u origin feature/new-feature\n```\n\n### Hotfix Workflow\n```bash\n# Create hotfix from main\ngit checkout main\ngit pull\ngit checkout -b hotfix/critical-fix\n\n# Fix and commit\ngit commit -am \"Fix critical bug\"\n\n# Merge back to main\ngit checkout main\ngit merge hotfix/critical-fix\ngit push\n\n# Clean up\ngit branch -d hotfix/critical-fix\n```\n\n## Configuration\n\n### User Setup\n```bash\ngit config --global user.name \"Your Name\"\ngit config --global user.email \"your@email.com\"\n```\n\n### Useful Aliases\n```bash\ngit config --global alias.co checkout\ngit config --global alias.br branch\ngit config --global alias.ci commit\ngit config --global alias.st status\ngit config --global alias.lg \"log --oneline --graph --all\"\n```\n\n### Editor\n```bash\ngit config --global core.editor \"vim\"\n```\n\n## Best Practices\n\n1. **Commit Messages**: Use clear, descriptive messages following conventional commits\n2. **Small Commits**: Make atomic commits that do one thing\n3. **Pull Before Push**: Always pull latest changes before pushing\n4. **Branch Naming**: Use descriptive names like `feature/`, `bugfix/`, `hotfix/`\n5. **Never Force Push**: Avoid `git push --force` on shared branches\n6. **Review Changes**: Use `git diff` before committing\n7. **Protect Main**: Never commit directly to main/master\n\n## Troubleshooting\n\n### Undo accidental commit to wrong branch\n```bash\ngit reset HEAD~1  # Undo commit, keep changes\ngit stash         # Stash changes\ngit checkout <correct-branch>\ngit stash pop     # Apply changes\ngit add .\ngit commit -m \"message\"\n```\n\n### Fix merge conflicts\n```bash\n# View conflicts\ngit status\n\n# Edit conflicting files (look for <<<<<<, ======, >>>>>>)\n# Remove conflict markers and keep desired code\n\n# Mark as resolved\ngit add <file>\ngit commit\n```\n\n### Recover deleted branch\n```bash\n# Find commit hash\ngit reflog\n\n# Recreate branch\ngit checkout -b <branch-name> <commit-hash>\n```\n"},"lastSynced":"2026-03-06T13:05:25.891Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined version control and collaborative workflow management using Git","zh":"适用于需要使用 Git 进行版本控制和协作工作流管理的开发代理","ja":"Git を使用したバージョン管理と共同ワークフローの管理が必要な開発エージェントに適しています","ko":"Git을 사용한 버전 관리 및 협업 워크플로 관리가 필요한 개발 에이전트에 적합합니다","es":"Ideal para Agentes de Desarrollo que requieren un control de versiones simplificado y una gestión de flujo de trabajo colaborativa utilizando Git","fr":"Idéal pour les agents de développement nécessitant un contrôle de version simplifié et une gestion de workflow collaborative à l''aide de Git","de":"Ideal für Entwicklungssagenten, die ein gestreamtes Versionskontrollsystem und eine kollaborative Workflowverwaltung mit Git erfordern","pt":"Ideal para Agentes de Desenvolvimento que requerem controle de versão simplificado e gerenciamento de fluxo de trabalho colaborativo usando Git","ru":"Идеально для агентов разработки, требующих упрощенного управления версиями и сотрудничества в управлении рабочим процессом с помощью Git","ar":"مثالي لعميل التطوير الذي يتطلب التحكم في الإصدار المُبسّط وإدارة تدفق العمل التعاوني باستخدام Git"},"recommendation":{"en":"Empowers agents to manage repositories with essential commands like `git init`, `git clone`, and `git commit`, streamlining daily workflows and collaborative development using protocols like Git remote and Git commit protocols","zh":"赋予代理管理存储库的能力，使用诸如 `git init`、`git clone` 和 `git commit` 的基本命令，简化日常工作流程和使用 Git 远程和 Git 提交协议的协作开发","ja":"エージェントが `git init`、`git clone`、`git commit` などの基本的なコマンドを使用してリポジトリを管理できるようにし、Git リモートと Git コミット プロトコルなどのプロトコルを使用した共同開発と日常のワークフローを効率化します","ko":"에이전트가 `git init`, `git clone`, `git commit` 등의 기본 명령어를 사용하여 리포지토리를 관리할 수 있도록 하며, Git 원격 및 Git 커밋 프로토콜 등을 사용한 협업 개발 및 일일 워크플로우를 간소화합니다","es":"Habilita a los agentes a gestionar repositorios con comandos esenciales como `git init`, `git clone` y `git commit`, simplificando los flujos de trabajo diarios y el desarrollo colaborativo utilizando protocolos como Git remote y Git commit protocols","fr":"Permet aux agents de gérer des référentiels avec des commandes essentielles comme `git init`, `git clone` et `git commit`, simplifiant ainsi les flux de travail quotidiens et le développement collaboratif à l''aide de protocoles tels que Git remote et Git commit protocols","de":"Ermächtigt die Agenten, Repositories mit wesentlichen Befehlen wie `git init`, `git clone` und `git commit` zu verwalten, wodurch tägliche Workflows und kollaborative Entwicklung mit Protokollen wie Git remote und Git commit protocols gestreamt werden","pt":"Habilita os agentes a gerenciar repositórios com comandos essenciais como `git init`, `git clone` e `git commit`, simplificando fluxos de trabalho diários e desenvolvimento colaborativo usando protocolos como Git remote e Git commit protocols","ru":"Наделяет агентов возможностью управлять репозиториями с помощью основных команд, таких как `git init`, `git clone` и `git commit`, оптимизируя ежедневные рабочие процессы и сотрудничество в разработке с использованием протоколов, таких как Git remote и Git commit protocols","ar":"يمنح الوكلاء القدرة على إدارة المستودعات بأوامر أساسية مثل `git init` و `git clone` و `git commit`، مما يُبسط تدفقات العمل اليومية والتنمية التعاونية باستخدام بروتوكولات مثل Git remote و Git commit protocols"},"useCases":{"en":["Initializing new repositories with `git init`","Cloning remote repositories using `git clone`","Managing daily workflows with `git status` and `git add`"],"zh":["使用 `git init` 初始化新存储库","使用 `git clone` 克隆远程存储库","使用 `git status` 和 `git add` 管理日常工作流程"],"ja":["`git init` を使用して新しいリポジトリを初期化する","`git clone` を使用してリモート リポジトリを複製する","`git status` と `git add` を使用して日常のワークフローを管理する"],"ko":["`git init`를 사용하여 새로운 리포지토리를 초기화하는 것","`git clone`을 사용하여 원격 리포지토리를 복제하는 것","`git status` 및 `git add`를 사용하여 일일 워크플로우를 관리하는 것"],"es":["Inicializar nuevos repositorios con `git init`","Clonar repositorios remotos utilizando `git clone`","Gestionar flujos de trabajo diarios con `git status` y `git add`"],"fr":["Initialiser de nouveaux référentiels avec `git init`","Cloner des référentiels distants à l''aide de `git clone`","Gérer les flux de travail quotidiens avec `git status` et `git add`"],"de":["Neue Repositories mit `git init` initialisieren","Remote-Repositories mit `git clone` klonen","Tägliche Workflows mit `git status` und `git add` verwalten"],"pt":["Inicializando novos repositórios com `git init`","Clonando repositórios remotos usando `git clone`","Gerenciando fluxos de trabalho diários com `git status` e `git add`"],"ru":["Инициализация новых репозиториев с помощью `git init`","Клонирование удаленных репозиториев с помощью `git clone`","Управление ежедневными рабочими процессами с помощью `git status` и `git add`"],"ar":["تثبيت مستودعات جديدة باستخدام `git init`","استنساخ مستودعات عن بُعد باستخدام `git clone`","إدارة تدفقات العمل اليومية باستخدام `git status` و `git add`"]},"limitations":{"en":["Requires Git installation","Limited to Git version control system"],"zh":["需要 Git 安装","仅限 Git 版本控制系统"],"ja":["Git のインストールが必要","Git 版本管理システムのみに限定される"],"ko":["Git 설치가 필요합니다","Git 버전 관리 시스템에만 제한됩니다"],"es":["Requiere instalación de Git","Limitado al sistema de control de versiones Git"],"fr":["Nécessite l''installation de Git","Limité au système de contrôle de version Git"],"de":["Benötigt Git-Installation","Begrenzt auf Git-Versionierungssystem"],"pt":["Requer instalação do Git","Limitado ao sistema de controle de versão Git"],"ru":["Требуется установка Git","Ограничен только системой управления версиями Git"],"ar":["يتطلب تثبيت Git","محدود بنظام التحكم في الإصدار Git"]},"version":4},"contentHash":"96ca8e0dcceb728b10cbb849944d1dc26dea2564718ab892ae4fa782597e2eab","qualityScore":33}');
