INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('oriolrius/pki-manager-web/Git', 'Git', 'oriolrius', 'pki-manager-web', 'community', 'Git oriolrius pki-manager-web community certificate-authority certificate-management cosmian fastify kms pki pki-manager react security trpc typescript x509 Git provides expert assistance with Git version control and collaborative workflows, benefiting developers and teams. It supports essential commands for repository setup and daily workflow. Git 是一个版本控制系统，提供了存储库设置和日常工作流程的基本命令 Git はバージョン管理システムであり、リポジトリの設定と日常のワークフローに必要な基本的なコマンドを提供します Git은 협업 워크플로우를 위한 버전 관리 시스템으로, 저장소 설정과 일상 작업 흐름의 기본 명령어를 제공합니다 Git es un sistema de control de versiones que permite a los desarrolladores colaborar en proyectos de código abierto Git est un système de contrôle de version qui permet aux développeurs de collaborer sur des projets de code ouvert Git ist ein Versionskontrollsystem, das es Entwicklern ermöglicht, an Open-Source-Projekten zusammenzuarbeiten O Git é um sistema de controle de versão que permite gerenciar diferentes versões de um projeto. Aprenda a configurá-lo e utilizá-lo. Git — это система версионного контроля, которая позволяет управлять различными версиями проекта. Узнайте, как настроить и использовать ее. Git هو نظام التحكم في الإصدار الذي يسمح بإدارة إصدارات مختلفة من المشروع. تعلم كيفية إعداده وتشغيله. how to use Git Git setup guide Git alternative to SVN Git vs Mercurial Git install on Linux Git repository management best practices Git 版本控制 存储库设置 日常工作流程 基本命令 交互式 staging 远程存储库 AI工具 版本管理系统 Initializes new repositories with `git init` command Clones remote repositories using `git clone <url>` Supports interactive staging with `git add -p` Commits changes with messages using `git commit -m "message"` Lists remotes with `git remote -v` command Git is a version control system that enables collaborative workflows and secure repository management through commands like git init and git clone.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('6/nitrocop/triage', 'community', '6', 'nitrocop', '6/nitrocop', 'triage', 1, 0, 33, '2026-02-26T02:57:19Z', '2026-03-06T13:08:24.817Z', 'b5b9f4ed4b95d0fbc22b000ad3ecf628efb253345d9ac98202faf929e3048671', '{"id":"6/nitrocop/triage","name":"triage","description":{"en":"The triage skill is an experimental RuboCop rewrite in Rust, helping developers identify top cops to fix. It benefits Ruby developers looking to optimize their code.","zh":"Triage 是一个实验性的 RuboCop 重写版本，使用 Rust 编写。它可以帮助您找出需要修复的顶级 cops。","ja":"Triage は、Rust で書き直された RuboCop の実験的なバージョンです。修正する必要があるトップレベルの cops を見つけるのに役立ちます。","ko":"Triage는 Rust로 다시 작성된 RuboCop의 실험 버전입니다. 수정해야 할 최고의 cops를 찾는 데 도움이 됩니다.","es":"Triage es una herramienta experimental que reescribe RuboCop en Rust para optimizar su funcionamiento","fr":"Triage est un outil expérimental qui réécrit RuboCop en Rust pour optimiser ses performances","de":"Triage ist ein experimentelles Tool, das RuboCop in Rust neu schreibt, um dessen Funktionsweise zu optimieren","pt":"O Triage é uma reimplementação experimental do RuboCop em Rust, permitindo a otimização de projetos Ruby.","ru":"Triage - это экспериментальная реализация RuboCop на Rust, позволяющая оптимизировать проекты Ruby.","ar":"Triage هو إعادة تنفيذ تجريبية ل RuboCop باستخدام Rust، مما يسمح بتحسين مشاريع Ruby."},"seo":{"title":{"en":"Triage: Experimental RuboCop Rewrite Setup Guide | AI Age...","zh":"Triage Setup Guide: 使用 Rust 重写的 RuboCop","ja":"Triage セットアップガイド: Rust で書き直された RuboCop","ko":"Triage 설정 가이드: Rust로 다시 작성된 RuboCop","es":"Guía de configuración de triage: Optimización de RuboCop ...","fr":"Guide de mise en place de triage: Optimisation de RuboCop...","de":"Einrichtungsleitfaden für triage: RuboCop-Optimierung mit...","pt":"Guia de Configuração do Triage: Otimizando RuboCop com Rust","ru":"Настройка Triage: Экспериментальный RuboCop на Rust","ar":"دليل إعداد Triage: تحسين RuboCop باستخدام Rust"},"description":{"en":"Discover how to run triage scripts with Python 3 and optimize your RuboCop workflow - learn more and get started today!","zh":"使用 Triage 脚本自动下载最新的 corpus-results.json 文件，并找出需要修复的顶级 cops","ja":"Triage スクリプトを使用して最新の corpus-results.json ファイルを自動的にダウンロードし、修正する必要があるトップレベルの cops を見つける","ko":"Triage 스크립트를 사용하여 최신의 corpus-results.json 파일을 자동으로 다운로드하고 수정해야 할 최고의 cops를 찾으십시오","es":"Aprende a utilizar triage para identificar y solucionar problemas de RuboCop en tu proyecto Ruby con la ayuda de Rust","fr":"Découvrez comment utiliser triage pour identifier et résoudre les problèmes de RuboCop dans votre projet Ruby avec l''aide de Rust","de":"Erfahren Sie, wie Sie triage verwenden, um RuboCop-Probleme in Ihrem Ruby-Projekt mit Hilfe von Rust zu identifizieren und zu lösen","pt":"Aprenda a configurar o Triage para melhorar a eficiência do RuboCop em projetos Ruby utilizando Rust","ru":"Узнайте, как настроить Triage для повышения эффективности RuboCop в проектах Ruby с помощью Rust","ar":"تعلم كيفية إعداد Triage لتحسين كفاءة RuboCop في مشاريع Ruby باستخدام Rust"},"definition":{"en":"Triage is an experimental RuboCop rewrite in Rust, used to find and fix top cops by divergence in Ruby codebases.","zh":"Triage 是一个 AI 工具，用于自动化代码检查和修复","ja":"Triage は、コードのチェックと修正を自動化する AI エージェントです","ko":"Triage는 코드를 자동으로 점검하고 수정하는 AI 도구입니다","es":"Triage es un agente de IA que utiliza Rust para optimizar la configuración de RuboCop","fr":"Triage est un agent IA qui utilise Rust pour optimiser la configuration de RuboCop","de":"Triage ist ein KI-Agent, der Rust verwendet, um die Konfiguration von RuboCop zu optimieren","pt":"O que é Triage? Uma ferramenta de otimização do RuboCop em Rust para projetos Ruby.","ru":"Что такое Triage? Инструмент для оптимизации RuboCop на Rust для проектов Ruby.","ar":"ما هو Triage؟ أداة لتحسين RuboCop باستخدام Rust لمشاريع Ruby."},"features":{"en":["Runs triage scripts using Python 3 and the `triage.py` command","Auto-downloads the latest `corpus-results.json` from CI via `gh run download`","Supports filtering by department using the `--department` flag","Allows excluding departments using the `--exclude-department` flag","Can show only cops with false positives using the `--fp-only` flag"],"zh":["自动下载最新的 corpus-results.json 文件","找出需要修复的顶级 cops","支持多种命令行参数，例如 --limit 和 --department","可以过滤和排除特定的 cops","支持 false positive 只显示"],"ja":["最新の corpus-results.json ファイルを自動的にダウンロードする","修正する必要があるトップレベルの cops を見つける","複数のコマンドラインパラメータをサポートする、たとえば --limit と --department","特定の cops をフィルタリングおよび除外する","false positive のみを表示することをサポートする"],"ko":["최신의 corpus-results.json 파일을 자동으로 다운로드합니다","수정해야 할 최고의 cops를 찾아냅니다","여러 가지 명령줄 매개변수를 지원합니다. 예를 들어 --limit 및 --department","특정 cops를 필터링하고 제외할 수 있습니다","false positive만 표시하는 것을 지원합니다"],"es":["Ejecución de scripts de triage para identificar problemas de RuboCop","Uso de Rust para optimizar el rendimiento de RuboCop","Compatibilidad con la descarga automática de resultados de CI","Filtrado de departamentos y exclusión de layout complejos","Opción para mostrar solo falsos positivos"],"fr":["Exécution de scripts de triage pour identifier les problèmes de RuboCop","Utilisation de Rust pour optimiser les performances de RuboCop","Compatibilité avec le téléchargement automatique des résultats de CI","Filtrage de départements et exclusion de layout complexes","Option pour afficher uniquement les faux positifs"],"de":["Ausführung von Triage-Skripten zur Identifizierung von RuboCop-Problemen","Verwendung von Rust zur Optimierung der Leistung von RuboCop","Kompatibilität mit dem automatischen Download von CI-Ergebnissen","Filterung von Abteilungen und Ausschluss komplexer Layouts","Option, nur Falschpositives anzuzeigen"],"pt":["Execução do script de triagem para encontrar os principais cops a serem corrigidos","Suporte à filtragem por departamento","Otimização de desempenho com Rust","Integração com o gh run download para obtenção de resultados de corpus","Opção para exibir apenas cops com falsos positivos"],"ru":["Выполнение скрипта триажа для поиска основных копов, требующих исправления","Поддержка фильтрации по отделам","Оптимизация производительности с помощью Rust","Интеграция с gh run download для получения результатов корпуса","Вариант отображения только копов с ложными срабатываниями"],"ar":["تشغيل نص برمجي لترياج لإيجاد أهم الشروط التي يجب تصحيحها","دعم التصفية حسب الإدارة","تحسين الأداء باستخدام Rust","التكامل مع gh run download للحصول على نتائج الكوربس","خيار عرض الشروط فقط مع الإيجابيات الكاذبة"]},"keywords":{"en":["how to use triage","what is triage","triage alternative","triage vs rubocop","triage install","triage setup guide","rubocop rewrite in rust","ruby code optimization"],"zh":["Triage","RuboCop","Rust","AI 工具","代码检查","代码修复","自动化","命令行参数","false positive"],"ja":["Triage","RuboCop","Rust","AI エージェント","コードのチェック","コードの修正","自動化","コマンドラインパラメータ","false positive"],"ko":["Triage","RuboCop","Rust","AI 도구","코드 점검","코드 수정","자동화","명령줄 매개변수","false positive"],"es":["triage","RuboCop","Rust","optimización de rendimiento","herramientas de desarrollo","agentes de IA","Herramientas de desarrollo de Ruby","Mejora de la configuración de RuboCop"],"fr":["triage","RuboCop","Rust","optimisation des performances","outils de développement","agents IA","Outils de développement Ruby","Amélioration de la configuration de RuboCop"],"de":["triage","RuboCop","Rust","Leistungsoptimierung","Entwicklungstools","KI-Agents","Ruby-Entwicklungstools","Verbesserung der RuboCop-Konfiguration"],"pt":["Triage","RuboCop","Rust","Otimização de projetos Ruby","Ferramentas de desenvolvimento","Desenvolvimento de software","Programação em Ruby","Melhorias de desempenho"],"ru":["Triage","RuboCop","Rust","Оптимизация проектов Ruby","Инструменты разработки","Разработка программного обеспечения","Программирование на Ruby","Улучшения производительности"],"ar":["Triage","RuboCop","Rust","تحسين مشاريع Ruby","أدوات تطوير","تطوير البرمجيات","برمجة Ruby","تحسين الأداء"]}},"owner":"6","repo":"nitrocop","repoPath":"6/nitrocop","stars":1,"forks":0,"updatedAt":"2026-02-26T02:57:19Z","topics":["rubocop","ruby","rust"],"category":"community","skillMd":{"name":"triage","description":"Rank cops by FP+FN from the corpus oracle to find the next batch to fix","bodyPreview":"Run the triage script to find the top cops to fix:\n\n```bash\npython3 .claude/skills/triage/scripts/triage.py $ARGUMENTS\n```\n\nIf no `--input` is provided, it auto-downloads the latest `corpus-results.json` from CI via `gh run download`.\n\nCommon invocations:\n- `/triage` — top 30 cops by divergence\n- `/triage --limit 50` — show more\n- `/triage --department RSpec` — filter to one department\n- `/triage --exclude-department Layout` — skip complex layout cops\n- `/triage --fp-only` — only cops with false","body":"Run the triage script to find the top cops to fix:\n\n```bash\npython3 .claude/skills/triage/scripts/triage.py $ARGUMENTS\n```\n\nIf no `--input` is provided, it auto-downloads the latest `corpus-results.json` from CI via `gh run download`.\n\nCommon invocations:\n- `/triage` — top 30 cops by divergence\n- `/triage --limit 50` — show more\n- `/triage --department RSpec` — filter to one department\n- `/triage --exclude-department Layout` — skip complex layout cops\n- `/triage --fp-only` — only cops with false positives\n- `/triage --input /tmp/corpus-report/corpus-results.json` — use local file\n\nAfter identifying targets, use `investigate-cop.py` to see all FP/FN locations with source context:\n\n```bash\npython3 scripts/investigate-cop.py Department/CopName --context --fp-only\n```\n\nThen read the cop source in `src/cop/<dept>/<cop>.rs` and the vendor spec at `vendor/rubocop*/spec/` to understand the root cause before fixing.\n\nThis skill is read-only. Parallel-agent activity may leave unrelated local modifications in the working tree; do not edit or revert them while triaging.\nIf triage transitions into code edits, switch to a dedicated git worktree before making changes, then use a fix skill workflow that integrates retained progress back into `main` before ending the run.\n"},"lastSynced":"2026-03-06T13:08:24.817Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Optimization Agents needing advanced Ruby code analysis capabilities via RuboCop and Rust","zh":"非常适合需要高级Ruby代码分析能力的代码优化代理，通过RuboCop和Rust实现","ja":"コード最適化エージェントが高度なRubyコード分析機能を必要とする場合に最適で、RuboCopとRustを使用する","ko":"고급 Ruby 코드 분석 기능이 필요한 코드 최적화 에이전트에게 적합하며, RuboCop와 Rust를 통해 제공됩니다","es":"Perfecto para agentes de optimización de código que necesitan capacidades de análisis de código Ruby avanzadas a través de RuboCop y Rust","fr":"Parfait pour les agents d''optimisation de code nécessitant des capacités d''analyse de code Ruby avancées via RuboCop et Rust","de":"Perfekt für Code-Optimierungsagenten, die erweiterte Ruby-Code-Analysefunktionen über RuboCop und Rust benötigen","pt":"Perfeito para Agentes de Otimização de Código que necessitam de capacidades avançadas de análise de código Ruby via RuboCop e Rust","ru":"Идеально подходит для агентов оптимизации кода, которым необходимы расширенные возможности анализа кода Ruby через RuboCop и Rust","ar":"مثالي للوكلاء تحسين الكود الذين يحتاجون إلى возможности متقدمة لتحليل رمز روبي عبر RuboCop و Rust"},"recommendation":{"en":"Empowers agents to identify and prioritize top cops to fix using Python scripts and JSON data, providing advanced filtering capabilities via arguments like --department and --exclude-department, and leveraging gh run download for corpus-results.json","zh":"赋予代理识别和优先修复最重要的cops的能力，使用Python脚本和JSON数据，通过参数如--department和--exclude-department提供高级过滤功能，并利用gh run download下载corpus-results.json","ja":"PythonスクリプトとJSONデータを使用して、最も重要なcopsを識別して優先的に修正するエージェントの能力を提供し、--departmentや--exclude-departmentなどの引数を使用した高度なフィルタリング機能を提供し、gh run downloadを使用してcorpus-results.jsonをダウンロードする","ko":"에이전트가 가장 중요한 cops를 식별하고 우선순위를 지정하여 수정할 수 있는 능력을 제공하며, Python 스크립트와 JSON 데이터를 사용하여 --department 및 --exclude-department와 같은 인수를 사용한 고급 필터링 기능을 제공하고, gh run download를 사용하여 corpus-results.json을 다운로드합니다","es":"Habilita a los agentes a identificar y priorizar a los principales policías para arreglarlos usando scripts de Python y datos JSON, proporcionando capacidades de filtrado avanzadas a través de argumentos como --department y --exclude-department, y aprovechando gh run download para corpus-results.json","fr":"Permet aux agents d''identifier et de prioriser les principaux policiers à corriger en utilisant des scripts Python et des données JSON, en fournissant des capacités de filtrage avancées via des arguments tels que --department et --exclude-department, et en exploitant gh run download pour corpus-results.json","de":"Ermächtigt die Agenten, die wichtigsten Polizisten zu identifizieren und zu priorisieren, um sie mit Python-Skripten und JSON-Daten zu beheben, wodurch erweiterte Filterfunktionen über Argumente wie --department und --exclude-department bereitgestellt werden und gh run download für corpus-results.json genutzt wird","pt":"Habilita os agentes a identificar e priorizar os principais problemas a serem corrigidos usando scripts Python e dados JSON, fornecendo capacidades de filtragem avançadas via argumentos como --department e --exclude-department, e aproveitando gh run download para corpus-results.json","ru":"Позволяет агентам выявлять и расставлять приоритеты для исправления наиболее важных проблем с помощью скриптов Python и данных JSON, обеспечивая расширенные возможности фильтрации через аргументы типа --department и --exclude-department, и использует gh run download для corpus-results.json","ar":"تمكن الوكلاء من تحديد وترتيب الأولويات لأهم المشاكل التي يجب исправاها باستخدام نصوص Python وبيانات JSON، وتوفر khảیات مرشحة متقدمة من خلال الحجج مثل --department و --exclude-department، وتستفيد من تنفيذ gh لتنزيل corpus-results.json"},"useCases":{"en":["Automating Ruby code optimization by identifying top cops to fix","Filtering cops by department using --department argument","Excluding complex layout cops using --exclude-department"],"zh":["通过识别需要修复的最重要的cops来自动化Ruby代码优化","使用--department参数按部门过滤cops","使用--exclude-department参数排除复杂布局的cops"],"ja":["最も重要なcopsを識別して修正することでRubyコードの最適化を自動化する","--department引数を使用してcopsを部門別にフィルタリングする","--exclude-department引数を使用して複雑なレイアウトのcopsを除外する"],"ko":["가장 중요한 cops를 식별하여 수정함으로써 Ruby 코드 최적화를 자동화하는 것","--department 인수를 사용하여 cops를 부서별로 필터링하는 것","--exclude-department 인수를 사용하여 복잡한 레이아웃의 cops를 제외하는 것"],"es":["Automatizar la optimización del código Ruby identificando a los principales policías para arreglar","Filtrar policías por departamento utilizando el argumento --department","Excluir policías de diseño complejo utilizando el argumento --exclude-department"],"fr":["Automatiser l''optimisation du code Ruby en identifiant les principaux policiers à corriger","Filtrer les policiers par département en utilisant l''argument --department","Exclure les policiers de disposition complexe en utilisant l''argument --exclude-department"],"de":["Automatisierung der Ruby-Code-Optimierung durch Identifizierung der wichtigsten Polizisten zur Behebung","Filtern von Polizisten nach Abteilung unter Verwendung des Arguments --department","Ausschluss von Polizisten mit komplexer Layout unter Verwendung des Arguments --exclude-department"],"pt":["Automatizar a otimização de código Ruby identificando os principais problemas a serem corrigidos","Filtrar os problemas por departamento usando o argumento --department","Excluir problemas de layout complexos usando o argumento --exclude-department"],"ru":["Автоматизировать оптимизацию кода Ruby, выявляя наиболее важные проблемы для исправления","Фильтровать проблемы по отделам с помощью аргумента --department","Исключать сложные проблемы компоновки с помощью аргумента --exclude-department"],"ar":["تأتمتة تحسين رمز روبي عن طريق تحديد أهم المشاكل التي يجب исправاها","ترشيح المشاكل حسب الإدارة باستخدام الحجة --department","استبعاد مشاكل التخطيط المعقدة باستخدام الحجة --exclude-department"]},"limitations":{"en":["Requires Python 3 to run triage.py script","Limited to Ruby developers using RuboCop","Needs gh run download for auto-downloading corpus-results.json"],"zh":["需要Python 3来运行triage.py脚本","仅限于使用RuboCop的Ruby开发人员","需要gh run download来自动下载corpus-results.json"],"ja":["triage.pyスクリプトを実行するためにPython 3が必要","RuboCopを使用するRuby開発者に限定される","corpus-results.jsonを自動ダウンロードするためにgh run downloadが必要"],"ko":["triage.py 스크립트를 실행하기 위해 Python 3가 필요함","RuboCop을 사용하는 Ruby 개발자에게만 한정됨","corpus-results.json을 자동으로 다운로드하기 위해 gh run download가 필요함"],"es":["Requiere Python 3 para ejecutar el script triage.py","Limitado a los desarrolladores de Ruby que utilizan RuboCop","Necesita gh run download para la descarga automática de corpus-results.json"],"fr":["Nécessite Python 3 pour exécuter le script triage.py","Limité aux développeurs Ruby utilisant RuboCop","Nécessite gh run download pour le téléchargement automatique de corpus-results.json"],"de":["Benötigt Python 3, um das Skript triage.py auszuführen","Begrenzt auf Ruby-Entwickler, die RuboCop verwenden","Benötigt gh run download für das automatische Herunterladen von corpus-results.json"],"pt":["Requer Python 3 para executar o script triage.py","Limitado a desenvolvedores Ruby que usam RuboCop","Necessita gh run download para baixar automaticamente corpus-results.json"],"ru":["Требует Python 3 для запуска скрипта triage.py","Ограничен разработчиками Ruby, использующими RuboCop","Требует gh run download для автоматического скачивания corpus-results.json"],"ar":["يتطلب Python 3 لتشغيل نص triage.py","محدود لمطوري روبي الذين يستخدمون RuboCop","يحتاج إلى تنفيذ gh لتنزيل corpus-results.json تلقائيًا"]},"version":4},"contentHash":"b5b9f4ed4b95d0fbc22b000ad3ecf628efb253345d9ac98202faf929e3048671","qualityScore":33}');
