INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('6/nitrocop/triage', 'triage', '6', 'nitrocop', 'community', 'triage 6 nitrocop community rubocop ruby rust The triage skill is an experimental RuboCop rewrite in Rust, helping developers identify top cops to fix. It benefits Ruby developers looking to optimize their code. Triage 是一个实验性的 RuboCop 重写版本，使用 Rust 编写。它可以帮助您找出需要修复的顶级 cops。 Triage は、Rust で書き直された RuboCop の実験的なバージョンです。修正する必要があるトップレベルの cops を見つけるのに役立ちます。 Triage는 Rust로 다시 작성된 RuboCop의 실험 버전입니다. 수정해야 할 최고의 cops를 찾는 데 도움이 됩니다. Triage es una herramienta experimental que reescribe RuboCop en Rust para optimizar su funcionamiento Triage est un outil expérimental qui réécrit RuboCop en Rust pour optimiser ses performances Triage ist ein experimentelles Tool, das RuboCop in Rust neu schreibt, um dessen Funktionsweise zu optimieren O Triage é uma reimplementação experimental do RuboCop em Rust, permitindo a otimização de projetos Ruby. Triage - это экспериментальная реализация RuboCop на Rust, позволяющая оптимизировать проекты Ruby. Triage هو إعادة تنفيذ تجريبية ل RuboCop باستخدام Rust، مما يسمح بتحسين مشاريع Ruby. how to use triage what is triage triage alternative triage vs rubocop triage install triage setup guide rubocop rewrite in rust ruby code optimization Triage RuboCop Rust AI 工具 代码检查 代码修复 自动化 命令行参数 false positive Runs triage scripts using Python 3 and the `triage.py` command Auto-downloads the latest `corpus-results.json` from CI via `gh run download` Supports filtering by department using the `--department` flag Allows excluding departments using the `--exclude-department` flag Can show only cops with false positives using the `--fp-only` flag Triage is an experimental RuboCop rewrite in Rust, used to find and fix top cops by divergence in Ruby codebases.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lorenzovenice/nanoclaw-venice/pdf-reader', 'community', 'lorenzovenice', 'nanoclaw-venice', 'lorenzovenice/nanoclaw-venice', 'pdf-reader', 13, 4, 33, '2026-03-07T19:06:22Z', '2026-03-08T01:59:12.572Z', '0046569626c967941f095c38b030951a7fc0523a3c66070f72229c39d93867f9', '{"id":"lorenzovenice/nanoclaw-venice/pdf-reader","name":"pdf-reader","description":{"en":"The pdf-reader skill is a command-line tool that enables developers to extract text and metadata from PDF files. It supports features like layout preservation and remote PDF fetching.","zh":"pdf-reader是基于Venice AI的个人AI助手，支持WhatsApp和Telegram。它可以提取PDF文本和元数据。","ja":"pdf-readerはVenice AIに基づいたパーソナルAIアシスタントで、WhatsAppとTelegramをサポートします。PDFのテキストとメタデータを抽出できます。","ko":"pdf-reader는 Venice AI 기반의 개인 AI 보조도구로 WhatsApp와 Telegram을 지원합니다. PDF 텍스트와 메타데이터를 추출할 수 있습니다.","es":"pdf-reader es una herramienta de línea de comandos para extraer texto de archivos PDF con opciones para preservar el diseño y extraer metadatos","fr":"pdf-reader est un outil en ligne de commande pour extraire du texte à partir de fichiers PDF avec des options pour préserver la mise en page et extraire des métadonnées","de":"pdf-reader ist ein Kommandozeilen-Tool zum Extrahieren von Text aus PDF-Dateien mit Optionen zum Erhalt des Layouts und zum Extrahieren von Metadaten","pt":"O pdf-reader é uma ferramenta de linha de comando que permite extrair texto de PDFs com facilidade. Com suporte a layout e metadados.","ru":"Pdf-reader — это консольный инструмент, который позволяет извлекать текст из PDF с поддержкой макета и метаданных с помощью ИИ Агентов.","ar":"pdf-reader هو أداة سطر أوامر تمكنك من استخراج النص من ملفات PDF بسهولة. تدعم Layout والميتادات"},"seo":{"title":{"en":"pdf-reader: Extract Text and Metadata with Ease | AI Agen...","zh":"PDF阅读器_setup指南","ja":"PDFリーダー_Best Practices","ko":"PDF 리더기_Setup 가이드","es":"Guía de configuración de pdf-reader para desarrolladores","fr":"Guide d''installation de pdf-reader pour les développeurs","de":"Einrichtungsanleitung für pdf-reader-Entwickler","pt":"Guia de Configuração do pdf-reader: Extraia Texto de PDFs...","ru":"Настройка pdf-reader: Извлечение Текста из PDF с ИИ Агентами","ar":"دليل إعداد pdf-reader: استخراج النص من ملفات PDF بسهولة"},"description":{"en":"Unlock the power of pdf-reader! Discover how to extract text, preserve layouts, and fetch PDFs with ease. Get started now and streamline your workflow!","zh":"使用NanoClaw（Venice API）实现PDF文本提取和元数据显示","ja":"NanoClaw（Venice API）を使用してPDFのテキスト抽出とメタデータ表示を行う","ko":"NanoClaw（Venice API）를 사용하여 PDF 텍스트 추출 및 메타데이터 표시","es":"Aprende a utilizar pdf-reader para extraer texto de archivos PDF de manera efectiva","fr":"Découvrez comment utiliser pdf-reader pour extraire du texte à partir de fichiers PDF","de":"Erfahren Sie, wie Sie pdf-reader verwenden, um Text aus PDF-Dateien zu extrahieren","pt":"Aprenda a usar o pdf-reader para extrair texto de PDFs com facilidade. Veja como configurar e utilizar essa ferramenta de forma eficaz.","ru":"Узнайте, как использовать pdf-reader для извлечения текста из PDF. Посмотрите, как настроить и использовать этот инструмент эффективно с ИИ Агентами.","ar":"تعرف على كيفية استخدام pdf-reader لاستخراج النص من ملفات PDF بسهولة. شاهد كيفية تعيين وتشغيل هذه الأداة بفعالية"},"definition":{"en":"pdf-reader is a personal AI assistant skill that allows users to extract text, metadata, and preserve layouts from PDF files using commands like extract, fetch, and info.","zh":"pdf-reader是一种AI工具，用于提取PDF文本和元数据","ja":"pdf-readerは、PDFのテキストとメタデータを抽出するAIエージェントです","ko":"pdf-reader는 PDF 텍스트와 메타데이터를 추출하는 AI 도구입니다","es":"pdf-reader es una herramienta de lectura de PDF que utiliza la línea de comandos para extraer texto y metadatos","fr":"pdf-reader est un outil de lecture de PDF qui utilise la ligne de commande pour extraire du texte et des métadonnées","de":"pdf-reader ist ein PDF-Lese-Tool, das die Kommandozeile verwendet, um Text und Metadaten zu extrahieren","pt":"O pdf-reader é uma ferramenta de extração de texto de PDF que utiliza linha de comando para processar arquivos PDF.","ru":"Pdf-reader — это инструмент для извлечения текста из PDF, который использует командную строку для обработки файлов PDF с помощью ИИ Агентов.","ar":"pdf-reader هو أداة لاستخراج النص من ملفات PDF التي تستخدم سطر الأوامر لمعالجة ملفات PDF"},"features":{"en":["Extract text from PDF files using the extract command","Preserve tables and columns with the --layout option","Fetch and extract PDFs from remote URLs using the fetch command","Display metadata and size information with the info command","List all PDFs in the directory tree using the list command"],"zh":["支持PDF文本提取","支持元数据显示","支持WhatsApp和Telegram","提供命令行接口（CLI）","支持PDF布局保留","支持远程PDF下载和提取"],"ja":["PDFのテキスト抽出をサポート","メタデータ表示をサポート","WhatsAppとTelegramをサポート","コマンドラインインターフェース（CLI）を提供","PDFのレイアウト保留をサポート","リモートPDFのダウンロードと抽出をサポート"],"ko":["PDF 텍스트 추출을 지원","메타데이터 표시를 지원","WhatsApp와 Telegram을 지원","명령줄 인터페이스（CLI）를 제공","PDF 레이아웃 보존을 지원","원격 PDF 다운로드 및 추출을 지원"],"es":["Extracción de texto de archivos PDF","Opción para preservar el diseño de tablas y columnas","Descarga y extracción de archivos PDF desde URLs","Visualización de metadatos y tamaño de archivos PDF","Listado de todos los archivos PDF en el directorio actual"],"fr":["Extraction de texte à partir de fichiers PDF","Option pour préserver la mise en page des tableaux et des colonnes","Téléchargement et extraction de fichiers PDF à partir d''URL","Affichage des métadonnées et de la taille des fichiers PDF","Liste de tous les fichiers PDF dans le répertoire courant"],"de":["Extraktion von Text aus PDF-Dateien","Option zum Erhalt des Layouts von Tabellen und Spalten","Herunterladen und Extrahieren von PDF-Dateien von URLs","Anzeige von Metadaten und Größe von PDF-Dateien","Auflistung aller PDF-Dateien im aktuellen Verzeichnis"],"pt":["Extraia texto de PDFs com facilidade","Suporte a layout para preservar tabelas e colunas","Exiba metadados e tamanho do arquivo","Baixe e extraia texto de PDFs da internet","Liste todos os PDFs em uma árvore de diretórios"],"ru":["Извлекайте текст из PDF с легкостью","Поддержка макета для сохранения таблиц и столбцов","Отображайте метаданные и размер файла","Скачивайте и извлекайте текст из PDF из интернета","Список всех PDF в дереве каталогов с помощью ИИ Агентов"],"ar":["استخرج النص من ملفات PDF بسهولة","دعم Layout لحفظ الجداول والأعمدة","عرض الميتادات وحجم الملف"," تحميل واستخراج النص من ملفات PDF من الانترنت","قائمة جميع ملفات PDF في شجرة الدلائل"]},"keywords":{"en":["how to use pdf-reader","pdf-reader setup guide","pdf-reader alternative","pdf-reader vs NanoClaw","extract text from pdf","pdf-reader install","what is pdf-reader","pdf-reader commands","pdf-reader metadata extraction"],"zh":["pdf阅读器","AI工具","PDF文本提取","元数据显示","WhatsApp","Telegram","命令行接口","PDF布局保留"],"ja":["PDFリーダー","AIエージェント","PDFのテキスト抽出","メタデータ表示","WhatsApp","Telegram","コマンドラインインターフェース","PDFのレイアウト保留"],"ko":["PDF 리더기","AI 도구","PDF 텍스트 추출","메타데이터 표시","WhatsApp","Telegram","명령줄 인터페이스","PDF 레이아웃 보존"],"es":["pdf-reader","herramienta de lectura de PDF","extracción de texto de PDF","preservar diseño de tablas","descarga de PDF desde URL","metadatos de PDF","lista de archivos PDF","CLI para PDF","nanoClaw","Venice API"],"fr":["pdf-reader","outil de lecture de PDF","extraction de texte à partir de PDF","préserver la mise en page des tableaux","téléchargement de PDF depuis URL","métadonnées de PDF","liste de fichiers PDF","CLI pour PDF","nanoClaw","Venice API"],"de":["pdf-reader","PDF-Lese-Tool","Extraktion von Text aus PDF","Erhalt des Layouts von Tabellen","Herunterladen von PDF von URL","Metadaten von PDF","Auflistung von PDF-Dateien","CLI für PDF","nanoClaw","Venice API"],"pt":["pdf-reader","extração de texto de PDF","ferramenta de linha de comando","suporte a layout","metadados de PDF","baixar PDF","listar PDFs","ferramentas de desenvolvedor","processamento de PDF"],"ru":["pdf-reader","извлечение текста из PDF","консольный инструмент","поддержка макета","метаданные PDF","скачать PDF","список PDF","инструменты разработчика","обработка PDF с ИИ Агентами"],"ar":["pdf-reader","استخراج النص من ملفات PDF","أداة سطر الأوامر","دعم Layout","ميتادات PDF","تحميل ملفات PDF","قائمة ملفات PDF","أدوات المطور","معالجة ملفات PDF"]}},"owner":"lorenzovenice","repo":"nanoclaw-venice","repoPath":"lorenzovenice/nanoclaw-venice","stars":13,"forks":4,"updatedAt":"2026-03-07T19:06:22Z","topics":[],"category":"community","skillMd":{"name":"pdf-reader","description":"Read and extract text from PDF files — documents, reports, contracts, spreadsheets. Use whenever you need to read PDF content, not just when explicitly asked. Handles local files, URLs, and WhatsApp attachments.","bodyPreview":"# PDF Reader\n\n## Quick start\n\n```bash\npdf-reader extract report.pdf              # Extract all text\npdf-reader extract report.pdf --layout     # Preserve tables/columns\npdf-reader fetch https://example.com/doc.pdf  # Download and extract\npdf-reader info report.pdf                 # Show metadata + size\npdf-reader list                            # List all PDFs in directory tree\n```\n\n## Commands\n\n### extract — Extract text from PDF\n\n```bash\npdf-reader extract <file>                        # Full","body":"# PDF Reader\n\n## Quick start\n\n```bash\npdf-reader extract report.pdf              # Extract all text\npdf-reader extract report.pdf --layout     # Preserve tables/columns\npdf-reader fetch https://example.com/doc.pdf  # Download and extract\npdf-reader info report.pdf                 # Show metadata + size\npdf-reader list                            # List all PDFs in directory tree\n```\n\n## Commands\n\n### extract — Extract text from PDF\n\n```bash\npdf-reader extract <file>                        # Full text to stdout\npdf-reader extract <file> --layout               # Preserve layout (tables, columns)\npdf-reader extract <file> --pages 1-5            # Pages 1 through 5\npdf-reader extract <file> --pages 3-3            # Single page (page 3)\npdf-reader extract <file> --layout --pages 2-10  # Layout + page range\n```\n\nOptions:\n- `--layout` — Maintains spatial positioning. Essential for tables, spreadsheets, multi-column docs.\n- `--pages N-M` — Extract only pages N through M (1-based, inclusive).\n\n### fetch — Download and extract PDF from URL\n\n```bash\npdf-reader fetch <url>                    # Download, verify, extract with layout\npdf-reader fetch <url> report.pdf         # Also save a local copy\n```\n\nDownloads the PDF, verifies it has a valid `%PDF` header, then extracts text with layout preservation. Temporary files are cleaned up automatically.\n\n### info — PDF metadata and file size\n\n```bash\npdf-reader info <file>\n```\n\nShows title, author, page count, page size, PDF version, and file size on disk.\n\n### list — Find all PDFs in directory tree\n\n```bash\npdf-reader list\n```\n\nRecursively lists all `.pdf` files with page count and file size.\n\n## WhatsApp PDF attachments\n\nWhen a user sends a PDF on WhatsApp, it is automatically saved to the `attachments/` directory. The message will include a path hint like:\n\n> [PDF attached: attachments/document.pdf]\n\nTo read the attached PDF:\n\n```bash\npdf-reader extract attachments/document.pdf --layout\n```\n\n## Example workflows\n\n### Read a contract and summarize key terms\n\n```bash\npdf-reader info attachments/contract.pdf\npdf-reader extract attachments/contract.pdf --layout\n```\n\n### Extract specific pages from a long report\n\n```bash\npdf-reader info report.pdf                    # Check total pages\npdf-reader extract report.pdf --pages 1-3     # Executive summary\npdf-reader extract report.pdf --pages 15-20   # Financial tables\n```\n\n### Fetch and analyze a public document\n\n```bash\npdf-reader fetch https://example.com/annual-report.pdf report.pdf\npdf-reader info report.pdf\n```\n"},"lastSynced":"2026-03-08T01:59:12.572Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing advanced PDF text extraction and metadata analysis capabilities.","zh":"适合需要高级PDF文本提取和元数据分析能力的文档分析代理。","ja":"PDF文書の分析エージェントが高度なPDFテキスト抽出とメタデータ分析機能を必要とする場合に適しています。","ko":"문서 분석 에이전트가 고급 PDF 텍스트 추출 및 메타데이터 분석 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Análisis de Documentos que necesitan capacidades avanzadas de extracción de texto y análisis de metadatos de PDF.","fr":"Parfait pour les Agents d''analyse de documents nécessitant des capacités avancées d''extraction de texte et d''analyse de métadonnées de PDF.","de":"Perfekt für Dokumentenanalyse-Agenten, die erweiterte PDF-Textextraktions- und Metadatenanalysefunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que necessitam de capacidades avançadas de extração de texto e análise de metadados em PDF.","ru":"Идеально подходит для агентов анализа документов, требующих передовых возможностей извлечения текста и анализа метаданных в формате PDF.","ar":"مثالي لعمليات تحليل الوثائق التي تحتاج إلى إمكانيات متقدمة لاستخراج النص وتحليل البيانات الوصفية لملفات PDF."},"recommendation":{"en":"Empowers agents to extract text and metadata from PDF files using layout preservation and remote PDF fetching, supporting features like tables and columns extraction via command-line interface.","zh":"赋予代理从PDF文件中提取文本和元数据的能力，使用布局保留和远程PDF获取，支持通过命令行接口的表格和列抽取等功能。","ja":"レイアウトの保留とリモートPDF取得を使用して、PDFファイルからテキストとメタデータを抽出するエージェントを可能にし、コマンドラインインターフェースを介したテーブルと列の抽出などの機能をサポートします。","ko":"레이아웃 보존 및 원격 PDF 가져오기를 사용하여 PDF 파일에서 텍스트 및 메타데이터를 추출하는 에이전트를 가능하게 하며, 명령줄 인터페이스를 통해 표 및 열 추출 등의 기능을 지원합니다.","es":"Habilita a los agentes a extraer texto y metadatos de archivos PDF utilizando la preservación del diseño y la recuperación remota de PDF, con características como la extracción de tablas y columnas a través de la interfaz de línea de comandos.","fr":"Permet aux agents d''extraire du texte et des métadonnées à partir de fichiers PDF en utilisant la préservation de la disposition et la récupération à distance de PDF, avec des fonctionnalités telles que l''extraction de tableaux et de colonnes via l''interface en ligne de commande.","de":"Ermächtigt Agenten, Text und Metadaten aus PDF-Dateien zu extrahieren, indem sie die Layouterhaltung und die Remote-PDF-Abruf verwenden, mit Funktionen wie der Extraktion von Tabellen und Spalten über die Kommandozeilenoberfläche.","pt":"Habilita os agentes a extrair texto e metadados de arquivos PDF usando preservação de layout e busca remota de PDF, com suporte a recursos como extração de tabelas e colunas via interface de linha de comando.","ru":"Наделяет агентов возможностью извлекать текст и метаданные из файлов PDF, используя сохранение макета и удаленную загрузку PDF, поддерживая функции, такие как извлечение таблиц и столбцов через командную строку.","ar":"يمنح العوامل القدرة على استخراج النص والبيانات الوصفية من ملفات PDF باستخدام الحفاظ على التصميم والاسترجاع البعدي لملفات PDF، مع دعم الميزات مثل استخراج الجداول والأعمدة عبر واجهة سطر الأوامر."},"useCases":{"en":["Extracting text from PDF reports while preserving layout","Fetching and analyzing remote PDF documents","Retrieving metadata and size information of PDF files"],"zh":["提取保留布局的PDF报告中的文本","获取和分析远程PDF文档","检索PDF文件的元数据和大小信息"],"ja":["レイアウトを保ったPDFレポートからテキストを抽出","リモートPDF文書を取得して分析","PDFファイルのメタデータとサイズ情報を取得"],"ko":["레이아웃을 보존한 PDF 보고서에서 텍스트 추출","원격 PDF 문서 가져오기 및 분석","PDF 파일의 메타데이터 및 크기 정보 가져오기"],"es":["Extraer texto de informes PDF mientras se conserva el diseño","Recuperar y analizar documentos PDF remotos","Recuperar información de metadatos y tamaño de archivos PDF"],"fr":["Extraire du texte à partir de rapports PDF tout en préservant la disposition","Récupérer et analyser des documents PDF à distance","Récupérer des informations de métadonnées et de taille de fichiers PDF"],"de":["Text aus PDF-Berichten extrahieren, während das Layout erhalten bleibt","Remote-PDF-Dokumente abrufen und analysieren","Metadaten- und Größeninformationen von PDF-Dateien abrufen"],"pt":["Extrair texto de relatórios PDF preservando o layout","Buscar e analisar documentos PDF remotos","Recuperar informações de metadados e tamanho de arquivos PDF"],"ru":["Извлечение текста из отчетов PDF с сохранением макета","Получение и анализ удаленных документов PDF","Получение информации о метаданных и размере файлов PDF"],"ar":["استخراج النص من تقارير PDF مع الحفاظ على التصميم","استرجاع وتحليل وثائق PDF عن بعد","استرجاع معلومات البيانات الوصفية وحجم ملفات PDF"]},"limitations":{"en":["Requires command-line interface access","Limited to PDF file format"],"zh":["需要命令行接口访问","仅限PDF文件格式"],"ja":["コマンドラインインターフェースへのアクセスが必要","PDFファイル形式のみ"],"ko":["명령줄 인터페이스 액세스가 필요","PDF 파일 형식만"],"es":["Requiere acceso a la interfaz de línea de comandos","Limitado al formato de archivo PDF"],"fr":["Nécessite un accès à l''interface en ligne de commande","Limité au format de fichier PDF"],"de":["Benötigt Zugriff auf die Kommandozeilenoberfläche","Begrenzt auf das PDF-Dateiformat"],"pt":["Requer acesso à interface de linha de comando","Limitado ao formato de arquivo PDF"],"ru":["Требует доступа к командной строке","Ограничен форматом файла PDF"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر","محدود بتنسيق ملف PDF"]},"version":4},"contentHash":"0046569626c967941f095c38b030951a7fc0523a3c66070f72229c39d93867f9","qualityScore":33}');
