INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lorenzovenice/nanoclaw-venice/pdf-reader', 'pdf-reader', 'lorenzovenice', 'nanoclaw-venice', 'community', 'pdf-reader lorenzovenice nanoclaw-venice community The pdf-reader skill is a command-line tool that enables developers to extract text and metadata from PDF files. It supports features like layout preservation and remote PDF fetching. pdf-reader是基于Venice AI的个人AI助手，支持WhatsApp和Telegram。它可以提取PDF文本和元数据。 pdf-readerはVenice AIに基づいたパーソナルAIアシスタントで、WhatsAppとTelegramをサポートします。PDFのテキストとメタデータを抽出できます。 pdf-reader는 Venice AI 기반의 개인 AI 보조도구로 WhatsApp와 Telegram을 지원합니다. PDF 텍스트와 메타데이터를 추출할 수 있습니다. pdf-reader es una herramienta de línea de comandos para extraer texto de archivos PDF con opciones para preservar el diseño y extraer metadatos pdf-reader est un outil en ligne de commande pour extraire du texte à partir de fichiers PDF avec des options pour préserver la mise en page et extraire des métadonnées pdf-reader ist ein Kommandozeilen-Tool zum Extrahieren von Text aus PDF-Dateien mit Optionen zum Erhalt des Layouts und zum Extrahieren von Metadaten O pdf-reader é uma ferramenta de linha de comando que permite extrair texto de PDFs com facilidade. Com suporte a layout e metadados. Pdf-reader — это консольный инструмент, который позволяет извлекать текст из PDF с поддержкой макета и метаданных с помощью ИИ Агентов. pdf-reader هو أداة سطر أوامر تمكنك من استخراج النص من ملفات PDF بسهولة. تدعم Layout والميتادات how to use pdf-reader pdf-reader setup guide pdf-reader alternative pdf-reader vs NanoClaw extract text from pdf pdf-reader install what is pdf-reader pdf-reader commands pdf-reader metadata extraction pdf阅读器 AI工具 PDF文本提取 元数据显示 WhatsApp Telegram 命令行接口 PDF布局保留 Extract text from PDF files using the extract command Preserve tables and columns with the --layout option Fetch and extract PDFs from remote URLs using the fetch command Display metadata and size information with the info command List all PDFs in the directory tree using the list command pdf-reader is a personal AI assistant skill that allows users to extract text, metadata, and preserve layouts from PDF files using commands like extract, fetch, and info.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('udecode/dotai/pr', 'community', 'udecode', 'dotai', 'udecode/dotai', 'pr', 0, 0, 33, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:08.744Z', 'b3e99f829bcd4a08ea6bcf4c8c9156d77acc1017e6e5efeec01ec132410dc007', '{"id":"udecode/dotai/pr","name":"pr","description":{"en":"The pr skill is a context manager for all agents, providing expert Git and GitHub workflow automation. It benefits developers by streamlining PR creation, drafting, and review processes.","zh":"PR技能是GitHub工作流自动化的上下文管理器，支持创建、草稿和审查PR等操作","ja":"PRスキルはGitHubワークフローの自動化を実現するコンテキストマネージャーです","ko":"PR_스킬은_GitHub_워크플로_자동화를_위한_컨텍스트_매니저입니다","es":"El agente PR es un administrador de contexto para todos los agentes, que automatiza el flujo de trabajo de Git y GitHub con operaciones de creación, borrador y revisión de solicitudes de extracción","fr":"L''agent PR est un gestionnaire de contexte pour tous les agents, qui automatise le workflow Git et GitHub avec des opérations de création, de brouillon et de révision de demandes d''extraction","de":"Der PR-Agent ist ein Kontext-Manager für alle Agenten, der den Git- und GitHub-Workflow mit Erstellung, Entwurf und Überprüfung von Pull-Requests automatisiert","pt":"O PR é um contexto de gerenciamento para todos os agentes, permitindo a automação de fluxo de trabalho do Git e GitHub com operações de criação, rascunho e revisão de PRs.","ru":"ИИ Агент PR является контекстным менеджером для всех агентов, позволяющим автоматизировать workflow Git и GitHub с операциями создания, черновика и обзора PR","ar":"وكيل PR هو مدير سياق لجميع الوكلاء، مما يسمح بتأتمة تدفق العمل في Git و GitHub مع عمليات إنشاء ومراجعة طلبات السحب"},"seo":{"title":{"en":"pr: GitHub Workflow Automation Setup Guide | AI Agent Skill","zh":"PR_setup_guide_for_GitHub_workflow_automation","ja":"GitHubワークフロー自動化のPRセットアップガイド","ko":"PR_설치_가이드_깃허브_워크플로_자동화","es":"Guía de configuración de PR: Automatización de flujo de t...","fr":"Guide de configuration de PR : Automatisation du workflow...","de":"PR-Setup-Leitfaden: Automatisierung des Git- und GitHub-W...","pt":"Guia de Configuração do PR: Automação de Fluxo de Trabalh...","ru":"ИИ Агент PR: Руководство по Настройке Автоматизации Workf...","ar":"دليل إعداد وكيل PR: أتمتة تدفق العمل في Git و GitHub"},"description":{"en":"Automate your GitHub workflow with pr skill - learn how to create, draft, and review PRs with ease. Get started now!","zh":"使用PR技能实现GitHub工作流自动化，包含创建、草稿和审查PR等功能，提高开发效率","ja":"PRスキルを使用してGitHubワークフローを自動化し、開発効率を向上させる","ko":"PR_스킬을_사용하여_GitHub_워크플로_자동화_개발_효율_향상","es":"Aprende a automatizar tu flujo de trabajo de Git y GitHub con PR, incluyendo operaciones de creación, borrador y revisión de solicitudes de extracción","fr":"Découvrez comment automatiser votre workflow Git et GitHub avec PR, y compris les opérations de création, de brouillon et de révision de demandes d''extraction","de":"Erfahren Sie, wie Sie Ihren Git- und GitHub-Workflow mit PR automatisieren, einschließlich Erstellung, Entwurf und Überprüfung von Pull-Requests","pt":"Aprenda a configurar o PR para automação de fluxo de trabalho do Git e GitHub, incluindo operações de criação, rascunho e revisão de PRs","ru":"Узнайте, как настроить ИИ Агент PR для автоматизации workflow Git и GitHub, включая операции создания, черновика и обзора PR","ar":"تعلم كيفية إعداد وكيل PR لتأتمة تدفق العمل في Git و GitHub، بما في ذلك عمليات إنشاء ومراجعة طلبات السحب"},"definition":{"en":"pr is a skill that automates GitHub workflow operations, including creating regular PRs, drafting WIP PRs, and reviewing code with severity ratings.","zh":"PR是GitHub工作流自动化中的一个技能，用于管理Pull Request","ja":"PRはGitHubワークフローの自動化におけるスキルで、Pull Requestを管理する","ko":"PR는_GitHub_워크플로_자동화_에서의_스킬로_Pull_Request_를_관리합니다","es":"PR es un agente que automatiza el flujo de trabajo de Git y GitHub, permitiendo la creación, revisión y administración d