INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('udecode/dotai/pr', 'pr', 'udecode', 'dotai', 'community', 'pr udecode dotai community The pr skill is a context manager for all agents, providing expert Git and GitHub workflow automation. It benefits developers by streamlining PR creation, drafting, and review processes. PR技能是GitHub工作流自动化的上下文管理器，支持创建、草稿和审查PR等操作 PRスキルはGitHubワークフローの自動化を実現するコンテキストマネージャーです PR_스킬은_GitHub_워크플로_자동화를_위한_컨텍스트_매니저입니다 El agente PR es un administrador de contexto para todos los agentes, que automatiza el flujo de trabajo de Git y GitHub con operaciones de creación, borrador y revisión de solicitudes de extracción L''agent PR est un gestionnaire de contexte pour tous les agents, qui automatise le workflow Git et GitHub avec des opérations de création, de brouillon et de révision de demandes d''extraction Der PR-Agent ist ein Kontext-Manager für alle Agenten, der den Git- und GitHub-Workflow mit Erstellung, Entwurf und Überprüfung von Pull-Requests automatisiert O PR é um contexto de gerenciamento para todos os agentes, permitindo a automação de fluxo de trabalho do Git e GitHub com operações de criação, rascunho e revisão de PRs. ИИ Агент PR является контекстным менеджером для всех агентов, позволяющим автоматизировать workflow Git и GitHub с операциями создания, черновика и обзора PR وكيل PR هو مدير سياق لجميع الوكلاء، مما يسمح بتأتمة تدفق العمل في Git و GitHub مع عمليات إنشاء ومراجعة طلبات السحب how to use pr pr alternative pr setup guide github workflow automation pr vs github cli pr install what is pr pr skill for ai agents github pr creation pr review process GitHub工作流自动化 PR管理 Pull Request Git工作流 GitHub CLI 代码分析 severity ratings AI工具 AIエージェント Creates regular PRs with comprehensive descriptions using gh pr create command Drafts WIP PRs without automatic review using gh pr create --draft flag Reviews code with severity ratings using gh pr view and gh pr diff commands Lists PRs using gh pr list command Views PR info using gh pr view command Gets diff for a specific PR using gh pr diff command pr is a skill that automates GitHub workflow operations, including creating regular PRs, drafting WIP PRs, and reviewing code with severity ratings.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('upstash/vector-js/upstash-vector-js', 'community', 'upstash', 'vector-js', 'upstash/vector-js', 'upstash-vector-js', 0, 0, 33, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:13.980Z', '5719b48049749f0bb829edce966ad3efc30054257e658a34ceb6a7c64f18e7d6', '{"id":"upstash/vector-js/upstash-vector-js","name":"upstash-vector-js","description":{"en":"The upstash-vector-js skill enables developers to interact with Upstash Vector, a high-performance vector database, for storing and querying vector embeddings. It benefits developers working with vector data.","zh":"Upstash Vector JS SDK 是一个高性能的向量数据库 SDK，用于存储、查询和管理向量嵌入","ja":"Upstash Vector JS SDK は、高性能のベクトルデータベース SDK で、ベクトル埋め込みのストレージ、クエリー、管理に使用","ko":"Upstash Vector JS SDK는 높은 성능의 벡터 데이터베이스 SDK로서, 벡터 임베딩의 저장, 조회 및 관리에 사용","es":"Upstash Vector JS SDK es un conjunto de herramientas para trabajar con vectores de embeddings de alta velocidad","fr":"Upstash Vector JS SDK est un ensemble d''outils pour travailler avec des vecteurs de embeddings haute performance","de":"Upstash Vector JS SDK ist ein Satz von Tools für die Arbeit mit Vektoren von Einbettungen mit hoher Leistung","pt":"O Upstash Vector JS SDK é uma biblioteca de alto desempenho para armazenar, consultar e gerenciar embeddings de vetores. Ele fornece uma API simples para upsert, consulta e gerenciamento de namespaces","ru":"Upstash Vector JS SDK — это высокопроизводительная библиотека для хранения, запроса и управления векторными вложениями. Она предоставляет простой API для upsert, запроса и управления namespaces, используя ИИ Агенты","ar":"Upstash Vector JS SDK هي مكتبة أداء عالية لتخزين الاستعلام وإدارة تعبئة المتجهات. توفر واجهة برمجة تطبيقات بسيطة للتعديل، الاستعلام وإدارة مساحات الأسماء باستخدام وكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"upstash-vector-js: Vector Database Setup Guide | AI Agent...","z