INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('upstash/search-js/upstash-search-js', 'upstash-search-js', 'upstash', 'search-js', 'community', 'upstash-search-js upstash search-js community The upstash-search-js skill provides an HTTP/REST based AI Search client for developers to interact with the Upstash REST API. It enables simple upsert and search operations. Upstash Search JS 是一个基于 Upstash REST API 的 HTTP/REST AI 搜索客户端，提供简单的 upsert 和搜索功能 Upstash Search JS は Upstash REST API を基盤とする HTTP/REST AI 検索クライアントです Upstash Search JS 는 Upstash REST API 를 기반으로 하는 HTTP/REST AI 검색 클라이언트입니다 upstash-search-js es un cliente de búsqueda de IA basado en HTTP/REST que permite una integración sencilla con tus aplicaciones. Instala el SDK de TypeScript con npm install @upstash/search upstash-search-js est un client de recherche d''IA basé sur HTTP/REST qui permet une intégration simple avec vos applications. Installez le SDK TypeScript avec npm install @upstash/search upstash-search-js ist ein HTTP/REST-basierter KI-Suchclient, der eine einfache Integration mit Ihren Anwendungen ermöglicht. Installieren Sie das TypeScript-SDK mit npm install @upstash/search O upstash-search-js é um cliente de busca em HTTP/REST construído em cima do Upstash REST API, permitindo buscas personalizadas. Upstash-search-js - это HTTP/REST-клиент, построенный на основе Upstash REST API, позволяющий выполнять индивидуальные поиски. upstash-search-js هو عميل بحث HTTP/REST مبني على Upstash REST API ، يسمح بالبحث المخصص. how to use upstash-search-js upstash-search-js setup guide upstash-search-js alternative upstash-search-js vs elastic search upstash-search-js install upstash-search-js REST API upstash-search-js TypeScript support upstash-search-js search client upstash-search-js upsert example Upstash Search JS AI 搜索 REST API JavaScript 库 TypeScript SDK 环境变量配置 索引管理 搜索结果管理 Installs via npm using `npm install @upstash/search` Creates a client instance with `new Search({ url, token })` Supports upsert operations with `index.upsert({ id, content })` Performs search operations with `index.search({ query })` Utilizes the Upstash REST API for search functionality Compatible with TypeScript via the `@upstash/search` SDK upstash-search-js is an HTTP/REST based AI Search client built on top of the Upstash REST API, allowing developers to perform search and upsert operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('imansmallapple/app-StrayPet/arkts-coding-standard', 'community', 'imansmallapple', 'app-StrayPet', 'imansmallapple/app-StrayPet', 'arkts-coding-standard', 0, 0, 33, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:27.608Z', '80f8972fd0c90ee14cc9a3c23e02663144ce5e1e3c9b79bd747cd2101f2b3e22', '{"id":"imansmallapple/app-StrayPet/arkts-coding-standard","name":"arkts-coding-standard","description":{"en":"The arkts-coding-standard skill provides guidelines for writing correct ArkTS code, focusing on strict typing and performance optimizations for HarmonyOS development. This skill benefits developers working with ArkTS and HarmonyOS.","zh":"ArkTS编码标准提供了HarmonyOS开发的严格类型和性能优化指南，帮助开发者避免非法类型和对象字面量类型。","ja":"ArkTSコーディングスタンダードは、HarmonyOS開発のための厳格な型とパフォーマンス最適化に関するガイドラインを提供し、開発者が不正な型やオブジェクトリテラル型を回避するのに役立ちます。","ko":"ArkTS 코딩 표준은 HarmonyOS 개발을 위한 엄격한 유형 및 성능 최적화를 제공하여 개발자가 불법 유형 및 객체 리터럴 유형을 피할 수 있도록 도와줍니다.","es":"El estándar de codificación ArkTS proporciona directrices y validación para escribir código ArkTS correcto, centrándose en tipos estrictos y optimizaciones de rendimiento para el desarrollo de HarmonyOS","fr":"La norme de codage ArkTS fournit des lignes directrices et une validation pour écrire du code ArkTS correct, en se concentrant sur les types stricts et les optimisations de performances pour le développement HarmonyOS","de":"Der ArkTS-Coding-Standard bietet Richtlinien und Validierung für die Erstellung von korrektem ArkTS-Code, mit Fokus auf strenge Typen und Leistungsoptimierungen für die HarmonyOS-Entwicklung","pt":"O ArkTS Coding Standard fornece diretrizes e validação para escrever código ArkTS correto, com foco em tipagem estrita e otimizações de desempenho","ru":"ИИ Агент ArkTS Coding Standard предоставляет руководство и проверку для написания правильного кода ArkTS, с уделением внимания строгой типизации и оптимизациям производительности","ar":"معيار الترميز ArkTS يوفر إرشادات وتصحيح للكتابة الصحيحة لكود ArkTS، مع التركيز على الترميز الصارم وتحسين الأداء"},"seo":{"title":{"en":"arkts-coding-standard: HarmonyOS Development Best Practic...","zh":"ArkTS编码标准设置指南","ja":"ArkTSコーディングスタンダードのベストプラクティス","ko":"ArkTS 코딩 표준 가이드","es":"Guía de configuración de ArkTS Coding Standard para Harmo...","fr":"Configurer les normes de codage ArkTS pour HarmonyOS","de":"Einrichtungsleitfaden für ArkTS-Coding-Standard unter Har...","pt":"Guia de Configuração do ArkTS Coding Standard","ru":"Настройка ИИ Агента ArkTS Coding Standard","ar":"دليل إعداد معيار الترميز ArkTS"},"description":{"en":"Unlock efficient ArkTS coding with our expert-backed guidelines. Learn how to avoid illegal practices and optimize performance for HarmonyOS development. Get...","zh":"了解ArkTS编码标准，优化HarmonyOS开发性能，避免非法类型和对象字面量类型","ja":"ArkTSコーディングスタンダードを理解して、HarmonyOS開発のパフォーマンスを最適化し、不正な型やオブジェクトリテラル型を避けます","ko":"ArkTS 코딩 표준을 이해하고 HarmonyOS 개발 성능을 최적화하여 불법 유형과 객체 리터럴 유형을 피하십시오","es":"Aprende a aplicar las normas de codage ArkTS para desarrollar aplicaciones de HarmonyOS con tipos estrictos y optimizaciones de rendimiento","fr":"Découvrez comment appliquer les normes de codage ArkTS pour développer des applications HarmonyOS avec des types stricts et des optimisations de performances","de":"Erfahren Sie, wie Sie die ArkTS-Coding-Standards anwenden, um HarmonyOS-Anwendungen mit strengen Typen und Leistungsoptimierungen zu entwickeln","pt":"Aprenda a configurar o ArkTS Coding Standard para melhorar a performance e a segurança do seu código HarmonyOS","ru":"Узнайте, как настроить ИИ Агент ArkTS Coding Standard для оптимизации производительности и безопасности вашего кода HarmonyOS","ar":"تعرف على كيفية إعداد معيار الترميز ArkTS لتحسين أداء وأمان كود HarmonyOS"},"definition":{"en":"arkts-coding-standard is a set of guidelines and validation rules for writing efficient and correct ArkTS code, emphasizing strict typing and performance optimizations.","zh":"ArkTS编码标准是一套用于HarmonyOS开发的编码规范，强调严格类型和性能优化","ja":"ArkTSコーディングスタンダードは、HarmonyOS開発用のコーディング規範であり、厳格な型とパフォーマンス最適化を重視しています","ko":"ArkTS 코딩 표준은 HarmonyOS 개발을 위한 코딩 규칙으로 엄격한 유형 및 성능 최적화를 강조합니다","es":"El estándar de codificación ArkTS es un conjunto de reglas para escribir código ArkTS correcto y optimizado para HarmonyOS","fr":"La norme de codage ArkTS est un ensemble de règles pour écrire du code ArkTS correct et optimisé pour HarmonyOS","de":"Der ArkTS-Coding-Standard ist eine Sammlung von Regeln für die Erstellung von korrektem und optimiertem ArkTS-Code für HarmonyOS","pt":"O ArkTS Coding Standard é um conjunto de regras para escrever código ArkTS correto e eficiente","ru":"ИИ Агент ArkTS Coding Standard - это набор правил для написания правильного и эффективного кода ArkTS","ar":"معيار الترميز ArkTS هو مجموعة من القواعد لكتابة كود ArkTS صحيح وفعال"},"features":{"en":["Enforces strict typing to prevent the use of Any/Unknown Types","Validates against illegal practices, such as Object Literal Types","Provides guidelines for performance optimizations in HarmonyOS development","Supports the development of efficient and correct ArkTS code","Helps avoid common pitfalls, such as using forbidden type annotations","Promotes best practices for ArkTS coding, including the avoidance of discouraged patterns"],"zh":["严格类型检查","性能优化指南","避免any和unknown类型","禁止对象字面量类型","HarmonyOS开发支持","代码质量提高"],"ja":["厳格な型チェック","パフォーマンス最適化ガイド","anyとunknown型の回避","オブジェクトリテラル型の禁止","HarmonyOS開発サポート","コード品質の向上"],"ko":["엄격한 유형 검사","성능 최적화 가이드","any 및 unknown 유형 회피","객체 리터럴 유형 금지","HarmonyOS 개발 지원","코드 품질 향상"],"es":["Tipos estrictos para evitar el uso de ''any'' y ''unknown''","Validación de patrones para evitar prácticas ilegales o desaconsejadas","Optimizaciones de rendimiento para el desarrollo de HarmonyOS","Guías para la escritura de código ArkTS correcto","Compatibilidad con el desarrollo de aplicaciones de HarmonyOS"],"fr":["Types stricts pour éviter l''utilisation de ''any'' et ''unknown''","Validation de modèles pour éviter les pratiques illégales ou déconseillées","Optimisations de performances pour le développement HarmonyOS","Guides pour l''écriture de code ArkTS correct","Compatibilité avec le développement d''applications HarmonyOS"],"de":["Strenge Typen, um den Einsatz von ''any'' und ''unknown'' zu vermeiden","Muster-Validierung, um unzulässige oder nicht empfohlene Praktiken zu vermeiden","Leistungsoptimierungen für die HarmonyOS-Entwicklung","Leitfäden für die Erstellung von korrektem ArkTS-Code","Kompatibilität mit der Entwicklung von HarmonyOS-Anwendungen"],"pt":["Proibição de tipos Any/Unknown","Validação de padrões de código","Otimizações de desempenho para HarmonyOS","Tipagem estrita para melhorar a segurança","Suporte à escrita de código ArkTS correto"],"ru":["Запрет типов Any/Unknown","Проверка шаблонов кода","Оптимизации производительности для HarmonyOS","Строгая типизация для повышения безопасности","Поддержка написания правильного кода ArkTS"],"ar":["منع أنواع Any/Unknown","التحقق من أنماط الكود","تحسينات الأداء لمنصة HarmonyOS","ترميز صارم لتحسين الأمان","دعم كتابة كود ArkTS صحيح"]},"keywords":{"en":["how to use arkts-coding-standard","what is arkts-coding-standard","arkts-coding-standard vs TypeScript","arkts-coding-standard install","arkts-coding-standard setup guide for HarmonyOS","arkts-coding-standard best practices","arkts-coding-standard alternative for efficient coding","arkts-coding-standard tutorial for beginners","arkts-coding-standard documentation","arkts-coding-standard examples"],"zh":["ArkTS编码标准","HarmonyOS开发","严格类型","性能优化","any类型","unknown类型","对象字面量类型","AIエージェント","代码质量"],"ja":["ArkTSコーディングスタンダード","HarmonyOS開発","厳格な型","パフォーマンス最適化","any型","unknown型","オブジェクトリテラル型","AIエージェント","コード品質"],"ko":["ArkTS 코딩 표준","HarmonyOS 개발","엄격한 유형","성능 최적화","any 유형","unknown 유형","객체 리터럴 유형","AI 에이전트","코드 품질"],"es":["ArkTS coding standard","desarrollo de HarmonyOS","tipos estrictos","optimizaciones de rendimiento","validación de código","guías de codificación","Herramientas de desarrollo de HarmonyOS","ArkTS para HarmonyOS","estándares de codificación para HarmonyOS"],"fr":["norme de codage ArkTS","développement HarmonyOS","types stricts","optimisations de performances","validation de code","guides de codage","Outils de développement HarmonyOS","ArkTS pour HarmonyOS","normes de codage pour HarmonyOS"],"de":["ArkTS-Coding-Standard","HarmonyOS-Entwicklung","strenge Typen","Leistungsoptimierungen","Code-Validierung","Codierleitfäden","Entwicklungstools für HarmonyOS","ArkTS für HarmonyOS","Codierstandards für HarmonyOS"],"pt":["ArkTS Coding Standard","Guia de configuração ArkTS","Otimizações de desempenho HarmonyOS","Tipagem estrita em TypeScript","Desenvolvimento de aplicativos HarmonyOS","Melhorias de segurança em ArkTS"],"ru":["ИИ Агент ArkTS Coding Standard","Настройка ИИ Агента ArkTS","Оптимизации производительности HarmonyOS","Строгая типизация в TypeScript","Разработка приложений HarmonyOS","Улучшения безопасности в ArkTS"],"ar":["معيار الترميز ArkTS","دليل إعداد ArkTS","تحسينات الأداء لمنصة HarmonyOS","ترميز صارم في TypeScript","تطوير تطبيقات HarmonyOS","تحسينات أمان في ArkTS"]}},"owner":"imansmallapple","repo":"app-StrayPet","repoPath":"imansmallapple/app-StrayPet","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"arkts-coding-standard","description":"Enforces ArkTS strict typing rules and coding standards. Invoke when writing, analyzing, or correcting ArkTS code for HarmonyOS to ensure compliance.","bodyPreview":"# ArkTS Coding Standards\n\nThis skill provides guidelines and validation for writing correct ArkTS code, focusing on strict typing and performance optimizations required for HarmonyOS development.\n\n## ❌ Illegal / Discouraged Practices\n\nThe following patterns are **forbidden** or highly discouraged in ArkTS:\n\n1.  **Any/Unknown Types**:\n    ```typescript\n    let x: any = 1; // ❌ Not allowed: `any` and `unknown` are forbidden.\n    ```\n\n2.  **Object Literal Types**:\n    ```typescript\n    type Inline","body":"# ArkTS Coding Standards\n\nThis skill provides guidelines and validation for writing correct ArkTS code, focusing on strict typing and performance optimizations required for HarmonyOS development.\n\n## ❌ Illegal / Discouraged Practices\n\nThe following patterns are **forbidden** or highly discouraged in ArkTS:\n\n1.  **Any/Unknown Types**:\n    ```typescript\n    let x: any = 1; // ❌ Not allowed: `any` and `unknown` are forbidden.\n    ```\n\n2.  **Object Literal Types**:\n    ```typescript\n    type Inline = { value: number }; // ❌ Don''t declare object-literal-based types.\n    ```\n\n3.  **Fresh Object Literals (Untyped)**:\n    ```typescript\n    const bad: Inline = { value: 1 }; // ❌ Fresh object literal without declared class/interface instance.\n    ```\n\n4.  **Runtime Shape Changes**:\n    ```typescript\n    bad.newProp = \"later\"; // ❌ Changing object shape (adding properties) at runtime is forbidden.\n    ```\n\n5.  **Implicit Object Shapes**:\n    ```typescript\n    const obj = {\n      value: 1,\n      double() {\n        return this.value + this.value; // ❌ `this` in a non-method context is disallowed.\n      }\n    }; // ❌ Even with an object literal, it must match an explicit class/interface.\n    ```\n\n6.  **Type Mismatches**:\n    ```typescript\n    bad.value = \"7\"; // ❌ Assigning string to a number-typed field fails.\n    ```\n\n7.  **Implicit Coercion**:\n    ```typescript\n    console.info(String(+bad.value)); // ❌ Unary `+` on a string for coercion is not permitted.\n    ```\n\n## ✅ Correct Practices\n\nUse explicit types, classes, and safe conversions:\n\n1.  **Explicit Numeric Parsing**:\n    ```typescript\n    const s: string = \"7\";\n    // Use explicit parsing methods instead of unary +\n    const n: number = Number.parseInt(s); \n    ```\n\n2.  **Classes and Interfaces**:\n    Always define explicit classes or interfaces for your data structures.\n\n    ```typescript\n    class Doubler {\n      value: number;\n      constructor(value: number) {\n        this.value = value;\n      }\n    }\n    \n    let obj = new Doubler(n);\n    ```\n\n## Summary of Rules\n\n*   **Static Typing**: ArkTS is statically typed. Avoid dynamic features like `any`.\n*   **Fixed Layout**: Object layout is fixed at compile time. You cannot add/remove properties at runtime.\n*   **Explicit Types**: Define types explicitly using `class` or `interface`. Avoid anonymous object types.\n*   **Strict Safety**: No implicit type coercion. Use standard library functions (e.g., `Number.parseInt`) for conversions.\n"},"lastSynced":"2026-03-08T02:00:27.608Z","agentAnalysis":{"suitability":{"en":"Perfect for HarmonyOS Developers needing strict typing and performance optimizations in ArkTS code.","zh":"非常适合需要在ArkTS代码中严格类型检查和性能优化的HarmonyOS开发者。","ja":"ArkTSコードで厳格な型チェックとパフォーマンス最適化を必要とするHarmonyOS開発者に最適。","ko":"ArkTS 코드에서 엄격한 타이핑과 성능 최적화를 필요로 하는 HarmonyOS 개발자를 위한 최적의 선택","es":"Perfecto para desarrolladores de HarmonyOS que necesitan tipado estricto y optimizaciones de rendimiento en código ArkTS.","fr":"Parfait pour les développeurs HarmonyOS ayant besoin d''un typage strict et d''optimisations de performances dans le code ArkTS.","de":"Perfekt für HarmonyOS-Entwickler, die strenges Typing und Leistungsoptimierungen in ArkTS-Code benötigen.","pt":"Perfeito para desenvolvedores HarmonyOS que necessitam de tipagem estrita e otimizações de desempenho em código ArkTS.","ru":"Идеально подходит для разработчиков HarmonyOS, которым требуются строгая типизация и оптимизации производительности в коде ArkTS.","ar":"مثالي للمطورين HarmonyOS الذين يحتاجون إلى تنصيب صارم وتحسين الأداء في رمز ArkTS."},"recommendation":{"en":"Empowers agents to enforce strict typing and performance optimizations in ArkTS code, utilizing guidelines for HarmonyOS development and validating against forbidden practices like Any/Unknown Types and Object Literal Types.","zh":"赋予代理人执行严格类型检查和性能优化的能力，利用HarmonyOS开发指南，并验证不允许的做法，如Any/Unknown类型和对象字面量类型。","ja":"厳格な型チェックとパフォーマンス最適化を実行する能力をエージェントに与え、HarmonyOS開発ガイドラインを使用し、Any/Unknownタイプやオブジェクトリテラルタイプなどの禁止されている実践を検証する。","ko":"엄격한 타이핑과 성능 최적화를 수행할 수 있는 능력을 에이전트에게 부여하여, HarmonyOS 개발 지침을 사용하고, Any/Unknown 타입 및 객체 리터럴 타입과 같은 금지된 관행을 검증합니다.","es":"Habilita a los agentes a aplicar tipado estricto y optimizaciones de rendimiento en el código ArkTS, utilizando directrices para el desarrollo de HarmonyOS y validando contra prácticas prohibidas como Any/Unknown Types y Object Literal Types.","fr":"Permet aux agents d''appliquer un typage strict et des optimisations de performances dans le code ArkTS, en utilisant des lignes directrices pour le développement HarmonyOS et en validant contre les pratiques interdites comme Any/Unknown Types et Object Literal Types.","de":"Ermächtigt Agenten, strenges Typing und Leistungsoptimierungen in ArkTS-Code durchzusetzen, unter Verwendung von Richtlinien für die HarmonyOS-Entwicklung und Validierung gegen verbotene Praktiken wie Any/Unknown Types und Object Literal Types.","pt":"Habilita agentes a impor tipagem estrita e otimizações de desempenho em código ArkTS, utilizando diretrizes para desenvolvimento HarmonyOS e validando contra práticas proibidas, como Any/Unknown Types e Object Literal Types.","ru":"Наделяет агентов возможностью обеспечивать строгую типизацию и оптимизацию производительности в коде ArkTS, используя руководящие принципы для разработки HarmonyOS и проверяя на предмет запрещенных практик, таких как Any/Unknown Types и Object Literal Types.","ar":"تمكين الوكلاء من فرض التنصيب الصارم وتحسين الأداء في رمز ArkTS، باستخدام إرشادات لتطوير HarmonyOS والتحقق من الممارسات المحظورة مثل Any/Unknown Types و Object Literal Types."},"useCases":{"en":["Enforcing strict typing in ArkTS projects","Optimizing performance in HarmonyOS applications","Validating ArkTS code against discouraged practices"],"zh":["在ArkTS项目中执行严格类型检查","在HarmonyOS应用程序中优化性能","验证ArkTS代码是否违反不推荐的做法"],"ja":["ArkTSプロジェクトで厳格な型チェックを実行する","HarmonyOSアプリケーションでパフォーマンスを最適化する","ArkTSコードを不推奨の実践に対して検証する"],"ko":["ArkTS 프로젝트에서 엄격한 타이핑을 수행하는 것","HarmonyOS 애플리케이션에서 성능을 최적화하는 것","ArkTS 코드가 권장하지 않는 관행을 위반하는지 확인"],"es":["Aplicar tipado estricto en proyectos ArkTS","Optimizar el rendimiento en aplicaciones HarmonyOS","Validar el código ArkTS contra prácticas desaconsejadas"],"fr":["Appliquer un typage strict dans les projets ArkTS","Optimiser les performances dans les applications HarmonyOS","Valider le code ArkTS contre les pratiques découragées"],"de":["Strenges Typing in ArkTS-Projekten durchsetzen","Leistungsoptimierung in HarmonyOS-Anwendungen","ArkTS-Code gegen nicht empfohlene Praktiken validieren"],"pt":["Impor tipagem estrita em projetos ArkTS","Otimizar o desempenho em aplicações HarmonyOS","Validar o código ArkTS contra práticas desencorajadas"],"ru":["Обеспечение строгой типизации в проектах ArkTS","Оптимизация производительности в приложениях HarmonyOS","Проверка кода ArkTS на предмет неодобренных практик"],"ar":["فرض التنصيب الصارم في مشاريع ArkTS","تحسين الأداء في تطبيقات HarmonyOS","التحقق من رمز ArkTS ضد الممارسات غير الموصى بها"]},"limitations":{"en":["Requires ArkTS and HarmonyOS development environment","Limited to TypeScript-based projects"],"zh":["需要ArkTS和HarmonyOS开发环境","仅限TypeScript基于项目"],"ja":["ArkTSとHarmonyOS開発環境が必要","TypeScriptベースのプロジェクトのみ"],"ko":["ArkTS 및 HarmonyOS 개발 환경이 필요","TypeScript 기반 프로젝트에만 제한"],"es":["Requiere un entorno de desarrollo ArkTS y HarmonyOS","Limitado a proyectos basados en TypeScript"],"fr":["Nécessite un environnement de développement ArkTS et HarmonyOS","Limité aux projets basés sur TypeScript"],"de":["Benötigt eine ArkTS- und HarmonyOS-Entwicklungsumgebung","Begrenzt auf TypeScript-basierte Projekte"],"pt":["Requer ambiente de desenvolvimento ArkTS e HarmonyOS","Limitado a projetos baseados em TypeScript"],"ru":["Требуется среда разработки ArkTS и HarmonyOS","Ограничен проектами на основе TypeScript"],"ar":["يتطلب بيئة تطوير ArkTS و HarmonyOS","محدود بمشاريع قائم على TypeScript"]},"version":4},"contentHash":"80f8972fd0c90ee14cc9a3c23e02663144ce5e1e3c9b79bd747cd2101f2b3e22","qualityScore":33}');
